  // Hook: MO-019 USER FLOW — Approve → Order → Receive @ คลัง Tub Lamu (UI simulation)
  // จำลองการกดปุ่มจริงผ่าน UI ของ User · By: ANON (แทน) · Date: 03/05/2026
  if(d._app_hooks && !d._app_hooks.mo019_user_flow_approve_order_receive && d._app_hooks.mo019_npsk_quotation_v2){
    const ACTION_DATE = '2026-05-03';
    const APPROVER    = 'ANON (แทน)';
    const RECEIVE_LOC = 'คลัง Tub Lamu';
    const mo19 = (d.fleet_memos||[]).find(x=>x.id==='mo_019_npsk_parts');
    if(mo19 && mo19.status==='pending_approval'){
      // ─── STEP 1: APPROVE (mirror flSaveApprove) ───
      mo19.currentStep   = 2;
      mo19.status        = 'approved';
      mo19.approvedBy    = APPROVER;
      mo19.approvedDate  = ACTION_DATE;
      mo19.approveNote   = '';

      // ─── STEP 2: ORDER (mirror flAdvanceMemo for parts) ───
      mo19.currentStep   = 3;
      mo19.status        = 'ordered';
      mo19.orderedDate   = ACTION_DATE;
      mo19.orderedBy     = APPROVER;

      // ─── STEP 3: RECEIVE @ คลัง Tub Lamu (mirror flSaveReceive) ───
      let updatedCount=0, createdCount=0;
      (mo19.items||[]).forEach(it=>{
        const cat = it.category || mo19.memoType || 'parts';
        if(cat === 'labor') return;
        const qty = it.qty || 0;
        if(qty <= 0) return;
        // match by invId first, then by exact name
        let inv = it.invId
          ? (d.fleet_inventory||[]).find(x=>x.id===it.invId)
          : (d.fleet_inventory||[]).find(x=>x.name===it.name||it.name.includes(x.name));
        if(inv){
          // sync legacy (ensure .stocks array exists)
          if(!Array.isArray(inv.stocks)){
            inv.stocks = [{location: inv.location||RECEIVE_LOC, qty: inv.qty||0, minQty: inv.minQty||0}];
          }
          // add at RECEIVE_LOC
          let s = inv.stocks.find(x=>x.location===RECEIVE_LOC);
          if(!s){ s={location:RECEIVE_LOC, qty:0, minQty:0}; inv.stocks.push(s); }
          s.qty = (s.qty||0) + qty;
          // recompute totals
          inv.totalQty = inv.stocks.reduce((sum,x)=>sum+(x.qty||0), 0);
          inv.qty = inv.totalQty;
          const sorted = [...inv.stocks].sort((a,b)=>(b.qty||0)-(a.qty||0));
          inv.primaryLocation = sorted[0]?.location || RECEIVE_LOC;
          inv.location = inv.primaryLocation;
          if(!Array.isArray(inv.history)) inv.history = [];
          inv.history.push({
            date:ACTION_DATE, type:'receive', qty, location:RECEIVE_LOC,
            note:`จาก ${mo19.no} · @ ${RECEIVE_LOC}`, by:APPROVER
          });
          updatedCount++;
        } else {
          // Auto-create new inventory item
          const newInv = {
            id: 'i_mo019_'+(it.name||'item').replace(/[^a-zA-Z0-9]/g,'').slice(0,12).toLowerCase()+'_'+Math.floor(Math.random()*1000),
            name: it.name,
            partNo: '',
            category: 'อื่นๆ',
            supplier: mo19.supplier || 'NPSK Marine',
            location: RECEIVE_LOC,
            stocks: [{location:RECEIVE_LOC, qty:qty, minQty:0}],
            qty: qty, totalQty: qty,
            primaryLocation: RECEIVE_LOC,
            minQty: 0,
            unit: it.unit || 'ชิ้น',
            cost: it.price || 0,
            note: `สร้างอัตโนมัติจาก ${mo19.no}`,
            createdFrom: mo19.no,
            createdDate: ACTION_DATE,
            history: [{date:ACTION_DATE, type:'receive', qty, location:RECEIVE_LOC, note:`รับครั้งแรก · จาก ${mo19.no} · @ ${RECEIVE_LOC}`, by:APPROVER}]
          };
          if(!d.fleet_inventory) d.fleet_inventory = [];
          d.fleet_inventory.push(newInv);
          it.invId = newInv.id;
          createdCount++;
        }
      });
      mo19.currentStep   = 4;
      mo19.status        = 'received';
      mo19.receivedDate  = ACTION_DATE;
      mo19.receivedBy    = APPROVER;
      mo19.receivedLocation = RECEIVE_LOC;
      mo19.receivedSummary  = `อัพเดท ${updatedCount} · สร้างใหม่ ${createdCount} items @ ${RECEIVE_LOC}`;
    }
    d._app_hooks.mo019_user_flow_approve_order_receive = true;
    localStorage.setItem(LS_KEY,JSON.stringify(d));
  }
  
  // Hook: MJ-006 USER FLOW — กด +Withdraw เบิก i60 (ตัวเรือนชุดเฟืองเกียร์ 250 สีขาว) 1 ชิ้น
  // จำลองการกด UI: flMaintAddPart('mj_al1_gb_006') · ใช้ logic เดียวกันเป๊ะๆ
  if(d._app_hooks && !d._app_hooks.mj006_withdraw_i60_v1 && d._app_hooks.mo019_user_flow_approve_order_receive){
    const WITHDRAW_DATE = '2026-05-03';  // วันเดียวกับที่รับของเข้า
    const WITHDRAW_BY   = 'ระบบ';
    const QTY = 1;
    const mj6 = (d.fleet_maintenance||[]).find(x=>x.id==='mj_al1_gb_006');
    const inv = (d.fleet_inventory||[]).find(x=>x.id==='i60');
    if(mj6 && inv && (inv.qty||0) >= QTY){
      // ─── 1. หัก stock จาก inventory (mirror flMaintAddPart) ───
      inv.qty = (inv.qty||0) - QTY;
      // กระจาย hit ไปที่ stocks[] ด้วย (เพื่อให้สมจริง · เลือก Tub Lamu ก่อนถ้ามี)
      if(Array.isArray(inv.stocks) && inv.stocks.length){
        const preferLoc = inv.stocks.find(s=>s.location==='คลัง Tub Lamu' && (s.qty||0)>=QTY);
        const target = preferLoc || inv.stocks.find(s=>(s.qty||0)>=QTY) || inv.stocks[0];
        if(target){ target.qty = Math.max(0, (target.qty||0) - QTY); }
        // recompute totals
        inv.totalQty = inv.stocks.reduce((sum,x)=>sum+(x.qty||0), 0);
      }
      // ─── 2. log inventory history ───
      if(!Array.isArray(inv.history)) inv.history = [];
      inv.history.push({
        date:WITHDRAW_DATE, type:'withdraw', qty:QTY,
        location:'คลัง Tub Lamu',
        note:`เบิกใช้งาน ${mj6.no||''} · ${mj6.title||''}`,
        by:WITHDRAW_BY, jobId:mj6.id
      });
      // ─── 3. เพิ่ม part เข้า maintenance job ───
      if(!Array.isArray(mj6.parts)) mj6.parts = [];
      const existing = mj6.parts.find(p=>p.invId==='i60');
      if(existing){ existing.qty += QTY; }
      else{ mj6.parts.push({invId:'i60', name:inv.name, qty:QTY, unit:inv.unit||'ชิ้น', cost:inv.cost||0}); }
      // ─── 4. log progress ───
      const logText = `📦 เบิก ${inv.name} ${QTY} ${inv.unit||'ชิ้น'} (฿${(QTY*(inv.cost||0)).toLocaleString()})`;
      if(!Array.isArray(mj6.progressLog)) mj6.progressLog = [];
      mj6.progressLog.push({date:WITHDRAW_DATE, text:logText, by:WITHDRAW_BY});
      // ─── 5. sync m.cost (ค่าใช้จ่ายรวมของ job · ใช้ logic เดียวกับ flMaintCalcCost) ───
      const partsCost = mj6.parts.reduce((s,p)=>s+((p.qty||0)*(p.cost||0)), 0);
      const memoCost = (d.fleet_memos||[])
        .filter(mo => mo.maintId===mj6.id && (mo.status==='paid' || mo.status==='received' || mo.status==='approved'))
        .reduce((s,mo)=>s+(mo.amount||0), 0);
      mj6.cost = partsCost + memoCost;
    }
    d._app_hooks.mj006_withdraw_i60_v1 = true;
    localStorage.setItem(LS_KEY,JSON.stringify(d));
  }
  
