  // Hook: Simulate user actions via UI flow for INC-012 + MJ-024
  //   1. User opens + Incident modal, fills in:
  //      - Boat: Zeus (b6) · Date: 11/5/2026 · Title: ไดร์ชาร์จเสีย
  //      - Damaged asset: engine e26 (BBNJ-1000049 · Port)
  //      - Priority: 3
  //   2. User opens + Job from incident, fills in:
  //      - Type: Corrective · Title: เปลี่ยนไดร์ชาร์จ Zeus Port
  //      - Boat status during job: Available
  //   This matches flSaveIncident() + flSaveAddMaint() schema exactly
  if(d._app_hooks && !d._app_hooks.inc012_mj024_via_ui_v1){
    const INC_DATE = '2026-05-11';
    if(!d.fleet_incidents) d.fleet_incidents = [];
    if(!d.fleet_maintenance) d.fleet_maintenance = [];
    
    // Check if already created (avoid duplicates)
    const incExists = d.fleet_incidents.some(i=>i.no === 'INC-012');
    const mjExists = d.fleet_maintenance.some(m=>m.no === 'MJ-024');
    
    if(!incExists && !mjExists){
      // STEP 1: Create incident (mimics flSaveIncident)
      const incId = 'inc_zeus_1779690941893';   /* static — Date.now() ids made every re-seed a duplicate */
      const mjId = 'mj_zeus_1779690941893';
      const damagedAssets = [
        {type:'engine', id:'e26', label:'BBNJ-1000049 · Port'}
      ];
      const incidentTitle = 'ไดร์ชาร์จเสีย';
      const priority = 3;
      
      const inc = {
        id: incId, no:'INC-012',
        boatId: 'b6',
        date: INC_DATE, time:'',
        title: incidentTitle,
        detail: 'ไดร์ชาร์จ Honda BF250D เครื่อง Port (BBNJ-1000049) เสีย · ต้องเปลี่ยน',
        remark: 'Anon',
        damagedAssets,
        priority,
        severity: priority>=4?'critical':priority>=3?'major':'minor',
        type:'incident', status:'open',
        maintId: null,  // Will be linked after MJ create
        progressLog: [{
          date: INC_DATE,
          text: `เปิด Incident: ${incidentTitle} · ความเสียหาย: ${damagedAssets.map(a=>a.label).join(', ')}`,
          by: 'Anon'
        }]
      };
      d.fleet_incidents.unshift(inc);
      
      // STEP 2: Create MJ from incident (mimics flSaveAddMaint)
      const initialAssets = damagedAssets.map(a=>({
        type: a.type, engId: a.id, label: a.label, detail:'', status:'fixing'
      }));
      
      const mj = {
        id: mjId, no:'MJ-024',
        boatId: 'b6',
        type:'corrective',
        title: 'เปลี่ยนไดร์ชาร์จ Zeus Port',
        detail: '',
        location: '',
        status: 'pending',
        startDate: INC_DATE,
        endDate: null,
        cost: 0,
        incidentId: incId,
        assets: initialAssets,
        progressLog: [],
        boatStatus: 'available',     // user เลือก Available
        boatStatusReason: '',
        setFixing: false             // available = ไม่ fix
      };
      d.fleet_maintenance.unshift(mj);
      
      // STEP 3: Link incident → MJ (system does this auto in real UI)
      inc.maintId = mjId;
      inc.progressLog.push({
        date: INC_DATE,
        text: `+ สร้าง Job ${mj.no} · ${mj.title}`,
        by: 'ระบบ'
      });
      
      // Note: We do NOT set engine status to 'fixing' because boat is still Available
      //       Engine status comes from MJ assets[*].status — handled by display logic
    }
    
    d._app_hooks.inc012_mj024_via_ui_v1 = true;
    localStorage.setItem(LS_KEY,JSON.stringify(d));
  }
  
  // Hook: Simulate user clicking "Start" button on MJ-024 (mimics flMaintStart)
  //   - status: pending → inprogress
  //   - boat: NO log push (boatStatus='available')
  //   - engine: NO cascade fixing (boat available)
  //   - asset log: service-start entry
  //   - progressLog: ▶ Start Job entry
  if(d._app_hooks && !d._app_hooks.mj024_started_v1){
    if(d.fleet_maintenance){
      const mj = d.fleet_maintenance.find(m=>m.no === 'MJ-024');
      if(mj && mj.status === 'pending'){
        const START_DATE = '2026-05-11';
        const targetStatus = mj.boatStatus || 'fixing';
        const cascadeAssetFixing = (targetStatus === 'fixing');
        const b = d.boats?.find(x=>x.id===mj.boatId);
        
        // 1. Update status
        mj.status = 'inprogress';
        
        // 2. Boat log push (only if NOT available)
        if(b && targetStatus !== 'available'){
          if(!b.log) b.log = [];
          b.log.push({
            id:'sl'+Date.now(),
            s: targetStatus,
            from: START_DATE, to: null,
            loc: mj.location || '',
            note: `Maintenance Job ${mj.no}`,
            reason: mj.boatStatusReason || ''
          });
        }
        
        // 3. Asset log entries (service-start)
        const statusLabel = targetStatus==='fixing'?'Fixing':targetStatus==='unavailable'?'Unavailable':'Available';
        (mj.assets||[]).forEach(a=>{
          if(a.type==='engine' && a.engId && d.fleet_engines){
            const eng = d.fleet_engines.find(e=>e.id===a.engId);
            if(eng){
              if(!eng.log) eng.log = [];
              eng.log.push({
                date: START_DATE, type: 'service-start',
                desc: `▶ เริ่มซ่อม · ${mj.no} · ${mj.title}${mj.location?' @ '+mj.location:''}`,
                detail: a.detail || mj.detail || '',
                hours: eng.baseHours || 0
              });
              if(cascadeAssetFixing) eng.status = 'fixing';
            }
          }
          // (gearbox + propeller similar · skip for this MJ since only engine asset)
        });
        
        // 4. Maintenance progressLog entry
        if(!mj.progressLog) mj.progressLog = [];
        mj.progressLog.push({
          date: START_DATE,
          text: `▶ Start Job · ${b?b.name+' = '+statusLabel:''}${mj.location?' → '+mj.location:''}`,
          by: 'ระบบ'
        });
      }
    }
    d._app_hooks.mj024_started_v1 = true;
    localStorage.setItem(LS_KEY,JSON.stringify(d));
  }
  
  // Hook: Simulate user UI actions on MO-020 (SAK Marine · ไดร์ชาร์จ Zeus)
  //   Step 1 → 2: Approve · Anon Pinchai (แทน)
  //   Step 2 → 3: Order
  //   Step 3 → 4: Receive · เข้าคลัง Tub Lamu · qty 1 ไปยัง i62
  //   (ยังไม่ Pay)
  if(d._app_hooks && !d._app_hooks.mo020_approve_order_receive_v1){
    if(d.fleet_memos && d.fleet_inventory){
      const mo = d.fleet_memos.find(m=>m.no === 'MO-020');
      if(mo && mo.status === 'pending_approval'){
        const APPROVE_DATE = '2026-05-13';
        const ORDER_DATE = '2026-05-13';
        const RECEIVE_DATE = '2026-05-13';
        const RECV_LOCATION = 'คลัง Tub Lamu';
        
        // Step 1 → 2: Approve
        mo.status = 'received';     // Final status at this point
        mo.currentStep = 4;
        mo.approvedBy = 'Anon Pinchai (แทน)';
        mo.approveNote = 'หัวหน้างาน';
        mo.approvedDate = APPROVE_DATE;
        
        // Step 2 → 3: Order
        mo.orderedDate = ORDER_DATE;
        mo.orderedBy = 'ฝ่ายจัดซื้อ';
        
        // Step 3 → 4: Receive
        mo.receivedDate = RECEIVE_DATE;
        mo.receivedBy = 'ฝ่ายซ่อมบำรุง';
        
        // Stock-in for parts items
        (mo.items || []).forEach(item => {
          if(item.fromInventory && item.invId && (item.category||'parts')==='parts'){
            const inv = d.fleet_inventory.find(x=>x.id===item.invId);
            if(inv){
              // Initialize multi-warehouse fields if missing
              if(!inv.stocks || !Array.isArray(inv.stocks)) inv.stocks = [];
              // Add to chosen location
              let stockEntry = inv.stocks.find(s=>s.location === RECV_LOCATION);
              if(!stockEntry){
                stockEntry = {location: RECV_LOCATION, qty: 0, minQty: inv.minQty || 0};
                inv.stocks.push(stockEntry);
              }
              stockEntry.qty = (stockEntry.qty || 0) + item.qty;
              // Sync legacy fields
              const total = inv.stocks.reduce((s,x)=>s+(x.qty||0), 0);
              inv.qty = total;
              inv.totalQty = total;
              const sorted = [...inv.stocks].sort((a,b)=>(b.qty||0)-(a.qty||0));
              inv.primaryLocation = sorted[0]?.location || RECV_LOCATION;
              inv.location = inv.primaryLocation;
              // Add history entry
              if(!inv.history) inv.history = [];
              inv.history.push({
                date: RECEIVE_DATE,
                type: 'receive',
                qty: item.qty,
                location: RECV_LOCATION,
                note: `จาก ${mo.no} · ${mo.supplier} · @ ${RECV_LOCATION}`,
                by: 'ฝ่ายซ่อมบำรุง'
              });
            }
          }
        });
      }
    }
    d._app_hooks.mo020_approve_order_receive_v1 = true;
    localStorage.setItem(LS_KEY,JSON.stringify(d));
  }
  
  // Hook: Simulate user UI actions on MJ-024
  //   Step 1: + Withdraw ไดร์ชาร์จ (i62) 1 ชิ้น  (deducts from inventory · adds to job parts)
  //   Step 2: Close · outcome=success · note="ใช้งานปกติ"
  if(d._app_hooks && !d._app_hooks.mj024_withdraw_close_v1){
    if(d.fleet_maintenance && d.fleet_inventory){
      const mj = d.fleet_maintenance.find(m=>m.no === 'MJ-024');
      const i62 = d.fleet_inventory.find(x=>x.id === 'i62');
      
      if(mj && mj.status === 'inprogress' && i62){
        const ACTION_DATE = '2026-05-13';  // วันรับของ + ติดตั้ง
        const CLOSE_DATE = '2026-05-13';
        
        // STEP 1: Withdraw ไดร์ชาร์จ 1 ชิ้น
        const wdQty = 1;
        const wdLocation = 'คลัง Tub Lamu';
        
        // Deduct from inventory (multi-warehouse)
        if(i62.stocks){
          const stockEntry = i62.stocks.find(s=>s.location === wdLocation);
          if(stockEntry && stockEntry.qty >= wdQty){
            stockEntry.qty -= wdQty;
            // Recompute legacy
            const total = i62.stocks.reduce((s,x)=>s+(x.qty||0), 0);
            i62.qty = total;
            i62.totalQty = total;
            const sorted = [...i62.stocks].sort((a,b)=>(b.qty||0)-(a.qty||0));
            i62.primaryLocation = sorted[0]?.location || wdLocation;
            i62.location = i62.primaryLocation;
          }
        }
        // Log withdraw to inventory history
        if(!i62.history) i62.history = [];
        i62.history.push({
          date: ACTION_DATE,
          type: 'withdraw',
          qty: wdQty,
          location: wdLocation,
          note: `เบิกใช้งาน ${mj.no} · ${mj.title}`,
          by: 'ระบบ',
          jobId: mj.id
        });
        
        // Add to job parts
        if(!mj.parts) mj.parts = [];
        mj.parts.push({
          invId: i62.id,
          name: i62.name,
          qty: wdQty,
          unit: i62.unit,
          cost: i62.cost,
          location: wdLocation
        });
        
        // Recompute MJ cost (parts only · no labor in this case)
        mj.cost = mj.parts.reduce((s,p)=>s+(p.qty*p.cost), 0);
        
        // Progress log: withdraw
        if(!mj.progressLog) mj.progressLog = [];
        mj.progressLog.push({
          date: ACTION_DATE,
          text: `📦 เบิก ${i62.name} ${wdQty} ${i62.unit} (฿${(wdQty*i62.cost).toLocaleString()})`,
          by: 'ระบบ'
        });
        
        // STEP 2: Close · outcome=success
        mj.status = 'done';
        mj.endDate = CLOSE_DATE;
        mj.outcome = 'success';
        mj.closeNote = 'ใช้งานปกติ';
        mj.awaitingInvoice = false;
        
        // Update boat log — outcome=success means boat status returns to 'available'
        // (but boat was already 'available' during this MJ, so no change needed visually)
        // Still push a "closed" log entry for history
        const b = d.boats?.find(x=>x.id === mj.boatId);
        if(b){
          if(!b.log) b.log = [];
          // Push closing log
          const lastLog = b.log[b.log.length-1];
          // Close any open log entry
          if(lastLog && !lastLog.to){
            lastLog.to = CLOSE_DATE;
          }
          // Add new "available" entry from CLOSE_DATE
          b.log.push({
            id: 'sl'+Date.now(),
            s: 'available',
            from: CLOSE_DATE, to: null,
            loc: lastLog?.loc || '',
            note: `ปิด Job ${mj.no}`,
            reason: ''
          });
          // Repair history
          if(!b.repairHistory) b.repairHistory = [];
          b.repairHistory.push({
            date: CLOSE_DATE,
            jobNo: mj.no,
            title: mj.title,
            detail: '',
            type: mj.type,
            location: '',
            cost: mj.cost,
            assets: (mj.assets||[]).map(a=>a.label),
            startDate: mj.startDate,
            endDate: CLOSE_DATE,
            outcome: 'success',
            closeNote: 'ใช้งานปกติ'
          });
        }
        
        // Reset engine assets back to ready (outcome=success)
        (mj.assets||[]).forEach(a=>{
          if(a.type === 'engine' && a.engId && d.fleet_engines){
            const eng = d.fleet_engines.find(e=>e.id===a.engId);
            if(eng){
              eng.status = 'ready';   // outcome=success
              if(!eng.log) eng.log = [];
              eng.log.push({
                date: CLOSE_DATE,
                type: 'service-end',
                desc: `✓ ปิด Job · ${mj.no} · ${mj.title} · ใช้งานปกติ`,
                detail: 'ใช้งานปกติ',
                hours: eng.baseHours || 0
              });
            }
          }
        });
        
        // Close linked incident
        if(mj.incidentId && d.fleet_incidents){
          const inc = d.fleet_incidents.find(i=>i.id === mj.incidentId);
          if(inc && inc.status === 'open'){
            inc.status = 'closed';
            inc.closedDate = CLOSE_DATE;
            if(!inc.progressLog) inc.progressLog = [];
            inc.progressLog.push({
              date: CLOSE_DATE,
              text: `✓ ปิด Incident · Job ${mj.no} เสร็จ · ใช้งานปกติ`,
              by: 'ระบบ'
            });
          }
        }
        
        // Final progress log
        mj.progressLog.push({
          date: CLOSE_DATE,
          text: `✓ ปิด Job · สำเร็จ — ใช้งานปกติ · ค่าใช้จ่ายรวม ฿${mj.cost.toLocaleString()}`,
          by: 'ระบบ'
        });
      }
    }
    d._app_hooks.mj024_withdraw_close_v1 = true;
    localStorage.setItem(LS_KEY,JSON.stringify(d));
  }
  
  // Hook: Simulate user creating MJ-025 (preventive · Aluminous1 · เปลี่ยนไดโว่ 12V)
  //        Asset: hull (ตัวเรือ · not engine/gearbox/propeller)
