  // Hook: Simulate user UI actions on MJ-025 (Aluminous1 · เปลี่ยน ไดโว่ 12V)
  //   Step 1: กด Start → status: pending → inprogress
  //   Step 2: + Withdraw ไดโว่ 12V (i63) · 1 ตัว · จาก คลัง Tub Lamu
  //   Step 3: Close · outcome=success · note="พร้อมวิ่ง"
  if(d._app_hooks && !d._app_hooks.mj025_start_withdraw_close_v1){
    if(d.fleet_maintenance && d.fleet_inventory){
      const mj = d.fleet_maintenance.find(m=>m.no === 'MJ-025');
      const i63 = d.fleet_inventory.find(x=>x.id === 'i63');
      
      if(mj && mj.status === 'pending' && i63){
        const ACTION_DATE = '2026-05-13';   // เริ่ม + เบิก + ปิด · all in same day
        const CLOSE_DATE = '2026-05-13';
        
        // ─── STEP 1: Start Job (mimics flMaintStart) ───
        mj.status = 'inprogress';
        const targetStatus = mj.boatStatus || 'fixing';  // 'available'
        const cascadeAssetFixing = (targetStatus === 'fixing');
        const b = d.boats?.find(x=>x.id === mj.boatId);
        
        // boat=available → ไม่ push log
        // asset log: hull type · no log file (hull doesn't have log field)
        
        if(!mj.progressLog) mj.progressLog = [];
        const statusLabel = targetStatus==='fixing'?'Fixing':targetStatus==='unavailable'?'Unavailable':'Available';
        mj.progressLog.push({
          date: ACTION_DATE,
          text: `▶ Start Job · ${b?b.name+' = '+statusLabel:''}`,
          by: 'ระบบ'
        });
        
        // ─── STEP 2: Withdraw ไดโว่ 12V × 1 ───
        const wdQty = 1;
        const wdLocation = 'คลัง Tub Lamu';
        
        if(i63.stocks){
          const stockEntry = i63.stocks.find(s=>s.location === wdLocation);
          if(stockEntry && stockEntry.qty >= wdQty){
            stockEntry.qty -= wdQty;
            const total = i63.stocks.reduce((s,x)=>s+(x.qty||0), 0);
            i63.qty = total;
            i63.totalQty = total;
            const sorted = [...i63.stocks].sort((a,b)=>(b.qty||0)-(a.qty||0));
            i63.primaryLocation = sorted[0]?.location || wdLocation;
            i63.location = i63.primaryLocation;
          }
        }
        if(!i63.history) i63.history = [];
        i63.history.push({
          date: ACTION_DATE,
          type: 'withdraw',
          qty: wdQty,
          location: wdLocation,
          note: `เบิกใช้งาน ${mj.no} · ${mj.title}`,
          by: 'ระบบ',
          jobId: mj.id
        });
        
        if(!mj.parts) mj.parts = [];
        mj.parts.push({
          invId: i63.id,
          name: i63.name,
          qty: wdQty,
          unit: i63.unit,
          cost: i63.cost,
          location: wdLocation
        });
        mj.cost = mj.parts.reduce((s,p)=>s+(p.qty*p.cost), 0);   // 1550
        
        mj.progressLog.push({
          date: ACTION_DATE,
          text: `📦 เบิก ${i63.name} ${wdQty} ${i63.unit} (฿${(wdQty*i63.cost).toLocaleString()})`,
          by: 'ระบบ'
        });
        
        // ─── STEP 3: Close · outcome=success · note=พร้อมวิ่ง ───
        mj.status = 'done';
        mj.endDate = CLOSE_DATE;
        mj.outcome = 'success';
        mj.closeNote = 'พร้อมวิ่ง';
        mj.awaitingInvoice = false;
        
        // Boat log: was available throughout → just push closing entry for history
        if(b){
          if(!b.log) b.log = [];
          const lastLog = b.log[b.log.length-1];
          // Don't add new log entry · boat was always available (no log was opened on Start)
          
          // Repair history
          if(!b.repairHistory) b.repairHistory = [];
          b.repairHistory.push({
            date: CLOSE_DATE,
            jobNo: mj.no,
            title: mj.title,
            detail: '',
            type: mj.type,
            location: '',
            cost: mj.cost,
            assets: (mj.assets||[]).map(a=>a.label),
            startDate: mj.startDate,
            endDate: CLOSE_DATE,
            outcome: 'success',
            closeNote: 'พร้อมวิ่ง'
          });
        }
        
        // Assets are 'hull' type · no engine/gearbox/propeller status to revert
        // (hull doesn't have its own log field on fleet_engines)
        
        // No incident to close (preventive job · no incidentId)
        
        // Final progress log
        mj.progressLog.push({
          date: CLOSE_DATE,
          text: `✓ ปิด Job · สำเร็จ — พร้อมวิ่ง · ค่าใช้จ่ายรวม ฿${mj.cost.toLocaleString()}`,
          by: 'ระบบ'
        });
      }
    }
    d._app_hooks.mj025_start_withdraw_close_v1 = true;
    localStorage.setItem(LS_KEY,JSON.stringify(d));
  }
  
  // Hook: Fix MJ-023 boat status — should have been 'available' since swap happened immediately
  //        User's correct workflow: เรือยังวิ่งได้ · งานซ่อมดำเนินต่อ · unassign+assign engine
  //        Original seed wrongly set boatStatus='fixing' which blocked Artemis incorrectly
  //  v2: also close any open boat.log fixing entries from MJ-023 + push proper available entry
  if(d._app_hooks && !d._app_hooks.mj023_artemis_status_fix_v2){
    if(d.fleet_maintenance && d.boats){
      const mj023 = d.fleet_maintenance.find(m=>m.no === 'MJ-023');
      if(mj023){
        const SWAP_DATE = mj023.startDate || '2026-05-01';
        const oldBoatStatus = mj023.boatStatus;
        
        // 1. Change MJ.boatStatus to available
        mj023.boatStatus = 'available';
        mj023.setFixing = false;
        
        // 2. Update progressLog · clarify Artemis stays available
        if(!mj023.progressLog) mj023.progressLog = [];
        mj023.progressLog = mj023.progressLog.map(p=>{
          if(p.text && p.text.includes('Artemis = Fixing')){
            return {...p, text:'▶ Start Job · Artemis = Available (เรือยังวิ่งได้ระหว่างซ่อม e5)'};
          }
          return p;
        });
        // Add a corrective progress entry
        const alreadyCorrected = mj023.progressLog.some(p=>p.text&&p.text.includes('Boat status: Fixing → Available'));
        if(!alreadyCorrected && oldBoatStatus === 'fixing'){
          mj023.progressLog.push({
            date: SWAP_DATE,
            text: '⚙️ เปลี่ยน Boat Status: 🟡 Fixing → 🟢 Available · "สลับเครื่องสำเร็จ · เรือพร้อมวิ่งระหว่างซ่อม e5"',
            by: 'ระบบ'
          });
        }
        
        // 3. Fix Artemis boat log
        const artemis = d.boats.find(b=>b.id === 'b2');
        if(artemis && artemis.log){
          // Close any open MJ-023 fixing entries on SWAP_DATE
          artemis.log.forEach(l => {
            if(!l.to && l.s === 'fixing' && l.note && (l.note.includes('MJ-023') || l.note.includes(mj023.id))){
              l.to = SWAP_DATE;
              l.note = l.note + ' (resolved: เรือกลับ available ทันทีหลัง swap)';
            }
          });
          // Push available entry from SWAP_DATE if no open available entry exists
          const hasOpenAvail = artemis.log.some(l => !l.to && l.s === 'available');
          if(!hasOpenAvail){
            artemis.log.push({
              id: 'sl_mj023_avail_'+Date.now(),
              s: 'available',
              from: SWAP_DATE, to: null,
              loc: '',
              note: 'MJ-023 · เรือกลับมาใช้งานได้หลังสลับเครื่อง · e5 ยังซ่อมต่อ',
              reason: ''
            });
          }
        }
      }
    }
    d._app_hooks.mj023_artemis_status_fix_v2 = true;
    localStorage.setItem(LS_KEY,JSON.stringify(d));
  }
  
  // Hook: Create Scheduled drydock jobs for Verona (MJ-026) + Romeo (MJ-027)
