    hidden.style.display = 'none';
    hidden.innerHTML = `
      <textarea id="maint-log-text-${mj.id}">${text}</textarea>
      <input id="maint-log-by-${mj.id}" value="${by}">
      <input type="date" id="maint-log-date-${mj.id}" value="${date}">
    `;
