  // Helper: Create labor memo by directly building memo data (no modal needed)
  // Mirrors flSaveMemo structure exactly so result matches user UI flow
  function _deferredCreateLaborMemo(jobNo, opts){
    const mj = FL_MAINT.find(x=>x.no === jobNo);
    if(!mj){ return false; }
    // Avoid duplicate
    const exists = FL_MEMOS.some(m=>m.maintId === mj.id && m.title === opts.subject);
    if(exists){ return true; }
    
    // Build items + calc totals (mirrors memoCalcTotal logic)
    const items = [{
      name: opts.itemName,
      qty: 1,
      unit: 'งาน',
      price: opts.amount,
      fromInventory: false,
      category: 'labor'
    }];
    const sub = items.reduce((s,it)=>s + ((it.qty||1) * (it.price||0)), 0);
    const discTotal = 0;
    const afterDisc = sub;
    const vatEnabled = false;  // No VAT
    const vatRate = 0;
    const vat = 0;
    const total = afterDisc;
    
    // §dupNo · เดิมใช้ FL_MEMOS.length + 1 · พอลิสต์มีรู เลขใหม่จะไปชนใบที่มีอยู่แล้ว
    //   (จุดอื่นในระบบใช้เลขสูงสุด + 1 อยู่แล้ว · เหลือจุดนี้จุดเดียวที่หลุด)
    let _moMax = FL_MEMOS.reduce(function(mx,x){
      var v = parseInt(String(x.no||'').replace(/\D/g,''),10); return (v>mx)?v:mx; }, 0);
    // §noFree · ยืนยันว่าเลขที่จะออกยังว่างจริง ไม่ใช่แค่มากกว่าเลขสูงสุด
    let no;
    do { _moMax++; no = 'MO-' + String(_moMax).padStart(3,'0'); }
    while(FL_MEMOS.some(function(x){ return x.no===no; }));
    const memo = {
      id: LA_UID('m') + '_' + jobNo,
      no,
      title: opts.subject,
      to: 'กรรมการผู้จัดการ',
      from: opts.from,
      proposer: opts.proposer,
      supplier: opts.supplier,
      note: '',
      boatId: mj.boatId,
      maintId: mj.id,
      scope: 'vessel',
      generalCategory: '',
      items,
      memoType: 'labor',
      discountPct: 0,
      discountAmt: 0,
      vatEnabled,
      vatRate,
      subtotal: sub,
      discount: discTotal,
      afterDiscount: afterDisc,
      vat,
      amount: total,
      status: 'pending_approval',
      currentStep: 1,
      createdDate: opts.date
    };
    FL_MEMOS.push(memo);
    
    // Push to maint progress log (mirrors flSaveMemo behavior)
    if(!mj.progressLog) mj.progressLog = [];
    mj.progressLog.push({
      date: opts.date,
      text: `📋 สร้าง Memo ${no} · ฿${total.toLocaleString()}`,
      by: 'ระบบ'
    });
    
    return true;
  }
  
