  epirb:       {label:'EPIRB / SART',       th:'สัญญาณฉุกเฉิน',     color:'#7B2D63', regulatory:true,  pmMonths:1, pmYears:1/12},
  flare:       {label:'Flare',              th:'พลุสัญญาณ',          color:'#C75A33', regulatory:true,  pmMonths:1, pmYears:1/12},
  vhf:         {label:'VHF radio',          th:'วิทยุ',              color:'#0E5E73', regulatory:true,  pmMonths:1, pmYears:1/12},
  first_aid:   {label:'First aid kit',      th:'ปฐมพยาบาล',          color:'#0F6E56', regulatory:false, pmMonths:1, pmYears:1/12},
  anchor:      {label:'Anchor + chain',     th:'สมอ + โซ่',          color:'#5F5E5A', regulatory:true,  pmMonths:1, pmYears:1/12},
