// Generate seed safety set for all boats — runs once if FL_SAFETY is empty
function _generateSafetySeed(){
  if(FL_SAFETY.length > 0) return; // don't regenerate
  const addYears  = (date, yrs)  => { const d = new Date(date); d.setFullYear(d.getFullYear()+yrs); return d.toISOString().slice(0,10); };
  const addMonths = (date, mos)  => { const d = new Date(date); d.setMonth(d.getMonth()+mos); return d.toISOString().slice(0,10); };
  const installBase = '2024-06-01';
  const inspectBase = '2025-12-01';
  // Compute nextPM from inspectBase using the category's monthly cadence
  const nextPMFor = (catKey) => {
    const meta = FL_SAFETY_CATEGORIES[catKey];
    const months = meta?.pmMonths || Math.round((meta?.pmYears||1)*12) || 1;
    return addMonths(inspectBase, months);
  };
  let sid = 1;
  const _nextId = () => 'sf' + String(sid++).padStart(4,'0');

  (BOATS||[]).filter(b=>!b.retired && b.ownership!=='charter').forEach(b => {
    const cap = b.cap || b.licensePax || 30;
    // Bilge pump (1)
    FL_SAFETY.push({
      id:_nextId(), boatId:b.id, category:'bilge_pump',
      name:'Bilge pump · aft engine room', brand:'Rule', model:'1500 GPH',
      serial:`BP-${b.id}-001`, qty:1,
      installDate:installBase, expiryDate:null,
      nextPM:nextPMFor('bilge_pump'), lastInspect:inspectBase,
      status:'active', location:'Engine room aft',
      note:'12V · auto float + manual switch',
      log:[{date:installBase,type:'install',desc:'Initial installation'}]
    });
    // Life jackets (qty = cap, default Adult)
    FL_SAFETY.push({
      id:_nextId(), boatId:b.id, category:'life_jacket',
      name:'Life jacket · adult', brand:'STANY', model:'Foam DBL/WT',
      serial:`LJ-${b.id}-SET01`, qty:cap,
      installDate:installBase, expiryDate:null,
      nextPM:nextPMFor('life_jacket'), lastInspect:inspectBase,
      status:'active', location:'Passenger bench storage',
      note:`Standard adult sized · qty matches PAX cap (${cap})`,
      log:[{date:installBase,type:'install',desc:`Installed ${cap} units`}]
    });
    // Fire extinguishers (2 · DCP)
    FL_SAFETY.push({
      id:_nextId(), boatId:b.id, category:'fire_ext',
      name:'Fire extinguisher · DCP 5lb', brand:'Marigold', model:'DCP-5',
      serial:`FE-${b.id}-001`, qty:2,
      installDate:installBase, expiryDate:addYears(installBase, 5),  // physical refill 5 yrs
      nextPM:nextPMFor('fire_ext'), lastInspect:inspectBase,
      status:'active', location:'Helm station + engine room',
      note:'Monthly pressure check · refill at 5 yrs',
      log:[{date:installBase,type:'install',desc:'2 units installed'}]
    });
    // EPIRB (1)
    FL_SAFETY.push({
      id:_nextId(), boatId:b.id, category:'epirb',
      name:'EPIRB · 406 MHz', brand:'McMurdo', model:'SmartFind G8',
      serial:`EP-${b.id}-001`, qty:1,
      installDate:installBase, expiryDate:addYears(installBase, 5),  // battery
      nextPM:nextPMFor('epirb'), lastInspect:inspectBase,
      status:'active', location:'Bridge bulkhead',
      note:'Battery 5 yrs · HRU also expires · registered with MMSI',
      log:[{date:installBase,type:'install',desc:'Battery installed + registered'}]
    });
    // VHF radio (1)
    FL_SAFETY.push({
      id:_nextId(), boatId:b.id, category:'vhf',
      name:'VHF radio · fixed mount', brand:'Icom', model:'IC-M330',
      serial:`VHF-${b.id}-001`, qty:1,
      installDate:installBase, expiryDate:null,
      nextPM:nextPMFor('vhf'), lastInspect:inspectBase,
      status:'active', location:'Helm station',
      note:'25W · DSC · MMSI assigned',
      log:[{date:installBase,type:'install',desc:'Installed and tested'}]
    });
    // First aid kit (1)
    FL_SAFETY.push({
      id:_nextId(), boatId:b.id, category:'first_aid',
      name:'First aid kit · marine grade', brand:'-', model:'Marine Pro',
      serial:`FA-${b.id}-001`, qty:1,
      installDate:installBase, expiryDate:addYears(installBase, 2),  // some items physically expire
      nextPM:nextPMFor('first_aid'), lastInspect:inspectBase,
      status:'active', location:'Bridge cabinet',
      note:'Monthly check · refill at meds expiry',
      log:[{date:installBase,type:'install',desc:'Initial kit stocked'}]
    });
  });
}

// ─────────── Multi-Warehouse Helper Functions ───────────
const WAREHOUSE_LOCATIONS = ['คลัง Tub Lamu', 'คลัง Visit Panwa', 'คลัง Ranong'];

// Sync legacy fields (qty, location) from stocks[]
function invSyncLegacy(item){
  if(!item) return;
  if(!item.stocks || !Array.isArray(item.stocks)){
    item.stocks = [{location: item.location||'คลัง Tub Lamu', qty: item.qty||0, minQty: item.minQty||0}];
  }
  // computed total
  item.totalQty = item.stocks.reduce((s,x)=>s+(x.qty||0), 0);
  item.qty = item.totalQty;
  // primary = location with most stock
  const sorted = [...item.stocks].sort((a,b)=>(b.qty||0)-(a.qty||0));
  item.primaryLocation = sorted[0]?.location || 'คลัง Tub Lamu';
  item.location = item.primaryLocation;
}

// Get qty at a specific location
function invQtyAt(item, location){
  if(!item || !item.stocks) return 0;
  const s = item.stocks.find(x=>x.location===location);
  return s?.qty || 0;
}

// Add qty to a location (creates entry if not exists)
function invAddAt(item, location, qty){
  if(!item) return;
  if(!item.stocks) item.stocks = [];
  let s = item.stocks.find(x=>x.location===location);
  if(!s){
    s = {location, qty:0, minQty:0};
    item.stocks.push(s);
  }
  s.qty = (s.qty||0) + qty;
  invSyncLegacy(item);
}

// Remove qty from a location (returns false if insufficient)
function invRemoveAt(item, location, qty){
  if(!item || !item.stocks) return false;
  const s = item.stocks.find(x=>x.location===location);
  if(!s || (s.qty||0) < qty) return false;
  s.qty -= qty;
  invSyncLegacy(item);
  return true;
}

// Transfer between warehouses (returns false if insufficient)
function invTransfer(item, fromLoc, toLoc, qty, date, note){
  if(!item) return false;
  if(!invRemoveAt(item, fromLoc, qty)) return false;
  invAddAt(item, toLoc, qty);
  if(!item.history) item.history = [];
  item.history.push({
    date: date || TODAY_STR,
    type: 'transfer-out',
    qty,
    location: fromLoc,
    note: `ย้ายไป ${toLoc}` + (note?` · ${note}`:''),
    by: ''
  });
  item.history.push({
    date: date || TODAY_STR,
    type: 'transfer-in',
    qty,
    location: toLoc,
    note: `ย้ายจาก ${fromLoc}` + (note?` · ${note}`:''),
    by: ''
  });
  return true;
}


// helpers
function flGetEng(id){return FL_ENGINES.find(e=>e.id===id);}
function flGetGb(id){return FL_GEARBOXES.find(g=>g.id===id);}
function flEngHours(id){
  const e=flGetEng(id);
  // Engine hours = ชั่วโมงสะสมเดิม (baseHours) + ชั่วโมงที่วิ่งจริง = (มิเตอร์ Daily-Log ล่าสุด − มิเตอร์แรกที่ log).
  //   มิเตอร์อยู่บนตัวเครื่องและต่อเนื่อง (ตามเครื่องไปแม้สลับลำ) → ไม่ต้อง scope ตามวันเกาะเรือ. ข้ามค่า 0/ติดลบ (placeholder).
  let max=null,maxDate='', first=null,firstDate='';
  Object.entries(FL_DAILY).forEach(([ds,dayBoats])=>{
    Object.values(dayBoats).forEach(bday=>{
      Object.values(bday.trips||{}).forEach(trip=>{
        const v=trip.engines?.[id]; if(v==null || +v<=0) return;
        if(ds>maxDate){maxDate=ds;max=v;}
        if(first===null||ds<firstDate){firstDate=ds;first=v;}
      });
    });
  });
  if(max!=null && first!=null) return +((e?(e.baseHours||0):0) + (max-first)).toFixed(1);
  return e?(e.baseHours||0):0;   // ยังไม่มี log → ชั่วโมงสะสมเดิม
}
// Service state for an engine · countdown is relative to the LAST recorded service (oil change), not a pure modulo.
//   baseline = e.lastServiceHours (set when a service is logged) · else e.baseHours · else 0
function flEngServiceState(e){
  if(!e) return null;
  const curH=(typeof flEngHours==='function')?(flEngHours(e.id)||0):(e.baseHours||0);
  const interval=+e.serviceInterval||0;
  const base=(e.lastServiceHours!=null)?(+e.lastServiceHours||0):(+e.baseHours||0);
  if(!interval) return {curH, interval:0, base, since:Math.max(0,curH-base), next:null, left:null, pct:0, overdue:false};
  const since=Math.max(0, curH-base);
  const next=base+interval;
  const left=+(next-curH).toFixed(1);
  const pct=Math.min(100, Math.max(0, since/interval*100));
  return {curH, interval, base, since, next, left, pct, overdue:left<0};
}
// Log an engine service (oil change) → set the service baseline to the engine hours at service time.
function flEngMarkService(engId){
  const e=flGetEng(engId); if(!e){ return; }
  const curH=(typeof flEngHours==='function')?(flEngHours(engId)||0):(e.baseHours||0);
  const ans=prompt('Log engine service (oil change).\nEngine hours at service time:', String(curH));
  if(ans===null) return;
  const h=parseFloat(ans);
  if(isNaN(h)||h<0){ alert('Please enter a valid hour reading.'); return; }
  e.lastServiceHours=h;
  e.lastServiceDate=(typeof TODAY_STR!=='undefined')?TODAY_STR:'';
  e.log=e.log||[];
  e.log.push({date:e.lastServiceDate, type:'service', desc:'Service / oil change · baseline reset at '+h+'h', hours:h});
  if(typeof flSave==='function') flSave();
  if(typeof flRenderEngDetailPink==='function') flRenderEngDetailPink();
  if(typeof flRenderEngList==='function') flRenderEngList();
}
// ── Gearbox service cycle (gear-oil change) — mirrors the engine cycle, counted on the ATTACHED ENGINE's hours ──
// Gearbox running hours = hours accrued from the engine it's mounted on. lifetime = prev-engine usage (remove logs) + current-engine hours since install.
const GB_DEF_SVC_INTERVAL=200; // default gear-oil interval (h) when a gearbox has no serviceInterval set · editable per gearbox
function flGbLifetimeHours(g){
  if(!g) return 0;
  const eng=g.engineId?flGetEng(g.engineId):null;
  const curH=eng?Math.max(0,(((typeof flEngHours==='function')?flEngHours(eng.id):(eng.baseHours||0))||0)-(g.baseHours||0)):0;
  const prevUsed=(g.log||[]).filter(l=>l.type==='remove').reduce((s,l)=>s+(l.usedHours||0),0);
  return +(prevUsed+curH).toFixed(1);
}
// Service state: countdown relative to the LAST gear-oil change (g.lastServiceHours, in lifetime hours). Resets when a service is logged.
function flGbServiceState(g){
  if(!g) return null;
  const life=flGbLifetimeHours(g);
  const interval=+g.serviceInterval||GB_DEF_SVC_INTERVAL;
  const base=(g.lastServiceHours!=null)?(+g.lastServiceHours||0):life;   // never serviced → assume "now" (don't spam overdue) until a real service is logged
  const since=Math.max(0, life-base);
  const next=base+interval;
  const left=+(next-life).toFixed(1);
  const pct=Math.min(100, Math.max(0, since/interval*100));
  return {life, interval, base, since, next, left, pct, overdue:left<0, defaulted:!g.serviceInterval, attached:!!(g.engineId)};
}
// Log a gearbox oil service → set the baseline to the gearbox's current lifetime hours.
function flGbMarkService(gbId){
  const g=flGetGb(gbId); if(!g){ return; }
  const life=flGbLifetimeHours(g);
  const ans=prompt('Log gearbox oil service.\nGearbox lifetime hours at service time:', String(life));
  if(ans===null) return;
  const h=parseFloat(ans);
  if(isNaN(h)||h<0){ alert('Please enter a valid hour reading.'); return; }
  g.lastServiceHours=h;
  g.lastServiceDate=(typeof TODAY_STR!=='undefined')?TODAY_STR:'';
  g.log=g.log||[];
  g.log.push({date:g.lastServiceDate, type:'service', desc:'Gear oil service · baseline reset at '+h+'h', hours:h});
  if(typeof flSave==='function') flSave();
  if(typeof flRenderGbDetailPink==='function') flRenderGbDetailPink();
  if(typeof flRenderGbList==='function') flRenderGbList();
}
function flGbSetInterval(gbId, val){
  const g=flGetGb(gbId); if(!g) return;
  const v=parseInt(val,10);
  if(isNaN(v)||v<=0){ alert('Enter a positive interval (hours).'); if(typeof flRenderGbDetailPink==='function') flRenderGbDetailPink(); return; }
  g.serviceInterval=v;
  if(typeof flSave==='function') flSave();
  if(typeof flRenderGbDetailPink==='function') flRenderGbDetailPink();
}
// On closing a Maintenance Job that looks like an engine service (oil change) → offer to reset the service-hour baseline
// for each engine on the job (asks the hour reading per engine · default = current). Does NOT flSave (caller saves).
// Cost share for an asset-detail page: split a job's total cost evenly across its assets of the SAME kind
// (so a 4-engine oil change shows ~1/4 per engine instead of the full cost on every engine). Job/boat/project totals are unaffected.
function flMaintCostShare(m, kind){
  const full=(typeof flMaintCalcCost==='function')?flMaintCalcCost(m.id):(m.cost||0);
  const key=kind==='gb'?'gbId':kind==='prop'?'propId':'engId';
  const n=(m.assets||[]).filter(a=>a[key]).length||1;
  return full/n;
}
function flMaintServiceReset(m, outcome){
  if(!m || !Array.isArray(m.assets)) return false;
  if(!['success','limited'].includes(outcome)) return false;   // only a completed service resets hours
  // fire for a service/oil-change (keyword in title/detail, or a routine "scheduled" job) — engine oil AND/OR gear oil
  const txt=(m.title||'')+' '+(m.detail||'');
  const looksService = m.type==='scheduled' || /น้ำมัน|ถ่าย|เซอร์วิส|service|\boil\b|svc|เกียร์|gear/i.test(txt);
  if(!looksService) return false;
  const engs=[...new Set(m.assets.filter(a=>a.engId).map(a=>a.engId))].map(id=>flGetEng(id)).filter(Boolean);
  const gbs =[...new Set(m.assets.filter(a=>a.gbId ).map(a=>a.gbId ))].map(id=>flGetGb(id)).filter(Boolean);
  if(!engs.length && !gbs.length) return false;
  const curOf=e=>(typeof flEngHours==='function')?(flEngHours(e.id)||0):(e.baseHours||0);
  const lines=[]
    .concat(engs.map(e=>'  - [ENG] '+e.serial+(e.pos?(' ('+e.pos+')'):'')+' = '+curOf(e).toFixed(1)+'h'))
    .concat(gbs.map(g=>'  - [GEAR] '+g.serial+' = '+flGbLifetimeHours(g).toFixed(1)+'h'))
    .join('\n');
  if(!confirm('Service (oil change) - reset the service-hour baseline?\nThe next cycle starts from current hours:\n'+lines+'\n\n(OK = reset all · Cancel = skip)')) return false;
  let n=0;
  engs.forEach(e=>{
    const hh=curOf(e);
    e.lastServiceHours=hh; e.lastServiceDate=TODAY_STR;
    e.log=e.log||[]; e.log.push({date:TODAY_STR, type:'service', desc:'Service / oil change · '+(m.no||m.id)+' · baseline reset at '+hh.toFixed(1)+'h', hours:hh});
    n++;
  });
  gbs.forEach(g=>{
    const hh=flGbLifetimeHours(g);
    g.lastServiceHours=hh; g.lastServiceDate=TODAY_STR;
    g.log=g.log||[]; g.log.push({date:TODAY_STR, type:'service', desc:'Gear oil service · '+(m.no||m.id)+' · baseline reset at '+hh.toFixed(1)+'h', hours:hh});
    n++;
  });
  return n>0;
}
function flMaintServiceResetManual(jobId){
  const m=(typeof FL_MAINT!=='undefined'?FL_MAINT:[]).find(x=>x.id===jobId); if(!m) return;
  const did=flMaintServiceReset(m,'success');
  if(did){ flSave(); if(typeof flRenderEngList==='function')flRenderEngList(); if(typeof flRenderMaintDetail==='function')flRenderMaintDetail(jobId); }
  else alert('Not reset (not a service job, no engines, or cancelled).');
}
function flStatusPill(s){
  const m={available:'pill-green',fixing:'pill-amber',unavailable:'pill-red',ready:'pill-green',broken:'pill-red',spare:'pill-gray',active:'pill-green'};
  const l={available:'Available',fixing:'Fixing',unavailable:'Unavailable',ready:'Ready',broken:'Broken',spare:'Spare',active:'Active'};
  return`<span class="pill ${m[s]||'pill-gray'}">${l[s]||s}</span>`;
}
function flFmtShort(s){if(!s)return'—';const d=new Date(s);return`${d.getDate()} ${['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][d.getMonth()]}`;}

