  const _pierKey = b => { const p=(typeof getBoatCurrentPier==='function'?getBoatCurrentPier(b):b.pier); return _pierMeta[p]?p:'other'; };
  const _pierGroups = {}; _boatWork.forEach(w=>{ if(w.load===0) return; const k=_pierKey(w.b); (_pierGroups[k]=_pierGroups[k]||[]).push(w); });
  const _clearBoats = _boatWork.filter(w=>w.load===0);
  const _pierOrder = Object.keys(_pierGroups).sort((a,b)=> _pierGroups[b].reduce((s,w)=>s+w.load,0) - _pierGroups[a].reduce((s,w)=>s+w.load,0));
