  const _port = (side,col,fill) => `<span style="position:absolute;${side}:-5px;top:50%;transform:translateY(-50%);width:9px;height:9px;border-radius:50%;background:${fill||'#fff'};border:2px solid ${col};z-index:2${fill?(';box-shadow:0 0 0 1.5px '+col):''}"></span>`;
  const _n8nUser = (typeof laSbUser==='function'?laSbUser():((typeof ME!=='undefined'&&ME&&(ME.username||ME.email))||'anon'));
  const _n8nLSK = 'fl_n8n_pos_'+_n8nUser;
  let _savedPos={}; try{ _savedPos=JSON.parse(localStorage.getItem(_n8nLSK)||'{}')||{}; }catch(_e){ _savedPos={}; }
  // deterministic layered layout · pier · boat · [incident + routine-maint] · [incident-linked maint] → each node absolute so it can be dragged
  const PIERX=14, BOATX=286, INCX=560, MJX=850, PIERH=48, BOATH=62, JOBH=54, JOBGAP=12, BOATGAP=26, PIERGAP=42, JOBSTEP=JOBH+JOBGAP;
