  const _linkedMaint = i => { const ids=[].concat(i.maintId?[i.maintId]:[], Array.isArray(i.relatedMaintIds)?i.relatedMaintIds:[]); const seen={},out=[]; ids.forEach(id=>{ if(_mById[id]&&!seen[id]){seen[id]=1;out.push(_mById[id]);} }); return out; };
  const _boatLink={};
  _boatWork.forEach(w=>{ if(w.load===0) return; const linkMap={}, linkedIds={};
    (w.incs||[]).forEach((i,ix)=>{ const lm=_linkedMaint(i).filter(m=>m.boatId===w.b.id); linkMap[ix]=lm; lm.forEach(m=>linkedIds[m.id]=1); });
    _boatLink[w.b.id]={linkMap, standalone:w.jobs.filter(m=>!linkedIds[m.id])};
  });
  // §n8n memo tier · งานซ่อม 1 งาน → memo(MO) หลายใบ (link ผ่าน memo.maintId) · การ์ด memo วางต่อขวาของการ์ดงาน
  const MEMOH=42, MEMOGAP=10, MEMOSTEP=MEMOH+MEMOGAP, JOB_TO_MEMO=292;
  // §dedupe memo ซ้ำ · ข้อมูลมี record ซ้ำ (no เดียวกัน maintId เดียวกัน ต่างแค่ status เช่น approved+paid) → โชว์ 1 ใบต่อ MO เก็บสถานะล่าสุดสุด
  const _memoRank={paid:4,received:3,approved:2,pending_approval:1};
  const _memoTmp={};
  (typeof FL_MEMOS!=='undefined'&&Array.isArray(FL_MEMOS)?FL_MEMOS:[]).forEach(mo=>{ if(mo&&mo.maintId){ const g=(_memoTmp[mo.maintId]=_memoTmp[mo.maintId]||{}); const k=mo.no||mo.id; const cur=g[k]; if(!cur || (_memoRank[mo.status]||0) > (_memoRank[cur.status]||0)) g[k]=mo; } });
  const _memosByMaint={}; Object.keys(_memoTmp).forEach(mid=>{ _memosByMaint[mid]=Object.values(_memoTmp[mid]); });
  const _pos={}; let _cy=16;
