function flProjIcon(name, size, color, strokeWidth){
  const path = PROJ_ICONS[name] || PROJ_ICONS.target;
  const s = size||16;
  const c = color||'currentColor';
  const sw = strokeWidth||2;
  return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="${c}" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round">${path}</svg>`;
}

// ── Cleanup v2 · one-shot · unlink non-scheduled MJs that were mis-linked by v1 ──
function flProjCleanupV2(d){
  d = d || JSON.parse(localStorage.getItem(LS_KEY)||'{}');
  if(d._fl_proj_cleanup_v2) return 0;
  let cleaned = 0;
  (FL_MAINT||[]).forEach(m=>{
    if(m.parentProjectId && m.type!=='scheduled'){
      const proj = (FL_PROJECTS||[]).find(p=>p.id===m.parentProjectId);
      if(proj){
        if(!proj.log) proj.log=[];
        proj.log.push({date:TODAY_STR, text:`- Auto-unlinked MJ ${m.no||m.id} (type=${m.type}, not scheduled)`, by:'cleanup-v2'});
      }
      m.parentProjectId = null;
      if(!m.progressLog) m.progressLog=[];
      m.progressLog.push({date:TODAY_STR, text:`Auto-unlinked from project (type=${m.type} not scheduled)`, by:'cleanup-v2'});
      cleaned++;
    }
  });
  d._fl_proj_cleanup_v2 = true;
  // Mirror to globals + persist immediately so flSave() right after sees the changes
  d.fleet_maintenance = FL_MAINT;
  d.fleet_projects = FL_PROJECTS;
  localStorage.setItem(LS_KEY, JSON.stringify(d));
  console.log(`[Projects cleanup v2] unlinked ${cleaned} non-scheduled MJ(s)`);
  return cleaned;
}

// ── Migration · one-shot · scan boats for dry_dock / long-unavailable → create Projects ──
// ── Auto-create Project for unlinked Scheduled MJ · 1 MJ = 1 Project minimum ──
// Runs after resync · catches MJs whose boat log isn't dry_dock (so migration skipped them)
function flProjAutoCreateForScheduledMJs(){
  let created = 0;
  const today = new Date(TODAY_STR);
  (FL_MAINT||[]).forEach(m=>{
    if(m.type!=='scheduled') return;
    if(m.parentProjectId) return;
    if(!m.startDate) return;
    if(!m.boatId) return;
    // Skip if a non-completed project already exists for this boat with overlapping dates
    const ms = new Date(m.startDate);
    const me = m.endDate ? new Date(m.endDate) : today;
    const overlap = (FL_PROJECTS||[]).find(p=>{
      if(p.boatId!==m.boatId) return false;
      if(p.status==='completed') return false;
      const ps = new Date(p.planFrom);
      const pe = new Date(p.planTo||TODAY_STR);
      return ms<=pe && me>=ps;
    });
    if(overlap){
      // Link to it instead of creating new
      m.parentProjectId = overlap.id;
      if(!overlap.log) overlap.log=[];
      overlap.log.push({date:TODAY_STR, text:`+ Auto-linked MJ ${m.no} (auto-create resync)`, by:'auto-create'});
      if(!m.progressLog) m.progressLog=[];
      m.progressLog.push({date:TODAY_STR, text:`Auto-linked to project ${overlap.no}`, by:'auto-create'});
      return;
    }
    // Create new Project from MJ
    const boat = BOATS.find(b=>b.id===m.boatId);
    const boatName = boat?boat.name:'(unknown boat)';
    const yr  = m.startDate.slice(0,4);
    const seq = (FL_PROJECTS.length+1).toString().padStart(3,'0');
    const pid = `proj_${yr}_${m.boatId}_${seq}_${Math.random().toString(36).slice(2,6)}`;
    const planTo = m.endDate || flProjGuessEnd(m.startDate);
    const status = m.status==='done' ? 'completed' : (m.status==='inprogress' ? 'inprogress' : 'planned');
    const proj = {
      id: pid,
      no: `PRJ-${seq}`,
      name: `Scheduled · ${boatName} · ${(m.title||'Service').slice(0,40)}`,
      boatId: m.boatId,
      type: 'scheduled',
      vendor: m.location||'',
      planFrom: m.startDate,
      planTo,
      originalPlanTo: planTo, // BASELINE
      actualFrom: m.status!=='pending' ? m.startDate : null,
      actualTo: m.endDate||null,
      status,
      plannedBudget: 0,
      notes: m.detail||'',
      log: [
        {date:m.startDate, text:`+ Auto-created from scheduled MJ ${m.no}`, by:'auto-create'}
      ],
      createdAt: TODAY_STR,
      createdBy: 'auto-create'
    };
    FL_PROJECTS.push(proj);
    m.parentProjectId = pid;
    if(!m.progressLog) m.progressLog=[];
    m.progressLog.push({date:TODAY_STR, text:`Auto-linked to new project ${proj.no}`, by:'auto-create'});
    created++;
  });
  if(created){
    flSave();
    console.log(`[Projects auto-create] created ${created} project(s) from scheduled MJs`);
  }
  return created;
}

// ── Resync · always runs · links any unlinked scheduled MJ to a matching project ──
// Runs every time you open Projects page · safe (idempotent) · ignores migration flag
function flProjResyncMJLinks(){
  let linked = 0;
  const today = new Date(TODAY_STR);
  (FL_MAINT||[]).forEach(m=>{
    if(m.type!=='scheduled') return;          // scheduled only
    if(m.parentProjectId) return;              // already linked
    if(!m.startDate) return;
    const ms = new Date(m.startDate);
    const me = m.endDate ? new Date(m.endDate) : today;
    // Find project on same boat with overlapping date range
    const proj = (FL_PROJECTS||[]).find(p=>{
      if(p.boatId!==m.boatId) return false;
      if(p.status==='completed') return false;  // don't re-attach to closed
      const ps = new Date(p.planFrom);
      const pe = new Date(p.planTo||TODAY_STR);
      return ms<=pe && me>=ps;
    });
    if(proj){
      m.parentProjectId = proj.id;
      if(!proj.log) proj.log=[];
      proj.log.push({date:TODAY_STR, text:`+ Auto-linked MJ ${m.no} (resync)`, by:'resync'});
      if(!m.progressLog) m.progressLog=[];
      m.progressLog.push({date:TODAY_STR, text:`Auto-linked to project ${proj.no} (resync)`, by:'resync'});
      linked++;
    }
  });
  if(linked){
    flSave();
    console.log(`[Projects resync] linked ${linked} scheduled MJ(s) to projects`);
  }
  return linked;
}

// ── Cleanup v4 · one-shot · backfill originalPlanTo (baseline) for existing projects ──
function flProjCleanupV4(d){
  d = d || JSON.parse(localStorage.getItem(LS_KEY)||'{}');
  if(d._fl_proj_cleanup_v4_baseline) return 0;
  let set = 0;
  (FL_PROJECTS||[]).forEach(p=>{
    if(p.originalPlanTo !== undefined) return; // already has baseline
    p.originalPlanTo = p.planTo || null; // snapshot current planTo as baseline
    set++;
  });
  d._fl_proj_cleanup_v4_baseline = true;
  d.fleet_projects = FL_PROJECTS;
  localStorage.setItem(LS_KEY, JSON.stringify(d));
  if(set) console.log(`[Projects cleanup v4] set originalPlanTo (baseline) for ${set} project(s)`);
  return set;
}

// ── Cleanup v3 · one-shot · clear default +30d planTo from auto-created projects ──
function flProjCleanupV3(d){
  d = d || JSON.parse(localStorage.getItem(LS_KEY)||'{}');
  if(d._fl_proj_cleanup_v3_open) return 0;
  let cleared = 0;
  (FL_PROJECTS||[]).forEach(p=>{
    if(!p.planFrom || !p.planTo) return;
    // Skip if user has edited (deliberate date set)
    const wasEdited = (p.log||[]).some(l=>l.text && (l.text.includes('Project edited')||l.text.indexOf('Edit')===0));
    if(wasEdited) return;
    // Only clean projects that were auto-generated
    const firstLog = (p.log||[])[0];
    if(!firstLog) return;
    const isAuto = firstLog.by==='migration' || firstLog.by==='auto-create' || firstLog.by==='resync';
    if(!isAuto) return;
    // Check if planTo - planFrom is exactly 30 days (the old default)
    const from = new Date(p.planFrom);
    const to   = new Date(p.planTo);
    const diffDays = Math.round((to-from)/86400000);
    if(diffDays!==30) return;
    // Clear it
    p.planTo = null;
    if(!p.log) p.log=[];
    p.log.push({date:TODAY_STR, text:`Auto-cleanup: end date set to Open (was +30d default)`, by:'cleanup-v3'});
    cleared++;
  });
  d._fl_proj_cleanup_v3_open = true;
  d.fleet_projects = FL_PROJECTS;
  localStorage.setItem(LS_KEY, JSON.stringify(d));
  if(cleared) console.log(`[Projects cleanup v3] cleared default +30d end date from ${cleared} project(s)`);
  return cleared;
}

function flProjMigrate(force){
  const d = JSON.parse(localStorage.getItem(LS_KEY)||'{}');
  // Cleanup v2 — unlinks non-scheduled MJs (one-shot per browser)
  flProjCleanupV2(d);
  // Cleanup v3 — clear default +30d planTo from auto-created projects (one-shot)
  flProjCleanupV3(d);
  // Cleanup v4 — backfill originalPlanTo baseline (one-shot)
  flProjCleanupV4(d);
  // Resync — links unlinked scheduled MJs to EXISTING projects (overlap on same boat)
  flProjResyncMJLinks();
  // Auto-create — for any STILL-unlinked scheduled MJ, create a fresh Project from MJ data
  // (covers MJs whose boat log isn't dry_dock, so step 1 migration didn't create a project)
  flProjAutoCreateForScheduledMJs();
  if(!force && d._fl_proj_migrated_v1) return {created:0, linked:0, skipped:'already migrated · resync + auto-create + cleanup ran'};
  if(!Array.isArray(FL_PROJECTS)) FL_PROJECTS=[];
  let created=0, linked=0;
  const today = new Date(TODAY_STR);
  (BOATS||[]).forEach(b=>{
    const log = b.log||[];
    if(!log.length) return;
    // Pick log entries that represent a dry-dock / major project state
    log.forEach(entry=>{
      const isDryDock = entry.reason==='dry_dock';
      const startDate = entry.from || entry.start || null;
      const endDate   = entry.to   || entry.end   || null;
      if(!startDate) return;
      // Long unavailable >= 14 days counts as project too
      const isLongUnavailable = entry.s==='unavailable' && (function(){
        const a = new Date(startDate);
        const b2 = endDate ? new Date(endDate) : today;
        return (b2-a)/86400000 >= 14;
      })();
      if(!isDryDock && !isLongUnavailable) return;
      // Skip if already linked (entry has projectId)
      if(entry.projectId) return;
      // Build project
      const yr  = startDate.slice(0,4);
      const seq = (FL_PROJECTS.length+1).toString().padStart(3,'0');
      const pid = `proj_${yr}_${b.id}_${seq}_${Math.random().toString(36).slice(2,6)}`;
      const status = endDate ? 'completed' : (new Date(startDate)<=today ? 'inprogress' : 'planned');
      const name = isDryDock
        ? `Annual Drydock · ${b.name}`
        : `Major Service · ${b.name}`;
      const _migPt = endDate || flProjGuessEnd(startDate);
      const proj = {
        id: pid,
        no: `PRJ-${seq}`,
        name,
        boatId: b.id,
        type: isDryDock ? 'drydock' : 'overhaul',
        vendor: entry.loc || '',
        planFrom: startDate,
        planTo: _migPt,
        originalPlanTo: _migPt, // BASELINE
        actualFrom: startDate,
        actualTo: endDate,
        status,
        plannedBudget: 0,
        notes: entry.note || '',
        log: [
          {date: startDate, text:`+ Auto-created from boat log entry (${entry.reason||entry.s})`, by:'migration'}
        ],
        createdAt: TODAY_STR,
        createdBy: 'migration'
      };
      FL_PROJECTS.push(proj);
      // Tag the boat log entry so we never re-migrate it
      entry.projectId = pid;
      created++;
      // Link existing scheduled MJs whose date range overlaps this project (same boat)
      // Only `scheduled` type — corrective/preventive are independent jobs
      (FL_MAINT||[]).forEach(m=>{
        if(m.boatId!==b.id) return;
        if(m.type!=='scheduled') return;
        if(m.parentProjectId) return;
        if(!m.startDate) return;
        const ms = new Date(m.startDate);
        const me = m.endDate ? new Date(m.endDate) : today;
        const ps = new Date(proj.planFrom);
        const pe = new Date(proj.planTo);
        // Overlap test
        if(ms<=pe && me>=ps){
          m.parentProjectId = pid;
          linked++;
        }
      });
    });
  });
  // Persist
  d._fl_proj_migrated_v1 = true;
  d.boats = BOATS;
  d.fleet_projects = FL_PROJECTS;
  d.fleet_maintenance = FL_MAINT;
  localStorage.setItem(LS_KEY, JSON.stringify(d));
  console.log(`[Projects migration] created=${created} · linked MJs=${linked}`);
  return {created, linked};
}
function flProjGuessEnd(startStr){
  // Default = Open (no fixed end) · user can edit later to set explicit date
  return null;
}

// ── Phase definitions per project type ──
const PROJ_PHASES = {
  drydock:    [{k:'planning',label:'Planning'},{k:'liftout',label:'Lift-out'},{k:'hull',label:'Hull / Paint'},{k:'mechanical',label:'Mechanical'},{k:'sea_trial',label:'Sea Trial'},{k:'handover',label:'Handover'}],
  overhaul:   [{k:'planning',label:'Planning'},{k:'disassembly',label:'Disassembly'},{k:'install',label:'Install'},{k:'test',label:'Bench Test'},{k:'sea_trial',label:'Sea Trial'},{k:'handover',label:'Handover'}],
  refit:      [{k:'planning',label:'Planning'},{k:'strip',label:'Strip-out'},{k:'rebuild',label:'Rebuild'},{k:'finishing',label:'Finishing'},{k:'handover',label:'Handover'}],
  scheduled:  [{k:'planning',label:'Planning'},{k:'service',label:'Service'},{k:'test',label:'Test'},{k:'handover',label:'Handover'}],
  other:      [{k:'planning',label:'Planning'},{k:'execute',label:'Execute'},{k:'verify',label:'Verify'},{k:'handover',label:'Handover'}]
};
function flProjPhasesFor(p){ return PROJ_PHASES[p.type] || PROJ_PHASES.other; }
function flProjCurrentPhaseIdx(p){
  const phases = flProjPhasesFor(p);
  if(p.status==='completed') return phases.length-1;
  if(p.status==='cancelled') return -1;
  if(p.phase){
    const idx = phases.findIndex(x=>x.k===p.phase);
    if(idx>=0) return idx;
  }
  // Default: if inprogress and no phase set → index 1 (after planning), else planning
  return p.status==='inprogress' ? 1 : 0;
}
function flProjSetPhase(projId, phaseKey){
  const p = flProjGetById(projId); if(!p) return;
  const phases = flProjPhasesFor(p);
  const newPhase = phases.find(x=>x.k===phaseKey);
  if(!newPhase) return;
  const oldLabel = p.phase ? (phases.find(x=>x.k===p.phase)?.label||p.phase) : '(none)';
  p.phase = phaseKey;
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`Phase: ${oldLabel} → ${newPhase.label}`, by:'user'});
  flSave();
  flRenderProjects();
}

// ── Health score · derived from cost variance + schedule adherence ──
function flProjHealth(p){
  if(p.status==='completed') return {key:'completed', label:'COMPLETED', color:'#0E7A5C', bg:'#E6F7F1', score:100};
  if(p.status==='cancelled') return {key:'cancelled', label:'CANCELLED', color:'#A32D2D', bg:'#FCEBEB', score:0};
  const budget = p.plannedBudget||0;
  const cost = (typeof flProjCalcCost==='function')?flProjCalcCost(p.id):0;
  const budgetPct = budget? (cost/budget*100) : 0;
  // Schedule progress · skip if planTo is Open (null)
  const ps = p.planFrom ? new Date(p.planFrom) : null;
  const pe = p.planTo   ? new Date(p.planTo)   : null;
  const today = new Date(TODAY_STR);
  let timePct = 0, schedOver = 0;
  if(ps && pe){
    const total = Math.max(1, (pe-ps)/86400000);
    const elapsed = Math.max(0, (today-ps)/86400000);
    timePct = Math.min(150, elapsed/total*100);
    if(today>pe) schedOver = (today-pe)/86400000;
  }
  // Open-ended projects don't get schedule penalty
  // Open MJ ratio
  const kids = flProjChildMJs(p.id);
  const openRatio = kids.length ? kids.filter(m=>m.status!=='done').length/kids.length : 0;
  // Score
  let score = 100;
  if(budget && budgetPct>100) score -= Math.min(40, (budgetPct-100)*1.5);
  if(budget && budgetPct>=80 && budgetPct<=100) score -= 5;
  if(schedOver>0) score -= Math.min(35, schedOver*2);
  if(timePct>80 && openRatio>0.5) score -= 15;
  if(p.status==='on_hold') score -= 10;
  score = Math.max(0, Math.min(100, Math.round(score)));
  // Bucket
  let key='ontrack', label='ON TRACK', color='#0E7A5C', bg='#E6F7F1';
  if(score<40){ key='critical'; label='CRITICAL'; color='#A32D2D'; bg='#FCEBEB'; }
  else if(score<70){ key='atrisk'; label='AT RISK'; color='#996A14'; bg='#FFF4E1'; }
  return {key, label, color, bg, score, budgetPct, schedOver, openRatio};
}

// ── YoY Analysis · compute year-over-year stats from FL_PROJECTS ──
function flProjYoYStats(yearTY){
  yearTY = yearTY || new Date(TODAY_STR).getFullYear();
  const yearLY = yearTY - 1;
  const projForYear = (yr) => (FL_PROJECTS||[]).filter(p=>{
    const ref = p.actualTo || p.planFrom || p.createdAt || '';
    return ref.startsWith(String(yr));
  });
  const calc = (projs) => {
    const completed = projs.filter(p=>p.status==='completed');
    const cancelled = projs.filter(p=>p.status==='cancelled');
    const totalSpend = projs.reduce((s,p)=>s+(typeof flProjCalcCost==='function'?flProjCalcCost(p.id):0), 0);
    const avgCost = completed.length ? Math.round(totalSpend/completed.length) : 0;
    // Avg duration in days for completed projects
    let durSum = 0, durCount = 0;
    completed.forEach(p=>{
      if(p.actualFrom && p.actualTo){
        const d = Math.max(0, (new Date(p.actualTo) - new Date(p.actualFrom))/86400000);
        durSum += d; durCount++;
      }
    });
    const avgDuration = durCount ? Math.round(durSum/durCount) : 0;
    // On-time = actualTo <= ORIGINAL plan (baseline · not editable)
    // Falls back to current planTo if no baseline (legacy)
    const baselineFor = p => p.originalPlanTo || p.planTo;
    const onTime = completed.filter(p=>p.actualTo && baselineFor(p) && p.actualTo<=baselineFor(p)).length;
    const onTimePct = completed.length ? Math.round(onTime/completed.length*100) : 0;
    // Schedule slip · days · negative = finished early · positive = late
    let slipSum = 0, slipCount = 0;
    completed.forEach(p=>{
      const base = baselineFor(p);
      if(p.actualTo && base){
        const d = Math.round((new Date(p.actualTo) - new Date(base))/86400000);
        slipSum += d; slipCount++;
      }
    });
    const avgSlip = slipCount ? Math.round(slipSum/slipCount) : 0;
    // Per-type counts
    const byType = {drydock:0, overhaul:0, refit:0, scheduled:0, other:0};
    projs.forEach(p=>{ const t=p.type||'other'; if(byType[t]!==undefined) byType[t]++; else byType.other++; });
    // Monthly spend (12 months)
    const monthSpend = Array(12).fill(0);
    completed.forEach(p=>{
      const ref = p.actualTo || p.planTo || '';
      if(!ref) return;
      const m = parseInt(ref.slice(5,7))-1;
      if(m>=0 && m<12) monthSpend[m] += (typeof flProjCalcCost==='function'?flProjCalcCost(p.id):0);
    });
    return {
      count: projs.length,
      completed: completed.length,
      cancelled: cancelled.length,
      totalSpend, avgCost, avgDuration, onTimePct, avgSlip,
      byType, monthSpend
    };
  };
  return { yearTY, yearLY, TY: calc(projForYear(yearTY)), LY: calc(projForYear(yearLY)) };
}

// ── Schedule slip KPI tile · negative = early (green) · positive = late (red) ──
function flProjRenderSlipTile(tySlip, lySlip, yearLY, P){
  const slipColor = (s) => s<0 ? P.mintInk : s>0 ? P.red : P.ink3;
  const slipLabel = (s) => s===0 ? 'on baseline' : s<0 ? `${Math.abs(s)} day${Math.abs(s)===1?'':'s'} early` : `${s} day${s===1?'':'s'} late`;
  const slipBg = (s) => s<0 ? P.mintSoft : s>0 ? P.redSoft : P.bg;
  const slipIcon = (s) => s<0 ? 'checkCircle' : s>0 ? 'alert' : 'target';
  // Delta: smaller (more negative or less positive) = better
  let deltaText = '—', deltaInk = P.ink3;
  if(tySlip !== lySlip){
    const diff = tySlip - lySlip;
    deltaText = diff<0 ? `↓ ${Math.abs(diff)}d better` : `↑ ${diff}d worse`;
    deltaInk = diff<0 ? P.mintInk : P.red;
  }
  return `
    <div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:16px 18px;box-shadow:${P.shadow}">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">
        <div style="width:36px;height:36px;border-radius:10px;background:${slipBg(tySlip)};color:${slipColor(tySlip)};display:flex;align-items:center;justify-content:center;flex-shrink:0">${flProjIcon(slipIcon(tySlip),18,slipColor(tySlip),1.8)}</div>
        <div style="font-size:11px;color:${P.ink2};font-weight:600">Schedule Slip</div>
      </div>
      <div style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin-bottom:6px">
        <span style="font-size:30px;font-weight:800;color:${slipColor(tySlip)};letter-spacing:-.7px;line-height:1;font-variant-numeric:tabular-nums">${tySlip>0?'+':''}${tySlip}</span>
        <span style="font-size:12px;color:${P.ink3};font-weight:500">days</span>
        <span style="background:${deltaInk}22;color:${deltaInk};padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;margin-left:auto">${deltaText}</span>
      </div>
      <div style="font-size:11px;color:${P.ink3}">${slipLabel(tySlip)} · vs <span style="font-weight:600;color:${P.ink2}">${lySlip>0?'+':''}${lySlip}d</span> in ${yearLY}</div>
    </div>`;
}

let _yoyYear = null; // overridden by year picker
function flProjOpenYoy(){
  if(!_yoyYear) _yoyYear = new Date(TODAY_STR).getFullYear();
  flProjRenderYoyModal();
  openModal('fl-modal-proj-yoy');
}
function flProjYoySetYear(y){
  _yoyYear = parseInt(y);
  flProjRenderYoyModal();
}

function flProjRenderYoyModal(){
  const P = PROJ_PALETTE;
  const mount = document.getElementById('fl-proj-yoy-body');
  if(!mount) return;
  const data = flProjYoYStats(_yoyYear);
  const {yearTY, yearLY, TY, LY} = data;

  // Delta helper · returns {pct, ink, label, arrow}
  const delta = (ty, ly, betterUp=true) => {
    if(ly===0 && ty===0) return {pct:0, ink:P.ink3, label:'—', arrow:''};
    if(ly===0) return {pct:100, ink:betterUp?P.mintInk:P.red, label:'new', arrow:''};
    const d = Math.round((ty-ly)/Math.max(1,Math.abs(ly))*100);
    const up = d>0;
    const positive = betterUp ? up : !up;
    return {
      pct: Math.abs(d),
      ink: d===0?P.ink3 : (positive?P.mintInk:P.red),
      label: `${up?'↑':'↓'} ${Math.abs(d)}%`,
      arrow: up?'↑':'↓'
    };
  };

  const kpiTile = (iconName, iconBg, iconColor, label, tyVal, lyVal, unit, deltaInfo) => `
    <div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:16px 18px;box-shadow:${P.shadow}">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">
        <div style="width:36px;height:36px;border-radius:10px;background:${iconBg};color:${iconColor};display:flex;align-items:center;justify-content:center;flex-shrink:0">${flProjIcon(iconName,18,iconColor,1.8)}</div>
        <div style="font-size:11px;color:${P.ink2};font-weight:600">${label}</div>
      </div>
      <div style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin-bottom:6px">
        <span style="font-size:30px;font-weight:800;color:${P.navy};letter-spacing:-.7px;line-height:1;font-variant-numeric:tabular-nums">${tyVal}</span>
        ${unit?`<span style="font-size:12px;color:${P.ink3};font-weight:500">${unit}</span>`:''}
        <span style="background:${deltaInfo.ink}22;color:${deltaInfo.ink};padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;margin-left:auto">${deltaInfo.label}</span>
      </div>
      <div style="font-size:11px;color:${P.ink3}">vs <span style="font-weight:600;color:${P.ink2}">${lyVal}${unit?` ${unit}`:''}</span> in ${yearLY}</div>
    </div>`;

  // Build monthly chart (SVG bars overlaid)
  const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const maxSpend = Math.max(...TY.monthSpend, ...LY.monthSpend, 1);
  const cw=720, ch=180, padL=40, padR=10, padT=10, padB=24;
  const chartW = cw-padL-padR, chartH = ch-padT-padB;
  const bw = chartW/12;
  const bars = MON.map((m,i)=>{
    const tyH = TY.monthSpend[i]/maxSpend*chartH;
    const lyH = LY.monthSpend[i]/maxSpend*chartH;
    const x = padL + i*bw;
    return `
      <rect x="${x+4}" y="${padT+chartH-lyH}" width="${bw/2-3}" height="${lyH}" fill="${P.ink4}" rx="2"/>
      <rect x="${x+bw/2+1}" y="${padT+chartH-tyH}" width="${bw/2-3}" height="${tyH}" fill="${P.blue}" rx="2"/>
      <text x="${x+bw/2}" y="${ch-8}" text-anchor="middle" font-size="9" fill="${P.ink3}" font-family="Inter,sans-serif" font-weight="600">${m}</text>`;
  }).join('');

  // Per-type breakdown side-by-side
  const TYPE_LABEL = {drydock:'Drydock', overhaul:'Overhaul', refit:'Refit', scheduled:'Scheduled', other:'Other'};
  const TYPE_COLOR = {drydock:P.blue, overhaul:P.amber, refit:P.purple, scheduled:P.mintInk, other:P.ink3};
  const typeRows = Object.keys(TYPE_LABEL).map(t=>{
    const ty = TY.byType[t]||0, ly = LY.byType[t]||0;
    if(ty===0 && ly===0) return '';
    const maxV = Math.max(ty, ly, 1);
    const color = TYPE_COLOR[t];
    return `
      <div style="display:grid;grid-template-columns:80px 1fr 60px 1fr 60px;gap:10px;align-items:center;padding:8px 0;border-bottom:1px solid ${P.line}">
        <div style="font-size:11px;font-weight:700;color:${P.navy}">${TYPE_LABEL[t]}</div>
        <div style="height:8px;background:${P.bg};border-radius:4px;position:relative"><div style="position:absolute;left:0;top:0;height:100%;width:${ty/maxV*100}%;background:${color};border-radius:4px"></div></div>
        <div style="font-size:12px;font-weight:700;color:${color};text-align:right;font-variant-numeric:tabular-nums">${ty}</div>
        <div style="height:8px;background:${P.bg};border-radius:4px;position:relative"><div style="position:absolute;left:0;top:0;height:100%;width:${ly/maxV*100}%;background:${P.ink4};border-radius:4px"></div></div>
        <div style="font-size:12px;color:${P.ink2};text-align:right;font-variant-numeric:tabular-nums">${ly}</div>
      </div>`;
  }).filter(s=>s).join('');

  // Year selector
  const allYears = (function(){
    const yrs = new Set([yearTY, yearLY]);
    (FL_PROJECTS||[]).forEach(p=>{
      const ref = p.actualTo || p.planFrom || p.createdAt || '';
      if(ref) yrs.add(parseInt(ref.slice(0,4)));
    });
    return Array.from(yrs).filter(y=>y).sort((a,b)=>b-a);
  })();

  mount.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px">
      <div>
        <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase">YoY Analysis · ${yearTY}</div>
        <div style="font-size:12px;color:${P.ink2};margin-top:4px">Compare ${yearTY} performance vs ${yearLY}</div>
      </div>
      <select onchange="flProjYoySetYear(this.value)" style="background:white;border:1px solid ${P.line};border-radius:10px;padding:6px 12px;font-size:12px;font-weight:600;color:${P.ink};cursor:pointer">
        ${allYears.map(y=>`<option value="${y}" ${y===yearTY?'selected':''}>${y} vs ${y-1}</option>`).join('')}
      </select>
    </div>

    <!-- KPI grid · 3 cols x 2 rows -->
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:18px">
      ${kpiTile('clipboard',  P.blueSoft, P.blue,    'Projects · total',  TY.count,      LY.count,      '',    delta(TY.count, LY.count, true))}
      ${kpiTile('checkCircle',P.mintSoft, P.mintInk, 'Completed',         TY.completed,  LY.completed,  '',    delta(TY.completed, LY.completed, true))}
      ${kpiTile('coin',       '#F3E8FF',  P.purple,  'YTD Spend',         '฿'+(TY.totalSpend>=1000?(TY.totalSpend/1000).toFixed(0)+'K':TY.totalSpend), '฿'+(LY.totalSpend>=1000?(LY.totalSpend/1000).toFixed(0)+'K':LY.totalSpend), '', delta(TY.totalSpend, LY.totalSpend, false))}
      ${kpiTile('clock',      P.amberSoft,P.amberInk,'Avg duration',      TY.avgDuration,LY.avgDuration,'days',delta(TY.avgDuration, LY.avgDuration, false))}
      ${kpiTile('target',     P.mintSoft, P.mintInk, 'On-time vs baseline', TY.onTimePct,LY.onTimePct,  '%',   delta(TY.onTimePct, LY.onTimePct, true))}
      ${flProjRenderSlipTile(TY.avgSlip, LY.avgSlip, yearLY, P)}
    </div>

    <!-- Monthly spend bar chart -->
    <div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:14px 18px;margin-bottom:14px;box-shadow:${P.shadow}">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px">
        <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase">Monthly Spend</div>
        <div style="display:flex;gap:12px;font-size:11px;color:${P.ink2};font-weight:600">
          <span style="display:inline-flex;align-items:center;gap:5px"><span style="width:10px;height:10px;border-radius:2px;background:${P.blue}"></span>${yearTY}</span>
          <span style="display:inline-flex;align-items:center;gap:5px"><span style="width:10px;height:10px;border-radius:2px;background:${P.ink4}"></span>${yearLY}</span>
        </div>
      </div>
      <svg viewBox="0 0 ${cw} ${ch}" width="100%" height="${ch}" preserveAspectRatio="xMidYMid meet">
        <line x1="${padL}" y1="${padT}" x2="${padL}" y2="${padT+chartH}" stroke="${P.line}" stroke-width="1"/>
        <line x1="${padL}" y1="${padT+chartH}" x2="${cw-padR}" y2="${padT+chartH}" stroke="${P.line}" stroke-width="1"/>
        <text x="${padL-6}" y="${padT+4}" text-anchor="end" font-size="9" fill="${P.ink3}" font-family="Inter,sans-serif">฿${(maxSpend/1000).toFixed(0)}K</text>
        <text x="${padL-6}" y="${padT+chartH/2+3}" text-anchor="end" font-size="9" fill="${P.ink3}" font-family="Inter,sans-serif">฿${(maxSpend/2000).toFixed(0)}K</text>
        ${bars}
      </svg>
    </div>

    <!-- Per-type breakdown -->
    <div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:14px 18px;box-shadow:${P.shadow}">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px">
        <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase">Projects by Type</div>
        <div style="display:flex;gap:12px;font-size:11px;color:${P.ink2};font-weight:600">
          <span style="display:inline-flex;align-items:center;gap:5px"><span style="width:10px;height:8px;border-radius:2px;background:${P.blue}"></span>${yearTY}</span>
          <span style="display:inline-flex;align-items:center;gap:5px"><span style="width:10px;height:8px;border-radius:2px;background:${P.ink4}"></span>${yearLY}</span>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:80px 1fr 60px 1fr 60px;gap:10px;padding:6px 0;border-bottom:2px solid ${P.line};font-size:10px;color:${P.ink3};font-weight:700;letter-spacing:.04em;text-transform:uppercase">
        <div>Type</div>
        <div style="text-align:center">${yearTY}</div>
        <div style="text-align:right">count</div>
        <div style="text-align:center">${yearLY}</div>
        <div style="text-align:right">count</div>
      </div>
      ${typeRows||`<div style="padding:16px;text-align:center;color:${P.ink3};font-size:12px">No project data for these years</div>`}
    </div>`;
}

// ── Rule-based AI Insight (no real AI, just smart rules) ──
function flProjInsight(p){
  const lines = [];
  const recs = [];
  const cost = (typeof flProjCalcCost==='function')?flProjCalcCost(p.id):0;
  const budget = p.plannedBudget||0;
  const today = new Date(TODAY_STR);
  const ps = p.planFrom?new Date(p.planFrom):null;
  const pe = p.planTo?new Date(p.planTo):null;
  const kids = flProjChildMJs(p.id);
  const openKids = kids.filter(m=>m.status!=='done');
  // Budget insights
  if(budget && cost>budget){
    lines.push(`Over budget by ฿${(cost-budget).toLocaleString()} (${Math.round((cost-budget)/budget*100)}% above plan).`);
    recs.push('Review remaining scope · consider raising budget or cutting non-critical items');
  } else if(budget && cost/budget>0.85){
    lines.push(`Budget ${Math.round(cost/budget*100)}% utilized · ฿${(budget-cost).toLocaleString()} remaining`);
    recs.push('Monitor any new memo · close to exhausting budget');
  }
  // Schedule insights · skip if no planTo (open-ended)
  if(!pe && p.status==='inprogress'){
    lines.push('No fixed end date set · project runs open-ended');
    recs.push('Set a target end date in Edit if vendor confirms timeline');
  } else if(pe && today>pe && p.status!=='completed'){
    const over = Math.ceil((today-pe)/86400000);
    lines.push(`${over} day${over>1?'s':''} past planned end date.`);
    recs.push('Update planned end date · negotiate handover · OR mark on-hold');
  } else if(pe && ps){
    const total = (pe-ps)/86400000;
    const elapsed = (today-ps)/86400000;
    const tPct = elapsed/total;
    const wPct = kids.length?(kids.length-openKids.length)/kids.length:0;
    if(tPct>0.5 && wPct<tPct-0.2){
      lines.push(`Behind schedule · ${Math.round(tPct*100)}% time elapsed but only ${Math.round(wPct*100)}% of MJs done.`);
      recs.push('Consider adding labor or re-prioritizing MJs');
    }
  }
  // Hold insight
  if(p.status==='on_hold'){
    lines.push(`On hold since ${p.holdSince||'?'} · reason: ${p.holdReason||'(none)'}`);
    recs.push('Resume when blocker cleared · or convert to cancellation');
  }
  // Documents
  const docs = p.docs||[];
  const verifiedDocs = docs.filter(d=>d.status==='verified').length;
  if(docs.length && verifiedDocs/docs.length<0.5){
    lines.push(`Only ${verifiedDocs} / ${docs.length} documents verified`);
    recs.push('Verify pending documents to maintain compliance');
  }
  if(!lines.length) lines.push('Project running smoothly · all KPIs within healthy range');
  return {lines, recs};
}

// ── Vendor visit log ──
function flProjAddVendorVisit(projId){
  const p = flProjGetById(projId); if(!p) return;
  const vendor = prompt('Vendor / contractor name:', p.vendor||''); if(!vendor) return;
  const role = prompt('Role / purpose (e.g. inspection · paint quote · sea trial):', '')||'';
  if(!p.vendorVisits) p.vendorVisits=[];
  p.vendorVisits.push({
    id:'vv_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),
    vendor: vendor.trim(),
    role: role.trim(),
    date: TODAY_STR,
    by:'user'
  });
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`Vendor visit: ${vendor.trim()}${role?' · '+role.trim():''}`, by:'user'});
  flSave();
  flRenderProjects();
}
function flProjDeleteVendorVisit(projId, vvId){
  const p = flProjGetById(projId); if(!p||!p.vendorVisits) return;
  const v = p.vendorVisits.find(x=>x.id===vvId); if(!v) return;
  if(!confirm(`Delete vendor visit: ${v.vendor}?`)) return;
  p.vendorVisits = p.vendorVisits.filter(x=>x.id!==vvId);
  flSave();
  flRenderProjects();
}

// ── Photo helpers (stored as docs[] with type='photo') ──
function flProjAddPhoto(projId){
  const p = flProjGetById(projId); if(!p) return;
  const url = prompt('Image URL (paste link or data: URL):', ''); if(!url) return;
  const caption = prompt('Caption (optional):', '')||'';
  const phase = prompt('Phase tag (planning/liftout/hull/mechanical/sea_trial/handover):', p.phase||'planning')||'planning';
  if(!p.docs) p.docs=[];
  p.docs.push({
    id:'ph_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),
    name: caption || `Photo · ${TODAY_STR}`,
    url: url.trim(),
    note: caption,
    type: 'photo',
    phase: phase,
    status: 'received',
    addedAt: TODAY_STR
  });
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`Photo added${caption?': '+caption:''}`, by:'user'});
  flSave();
  flRenderProjects();
}
function flProjLightbox(url, caption){
  const html = `<div onclick="this.remove()" style="position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:9999;display:flex;align-items:center;justify-content:center;cursor:zoom-out">
    <div style="position:relative;max-width:92vw;max-height:92vh;display:flex;flex-direction:column;align-items:center;gap:10px">
      <img src="${url}" style="max-width:92vw;max-height:88vh;object-fit:contain;border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,.4)">
      ${caption?`<div style="color:white;font-size:13px;font-family:Manrope,sans-serif;padding:6px 14px;background:rgba(0,0,0,.5);border-radius:14px">${caption}</div>`:''}
    </div>
  </div>`;
  const wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
}

function flProjChildMJs(projId){
  return (FL_MAINT||[]).filter(m=>m.parentProjectId===projId);
}
function flProjCalcCost(projId){
  const kids = flProjChildMJs(projId);
  return kids.reduce((s,m)=>s+(typeof flMaintCalcCost==='function'?flMaintCalcCost(m.id):(m.cost||0)),0);
}
// Cost breakdown · per-MJ
function flProjMJCostBreakdown(mjId){
  const m = (FL_MAINT||[]).find(x=>x.id===mjId);
  if(!m) return {parts:0, labour:0, memos:0, total:0};
  const partsDirect = (m.parts||[]).reduce((s,p)=>s+((p.qty||0)*(p.cost||0)),0);
  let memoParts = 0, memoLabour = 0, memoOther = 0;
  (FL_MEMOS||[]).filter(mo=>mo.maintId===mjId && (mo.status==='paid'||mo.status==='received'||mo.status==='approved')).forEach(mo=>{
    const items = mo.items||[];
    if(items.length===0){ memoOther += (mo.amount||0); return; }
    items.forEach(it=>{
      const sub = (it.qty||0)*(it.price||it.cost||0);
      const cat = (it.category||'').toLowerCase();
      if(cat==='labor'||cat==='labour') memoLabour += sub;
      else if(cat==='parts') memoParts += sub;
      else memoOther += sub;
    });
  });
  const parts = partsDirect + memoParts;
  const labour = memoLabour;
  const memos = memoOther; // legacy / mixed bucket
  const total = parts + labour + memos;
  return {parts, labour, memos, total};
}
// Cost breakdown · project sum (includes direct project-level memos)
function flProjCostBreakdown(projId){
  const kids = flProjChildMJs(projId);
  let parts=0, labour=0, memos=0;
  kids.forEach(m=>{
    const b = flProjMJCostBreakdown(m.id);
    parts += b.parts; labour += b.labour; memos += b.memos;
  });
  // Add direct project-level memos (overhead)
  (FL_MEMOS||[]).filter(mo=>mo.projectId===projId && (mo.status==='paid'||mo.status==='received'||mo.status==='approved')).forEach(mo=>{
    const items = mo.items||[];
    if(items.length===0){ memos += (mo.amount||0); return; }
    items.forEach(it=>{
      const sub = (it.qty||0)*(it.price||it.cost||0);
      const cat = (it.category||'').toLowerCase();
      if(cat==='labor'||cat==='labour') labour += sub;
      else if(cat==='parts') parts += sub;
      else memos += sub;
    });
  });
  const total = parts + labour + memos;
  return {parts, labour, memos, total};
}
function flProjGetById(id){ return FL_PROJECTS.find(p=>p.id===id); }
function flProjBoatName(p){ if(!p.boatId) return 'General · ไม่เกี่ยวกับเรือ'; const b=BOATS.find(x=>x.id===p.boatId); return b?b.name:'(unknown boat)'; }

// ── Boat avatar helpers (match Boat Status design · same palette + initials logic) ──
const BOAT_AVATAR_PALETTE = ['#185FA5','#534AB7','#1D9E75','#BA7517','#A32D2D','#0F6E56','#7F77DD','#D85A30','#993556','#185FA5'];
function flBoatAvatarColor(boat){
  if(!boat) return '#999';
  // Use index in company boats list (matches Boat Status)
  const company = (BOATS||[]).filter(b=>b.ownership!=='charter' && !b.retired);
  const i = company.findIndex(x=>x.id===boat.id);
  const idx = i>=0 ? (i % BOAT_AVATAR_PALETTE.length) : 0;
  return BOAT_AVATAR_PALETTE[idx];
}
function flBoatInitials(name){
  if(!name) return '?';
  const w = name.split(/\s+/);
  if(w.length>=2) return (w[0][0]+w[1][0]).toUpperCase();
  if(name.length>=2 && /\d/.test(name)) return (name.match(/[A-Z]/g)?.[0]||name[0]) + name.slice(-1);
  return name.slice(0,2).toUpperCase();
}
function flBoatMeta(boat){
  // Build "Speedboat · 65 PAX · 4 EN" style meta line
  if(!boat) return '';
  const parts = [];
  if(boat.type) parts.push(boat.type);
  if(boat.cap) parts.push(`${boat.cap} PAX`);
  const engCount = (typeof FL_ENGINES!=='undefined') ? FL_ENGINES.filter(e=>e.boatId===boat.id).length : (boat.engineCount||0);
  if(engCount) parts.push(`${engCount} EN`);
  return parts.join(' · ');
}

// ── Render entry point ──
function flRenderProjects(){
  // Run migration once on first visit
  flProjMigrate(false);
  const wrap = document.getElementById('fl-proj-mount');
  if(!wrap) return;
  if(_selProjId){
    flProjRenderDetail(_selProjId);
    return;
  }
  flProjRenderList();
}

function flProjRenderList(){
  const P = PROJ_PALETTE;
  const wrap = document.getElementById('fl-proj-mount');
  if(!wrap) return;
  const all = FL_PROJECTS||[];
  const byStatus = {
    planned:   all.filter(p=>p.status==='planned'),
    inprogress:all.filter(p=>p.status==='inprogress'),
    on_hold:   all.filter(p=>p.status==='on_hold'),
    completed: all.filter(p=>p.status==='completed'),
    cancelled: all.filter(p=>p.status==='cancelled')
  };
  const visible = byStatus[_projTab]||[];
  const yr = new Date(TODAY_STR).getFullYear();
  const ytdSpend = all.filter(p=>p.status==='completed' && (p.actualFrom||p.planFrom||'').startsWith(String(yr)))
                      .reduce((s,p)=>s+flProjCalcCost(p.id),0);
  const activeBoats = new Set(byStatus.inprogress.map(p=>p.boatId)).size;

  // ── Greeting hero card (BuildAxis style) ──
  const _now = new Date();
  const greetTxt = _now.getHours()<12 ? 'Good morning' : _now.getHours()<17 ? 'Good afternoon' : 'Good evening';
  const todayLbl = _now.toLocaleDateString('en-US', {weekday:'long', day:'numeric', month:'short', year:'numeric'});
  const keyInsight = (function(){
    if(byStatus.inprogress.length>0 && activeBoats>=3) return `${activeBoats} boats off-line · plan handover ahead`;
    if(byStatus.on_hold && byStatus.on_hold.length>0) return `${byStatus.on_hold.length} project(s) on hold · needs attention`;
    if(byStatus.planned.length>3) return `${byStatus.planned.length} projects scheduled · review capacity`;
    return 'Fleet operations running smoothly';
  })();

  const header = `
    <div style="display:grid;grid-template-columns:2fr 1fr;gap:14px;margin-bottom:16px;align-items:stretch">
      <div style="background:linear-gradient(120deg,#EEF3FF 0%, #F5F8FF 60%, #FFFFFF 100%);border:1px solid ${P.line};border-radius:18px;padding:24px 28px;display:grid;grid-template-columns:1fr auto;gap:20px;align-items:center">
        <div>
          <div style="font-size:11px;letter-spacing:1.4px;color:${P.blue};font-weight:700;text-transform:uppercase">Fleet Operations · Projects</div>
          <div style="font-size:30px;font-weight:800;color:${P.navy};letter-spacing:-.6px;margin-top:4px">${greetTxt}, Operations 👋</div>
          <div style="font-size:13px;color:${P.ink2};margin-top:4px">Here's what's happening across your projects today.</div>
          <div style="display:flex;align-items:center;gap:14px;margin-top:14px;flex-wrap:wrap">
            <span style="background:white;border:1px solid ${P.line};border-radius:20px;padding:6px 14px;font-size:11px;color:${P.ink2};font-weight:600;display:inline-flex;align-items:center;gap:8px">${flProjIcon('calendar',13,P.ink2)} ${todayLbl}</span>
            <span style="background:white;border:1px solid ${P.line};border-radius:20px;padding:6px 14px;font-size:11px;color:${P.ink2};font-weight:600;display:inline-flex;align-items:center;gap:6px"><span style="width:7px;height:7px;border-radius:50%;background:${P.mint}"></span>Live Data</span>
          </div>
        </div>
        <div style="width:120px;height:120px;border-radius:24px;background:white;border:1px solid ${P.line};display:flex;align-items:center;justify-content:center;color:${P.blue};box-shadow:${P.shadow}">${flProjIcon('wrench',56,P.blue,1.6)}</div>
      </div>

      <div style="background:white;border:1px solid ${P.line};border-radius:18px;padding:18px 20px;box-shadow:${P.shadow};display:flex;flex-direction:column;justify-content:space-between">
        <div>
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
            <span style="background:${P.blueSoft};color:${P.blue};width:30px;height:30px;border-radius:50%;display:flex;align-items:center;justify-content:center">${flProjIcon('sparkle',14,P.blue)}</span>
            <span style="font-size:12px;font-weight:700;color:${P.navy}">AI Project Insight</span>
          </div>
          <div style="display:flex;align-items:baseline;gap:8px;margin-top:6px">
            <span style="font-size:42px;font-weight:800;color:${P.navy};letter-spacing:-1px;line-height:1">${Math.round((byStatus.inprogress.length+byStatus.completed.length)/(all.length||1)*100)}</span>
            <span style="font-size:13px;color:${P.ink3};font-weight:600">/100</span>
            <span style="font-size:11px;color:${P.ink2};margin-left:6px">Health Score</span>
          </div>
          <div style="font-size:11px;color:${P.ink2};margin-top:10px;line-height:1.45">${keyInsight}</div>
        </div>
        <div onclick="flProjOpenYoy()" style="margin-top:12px;font-size:11px;color:${P.blue};font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">
          ${flProjIcon('trending',12,P.blue)} View Year-over-Year Analysis →
        </div>
      </div>
    </div>

    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;flex-wrap:wrap;gap:10px">
      <div style="display:flex;gap:8px;align-items:center">
        <div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:3px;display:inline-flex;gap:2px;box-shadow:${P.shadow}">
          <button onclick="_projViewMode='list';flRenderProjects()" style="background:${_projViewMode==='list'?P.blue:'transparent'};color:${_projViewMode==='list'?'white':P.ink2};border:none;border-radius:11px;padding:7px 14px;font-size:12px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">${flProjIcon('list',14,_projViewMode==='list'?'white':P.ink2)} List</button>
          <button onclick="_projViewMode='timeline';flRenderProjects()" style="background:${_projViewMode==='timeline'?P.blue:'transparent'};color:${_projViewMode==='timeline'?'white':P.ink2};border:none;border-radius:11px;padding:7px 14px;font-size:12px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">${flProjIcon('clock',14,_projViewMode==='timeline'?'white':P.ink2)} Timeline</button>
          <button onclick="_projViewMode='gantt';flRenderProjects()" style="background:${_projViewMode==='gantt'?P.blue:'transparent'};color:${_projViewMode==='gantt'?'white':P.ink2};border:none;border-radius:11px;padding:7px 14px;font-size:12px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">${flProjIcon('ganttChart',14,_projViewMode==='gantt'?'white':P.ink2)} Gantt</button>
        </div>
      </div>
      <div style="display:flex;gap:8px;align-items:center">
        <button onclick="flProjMigrate(true);flRenderProjects();flShowToast('Re-scanned boat logs')" style="background:white;border:1px solid ${P.line};color:${P.ink2};border-radius:14px;padding:8px 16px;font-size:12px;font-weight:600;cursor:pointer;box-shadow:${P.shadow};display:inline-flex;align-items:center;gap:7px">${flProjIcon('refresh',14,P.ink2)} Re-scan logs</button>
        <button onclick="flProjOpenNew()" style="background:${P.blue};color:white;border:none;border-radius:14px;padding:8px 18px;font-size:12px;font-weight:600;cursor:pointer;box-shadow:0 2px 6px rgba(58,111,247,.3);display:inline-flex;align-items:center;gap:8px">
          <span style="background:rgba(255,255,255,.22);border-radius:50%;width:20px;height:20px;display:inline-flex;align-items:center;justify-content:center">${flProjIcon('plus',12,'white',2.5)}</span>
          Quick Create
        </button>
      </div>
    </div>`;

  // BuildAxis-style KPI tiles: 6 cards in a row, each with circular icon + label + big number + comparison
  const kpiTile = (iconName, iconBg, iconColor, label, value, sub, subColor)=>`
    <div style="background:white;border:1px solid ${P.line};border-radius:16px;padding:18px 18px;box-shadow:${P.shadow};display:flex;flex-direction:column;gap:10px">
      <div style="display:flex;align-items:center;gap:12px">
        <div style="width:42px;height:42px;border-radius:12px;background:${iconBg};color:${iconColor};display:flex;align-items:center;justify-content:center;flex-shrink:0">${flProjIcon(iconName,22,iconColor,1.8)}</div>
        <div style="flex:1;min-width:0">
          <div style="font-size:11px;color:${P.ink2};font-weight:500;letter-spacing:.02em">${label}</div>
          <div style="font-size:28px;font-weight:800;color:${P.navy};letter-spacing:-1px;line-height:1.1;margin-top:2px;font-variant-numeric:tabular-nums">${value}</div>
        </div>
      </div>
      <div style="font-size:11px;color:${subColor||P.ink3};font-weight:500">${sub||''}</div>
    </div>`;
  const totalProjects = all.length;
  const kpi = `
    <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-bottom:16px;align-items:stretch">
      ${kpiTile('clipboard',   '#EEF3FF',  P.blue,    'Total Projects',  totalProjects,              `↑ ${all.length} all-time`, P.mintInk)}
      ${kpiTile('calendar',    P.blueSoft, P.blue,    'Scheduled',       byStatus.planned.length,    `${byStatus.planned.length?'upcoming':'none queued'}`, P.ink3)}
      ${kpiTile('wrench',      '#FFF7E6',  P.amberInk,'In Progress',     byStatus.inprogress.length, `${activeBoats} boat${activeBoats===1?'':'s'} off-line`, P.amberInk)}
      ${kpiTile('pause',       '#FFFBEB',  P.amber,   'On Hold',         (byStatus.on_hold||[]).length, (byStatus.on_hold||[]).length?'needs attention':'none', (byStatus.on_hold||[]).length?P.amber:P.ink3)}
      ${kpiTile('checkCircle', P.mintSoft, P.mintInk, 'Completed',       byStatus.completed.length,  `↑ ${byStatus.completed.length} archived`, P.mintInk)}
      ${kpiTile('coin',        '#F3E8FF',  P.purple,  'YTD Spend',       '฿'+(ytdSpend>=1000?(ytdSpend/1000).toFixed(0)+'K':ytdSpend), 'across all projects', P.ink3)}
    </div>`;

  const tabs = ['planned','inprogress','on_hold','completed','cancelled'];
  const tabLabel = {planned:'Scheduled', inprogress:'In Progress', on_hold:'On Hold', completed:'Completed', cancelled:'Cancelled'};
  const tabStrip = `
    <div style="display:flex;gap:6px;margin-bottom:12px;border-bottom:1px solid ${P.line};padding-bottom:0">
      ${tabs.map(t=>{
        const on = t===_projTab;
        return `<button onclick="_projTab='${t}';flRenderProjects()" style="background:none;border:none;padding:8px 14px 10px;font-size:12px;font-weight:600;color:${on?P.navy:P.ink3};border-bottom:2px solid ${on?P.navy:'transparent'};cursor:pointer">${tabLabel[t]} <span style="color:${P.ink4};font-weight:500">· ${byStatus[t].length}</span></button>`;
      }).join('')}
    </div>`;

  const list = visible.length ? `
    <div style="display:flex;flex-direction:column;gap:10px">
      ${visible.sort((a,b)=>(b.planFrom||'').localeCompare(a.planFrom||'')).map(p=>flProjRowCard(p)).join('')}
    </div>` : `
    <div style="background:white;border:1px dashed ${P.line};border-radius:14px;padding:40px;text-align:center;color:${P.ink3};font-size:13px">
      No ${tabLabel[_projTab].toLowerCase()} projects. ${_projTab==='planned'?'Click + New Project to schedule one.':''}
    </div>`;

  // Hub Dashboard panels (At Risk · Upcoming · Activity · Spend trend) shown above list only
  const hubPanels = _projViewMode==='list' ? flProjRenderHubPanels(all) : '';
  // Dispatch by view mode
  let mainBody;
  if(_projViewMode==='timeline')      mainBody = flProjRenderTimeline(all);
  else if(_projViewMode==='gantt')    mainBody = flProjRenderGantt(all);
  else                                 mainBody = hubPanels + tabStrip + list;
  wrap.innerHTML = `
    <div style="background:${P.bg};min-height:100vh;padding:28px 32px;font-family:'Inter','Manrope',system-ui,-apple-system,sans-serif;color:${P.ink}">
      ${header}
      ${kpi}
      ${mainBody}
    </div>`;
}

// ═══════════════ HUB DASHBOARD PANELS ═══════════════
function flProjRenderHubPanels(all){
  const P = PROJ_PALETTE;
  // At-Risk projects (health critical or atrisk)
  const active = all.filter(p=>p.status==='inprogress'||p.status==='on_hold'||p.status==='planned');
  const withHealth = active.map(p=>({p, h:flProjHealth(p)}));
  const atRisk = withHealth.filter(x=>x.h.key==='critical'||x.h.key==='atrisk')
                            .sort((a,b)=>a.h.score-b.h.score).slice(0,5);

  // Upcoming Deadlines · projects with planTo within next 30 days
  const today = new Date(TODAY_STR);
  const horizon = new Date(today); horizon.setDate(today.getDate()+30);
  const upcoming = active.filter(p=>{
    if(!p.planTo) return false;
    const pe = new Date(p.planTo);
    return pe>=today && pe<=horizon;
  }).sort((a,b)=>(a.planTo||'').localeCompare(b.planTo||'')).slice(0,5);

  // Recent Activity feed · combine logs from all projects · last 8 entries
  const allActivity = [];
  all.forEach(p=>{
    (p.log||[]).forEach(l=>allActivity.push({date:l.date||'', text:l.text||'', by:l.by||'', projNo:p.no, projId:p.id, projName:p.name}));
  });
  allActivity.sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  const recent = allActivity.slice(0,8);

  // Spend trend · monthly spend over last 6 months (completed projects)
  const months = [];
  const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  for(let i=5;i>=0;i--){
    const d = new Date(today); d.setMonth(d.getMonth()-i);
    const y=d.getFullYear(), m=d.getMonth();
    const mkey = `${y}-${String(m+1).padStart(2,'0')}`;
    let spend = 0;
    all.filter(p=>p.status==='completed' && (p.actualTo||p.planTo||'').startsWith(mkey))
       .forEach(p=>{ spend += flProjCalcCost(p.id); });
    months.push({label:`${MON[m]} ${String(y).slice(2)}`, spend});
  }
  const maxSpend = Math.max(...months.map(m=>m.spend), 1);

  const atRiskCard = `
    <div style="background:white;border:1px solid ${P.line};border-radius:16px;padding:16px 18px;height:100%;box-shadow:${P.shadow}">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px">
        <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px">${flProjIcon('alert',13,P.red)} At-Risk Projects</div>
        <span style="background:${P.redSoft};color:${P.red};padding:2px 9px;border-radius:10px;font-size:10px;font-weight:700">${atRisk.length}</span>
      </div>
      ${atRisk.length ? `
        <div style="display:flex;flex-direction:column;gap:6px">
          ${atRisk.map(({p,h})=>{
            const boat = BOATS.find(b=>b.id===p.boatId);
            return `<div onclick="flProjOpen('${p.id}')" style="display:flex;align-items:center;gap:10px;padding:8px 10px;background:${P.bg};border-radius:8px;cursor:pointer;border-left:3px solid ${h.color}">
              <div style="flex:1;min-width:0">
                <div style="font-size:11px;font-weight:700;color:${P.navy};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${p.no} · ${boat?boat.name:'?'}</div>
                <div style="font-size:10px;color:${P.ink3};margin-top:1px">${h.label} · score ${h.score}/100</div>
              </div>
              <span style="font-size:10px;color:${h.color};font-weight:700">›</span>
            </div>`;
          }).join('')}
        </div>
      ` : `<div style="font-size:11px;color:${P.mintInk};text-align:center;padding:18px;font-weight:600">✓ All active projects on track</div>`}
    </div>`;

  const upcomingCard = `
    <div style="background:white;border:1px solid ${P.line};border-radius:16px;padding:16px 18px;height:100%;box-shadow:${P.shadow}">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px">
        <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px">${flProjIcon('calendar',13,P.amber)} Upcoming Deadlines</div>
        <span style="background:${P.amberSoft};color:${P.amber};padding:2px 9px;border-radius:10px;font-size:10px;font-weight:700">${upcoming.length}</span>
      </div>
      ${upcoming.length ? `
        <div style="display:flex;flex-direction:column;gap:6px">
          ${upcoming.map(p=>{
            const boat = BOATS.find(b=>b.id===p.boatId);
            const daysLeft = Math.ceil((new Date(p.planTo)-today)/86400000);
            const urgColor = daysLeft<=3?P.red:daysLeft<=7?P.amber:P.ink2;
            return `<div onclick="flProjOpen('${p.id}')" style="display:flex;align-items:center;gap:10px;padding:8px 10px;background:${P.bg};border-radius:8px;cursor:pointer">
              <div style="flex:1;min-width:0">
                <div style="font-size:11px;font-weight:700;color:${P.navy};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${p.no} · ${boat?boat.name:'?'}</div>
                <div style="font-size:10px;color:${P.ink3};margin-top:1px;font-variant-numeric:tabular-nums">due ${p.planTo}</div>
              </div>
              <span style="background:white;color:${urgColor};padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;border:1px solid ${urgColor}33">${daysLeft}d</span>
            </div>`;
          }).join('')}
        </div>
      ` : `<div style="font-size:11px;color:${P.ink3};text-align:center;padding:18px">No deadlines in the next 30 days</div>`}
    </div>`;

  const activityCard = `
    <div style="background:white;border:1px solid ${P.line};border-radius:16px;padding:16px 18px;height:100%;box-shadow:${P.shadow}">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px">
        <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px">${flProjIcon('clock',13,P.blue)} Recent Activity</div>
        <span style="font-size:10px;color:${P.ink3}">across all projects</span>
      </div>
      ${recent.length ? `
        <div style="display:flex;flex-direction:column;gap:5px">
          ${recent.map(a=>`
            <div onclick="flProjOpen('${a.projId}')" style="padding:6px 0;border-bottom:1px dashed ${P.line};cursor:pointer">
              <div style="font-size:11px;color:${P.ink};line-height:1.4">${a.text}</div>
              <div style="font-size:10px;color:${P.ink3};margin-top:1px;font-variant-numeric:tabular-nums">${a.date||'—'} · <span style="color:${P.navy};font-weight:600">${a.projNo}</span>${a.by?` · ${a.by}`:''}</div>
            </div>
          `).join('')}
        </div>
      ` : `<div style="font-size:11px;color:${P.ink3};text-align:center;padding:18px">No activity yet</div>`}
    </div>`;

  // Spend trend SVG mini-bar chart
  const w=300, h=110, padL=30, padR=10, padT=10, padB=22;
  const cw=w-padL-padR, ch=h-padT-padB;
  const bw=cw/months.length;
  const bars = months.map((m,i)=>{
    const bh = (m.spend/maxSpend)*ch;
    const x = padL + i*bw + 4;
    const y = padT + (ch-bh);
    return `<g>
      <rect x="${x}" y="${y}" width="${bw-8}" height="${bh}" fill="${P.navy}" rx="3"/>
      <text x="${x+(bw-8)/2}" y="${h-6}" text-anchor="middle" font-size="8" fill="${P.ink3}" font-family="Manrope,sans-serif" font-weight="600">${m.label}</text>
      ${m.spend>0?`<text x="${x+(bw-8)/2}" y="${y-3}" text-anchor="middle" font-size="8" fill="${P.navy}" font-family="Manrope,sans-serif" font-weight="700">${(m.spend/1000).toFixed(0)}K</text>`:''}
    </g>`;
  }).join('');
  const ytickY = padT + ch/2;
  const totalSpend = months.reduce((s,m)=>s+m.spend,0);

  const spendCard = `
    <div style="background:white;border:1px solid ${P.line};border-radius:16px;padding:16px 18px;height:100%;box-shadow:${P.shadow}">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px">
        <div>
          <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px">${flProjIcon('trending',13,P.purple)} Spend Trend</div>
          <div style="font-size:10px;color:${P.ink3};margin-top:1px">last 6 months · completed projects</div>
        </div>
        <div style="text-align:right">
          <div style="font-size:16px;color:${P.navy};font-weight:700;font-variant-numeric:tabular-nums">฿${(totalSpend/1000).toFixed(0)}K</div>
          <div style="font-size:9px;color:${P.ink3}">6mo total</div>
        </div>
      </div>
      <svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}" preserveAspectRatio="xMidYMid meet">
        <line x1="${padL}" y1="${padT}" x2="${padL}" y2="${padT+ch}" stroke="${P.line}" stroke-width="1"/>
        <line x1="${padL}" y1="${padT+ch}" x2="${w-padR}" y2="${padT+ch}" stroke="${P.line}" stroke-width="1"/>
        <line x1="${padL}" y1="${ytickY}" x2="${w-padR}" y2="${ytickY}" stroke="${P.line}" stroke-width="1" stroke-dasharray="2 2"/>
        <text x="${padL-4}" y="${padT+4}" text-anchor="end" font-size="8" fill="${P.ink3}" font-family="Manrope,sans-serif">${(maxSpend/1000).toFixed(0)}K</text>
        <text x="${padL-4}" y="${ytickY+3}" text-anchor="end" font-size="8" fill="${P.ink3}" font-family="Manrope,sans-serif">${(maxSpend/2000).toFixed(0)}K</text>
        ${bars}
      </svg>
    </div>`;

  return `<div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:10px;margin-bottom:14px;align-items:stretch">
    ${atRiskCard}
    ${upcomingCard}
    ${activityCard}
    ${spendCard}
  </div>`;
}

// ═══════════════ NEW TIMELINE VIEW (project cards with day swimlane) ═══════════════
function flProjRenderTimeline(allProjects){
  const P = PROJ_PALETTE;
  // Filter to active-ish projects (planned, inprogress, on_hold) — completed/cancelled go to Gantt history
  const visible = allProjects.filter(p=>p.status==='planned'||p.status==='inprogress'||p.status==='on_hold')
                              .sort((a,b)=>(a.planFrom||'').localeCompare(b.planFrom||''));
  if(!visible.length){
    return `<div style="background:white;border:1px dashed ${P.line};border-radius:18px;padding:48px;text-align:center;color:${P.ink3};font-size:13px">No active projects to show in Timeline.</div>`;
  }
  const cards = visible.map(p=>flProjRenderTimelineCard(p)).join('');
  return `<div style="display:flex;flex-direction:column;gap:14px">${cards}</div>`;
}

// One project card with side panel + tabbed body
function flProjRenderTimelineCard(p){
  const P = PROJ_PALETTE;
  const boat = BOATS.find(b=>b.id===p.boatId);
  const kids = flProjChildMJs(p.id);
  const done = kids.filter(m=>m.status==='done').length;
  const open = kids.length - done;
  const today = new Date(TODAY_STR);
  const pe = p.planTo ? new Date(p.planTo) : null;
  const daysLeft = pe ? Math.ceil((pe-today)/86400000) : null;
  const overdue = pe && today>pe;
  // Side panel palette by status
  const sideTone = (function(){
    if(p.status==='inprogress') return {bg:'#FEEDE8', ink:'#C2410C', accent:'#F97316', label:overdue?'OVERDUE':'IN PROGRESS'};
    if(p.status==='on_hold')    return {bg:'#FEF3CD', ink:'#92400E', accent:'#F59E0B', label:'ON HOLD'};
    if(p.status==='planned')    return {bg:'#E0E7FF', ink:'#3730A3', accent:'#6366F1', label:'SCHEDULED'};
    return {bg:'#DCFCE7', ink:'#15803D', accent:'#22C55E', label:'COMPLETED'};
  })();
  const dueText = pe===null ? 'Open' : (overdue?`${Math.abs(daysLeft)} Past` : daysLeft===0?'Today' : `${daysLeft} Due`);

  // Card sub-tab
  const cardTab = flProjGetCardTab(p.id);
  const tabs = [
    {k:'general', label:'GENERAL'},
    {k:'info',    label:'MORE INFO'},
    {k:'fin',     label:'FINANCIALS'}
  ];
  const tabBar = tabs.map(t=>{
    const on = t.k===cardTab;
    return `<button onclick="event.stopPropagation();flProjSetCardTab('${p.id}','${t.k}')" style="background:none;border:none;padding:8px 0;margin-right:24px;font-size:11px;font-weight:700;letter-spacing:.08em;color:${on?P.navy:P.ink3};border-bottom:2px solid ${on?P.navy:'transparent'};cursor:pointer">${t.label}</button>`;
  }).join('');

  const actionIcons = `
    <div style="display:flex;align-items:center;gap:4px">
      <button onclick="event.stopPropagation();flProjOpen('${p.id}')" title="View detail" style="background:none;border:none;cursor:pointer;padding:6px;color:${P.ink3};border-radius:6px">${flProjIcon('camera',16,P.ink3)}</button>
      <button onclick="event.stopPropagation();flProjOpen('${p.id}')" title="Plan" style="background:none;border:none;cursor:pointer;padding:6px;color:${P.ink3};border-radius:6px">${flProjIcon('clipboard',16,P.ink3)}</button>
      <button onclick="event.stopPropagation();flProjOpenEdit('${p.id}')" title="Edit" style="background:none;border:none;cursor:pointer;padding:6px;color:${P.ink3};border-radius:6px">${flProjIcon('edit',16,P.ink3)}</button>
      <div title="${(p.vendorVisits||[]).length} vendor visits" style="position:relative;width:28px;height:28px;border-radius:50%;background:${P.bg};border:1px solid ${P.line};display:flex;align-items:center;justify-content:center;color:${P.ink2}">${flProjIcon('users',14,P.ink2)}${(p.vendorVisits||[]).length?`<span style="position:absolute;top:-4px;right:-4px;background:${P.blue};color:white;font-size:9px;font-weight:700;width:16px;height:16px;border-radius:50%;display:flex;align-items:center;justify-content:center">${(p.vendorVisits||[]).length}</span>`:''}</div>
      <button onclick="event.stopPropagation();flProjOpen('${p.id}')" title="Expand" style="background:none;border:none;cursor:pointer;padding:6px;color:${P.ink3};border-radius:6px">${flProjIcon('arrowRight',16,P.ink3)}</button>
    </div>`;

  // Per-tab body
  let body = '';
  if(cardTab==='general')      body = flProjRenderTimelineGeneral(p, kids);
  else if(cardTab==='info')    body = flProjRenderTimelineInfo(p, boat);
  else                          body = flProjRenderTimelineFin(p, kids);

  // Side panel
  const sidePanel = `
    <div style="background:${sideTone.bg};padding:18px 16px;display:flex;flex-direction:column;align-items:center;gap:14px;min-height:100%">
      <div style="background:white;border:2px solid ${sideTone.accent};border-radius:16px;padding:10px 12px;text-align:center;min-width:96px">
        <div style="display:flex;justify-content:center;color:${sideTone.accent};margin-bottom:4px">${flProjIcon('clock',16,sideTone.accent)}</div>
        <div style="font-size:14px;font-weight:800;color:${sideTone.ink};line-height:1">${dueText}</div>
      </div>
      <div style="text-align:center">
        <div style="font-size:14px;font-weight:700;color:${sideTone.ink};font-variant-numeric:tabular-nums">${done}/${kids.length||'—'}</div>
        <div style="font-size:11px;color:${sideTone.ink};opacity:.7;margin-top:1px">Completed MJs</div>
      </div>
      <div style="width:60%;height:1px;background:${sideTone.ink};opacity:.25"></div>
      <div style="text-align:center">
        <div style="font-size:11px;color:${sideTone.ink};opacity:.8;font-weight:600">Complete by</div>
        <div style="font-size:13px;font-weight:700;color:${sideTone.ink};margin-top:2px;font-variant-numeric:tabular-nums">${p.planTo||'Open'}</div>
      </div>
    </div>`;

  // Title bar
  const titleBar = `
    <div style="padding:18px 22px 0">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:14px">
        <div style="flex:1;min-width:0">
          <div style="font-size:11px;color:${P.ink3};font-weight:600;letter-spacing:.06em;text-transform:uppercase;margin-bottom:4px">${p.no} · ${boat?boat.name:'?'}</div>
          <div style="font-size:18px;font-weight:700;color:${P.navy};letter-spacing:-.3px;line-height:1.3">${p.name}</div>
        </div>
        ${actionIcons}
      </div>
      <div style="display:flex;align-items:center;border-bottom:1px solid ${P.line};margin-top:14px;padding-bottom:0">
        ${tabBar}
      </div>
    </div>`;

  return `
    <div style="background:white;border:1px solid ${P.line};border-radius:18px;overflow:hidden;box-shadow:${P.shadow};display:grid;grid-template-columns:140px 1fr">
      ${sidePanel}
      <div style="display:flex;flex-direction:column">
        ${titleBar}
        <div style="padding:18px 22px 22px">${body}</div>
      </div>
    </div>`;
}

// ── GENERAL tab body: TODAY line + horizontal day swimlane ──
function flProjRenderTimelineGeneral(p, kids){
  const P = PROJ_PALETTE;
  const today = new Date(TODAY_STR);
  const days = [];
  for(let i=0; i<_projTimelineDays; i++){
    const d = new Date(today);
    d.setDate(today.getDate()+i);
    days.push(d);
  }
  const MON_SHORT = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
  // Helper: MJs active on a given day
  const mjsOn = (date)=>{
    const ds = date.toISOString().slice(0,10);
    return kids.filter(m=>{
      const ms = m.startDate || '';
      const me = m.endDate || p.planTo || ds;
      return ms<=ds && me>=ds;
    });
  };
  const overdueCount = kids.filter(m=>{
    if(m.status==='done') return false;
    const me = m.endDate || p.planTo;
    return me && me<today.toISOString().slice(0,10);
  }).length;
  // Today marker + day columns
  const dayCols = days.map((d,i)=>{
    const ds = d.toISOString().slice(0,10);
    const isToday = i===0;
    const list = mjsOn(d);
    return `<div style="min-width:200px;flex-shrink:0">
      <div style="background:${P.bg};border:1px solid ${P.line};border-radius:10px 10px 0 0;padding:6px 10px;text-align:center;font-size:11px;font-weight:700;color:${P.ink2};letter-spacing:.06em">${MON_SHORT[d.getMonth()]} ${d.getDate()}</div>
      <div style="border:1px solid ${P.line};border-top:none;border-radius:0 0 10px 10px;padding:10px;min-height:140px;display:flex;flex-direction:column;gap:8px">
        ${list.length ? list.map(m=>{
          const stColor = m.status==='done'?P.mintInk : m.status==='inprogress'?P.amber : P.blue;
          return `<div onclick="event.stopPropagation();_selMaintId='${m.id}';nav(document.querySelector('[data-view=\\'fl-maintenance\\']'))" style="cursor:pointer;padding:8px;background:white;border:1px solid ${P.line};border-radius:8px;border-left:3px solid ${stColor}">
            <div style="display:flex;align-items:flex-start;gap:6px;margin-bottom:6px">
              <span style="color:${stColor};flex-shrink:0;margin-top:1px">${flProjIcon('wrench',12,stColor)}</span>
              <div style="font-size:11px;font-weight:600;color:${P.ink};line-height:1.3">${(m.title||'').slice(0,40)}${(m.title||'').length>40?'…':''}</div>
            </div>
            <div style="font-size:10px;color:${P.ink3};margin-bottom:4px">${m.startDate||''}${m.endDate?` → ${m.endDate}`:''}</div>
            ${m.location?`<div style="display:flex;align-items:center;gap:5px;margin-bottom:4px">
              <span style="width:18px;height:18px;border-radius:50%;background:${P.blueSoft};color:${P.blue};display:flex;align-items:center;justify-content:center;flex-shrink:0">${flProjIcon('hardHat',10,P.blue)}</span>
              <span style="font-size:10px;color:${P.ink2}">${m.location}</span>
            </div>`:''}
            <div style="font-size:9.5px;color:${P.ink3};font-weight:600;letter-spacing:.04em">NOTES (${(m.progressLog||[]).length})</div>
          </div>`;
        }).join('') : `<div style="color:${P.ink4};font-size:11px;text-align:center;padding:30px 0">—</div>`}
      </div>
    </div>`;
  }).join('<div style="flex-shrink:0;display:flex;align-items:center;justify-content:center;min-width:18px;color:'+P.ink4+'">↔</div>');

  return `
    <div style="position:relative">
      <div style="display:flex;align-items:center;gap:14px;margin-bottom:10px">
        <div style="display:flex;align-items:center;gap:5px">
          <div style="width:2px;height:16px;background:${P.blue};border-radius:1px"></div>
          <span style="font-size:11px;font-weight:700;color:${P.blue};letter-spacing:.08em">TODAY</span>
        </div>
      </div>
      <div style="position:relative;overflow-x:auto;overflow-y:visible;padding-bottom:8px">
        <div style="display:flex;align-items:stretch;gap:0;min-width:max-content">
          ${dayCols}
        </div>
      </div>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px">
        ${overdueCount?`<button onclick="event.stopPropagation();_selProjId='${p.id}';flRenderProjects()" style="background:${P.red};color:white;border:none;border-radius:14px;padding:6px 14px;font-size:11px;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:6px">${flProjIcon('clock',12,'white')} ${overdueCount} DUE</button>`:`<span></span>`}
        <button onclick="event.stopPropagation();flProjCreateMJ('${p.id}')" style="background:white;border:1px dashed ${P.line};color:${P.ink2};border-radius:14px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">${flProjIcon('plus',12,P.ink2)} Add MJ</button>
      </div>
    </div>`;
}

// ── MORE INFO tab body ──
function flProjRenderTimelineInfo(p, boat){
  const P = PROJ_PALETTE;
  const budget = p.plannedBudget||0;
  const approveBadge = budget ? `<div style="display:inline-flex;align-items:center;gap:6px;background:#ECFDF5;color:${P.mintInk};border:1px solid #A7F3D0;border-radius:20px;padding:5px 14px;font-size:12px;font-weight:600">${flProjIcon('checkCircle',14,P.mintInk)} Budget approved · ฿${budget.toLocaleString()}</div>` : `<div style="display:inline-flex;align-items:center;gap:6px;background:${P.amberSoft};color:${P.amberInk};border:1px solid #FDE68A;border-radius:20px;padding:5px 14px;font-size:12px;font-weight:600">${flProjIcon('alert',14,P.amberInk)} No budget set</div>`;
  const phases = flProjPhasesFor(p);
  const cIdx = flProjCurrentPhaseIdx(p);
  const curPhase = phases[cIdx]||phases[0];
  return `
    <div style="display:flex;flex-direction:column;gap:14px">
      ${approveBadge}
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px">
        <div>
          <div style="display:flex;align-items:center;gap:6px;color:${P.ink2};font-size:11px;margin-bottom:6px">${flProjIcon('hardHat',13,P.ink2)} <span style="font-weight:600">${boat?boat.name:'?'}</span></div>
          <div style="font-size:10px;color:${P.ink3}">${p.type==='drydock'?'Drydock':p.type==='overhaul'?'Overhaul':p.type==='refit'?'Refit':'Scheduled'} project</div>
        </div>
        <div>
          <div style="display:flex;align-items:center;gap:6px;color:${P.ink2};font-size:11px;margin-bottom:6px">${flProjIcon('folder',13,P.ink2)} <span style="font-weight:600">${p.vendor||'No vendor set'}</span></div>
          <div style="font-size:10px;color:${P.ink3}">Vendor / location</div>
        </div>
        <div>
          <div style="display:flex;align-items:center;gap:6px;color:${P.ink2};font-size:11px;margin-bottom:6px">${flProjIcon('target',13,P.ink2)} <span style="font-weight:600">${curPhase.label}</span></div>
          <div style="font-size:10px;color:${P.ink3}">Current phase · ${cIdx+1}/${phases.length}</div>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:auto auto auto;gap:14px;align-items:start">
        <div>
          <div style="font-size:10px;color:${P.ink3};letter-spacing:.6px;text-transform:uppercase;font-weight:700;margin-bottom:4px">Created by</div>
          <div style="display:flex;align-items:center;gap:8px">
            <div style="width:24px;height:24px;border-radius:50%;background:${P.blueSoft};color:${P.blue};display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700">${(p.createdBy||'?').slice(0,1).toUpperCase()}</div>
            <span style="font-size:12px;color:${P.ink};font-weight:600">${p.createdBy||'system'}</span>
          </div>
        </div>
        <div>
          <div style="font-size:10px;color:${P.ink3};letter-spacing:.6px;text-transform:uppercase;font-weight:700;margin-bottom:4px">Project lead</div>
          <div style="display:flex;align-items:center;gap:8px">
            <div style="width:24px;height:24px;border-radius:50%;background:${P.amberSoft};color:${P.amber};display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700">L</div>
            <span style="font-size:12px;color:${P.ink};font-weight:600">Operations</span>
          </div>
        </div>
        <div>
          <div style="font-size:10px;color:${P.ink3};letter-spacing:.6px;text-transform:uppercase;font-weight:700;margin-bottom:4px">Vendor contacts</div>
          <div style="display:flex;align-items:center;gap:4px">
            ${(p.vendorVisits||[]).slice(0,4).map((v,i)=>`<div style="width:24px;height:24px;border-radius:50%;background:${P.bg};border:1px solid ${P.line};color:${P.ink2};display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700" title="${v.vendor}">${(v.vendor||'?').slice(0,1).toUpperCase()}</div>`).join('')}
            ${(p.vendorVisits||[]).length>4?`<span style="font-size:11px;color:${P.ink3};margin-left:4px">+${(p.vendorVisits||[]).length-4}</span>`:''}
            ${!(p.vendorVisits||[]).length?`<span style="font-size:11px;color:${P.ink3}">no visits logged</span>`:''}
          </div>
        </div>
      </div>
    </div>`;
}

// ── FINANCIALS tab body ──
function flProjRenderTimelineFin(p, kids){
  const P = PROJ_PALETTE;
  const cb = flProjCostBreakdown(p.id);
  const memos = (FL_MEMOS||[]).filter(mo=>kids.some(k=>k.id===mo.maintId));
  const paid = memos.filter(m=>m.status==='paid').reduce((s,m)=>s+(m.amount||0),0);
  const dueMemos = memos.filter(m=>m.status==='pending'||m.status==='approved'||m.status==='received');
  const due = dueMemos.reduce((s,m)=>s+(m.amount||0),0);
  const budget = p.plannedBudget||0;
  const total = cb.total;
  const partsPct = total ? Math.round(cb.parts/total*100) : 0;
  const labourPct = total ? Math.round(cb.labour/total*100) : 0;
  return `
    <div style="display:flex;flex-direction:column;gap:14px">
      <div style="display:flex;align-items:baseline;gap:18px;flex-wrap:wrap">
        <div>
          <span style="font-size:11px;color:${P.ink2};font-weight:600">Total Spent : </span>
          <span style="font-size:14px;font-weight:700;color:${P.navy}">฿${total.toLocaleString()}</span>
          <span style="font-size:11px;color:${P.ink3}"> (${memos.length} memos)</span>
        </div>
        <span style="width:6px;height:6px;border-radius:50%;background:${P.ink4}"></span>
        <div>
          <span style="font-size:11px;color:${P.ink2};font-weight:600">Planned Budget : </span>
          <span style="font-size:14px;font-weight:700;color:${P.navy}">${budget?'฿'+budget.toLocaleString():'—'}</span>
          <span style="font-size:11px;color:${P.ink3}"> (${kids.length} MJs)</span>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
        <div style="background:#DCFCE7;border-radius:12px;padding:14px 18px"><div style="font-size:15px;font-weight:700;color:${P.mintInk}">฿${paid.toLocaleString()} Paid <span style="font-weight:500;color:#15803D">(${memos.filter(m=>m.status==='paid').length} Invoices)</span></div></div>
        <div style="background:#FED7AA;border-radius:12px;padding:14px 18px"><div style="font-size:15px;font-weight:700;color:#9A3412">฿${due.toLocaleString()} Due <span style="font-weight:500;color:#C2410C">(${dueMemos.length} Invoices)</span></div></div>
      </div>
      <div>
        <div style="font-size:10px;color:${P.ink3};letter-spacing:.6px;text-transform:uppercase;font-weight:700;margin-bottom:6px">Add Notes</div>
        <button style="background:none;border:1px dashed ${P.line};color:${P.ink2};border-radius:10px;padding:8px 14px;font-size:12px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">${flProjIcon('fileText',14,P.ink2)} Add note</button>
      </div>
      <div>
        <div style="font-size:10px;color:${P.ink3};letter-spacing:.6px;text-transform:uppercase;font-weight:700;margin-bottom:8px">Project Hard Costs</div>
        <div style="display:flex;flex-direction:column;gap:6px">
          <div style="display:grid;grid-template-columns:1.5fr auto auto;gap:14px;font-size:12px;color:${P.ink2};padding:6px 0;border-bottom:1px solid ${P.line}"><span>Parts cost</span><span style="font-weight:700;color:${P.navy};font-variant-numeric:tabular-nums">฿${cb.parts.toLocaleString()}</span><span style="color:${P.ink3};font-variant-numeric:tabular-nums">${partsPct}%</span></div>
          <div style="display:grid;grid-template-columns:1.5fr auto auto;gap:14px;font-size:12px;color:${P.ink2};padding:6px 0;border-bottom:1px solid ${P.line}"><span>Labour cost</span><span style="font-weight:700;color:${P.navy};font-variant-numeric:tabular-nums">฿${cb.labour.toLocaleString()}</span><span style="color:${P.ink3};font-variant-numeric:tabular-nums">${labourPct}%</span></div>
          <div style="display:grid;grid-template-columns:1.5fr auto auto;gap:14px;font-size:12px;color:${P.ink2};padding:6px 0"><span>Memos (mixed)</span><span style="font-weight:700;color:${P.navy};font-variant-numeric:tabular-nums">฿${cb.memos.toLocaleString()}</span><span style="color:${P.ink3};font-variant-numeric:tabular-nums">${total?Math.round(cb.memos/total*100):0}%</span></div>
        </div>
      </div>
    </div>`;
}

// ═══════════════ GANTT VIEW (original bar chart) ═══════════════
function flProjRenderGantt(allProjects){
  const P = PROJ_PALETTE;
  // Build month range: from earliest planFrom (or today - 1m) to latest planTo + buffer
  const today = new Date(TODAY_STR);
  const monthsBack = 1;
  const monthsForward = Math.max(_projTimelineMonths, 6);
  const start = new Date(today.getFullYear(), today.getMonth()-monthsBack, 1);
  const end   = new Date(today.getFullYear(), today.getMonth()+monthsForward, 0);
  const totalDays = Math.ceil((end-start)/86400000) + 1;
  const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  // Build month columns
  const months = [];
  let cursor = new Date(start);
  while(cursor<=end){
    const y = cursor.getFullYear(), m = cursor.getMonth();
    const dim = new Date(y,m+1,0).getDate();
    const monthStart = new Date(y,m,1);
    const offset = Math.ceil((monthStart-start)/86400000);
    months.push({label:`${MON[m]} ${String(y).slice(2)}`, days:dim, offset, y, m});
    cursor.setMonth(cursor.getMonth()+1);
  }
  // Filter projects with valid date ranges + overlap window
  const inWindow = allProjects.filter(p=>{
    if(!p.planFrom||!p.planTo) return false;
    return p.planFrom<=end.toISOString().slice(0,10) && p.planTo>=start.toISOString().slice(0,10);
  });
  if(!inWindow.length){
    return `<div style="background:white;border:1px dashed ${P.line};border-radius:18px;padding:48px;text-align:center;color:${P.ink3};font-size:13px;box-shadow:${P.shadow}">
      <div style="display:inline-flex;width:48px;height:48px;border-radius:50%;background:${P.bg};color:${P.ink3};align-items:center;justify-content:center;margin-bottom:12px">${flProjIcon('ganttChart',22,P.ink3)}</div>
      <div>No projects with date range overlapping this window.</div>
      <div style="font-size:11px;color:${P.ink4};margin-top:6px">${start.toISOString().slice(0,10)} → ${end.toISOString().slice(0,10)}</div>
    </div>`;
  }
  // Group by boat
  const byBoat = {};
  inWindow.forEach(p=>{
    if(!byBoat[p.boatId]) byBoat[p.boatId] = [];
    byBoat[p.boatId].push(p);
  });
  // Bar style by status — match Timeline side-panel tone palette (BuildAxis style)
  const barStyle = (status)=>{
    if(status==='completed')  return {bg:'#DCFCE7', border:'#22C55E', ink:'#15803D', icon:'checkCircle'};
    if(status==='inprogress') return {bg:'#FEEDE8', border:'#F97316', ink:'#C2410C', icon:'wrench'};
    if(status==='on_hold')    return {bg:'#FEF3CD', border:'#F59E0B', ink:'#92400E', icon:'pause'};
    if(status==='cancelled')  return {bg:'#FEE7E7', border:'#EF4444', ink:'#B91C1C', icon:'xCircle'};
    return {bg:'#E0E7FF', border:'#6366F1', ink:'#3730A3', icon:'calendar'};
  };
  // Today marker position
  const todayOffset = Math.ceil((today-start)/86400000);
  const todayPct = todayOffset/totalDays*100;

  // Header: month columns
  const monthHeader = months.map(mo=>`
    <div style="flex:${mo.days};text-align:center;padding:10px 6px;font-size:10px;font-weight:700;color:${P.ink3};border-right:1px solid ${P.line};letter-spacing:.08em;text-transform:uppercase">${mo.label}</div>
  `).join('');

  // Boat rows
  const rows = Object.keys(byBoat).map((bId, rowIdx)=>{
    const boat = BOATS.find(b=>b.id===bId);
    const projs = byBoat[bId].sort((a,b)=>(a.planFrom||'').localeCompare(b.planFrom||''));
    const bars = projs.map(p=>{
      const ps = new Date(p.planFrom);
      const pe = new Date(p.planTo);
      const startOffset = Math.max(0, Math.ceil((ps-start)/86400000));
      const endOffset   = Math.min(totalDays, Math.ceil((pe-start)/86400000)+1);
      const leftPct = startOffset/totalDays*100;
      const widthPct = Math.max(1, (endOffset-startOffset)/totalDays*100);
      const s = barStyle(p.status);
      const label = `${p.no} · ${p.name.length>34?p.name.slice(0,32)+'…':p.name}`;
      const showIcon = widthPct > 3;
      return `<div onclick="flProjOpen('${p.id}')" style="position:absolute;left:${leftPct}%;width:${widthPct}%;top:8px;bottom:8px;background:${s.bg};border:1px solid ${s.border};border-radius:10px;color:${s.ink};font-size:11px;padding:0 10px;cursor:pointer;display:flex;align-items:center;gap:6px;overflow:hidden;white-space:nowrap;font-weight:600;transition:all .15s;box-shadow:0 1px 2px rgba(15,23,42,.05)" onmouseover="this.style.transform='translateY(-1px)';this.style.boxShadow='0 4px 8px rgba(15,23,42,.08)'" onmouseout="this.style.transform='translateY(0)';this.style.boxShadow='0 1px 2px rgba(15,23,42,.05)'" title="${p.name} · ${p.planFrom} → ${p.planTo} · ${p.status}">
        ${showIcon?`<span style="flex-shrink:0;display:inline-flex">${flProjIcon(s.icon,12,s.border,2)}</span>`:''}
        <span style="overflow:hidden;text-overflow:ellipsis">${label}</span>
      </div>`;
    }).join('');
    const rowBg = rowIdx%2===0 ? 'white' : '#FAFBFD';
    const isGen = !boat;   // null boatId = General / non-vessel project
    const avatarColor = isGen ? '#64748B' : flBoatAvatarColor(boat);
    const initials = isGen ? flProjIcon('clipboard',17,'white',2) : flBoatInitials(boat.name);
    const _genVends = isGen ? [...new Set(projs.map(p=>p.vendor).filter(Boolean))] : [];
    const meta = isGen ? `${projs.length} project${projs.length===1?'':'s'}${_genVends.length?` · ${_genVends.join(' · ')}`:' · ไม่เกี่ยวกับเรือ'}` : flBoatMeta(boat);
    const rowName = isGen ? 'General' : boat.name;
    return `<div style="display:grid;grid-template-columns:200px 1fr;border-bottom:1px solid ${P.line};min-height:58px;background:${rowBg}">
      <div style="padding:12px 16px;border-right:1px solid ${P.line};display:flex;align-items:center;gap:11px">
        <div style="width:36px;height:36px;border-radius:50%;background:${avatarColor};color:white;font-size:11px;display:flex;align-items:center;justify-content:center;font-weight:700;flex-shrink:0;letter-spacing:.02em">${initials}</div>
        <div style="min-width:0;flex:1">
          <div style="font-size:13px;font-weight:700;color:${P.navy};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${rowName}</div>
          <div style="font-size:10px;color:${P.ink3};margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${meta||`${projs.length} project${projs.length===1?'':'s'}`}</div>
        </div>
      </div>
      <div style="position:relative">${bars}</div>
    </div>`;
  }).join('');

  // Legend chips (BuildAxis style)
  const legendChip = (label, bg, border, ink, icon)=>`<span style="display:inline-flex;align-items:center;gap:6px;background:${bg};color:${ink};border:1px solid ${border};border-radius:14px;padding:3px 10px;font-size:10px;font-weight:600">${flProjIcon(icon,11,border,2)} ${label}</span>`;

  return `
    <div style="background:white;border:1px solid ${P.line};border-radius:18px;overflow:hidden;box-shadow:${P.shadow}">
      <!-- Top header bar -->
      <div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid ${P.line};background:linear-gradient(180deg, #FAFBFD 0%, white 100%)">
        <div>
          <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px">${flProjIcon('ganttChart',13,P.blue)} Gantt Overview</div>
          <div style="font-size:14px;color:${P.navy};font-weight:700;margin-top:4px;font-variant-numeric:tabular-nums">${(function(){const ks=Object.keys(byBoat);const g=ks.filter(k=>!BOATS.find(b=>b.id===k)).length;const rb=ks.length-g;return `${rb} boat${rb===1?'':'s'}${g?` · ${g} general`:''}`;})()} · ${inWindow.length} projects</div>
        </div>
        <div style="display:flex;gap:6px;align-items:center">
          <button onclick="_projTimelineMonths=Math.max(3,_projTimelineMonths-3);flRenderProjects()" style="background:white;border:1px solid ${P.line};color:${P.ink2};border-radius:10px;padding:6px 12px;font-size:11px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:4px">${flProjIcon('arrowLeft',12,P.ink2)} 3m</button>
          <span style="font-size:10px;color:${P.ink3};padding:0 4px">${monthsBack}m back · ${monthsForward}m fwd</span>
          <button onclick="_projTimelineMonths+=3;flRenderProjects()" style="background:white;border:1px solid ${P.line};color:${P.ink2};border-radius:10px;padding:6px 12px;font-size:11px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:4px">3m ${flProjIcon('arrowRight',12,P.ink2)}</button>
        </div>
      </div>

      <!-- Month header strip -->
      <div style="display:grid;grid-template-columns:200px 1fr;border-bottom:1px solid ${P.line};background:${P.bg}">
        <div style="padding:10px 16px;font-size:10px;font-weight:700;color:${P.ink3};border-right:1px solid ${P.line};letter-spacing:.08em;text-transform:uppercase;display:flex;align-items:center;gap:6px">${flProjIcon('hardHat',12,P.ink3)} Boat <span style="background:white;color:${P.ink3};border:1px solid ${P.line};border-radius:8px;padding:1px 7px;font-size:9px;font-weight:700;margin-left:4px">${Object.keys(byBoat).filter(k=>BOATS.find(b=>b.id===k)).length}</span></div>
        <div style="display:flex">${monthHeader}</div>
      </div>

      <!-- Rows with today marker overlay -->
      <div style="position:relative">
        ${rows}
        ${todayPct>=0 && todayPct<=100 ? `
          <div style="position:absolute;left:calc(200px + (100% - 200px) * ${todayPct}/100);top:0;bottom:0;width:0;pointer-events:none">
            <div style="position:absolute;top:0;bottom:0;width:2px;background:${P.red};opacity:.45;transform:translateX(-1px)"></div>
            <div style="position:absolute;top:-1px;left:-22px;background:${P.red};color:white;font-size:9px;font-weight:700;padding:2px 8px;border-radius:0 0 8px 8px;letter-spacing:.06em">TODAY</div>
          </div>
        ` : ''}
      </div>

      <!-- Footer legend bar -->
      <div style="padding:14px 20px;border-top:1px solid ${P.line};background:${P.bg};display:flex;align-items:center;gap:8px;flex-wrap:wrap">
        ${legendChip('Scheduled',   '#E0E7FF', '#6366F1', '#3730A3', 'calendar')}
        ${legendChip('In Progress', '#FEEDE8', '#F97316', '#C2410C', 'wrench')}
        ${legendChip('On Hold',     '#FEF3CD', '#F59E0B', '#92400E', 'pause')}
        ${legendChip('Completed',   '#DCFCE7', '#22C55E', '#15803D', 'checkCircle')}
        ${legendChip('Cancelled',   '#FEE7E7', '#EF4444', '#B91C1C', 'xCircle')}
        <span style="margin-left:auto;display:inline-flex;align-items:center;gap:6px;font-size:10px;color:${P.ink2};font-weight:600">
          <span style="display:inline-block;width:2px;height:14px;background:${P.red};opacity:.45;border-radius:1px"></span>
          Today line
        </span>
      </div>
    </div>`;
}

function flProjKpiCard(label, val, ink, soft, sub){
  const P = PROJ_PALETTE;
  return `<div style="background:white;border-radius:14px;padding:11px 13px;border:1px solid ${P.line}">
    <div style="font-size:10px;color:${P.ink3}">${label}</div>
    <div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="background:${ink};color:white;padding:2px 10px;border-radius:14px;font-size:14px;font-weight:700">${val}</span></div>
    <div style="font-size:11px;color:${ink};margin-top:7px;font-weight:600">${sub}</div>
  </div>`;
}

function flProjStatusPillStyle(status, P){
  P = P || PROJ_PALETTE;
  if(status==='completed') return {bg:P.mintSoft, color:P.mintInk, label:'COMPLETED'};
  if(status==='inprogress') return {bg:P.amberSoft, color:P.amber, label:'IN PROGRESS'};
  if(status==='on_hold') return {bg:'#FFF4E1', color:'#996A14', label:'ON HOLD'};
  if(status==='cancelled') return {bg:P.redSoft, color:P.red, label:'CANCELLED'};
  return {bg:P.blueSoft, color:P.blue, label:'SCHEDULED'};
}

function flProjRowCard(p){
  const P = PROJ_PALETTE;
  const kids = flProjChildMJs(p.id);
  const openKids = kids.filter(m=>m.status!=='done').length;
  const cost = flProjCalcCost(p.id);
  const boatName = flProjBoatName(p);
  const sp = flProjStatusPillStyle(p.status, P);
  const statusPill = `<span style="background:${sp.bg};color:${sp.color};padding:3px 10px;border-radius:12px;font-size:10px;font-weight:700">${sp.label}</span>`;
  const health = flProjHealth(p);
  const healthPill = `<span style="background:${health.bg};color:${health.color};padding:3px 8px;border-radius:10px;font-size:9px;font-weight:700" title="Health ${health.score}/100">${health.label}</span>`;
  const budget = p.plannedBudget||0;
  const variance = cost - budget;
  const varianceColor = budget ? (cost>budget?P.red:P.mintInk) : P.ink3;
  const variancePct = budget ? Math.round(variance/budget*100) : 0;
  // Phase chip
  const phases = flProjPhasesFor(p);
  const cIdx = flProjCurrentPhaseIdx(p);
  const phaseChip = (cIdx>=0 && phases[cIdx]) ? `<span style="background:${P.bg};color:${P.ink2};padding:2px 8px;border-radius:8px;font-size:9px;font-weight:600;letter-spacing:.02em">Phase ${cIdx+1}/${phases.length} · ${phases[cIdx].label}</span>` : '';
  const dur = (function(){
    if(!p.planFrom) return '—';
    const a = new Date(p.planFrom);
    const b = new Date(p.planTo||p.actualTo||TODAY_STR);
    const days = Math.max(1, Math.ceil((b-a)/86400000));
    return `${days}d`;
  })();
  const typeBadge = (function(){
    const map = {drydock:'DD', overhaul:'OV', refit:'RF', scheduled:'SC', other:'PR'};
    return map[p.type]||'PR';
  })();
  // Icon color by type
  const typeColor = (function(){
    if(p.type==='drydock')  return {bg:'#EEF3FF', ink:P.blue};
    if(p.type==='overhaul') return {bg:'#FFF7E6', ink:P.amberInk};
    if(p.type==='refit')    return {bg:'#F3E8FF', ink:P.purple};
    if(p.type==='scheduled')return {bg:P.mintSoft, ink:P.mintInk};
    return {bg:P.bg, ink:P.ink2};
  })();
  return `
    <div onclick="flProjOpen('${p.id}')" style="background:white;border:1px solid ${P.line};border-radius:16px;padding:16px 18px;cursor:pointer;display:grid;grid-template-columns:auto 2.2fr 1.3fr 0.9fr 0.9fr 1.1fr auto;gap:14px;align-items:center;transition:all .15s;box-shadow:${P.shadow}" onmouseover="this.style.boxShadow='${P.shadowLg}';this.style.transform='translateY(-1px)'" onmouseout="this.style.boxShadow='${P.shadow}';this.style.transform='translateY(0)'">
      <div style="width:44px;height:44px;border-radius:12px;background:${typeColor.bg};color:${typeColor.ink};display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;letter-spacing:.04em">${typeBadge}</div>
      <div>
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <span style="font-size:13px;font-weight:700;color:${P.navy}">${p.name}</span>
          ${healthPill}
        </div>
        <div style="font-size:11px;color:${P.ink3};margin-top:2px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
          <span>${p.no} · ${boatName} · ${p.vendor||'—'}</span>
          ${phaseChip}
        </div>
      </div>
      <div>
        <div style="font-size:10px;color:${P.ink4};text-transform:uppercase;letter-spacing:.6px">Schedule</div>
        <div style="font-size:11px;color:${P.ink2};margin-top:2px;font-variant-numeric:tabular-nums">${p.planFrom||'—'} → ${p.planTo||`<span style="color:${P.blue};font-weight:600">Open</span>`}</div>
        <div style="font-size:10px;color:${P.ink3}">${p.planTo?dur:'open-ended'} · ${kids.length} MJ${openKids?` (${openKids} open)`:''}</div>
      </div>
      <div>
        <div style="font-size:10px;color:${P.ink4};text-transform:uppercase;letter-spacing:.6px">Budget</div>
        <div style="font-size:13px;color:${P.navy};font-weight:700;margin-top:1px;font-variant-numeric:tabular-nums">${budget?`฿${(budget/1000).toFixed(0)}K`:'—'}</div>
      </div>
      <div>
        <div style="font-size:10px;color:${P.ink4};text-transform:uppercase;letter-spacing:.6px">Actual</div>
        <div style="font-size:13px;color:${P.navy};font-weight:700;margin-top:1px;font-variant-numeric:tabular-nums">${cost?`฿${(cost/1000).toFixed(0)}K`:'฿0'}</div>
      </div>
      <div>
        <div style="font-size:10px;color:${P.ink4};text-transform:uppercase;letter-spacing:.6px">Variance</div>
        <div style="font-size:13px;color:${varianceColor};font-weight:700;margin-top:1px;font-variant-numeric:tabular-nums">${budget?`${variance>0?'+':''}฿${Math.abs(variance/1000).toFixed(0)}K`:'—'}</div>
        <div style="font-size:10px;color:${varianceColor}">${budget?`${variance>0?'+':''}${variancePct}%`:'no budget'}</div>
      </div>
      <div>${statusPill}</div>
    </div>`;
}

// ── Detail view ──
let _projDetailTab = 'overview'; // overview | plan | docs | memos | activity

function flProjOpen(id){ _selProjId=id; _projDetailTab='overview'; flRenderProjects(); }
function flProjCloseDetail(){ _selProjId=null; flRenderProjects(); }
function flProjSwitchTab(t){ _projDetailTab=t; flRenderProjects(); }

function flProjRenderDetail(id){
  const P = PROJ_PALETTE;
  const p = flProjGetById(id);
  const wrap = document.getElementById('fl-proj-mount');
  if(!wrap) return;
  if(!p){ wrap.innerHTML = `<div style="padding:40px;color:${P.ink3}">Project not found. <button onclick="flProjCloseDetail()" style="background:none;border:none;color:${P.navy};cursor:pointer;font-weight:600">← Back</button></div>`; return; }
  const kids = flProjChildMJs(p.id);
  const openKids = kids.filter(m=>m.status!=='done');
  const cost = flProjCalcCost(p.id);
  const boat = BOATS.find(b=>b.id===p.boatId);
  const boatName = !p.boatId ? 'General · ไม่เกี่ยวกับเรือ' : (boat?boat.name:'(unknown)');
  const sp = flProjStatusPillStyle(p.status, P);
  const statusPill = `<span style="background:${sp.bg};color:${sp.color};padding:4px 12px;border-radius:14px;font-size:11px;font-weight:700">${sp.label}</span>`;
  const health = flProjHealth(p);
  const healthPill = `<span style="background:${health.bg};color:${health.color};padding:4px 12px;border-radius:14px;font-size:11px;font-weight:700" title="Health score ${health.score}/100">${health.label} · ${health.score}</span>`;
  const btnBase = 'border-radius:14px;padding:8px 16px;font-size:12px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:7px';
  const editBtn = `<button onclick="flProjOpenEdit('${p.id}')" style="background:white;border:1px solid ${P.line};color:${P.ink2};${btnBase};box-shadow:${P.shadow}">${flProjIcon('edit',13,P.ink2)} Edit</button>`;
  const cancelBtn = `<button onclick="flProjCancel('${p.id}')" style="background:white;border:1px solid #FECACA;color:${P.red};${btnBase};box-shadow:${P.shadow}">${flProjIcon('xCircle',13,P.red)} Cancel</button>`;
  const holdBtn   = `<button onclick="flProjHold('${p.id}')" style="background:white;border:1px solid #FDE68A;color:${P.amberInk};${btnBase};box-shadow:${P.shadow}">${flProjIcon('pause',13,P.amberInk)} Hold</button>`;
  const resumeBtn = `<button onclick="flProjResume('${p.id}')" style="background:${P.amber};color:white;border:none;${btnBase};box-shadow:0 2px 6px rgba(245,158,11,.3)">${flProjIcon('play',13,'white')} Resume</button>`;
  const reopenBtn = `<button onclick="flProjReopen('${p.id}')" style="background:${P.blue};color:white;border:none;${btnBase};box-shadow:0 2px 6px rgba(58,111,247,.3)">${flProjIcon('refresh',13,'white')} Reopen</button>`;
  const startBtn  = `<button onclick="flProjStart('${p.id}')" style="background:${P.amber};color:white;border:none;${btnBase};box-shadow:0 2px 6px rgba(245,158,11,.3)">${flProjIcon('play',13,'white')} Start Project</button>`;
  const completeBtn = `<button onclick="flProjMarkComplete('${p.id}')" style="background:${P.mintInk};color:white;border:none;${btnBase};box-shadow:0 2px 6px rgba(16,185,129,.3)">${flProjIcon('check',13,'white')} Mark Complete${openKids.length?` (closes ${openKids.length} MJ)`:''}</button>`;
  const actionBtns = (function(){
    if(p.status==='completed')  return editBtn;
    if(p.status==='cancelled')  return `${editBtn}${reopenBtn}`;
    if(p.status==='on_hold')    return `${editBtn}${cancelBtn}${resumeBtn}`;
    if(p.status==='planned')    return `${editBtn}${cancelBtn}${startBtn}`;
    return `${editBtn}${cancelBtn}${holdBtn}${completeBtn}`;
  })();
  // Hold/Cancel reason banner
  const reasonBanner = (function(){
    if(p.status==='on_hold' && p.holdReason)
      return `<div style="background:#FFFBEB;border:1px solid #FDE68A;border-radius:12px;padding:12px 16px;margin-top:14px;display:flex;align-items:center;gap:12px">
        <span style="background:${P.amber};color:white;width:32px;height:32px;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0">${flProjIcon('pause',16,'white')}</span>
        <div style="flex:1"><div style="font-size:10px;color:${P.amberInk};font-weight:700;letter-spacing:.6px;text-transform:uppercase">On Hold · ${p.holdSince||''}</div><div style="font-size:12px;color:${P.amberInk};margin-top:2px">${p.holdReason}</div></div>
      </div>`;
    if(p.status==='cancelled' && p.cancelReason)
      return `<div style="background:${P.redSoft};border:1px solid #FECACA;border-radius:12px;padding:12px 16px;margin-top:14px;display:flex;align-items:center;gap:12px">
        <span style="background:${P.red};color:white;width:32px;height:32px;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0">${flProjIcon('xCircle',16,'white')}</span>
        <div style="flex:1"><div style="font-size:10px;color:${P.redInk};font-weight:700;letter-spacing:.6px;text-transform:uppercase">Cancelled · ${p.cancelledOn||''}</div><div style="font-size:12px;color:${P.redInk};margin-top:2px">${p.cancelReason}</div></div>
      </div>`;
    return '';
  })();

  // Cost breakdown
  const cb = flProjCostBreakdown(p.id);
  const budget = p.plannedBudget||0;
  const pct = budget? Math.min(100, Math.round(cb.total/budget*100)) : 0;
  const variance = cb.total - budget;
  const overBudget = budget && cb.total>budget;
  const barColor = overBudget ? P.red : (pct>=85 ? P.amber : P.mintInk);
  const barBg = overBudget ? P.redSoft : (pct>=85 ? P.amberSoft : P.mintSoft);

  const headerCard = `
    <div style="background:white;border:1px solid ${P.line};border-radius:18px;padding:22px 26px;margin-bottom:14px;box-shadow:${P.shadow}">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:14px">
        <div style="flex:1">
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;flex-wrap:wrap">
            <span style="font-size:10px;letter-spacing:1px;color:${P.ink3};font-weight:600;text-transform:uppercase">${p.no} · ${p.type==='drydock'?'Drydock':p.type==='overhaul'?'Overhaul':p.type==='scheduled'?'Scheduled':p.type==='refit'?'Refit':p.type==='general'?'General':'Project'}</span>
            ${statusPill}
            ${healthPill}
          </div>
          <div style="font-size:22px;font-weight:700;color:${P.navy};letter-spacing:-.4px">${p.name}</div>
          <div style="font-size:12px;color:${P.ink2};margin-top:4px">${boatName} · Vendor: <strong>${p.vendor||'—'}</strong></div>
        </div>
        <div style="display:flex;gap:8px;align-items:center">${actionBtns}</div>
      </div>
      <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:18px;padding-top:14px;border-top:1px solid ${P.line}">
        <div><div style="font-size:10px;color:${P.ink4};letter-spacing:.6px;text-transform:uppercase">Planned</div><div style="font-size:12px;color:${P.ink};margin-top:3px;font-weight:600;font-variant-numeric:tabular-nums">${p.planFrom||'—'} → ${p.planTo||'<span style=\'color:'+P.blue+'\'>Open</span>'}</div></div>
        <div><div style="font-size:10px;color:${P.ink4};letter-spacing:.6px;text-transform:uppercase">Actual</div><div style="font-size:12px;color:${P.ink};margin-top:3px;font-weight:600;font-variant-numeric:tabular-nums">${p.actualFrom||'—'} → ${p.actualTo||'ongoing'}</div></div>
        <div><div style="font-size:10px;color:${P.ink4};letter-spacing:.6px;text-transform:uppercase">Linked MJs</div><div style="font-size:16px;color:${P.navy};margin-top:1px;font-weight:700;font-variant-numeric:tabular-nums">${kids.length}<span style="font-size:11px;color:${P.ink3};font-weight:500"> · ${openKids.length} open</span></div></div>
        <div><div style="font-size:10px;color:${P.ink4};letter-spacing:.6px;text-transform:uppercase">Variance</div><div style="font-size:16px;color:${overBudget?P.red:P.mintInk};margin-top:1px;font-weight:700;font-variant-numeric:tabular-nums">${overBudget?'+':''}฿${Math.abs(variance).toLocaleString()}</div></div>
      </div>
      ${flProjRenderPhaseTracker(p)}
      ${reasonBanner}
    </div>`;

  // ── AI Insight card ──
  const insight = flProjInsight(p);
  const insightCard = `
    <div style="background:linear-gradient(135deg,#EEF3FF 0%, #F8FAFF 60%, #FFFFFF 100%);border:1px solid ${P.line};border-radius:18px;padding:20px 24px;margin-bottom:14px;display:grid;grid-template-columns:auto 1fr;gap:18px;align-items:start;box-shadow:${P.shadow}">
      <div style="width:54px;height:54px;border-radius:50%;background:white;border:2px solid ${health.color};display:flex;align-items:center;justify-content:center;flex-direction:column;font-family:Manrope,sans-serif">
        <div style="font-size:16px;font-weight:800;color:${health.color};line-height:1;font-variant-numeric:tabular-nums">${health.score}</div>
        <div style="font-size:8px;color:${P.ink3};font-weight:600;margin-top:1px">/100</div>
      </div>
      <div>
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
          <span style="display:inline-flex;align-items:center;gap:6px;font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase">${flProjIcon('sparkle',13,P.blue)} Project Insight</span>
          <span style="background:${health.bg};color:${health.color};padding:2px 9px;border-radius:10px;font-size:9px;font-weight:700">${health.label}</span>
        </div>
        ${insight.lines.map(l=>`<div style="font-size:12px;color:${P.ink};margin-bottom:3px;display:flex;align-items:flex-start;gap:8px"><span style="color:${P.blue};flex-shrink:0;margin-top:3px">${flProjIcon('arrowRight',11,P.blue)}</span><span>${l}</span></div>`).join('')}
        ${insight.recs.length?`<div style="margin-top:8px;padding-top:8px;border-top:1px dashed ${P.line}"><div style="font-size:10px;color:${P.ink3};font-weight:700;letter-spacing:.6px;text-transform:uppercase;margin-bottom:4px">Recommended</div>${insight.recs.map(r=>`<div style="font-size:11px;color:${P.ink2};margin-bottom:3px;display:flex;align-items:flex-start;gap:8px"><span style="color:${P.amber};flex-shrink:0;margin-top:2px">${flProjIcon('target',11,P.amber)}</span><span>${r}</span></div>`).join('')}</div>`:''}
      </div>
    </div>`;

  // Cost Breakdown card · Parts / Labour / Memos + Budget bar
  const costCard = `
    <div style="background:white;border:1px solid ${P.line};border-radius:18px;padding:22px 26px;margin-bottom:14px;box-shadow:${P.shadow}">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px">
        <div>
          <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase">Cost Breakdown</div>
          <div style="font-size:12px;color:${P.ink2};margin-top:2px">aggregated from ${kids.length} child MJ${kids.length===1?'':'s'}</div>
        </div>
        <div style="text-align:right">
          <div style="font-size:10px;color:${P.ink4};letter-spacing:.6px;text-transform:uppercase">Actual / Budget</div>
          <div style="font-size:18px;color:${P.navy};font-weight:700;font-variant-numeric:tabular-nums;margin-top:2px">฿${cb.total.toLocaleString()} <span style="color:${P.ink4};font-weight:500">/</span> ฿${budget.toLocaleString()}</div>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:160px 1fr;gap:18px;align-items:center;margin-bottom:14px">
        <div style="display:flex;justify-content:center">
          ${flProjRenderDonut(
            [
              {label:'Parts',  value:cb.parts,  color:P.blue},
              {label:'Labour', value:cb.labour, color:P.amber},
              {label:'Memos',  value:cb.memos,  color:P.mintInk}
            ],
            'TOTAL',
            '฿'+(cb.total>=1000?(cb.total/1000).toFixed(1)+'K':cb.total.toLocaleString())
          )}
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
          <div style="background:${P.blueSoft};border-radius:10px;padding:10px 12px;border-left:3px solid ${P.blue}">
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px"><span style="width:8px;height:8px;border-radius:50%;background:${P.blue}"></span><div style="font-size:10px;color:${P.blue};letter-spacing:.6px;text-transform:uppercase;font-weight:700">Parts</div></div>
            <div style="font-size:16px;color:${P.navy};font-weight:700;font-variant-numeric:tabular-nums">฿${cb.parts.toLocaleString()}</div>
            <div style="font-size:10px;color:${P.ink3}">${cb.total?Math.round(cb.parts/cb.total*100):0}% of total</div>
          </div>
          <div style="background:${P.amberSoft};border-radius:10px;padding:10px 12px;border-left:3px solid ${P.amber}">
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px"><span style="width:8px;height:8px;border-radius:50%;background:${P.amber}"></span><div style="font-size:10px;color:${P.amber};letter-spacing:.6px;text-transform:uppercase;font-weight:700">Labour</div></div>
            <div style="font-size:16px;color:${P.navy};font-weight:700;font-variant-numeric:tabular-nums">฿${cb.labour.toLocaleString()}</div>
            <div style="font-size:10px;color:${P.ink3}">${cb.total?Math.round(cb.labour/cb.total*100):0}% of total</div>
          </div>
          <div style="background:${P.mintSoft};border-radius:10px;padding:10px 12px;border-left:3px solid ${P.mintInk}">
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px"><span style="width:8px;height:8px;border-radius:50%;background:${P.mintInk}"></span><div style="font-size:10px;color:${P.mintInk};letter-spacing:.6px;text-transform:uppercase;font-weight:700">Memos</div></div>
            <div style="font-size:16px;color:${P.navy};font-weight:700;font-variant-numeric:tabular-nums">฿${cb.memos.toLocaleString()}</div>
            <div style="font-size:10px;color:${P.ink3}">other / mixed bucket</div>
          </div>
          <div style="background:${P.bg};border-radius:10px;padding:10px 12px;border-left:3px solid ${P.ink3}">
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px"><div style="font-size:10px;color:${P.ink3};letter-spacing:.6px;text-transform:uppercase;font-weight:700">Cumulative</div></div>
            <div style="font-size:16px;color:${P.navy};font-weight:700;font-variant-numeric:tabular-nums">฿${cb.total.toLocaleString()}</div>
            <div style="font-size:10px;color:${P.ink3}">${budget?`${Math.round(cb.total/budget*100)}% of ฿${budget.toLocaleString()} budget`:'no budget set'}</div>
          </div>
        </div>
      </div>
      ${budget ? `
        <div>
          <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px">
            <span style="font-size:11px;color:${P.ink2};font-weight:600">Budget utilization</span>
            <span style="font-size:11px;color:${barColor};font-weight:700;font-variant-numeric:tabular-nums">${pct}%${overBudget?' · OVER':''}</span>
          </div>
          <div style="height:8px;background:${barBg};border-radius:6px;overflow:hidden">
            <div style="width:${Math.min(100,pct)}%;height:100%;background:${barColor};transition:width .3s"></div>
          </div>
          ${overBudget ? `<div style="margin-top:6px;font-size:11px;color:${P.red};font-weight:600">⚠ Over budget by ฿${Math.abs(variance).toLocaleString()}</div>` : (pct>=85 ? `<div style="margin-top:6px;font-size:11px;color:${P.amber};font-weight:600">⚠ Approaching budget · ฿${(budget-cb.total).toLocaleString()} remaining</div>` : (pct?`<div style="margin-top:6px;font-size:11px;color:${P.ink3}">฿${(budget-cb.total).toLocaleString()} budget remaining</div>`:''))}
        </div>
      ` : `<div style="font-size:11px;color:${P.ink3};font-style:italic">No budget set · click <strong>Edit</strong> to add a planned budget</div>`}
    </div>`;

  const mjList = kids.length ? `
    <div style="display:flex;flex-direction:column;gap:8px">
      ${kids.sort((a,b)=>(a.no||'').localeCompare(b.no||'')).map(m=>{
        const stColor = m.status==='done'?P.mintInk : m.status==='inprogress'?P.amber : P.blue;
        const stSoft  = m.status==='done'?P.mintSoft: m.status==='inprogress'?P.amberSoft: P.blueSoft;
        const stTxt   = m.status==='done'?'DONE'   : m.status==='inprogress'?'IN PROGRESS':'PENDING';
        const mb = flProjMJCostBreakdown(m.id);
        return `<div onclick="_selMaintId='${m.id}';nav(document.querySelector('[data-view=\\'fl-maintenance\\']'))" style="background:white;border:1px solid ${P.line};border-radius:12px;padding:11px 14px;cursor:pointer;display:grid;grid-template-columns:80px 1.6fr 1fr auto auto;gap:14px;align-items:center" onmouseover="this.style.borderColor='${P.navy}'" onmouseout="this.style.borderColor='${P.line}'">
          <div style="font-size:11px;font-weight:700;color:${P.navy}">${m.no||''}</div>
          <div>
            <div style="font-size:12px;color:${P.ink};font-weight:600">${m.title||''}</div>
            <div style="font-size:10px;color:${P.ink3};margin-top:2px">${m.startDate||''}${m.endDate?' → '+m.endDate:''} · ${m.location||m.type||''}</div>
          </div>
          <div style="font-size:10px;color:${P.ink3};line-height:1.5">
            ${mb.parts?`<span style="color:${P.blue};font-weight:600">P ฿${(mb.parts/1000).toFixed(1)}K</span> `:''}
            ${mb.labour?`<span style="color:${P.amber};font-weight:600">L ฿${(mb.labour/1000).toFixed(1)}K</span> `:''}
            ${mb.memos?`<span style="color:${P.mintInk};font-weight:600">M ฿${(mb.memos/1000).toFixed(1)}K</span>`:''}
            ${!mb.total?'<span style="color:'+P.ink4+'">no cost yet</span>':''}
          </div>
          <div style="font-size:12px;color:${P.ink2};font-variant-numeric:tabular-nums">฿${mb.total.toLocaleString()}</div>
          <div><span style="background:${stSoft};color:${stColor};padding:3px 9px;border-radius:10px;font-size:9px;font-weight:700">${stTxt}</span></div>
        </div>`;
      }).join('')}
    </div>` : `
    <div style="background:white;border:1px dashed ${P.line};border-radius:12px;padding:24px;text-align:center;color:${P.ink3};font-size:12px">
      No MJs linked to this project yet. Click <strong>+ Create MJ</strong> to add one.
    </div>`;

  const logList = (p.log||[]).length ? `
    <div style="display:flex;flex-direction:column;gap:6px">
      ${(p.log||[]).slice().reverse().map(l=>`
        <div style="font-size:11px;color:${P.ink2};padding:7px 0;border-bottom:1px dashed ${P.line}">
          <span style="color:${P.ink3};font-variant-numeric:tabular-nums">${l.date||''}</span>
          <span style="margin:0 6px;color:${P.ink4}">·</span>
          <span style="color:${P.ink}">${l.text||''}</span>
          ${l.by?`<span style="margin-left:6px;color:${P.ink3};font-size:10px">${l.by}</span>`:''}
        </div>`).join('')}
    </div>` : `<div style="font-size:11px;color:${P.ink3}">No log entries</div>`;

  const canCreateMJ = p.status!=='completed';
  const planItems = p.plan||[];
  const docItems = p.docs||[];
  // Project memos · either via MJ link OR direct project link
  const projMemos = (FL_MEMOS||[]).filter(mo=>
    kids.some(k=>k.id===mo.maintId) ||  // via child MJ
    mo.projectId === p.id                 // direct project-level memo
  );

  // ─── Vendor section (used in Activity card bottom-right) ───
  const vendorVisits = p.vendorVisits||[];
  const vendorList = vendorVisits.length ? `
    <div style="display:flex;flex-direction:column;gap:5px;margin-bottom:12px">
      ${vendorVisits.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,4).map(v=>`
        <div style="display:grid;grid-template-columns:80px 1fr auto;gap:8px;align-items:center;padding:7px 10px;background:${P.bg};border-radius:8px;border:1px solid ${P.line};font-size:11px">
          <div style="color:${P.ink2};font-variant-numeric:tabular-nums;font-weight:600;font-size:10px">${v.date||''}</div>
          <div>
            <div style="color:${P.ink};font-weight:700;font-size:11px;line-height:1.2">${v.vendor||''}</div>
            ${v.role?`<div style="font-size:9px;color:${P.ink3};margin-top:1px">${v.role}</div>`:''}
          </div>
          <button onclick="flProjDeleteVendorVisit('${p.id}','${v.id}')" style="background:none;border:none;color:${P.ink4};font-size:13px;cursor:pointer;padding:0 4px">×</button>
        </div>
      `).join('')}
      ${vendorVisits.length>4?`<div style="font-size:10px;color:${P.ink3};text-align:center;padding:4px">+${vendorVisits.length-4} more visits</div>`:''}
    </div>` : '';

  // Strip the built-in margin-bottom on these cards (the grid gap handles spacing here)
  const _stripMb = s => s.replace('margin-bottom:14px;box-shadow','margin-bottom:0;box-shadow');
  // ─── Build the new all-in-one layout ───
  const layoutBody = `
    <!-- ROW 1 · Header (left) + Cost Breakdown (right) -->
    <div style="display:grid;grid-template-columns:1.5fr 1fr;gap:14px;margin-bottom:14px;align-items:stretch">
      <div>${_stripMb(headerCard)}</div>
      <div>${_stripMb(costCard)}</div>
    </div>

    <!-- ROW 2 · Plan + Documents + Memos (3 columns) -->
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;margin-bottom:14px;align-items:start">
      <div>${flProjRenderPlanTab(p)}</div>
      <div>${flProjRenderDocsTab(p)}</div>
      <div>${flProjRenderMemosTab(p, kids, projMemos)}</div>
    </div>

    <!-- ROW 3 · Child MJs + Activity (2 columns) -->
    <div style="display:grid;grid-template-columns:1.6fr 1fr;gap:14px">
      <div style="background:white;border:1px solid ${P.line};border-radius:18px;padding:18px 22px;box-shadow:${P.shadow}">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
          <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px">${flProjIcon('wrench',13,P.amber)} Child Maintenance Jobs <span style="background:${P.bg};color:${P.ink2};padding:2px 9px;border-radius:9px;font-size:10px;font-weight:700">${kids.length}</span></div>
          ${canCreateMJ?`<button onclick="flProjCreateMJ('${p.id}')" style="background:${P.navy};color:white;border:none;border-radius:14px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">${flProjIcon('plus',12,'white',2.5)} Create MJ</button>`:''}
        </div>
        ${mjList}
      </div>
      <div style="background:white;border:1px solid ${P.line};border-radius:18px;padding:18px 22px;box-shadow:${P.shadow}">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
          <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px">${flProjIcon('clock',13,P.blue)} Activity <span style="background:${P.bg};color:${P.ink2};padding:2px 9px;border-radius:9px;font-size:10px;font-weight:700">${(p.log||[]).length}</span></div>
          <button onclick="flProjAddVendorVisit('${p.id}')" style="background:white;border:1px solid ${P.line};color:${P.ink2};border-radius:12px;padding:5px 11px;font-size:11px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">${flProjIcon('hardHat',12,P.ink2)} + Vendor Visit</button>
        </div>
        ${vendorList}
        ${vendorList?`<div style="font-size:10px;color:${P.ink3};font-weight:700;letter-spacing:.06em;text-transform:uppercase;margin-bottom:8px">Log</div>`:''}
        ${logList}
      </div>
    </div>`;

  wrap.innerHTML = `
    <div style="background:${P.bg};min-height:100vh;padding:28px 32px;font-family:'Inter','Manrope',system-ui,-apple-system,sans-serif;color:${P.ink}">
      <div style="margin-bottom:14px">
        <button onclick="flProjCloseDetail()" style="background:white;border:1px solid ${P.line};color:${P.ink2};font-size:12px;cursor:pointer;padding:7px 14px;border-radius:10px;font-weight:600;box-shadow:${P.shadow};display:inline-flex;align-items:center;gap:7px">${flProjIcon('arrowLeft',13,P.ink2)} Back to Projects</button>
      </div>
      ${layoutBody}
    </div>`;
}

// ═══════════════ PHASE TRACKER ═══════════════
function flProjRenderPhaseTracker(p){
  const P = PROJ_PALETTE;
  if(p.status==='cancelled') return '';
  const phases = flProjPhasesFor(p);
  const curIdx = flProjCurrentPhaseIdx(p);
  return `
    <div style="margin-top:16px;padding-top:14px;border-top:1px solid ${P.line}">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px">
        <span style="font-size:10px;letter-spacing:.6px;color:${P.ink3};font-weight:700;text-transform:uppercase">Project Phase</span>
        <span style="font-size:10px;color:${P.ink3}">Click a step to advance</span>
      </div>
      <div style="display:flex;align-items:center;gap:0;width:100%">
        ${phases.map((ph,i)=>{
          const done = i<curIdx;
          const cur  = i===curIdx;
          const bg = done?P.mintInk : cur?P.navy : 'white';
          const fg = (done||cur)?'white':P.ink3;
          const border = done?P.mintInk : cur?P.navy : P.line;
          const icon = done?'✓':(i+1);
          const lineColor = i<curIdx?P.mintInk:P.line;
          return `
            <div style="display:flex;align-items:center;flex:1;${i===phases.length-1?'flex:0':''}">
              <div onclick="flProjSetPhase('${p.id}','${ph.k}')" style="display:flex;flex-direction:column;align-items:center;cursor:pointer;min-width:64px" title="${ph.label}">
                <div style="width:32px;height:32px;border-radius:50%;background:${bg};border:2px solid ${border};color:${fg};display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;transition:all .15s">${icon}</div>
                <div style="font-size:10px;color:${cur?P.navy:done?P.mintInk:P.ink3};font-weight:${cur||done?700:500};margin-top:5px;text-align:center;letter-spacing:.02em">${ph.label}</div>
              </div>
              ${i<phases.length-1?`<div style="flex:1;height:2px;background:${lineColor};margin:0 4px;margin-top:-16px"></div>`:''}
            </div>`;
        }).join('')}
      </div>
    </div>`;
}

// ═══════════════ SVG DONUT (cost breakdown) ═══════════════
function flProjRenderDonut(parts, centerLabel, centerVal){
  // parts: [{label, value, color}]
  const total = parts.reduce((s,p)=>s+p.value, 0);
  if(total<=0){
    return `<svg viewBox="0 0 140 140" width="140" height="140">
      <circle cx="70" cy="70" r="56" fill="none" stroke="#EEE" stroke-width="18"/>
      <text x="70" y="68" text-anchor="middle" font-size="10" fill="#999" font-family="Manrope,sans-serif" font-weight="600">${centerLabel}</text>
      <text x="70" y="84" text-anchor="middle" font-size="12" fill="#666" font-family="Manrope,sans-serif" font-weight="700">no data</text>
    </svg>`;
  }
  const cx=70, cy=70, r=56, sw=18;
  const C = 2 * Math.PI * r;
  let offset = 0;
  const segs = parts.map(p=>{
    const len = p.value/total*C;
    const seg = `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${p.color}" stroke-width="${sw}" stroke-dasharray="${len} ${C-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 ${cx} ${cy})"/>`;
    offset += len;
    return seg;
  }).join('');
  return `<svg viewBox="0 0 140 140" width="140" height="140">
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#F4F2EE" stroke-width="${sw}"/>
    ${segs}
    <text x="70" y="66" text-anchor="middle" font-size="9" fill="#8896AB" font-family="Manrope,sans-serif" font-weight="600" letter-spacing=".5">${centerLabel}</text>
    <text x="70" y="84" text-anchor="middle" font-size="14" fill="#1B2A4E" font-family="Manrope,sans-serif" font-weight="800">${centerVal}</text>
  </svg>`;
}

// ═══════════════ TAB · PLAN (scope checklist) ═══════════════
function flProjRenderPlanTab(p){
  const P = PROJ_PALETTE;
  const items = p.plan||[];
  const doneCount = items.filter(i=>i.done).length;
  const pct = items.length? Math.round(doneCount/items.length*100):0;
  // Suggest common scope items based on type
  const suggestions = (function(){
    if(p.type==='drydock') return ['ขัดสี + ทาสีกันเพรียง','เปลี่ยน Anode','เช็คใต้ท้องเรือ','ทดสอบ Hull','Service เครื่องยนต์','Service เกียร์','เช็คใบจักร'];
    if(p.type==='overhaul') return ['ถอดเครื่องเก่า','ติดตั้งเครื่องใหม่','เช็คระบบเชื้อเพลิง','Sea trial','Test ระบบไฟฟ้า'];
    if(p.type==='refit') return ['ปรับปรุง interior','ทาสีใหม่','เปลี่ยน upholstery','ตรวจระบบ safety'];
    return ['งานหลัก #1','งานหลัก #2','ตรวจสอบหลังเสร็จ'];
  })();
  return `
    <div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:18px 22px">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px">
        <div>
          <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase">Scope of Work</div>
          <div style="font-size:12px;color:${P.ink2};margin-top:2px">รายการงานที่ต้องทำในโปรเจคนี้</div>
        </div>
        <div style="text-align:right;font-size:13px;font-weight:700;color:${P.navy};font-variant-numeric:tabular-nums">${doneCount} / ${items.length} <span style="color:${P.ink3};font-weight:500;font-size:11px">(${pct}%)</span></div>
      </div>
      ${items.length ? `
        <div style="height:6px;background:${P.bg};border-radius:4px;overflow:hidden;margin-bottom:14px">
          <div style="width:${pct}%;height:100%;background:${P.mintInk}"></div>
        </div>
        <div style="display:flex;flex-direction:column;gap:6px;margin-bottom:14px">
          ${items.map(it=>`
            <div style="display:flex;align-items:center;gap:10px;padding:9px 12px;background:${it.done?P.mintSoft:P.bg};border-radius:8px;border:1px solid ${it.done?'rgba(52,193,154,.2)':P.line}">
              <input type="checkbox" ${it.done?'checked':''} onchange="flProjTogglePlanItem('${p.id}','${it.id}')" style="cursor:pointer;width:16px;height:16px;accent-color:${P.mintInk}">
              <span style="flex:1;font-size:12px;color:${it.done?P.mintInk:P.ink};text-decoration:${it.done?'line-through':'none'}">${it.text||''}</span>
              ${it.done?`<span style="font-size:10px;color:${P.ink3};font-variant-numeric:tabular-nums">${it.doneDate||''}</span>`:''}
              <button onclick="flProjDeletePlanItem('${p.id}','${it.id}')" style="background:none;border:none;color:${P.ink4};font-size:14px;cursor:pointer;padding:0 4px" title="Delete">×</button>
            </div>
          `).join('')}
        </div>
      ` : `<div style="background:${P.bg};border:1px dashed ${P.line};border-radius:10px;padding:24px;text-align:center;color:${P.ink3};font-size:12px;margin-bottom:14px">ยังไม่มีรายการงาน · เพิ่มจากด้านล่าง หรือคลิก suggestions</div>`}
      <div style="display:flex;gap:8px;margin-bottom:10px">
        <input id="proj-plan-input-${p.id}" type="text" placeholder="เพิ่มรายการงาน เช่น เปลี่ยน Anode 8 ตัว" style="flex:1;font-size:12px;padding:9px 12px;border:1px solid ${P.line};border-radius:8px" onkeypress="if(event.key==='Enter')flProjAddPlanItem('${p.id}')">
        <button onclick="flProjAddPlanItem('${p.id}')" style="background:${P.navy};color:white;border:none;border-radius:8px;padding:0 16px;font-size:12px;font-weight:600;cursor:pointer">+ Add</button>
      </div>
      <div style="font-size:10px;color:${P.ink3};margin-bottom:6px;letter-spacing:.6px;text-transform:uppercase;font-weight:600">Suggestions for ${p.type}</div>
      <div style="display:flex;flex-wrap:wrap;gap:6px">
        ${suggestions.map(s=>`<button onclick="flProjAddPlanItemDirect('${p.id}','${s.replace(/'/g,"\\'")}')" style="background:${P.blueSoft};color:${P.blue};border:none;border-radius:14px;padding:4px 11px;font-size:11px;cursor:pointer;font-weight:500">+ ${s}</button>`).join('')}
      </div>
    </div>`;
}
function flProjAddPlanItem(projId){
  const inp = document.getElementById('proj-plan-input-'+projId);
  if(!inp) return;
  const text = inp.value.trim();
  if(!text) return;
  flProjAddPlanItemDirect(projId, text);
  inp.value = '';
}
function flProjAddPlanItemDirect(projId, text){
  const p = flProjGetById(projId); if(!p) return;
  if(!p.plan) p.plan=[];
  p.plan.push({id:'pl_'+Date.now()+'_'+Math.random().toString(36).slice(2,6), text, done:false, addedAt:TODAY_STR});
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`+ Plan item: ${text}`, by:'user'});
  flSave();
  flRenderProjects();
}
function flProjTogglePlanItem(projId, itemId){
  const p = flProjGetById(projId); if(!p||!p.plan) return;
  const it = p.plan.find(x=>x.id===itemId); if(!it) return;
  it.done = !it.done;
  it.doneDate = it.done ? TODAY_STR : null;
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`${it.done?'✓':'↺'} ${it.text}`, by:'user'});
  flSave();
  flRenderProjects();
}
function flProjDeletePlanItem(projId, itemId){
  const p = flProjGetById(projId); if(!p||!p.plan) return;
  const it = p.plan.find(x=>x.id===itemId); if(!it) return;
  if(!confirm(`Delete plan item: ${it.text}?`)) return;
  p.plan = p.plan.filter(x=>x.id!==itemId);
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`- Plan item removed: ${it.text}`, by:'user'});
  flSave();
  flRenderProjects();
}

// ═══════════════ TAB · DOCUMENTS (incl. Photo grid) ═══════════════
function flProjRenderDocsTab(p){
  const P = PROJ_PALETTE;
  const allDocs = p.docs||[];
  const photos = allDocs.filter(d=>d.type==='photo');
  const docs = allDocs.filter(d=>d.type!=='photo');
  // Suggest required docs based on type
  const required = (function(){
    if(p.type==='drydock') return ['ใบเสนอราคา (Quotation)','Work Order','Hull Survey Report','ใบรับรอง Anode','Paint Certificate','Sea Trial Report','Final Invoice'];
    if(p.type==='overhaul') return ['ใบเสนอราคา','Work Order','Engine Pre-test Report','Engine Post-install Report','Sea Trial Report','Final Invoice'];
    return ['ใบเสนอราคา','Work Order','Completion Report','Final Invoice'];
  })();
  const existing = new Set(docs.map(d=>d.name.toLowerCase()));
  const missingRequired = required.filter(r=>!existing.has(r.toLowerCase()));
  const ST = {
    required:{bg:P.amberSoft, color:P.amber, label:'REQUIRED'},
    pending: {bg:P.amberSoft, color:P.amber, label:'PENDING'},
    received:{bg:P.blueSoft,  color:P.blue,  label:'RECEIVED'},
    verified:{bg:P.mintSoft,  color:P.mintInk,label:'VERIFIED'}
  };
  return `
    <div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:18px 22px">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px">
        <div>
          <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase">Project Documents</div>
          <div style="font-size:12px;color:${P.ink2};margin-top:2px">เอกสารที่เกี่ยวข้องกับโปรเจคนี้ทั้งหมด</div>
        </div>
        <div style="text-align:right;font-size:13px;font-weight:700;color:${P.navy};font-variant-numeric:tabular-nums">${docs.length} <span style="color:${P.ink3};font-weight:500;font-size:11px">docs</span></div>
      </div>
      ${docs.length ? `
        <div style="display:flex;flex-direction:column;gap:6px;margin-bottom:14px">
          ${docs.map(d=>{
            const st = ST[d.status||'pending'] || ST.pending;
            return `<div style="display:grid;grid-template-columns:1fr auto auto auto auto;gap:10px;align-items:center;padding:11px 14px;background:${P.bg};border-radius:8px;border:1px solid ${P.line}">
              <div>
                <div style="font-size:12px;font-weight:600;color:${P.ink}">${d.name||''}</div>
                ${d.note?`<div style="font-size:10px;color:${P.ink3};margin-top:1px">${d.note}</div>`:''}
              </div>
              ${d.url?`<a href="${d.url}" target="_blank" style="font-size:11px;color:${P.blue};text-decoration:none;font-weight:600">📎 link</a>`:''}
              <span style="background:${st.bg};color:${st.color};padding:3px 9px;border-radius:10px;font-size:9px;font-weight:700">${st.label}</span>
              <select onchange="flProjUpdateDocStatus('${p.id}','${d.id}',this.value)" style="font-size:10px;padding:3px 6px;border:1px solid ${P.line};border-radius:6px;background:white;cursor:pointer">
                <option value="pending" ${d.status==='pending'?'selected':''}>Pending</option>
                <option value="received" ${d.status==='received'?'selected':''}>Received</option>
                <option value="verified" ${d.status==='verified'?'selected':''}>Verified</option>
              </select>
              <button onclick="flProjDeleteDoc('${p.id}','${d.id}')" style="background:none;border:none;color:${P.ink4};font-size:14px;cursor:pointer;padding:0 4px" title="Delete">×</button>
            </div>`;
          }).join('')}
        </div>
      ` : `<div style="background:${P.bg};border:1px dashed ${P.line};border-radius:10px;padding:24px;text-align:center;color:${P.ink3};font-size:12px;margin-bottom:14px">ยังไม่มีเอกสาร · เพิ่มจากด้านล่าง</div>`}
      <div style="display:grid;grid-template-columns:1.5fr 1fr 1fr auto;gap:6px;margin-bottom:10px">
        <input id="proj-doc-name-${p.id}" type="text" placeholder="ชื่อเอกสาร เช่น Quotation จากอู่ A" style="font-size:12px;padding:9px 12px;border:1px solid ${P.line};border-radius:8px">
        <input id="proj-doc-url-${p.id}" type="text" placeholder="URL / file link (optional)" style="font-size:12px;padding:9px 12px;border:1px solid ${P.line};border-radius:8px">
        <input id="proj-doc-note-${p.id}" type="text" placeholder="หมายเหตุ" style="font-size:12px;padding:9px 12px;border:1px solid ${P.line};border-radius:8px">
        <button onclick="flProjAddDoc('${p.id}')" style="background:${P.navy};color:white;border:none;border-radius:8px;padding:0 16px;font-size:12px;font-weight:600;cursor:pointer">+ Add</button>
      </div>
      ${missingRequired.length ? `
        <div style="font-size:10px;color:${P.ink3};margin:14px 0 6px;letter-spacing:.6px;text-transform:uppercase;font-weight:600">Required for ${p.type} (still missing)</div>
        <div style="display:flex;flex-wrap:wrap;gap:6px">
          ${missingRequired.map(r=>`<button onclick="flProjAddDocPreset('${p.id}','${r.replace(/'/g,"\\'")}')" style="background:${P.amberSoft};color:${P.amber};border:none;border-radius:14px;padding:4px 11px;font-size:11px;cursor:pointer;font-weight:600">+ ${r}</button>`).join('')}
        </div>
      ` : `<div style="font-size:11px;color:${P.mintInk};margin-top:14px;font-weight:600">✓ Required documents complete</div>`}
    </div>

    <div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:18px 22px;margin-top:14px">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px">
        <div>
          <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px">${flProjIcon('camera',13,P.purple)} Photo Gallery</div>
          <div style="font-size:12px;color:${P.ink2};margin-top:2px">Before · during · after photos · grouped by phase</div>
        </div>
        <button onclick="flProjAddPhoto('${p.id}')" style="background:${P.navy};color:white;border:none;border-radius:14px;padding:5px 12px;font-size:11px;font-weight:600;cursor:pointer">+ Add Photo</button>
      </div>
      ${photos.length ? `
        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px">
          ${photos.map(ph=>`
            <div style="position:relative;background:${P.bg};border:1px solid ${P.line};border-radius:10px;overflow:hidden;aspect-ratio:1;cursor:zoom-in" onclick="flProjLightbox('${(ph.url||'').replace(/'/g,'%27')}','${(ph.note||ph.name||'').replace(/'/g,'%27')}')">
              <img src="${ph.url}" alt="${ph.name||''}" style="width:100%;height:75%;object-fit:cover;display:block" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">
              <div style="display:none;width:100%;height:75%;align-items:center;justify-content:center;background:${P.bg};color:${P.ink3};font-size:11px">image failed to load</div>
              <div style="padding:5px 8px;height:25%;display:flex;align-items:center;justify-content:space-between;background:white">
                <div style="overflow:hidden">
                  <div style="font-size:10px;color:${P.ink};font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${ph.note||ph.name||'photo'}</div>
                  <div style="font-size:9px;color:${P.ink3}">${ph.phase||'—'} · ${ph.addedAt||''}</div>
                </div>
                <button onclick="event.stopPropagation();flProjDeleteDoc('${p.id}','${ph.id}')" style="background:none;border:none;color:${P.ink4};font-size:12px;cursor:pointer;padding:0 2px">×</button>
              </div>
            </div>
          `).join('')}
        </div>
      ` : `<div style="background:${P.bg};border:1px dashed ${P.line};border-radius:10px;padding:24px;text-align:center;color:${P.ink3};font-size:12px">
        No photos yet · click <strong>+ Add Photo</strong> to start a visual record
      </div>`}
    </div>`;
}
function flProjAddDoc(projId){
  const nameEl = document.getElementById('proj-doc-name-'+projId);
  const urlEl  = document.getElementById('proj-doc-url-'+projId);
  const noteEl = document.getElementById('proj-doc-note-'+projId);
  const name = nameEl?.value.trim(); if(!name){ alert('Document name required'); return; }
  flProjAddDocRecord(projId, name, urlEl?.value.trim()||'', noteEl?.value.trim()||'');
  if(nameEl) nameEl.value=''; if(urlEl) urlEl.value=''; if(noteEl) noteEl.value='';
}
function flProjAddDocPreset(projId, name){ flProjAddDocRecord(projId, name, '', ''); }
function flProjAddDocRecord(projId, name, url, note){
  const p = flProjGetById(projId); if(!p) return;
  if(!p.docs) p.docs=[];
  p.docs.push({
    id:'dc_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),
    name, url, note,
    status: url? 'received' : 'pending',
    addedAt: TODAY_STR
  });
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`+ Document: ${name}`, by:'user'});
  flSave();
  flRenderProjects();
}
function flProjUpdateDocStatus(projId, docId, status){
  const p = flProjGetById(projId); if(!p||!p.docs) return;
  const d = p.docs.find(x=>x.id===docId); if(!d) return;
  const oldSt = d.status||'pending';
  d.status = status;
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`Document "${d.name}" · ${oldSt} → ${status}`, by:'user'});
  flSave();
  flRenderProjects();
}
function flProjDeleteDoc(projId, docId){
  const p = flProjGetById(projId); if(!p||!p.docs) return;
  const d = p.docs.find(x=>x.id===docId); if(!d) return;
  if(!confirm(`Delete document: ${d.name}?`)) return;
  p.docs = p.docs.filter(x=>x.id!==docId);
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`- Document removed: ${d.name}`, by:'user'});
  flSave();
  flRenderProjects();
}

// ═══════════════ TAB · MEMOS (roll-up · MJ + direct project) ═══════════════
function flProjRenderMemosTab(p, kids, memos){
  const P = PROJ_PALETTE;
  const addBtn = `<button onclick="flProjAddMemo('${p.id}')" style="background:${P.navy};color:white;border:none;border-radius:12px;padding:5px 11px;font-size:11px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">${flProjIcon('plus',12,'white',2.5)} Project Memo</button>`;
  if(!memos.length){
    return `<div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:18px 22px;box-shadow:${P.shadow}">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px">
        <div>
          <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase">Project Memos</div>
          <div style="font-size:12px;color:${P.ink2};margin-top:2px">From child MJs + Project-level overhead</div>
        </div>
        ${addBtn}
      </div>
      <div style="background:${P.bg};border:1px dashed ${P.line};border-radius:10px;padding:24px;text-align:center;color:${P.ink3};font-size:12px">
        No memos yet.<br>
        <span style="font-size:11px;color:${P.ink4};margin-top:6px;display:inline-block">Create memos from MJ detail page · or click <strong>+ Project Memo</strong> for overhead costs (yard rental · transport · etc.)</span>
      </div>
    </div>`;
  }
  // Group by status
  const groups = {
    pending:  memos.filter(m=>m.status==='pending'||!m.status),
    approved: memos.filter(m=>m.status==='approved'),
    received: memos.filter(m=>m.status==='received'),
    paid:     memos.filter(m=>m.status==='paid')
  };
  const ST = {
    pending: {color:P.amber,   bg:P.amberSoft, label:'PENDING'},
    approved:{color:P.blue,    bg:P.blueSoft,  label:'APPROVED'},
    received:{color:P.mintInk, bg:P.mintSoft,  label:'RECEIVED'},
    paid:    {color:P.navy,    bg:'#E6EAF2',   label:'PAID'}
  };
  const totalAmt = memos.filter(m=>m.status!=='cancelled').reduce((s,m)=>s+(m.amount||0),0);   // cancelled memos excluded from spend
  const projDirectCount = memos.filter(m=>m.projectId===p.id).length;
  const mjMemoCount = memos.length - projDirectCount;
  const grandTotalRow = `
    <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px;gap:10px;flex-wrap:wrap">
      <div>
        <div style="font-size:14px;letter-spacing:.4px;color:${P.navy};font-weight:800;text-transform:uppercase">Project Memos</div>
        <div style="font-size:11px;color:${P.ink2};margin-top:2px">${mjMemoCount} via MJ · ${projDirectCount} project-level (overhead)</div>
      </div>
      <div style="display:flex;align-items:center;gap:10px">
        <div style="text-align:right">
          <div style="font-size:10px;color:${P.ink4};letter-spacing:.6px;text-transform:uppercase">Total</div>
          <div style="font-size:18px;color:${P.navy};font-weight:700;font-variant-numeric:tabular-nums">฿${totalAmt.toLocaleString()}</div>
        </div>
        ${addBtn}
      </div>
    </div>`;
  const renderGroup = (st, list)=>{
    if(!list.length) return '';
    const s = ST[st];
    const subTotal = list.reduce((sum,m)=>sum+(m.amount||0),0);
    return `<div style="margin-bottom:12px">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
        <span style="background:${s.bg};color:${s.color};padding:3px 9px;border-radius:10px;font-size:9px;font-weight:700">${s.label}</span>
        <span style="font-size:11px;color:${P.ink3}">${list.length} · ฿${subTotal.toLocaleString()}</span>
      </div>
      <div style="display:flex;flex-direction:column;gap:5px">
        ${list.map(mo=>{
          const mj = kids.find(k=>k.id===mo.maintId);
          const isProjLevel = mo.projectId===p.id && !mo.maintId;
          const refBadge = isProjLevel
            ? `<span style="background:${P.purpleSoft};color:${P.purple};padding:2px 7px;border-radius:8px;font-size:9px;font-weight:700">PROJECT</span>`
            : (mj ? `<span style="background:${P.amberSoft};color:${P.amberInk};padding:2px 7px;border-radius:8px;font-size:9px;font-weight:700">${mj.no}</span>` : '');
          const sourceText = isProjLevel ? 'Project overhead' : (mj ? `via ${mj.no}` : `MJ ${mo.maintId}`);
          return `<div style="display:grid;grid-template-columns:auto 1fr auto auto;gap:10px;align-items:center;padding:10px 12px;background:${P.bg};border-radius:8px;border:1px solid ${P.line}">
            <div style="display:flex;flex-direction:column;gap:3px;align-items:flex-start">
              <span style="font-size:11px;font-weight:700;color:${P.navy}">${mo.no||''}</span>
              ${refBadge}
            </div>
            <div>
              <div style="font-size:12px;color:${P.ink};font-weight:600">${mo.subject||mo.title||'(no subject)'}</div>
              <div style="font-size:10px;color:${P.ink3};margin-top:2px">${mo.date||''} · ${sourceText} · ${mo.supplier||''}</div>
            </div>
            <div style="font-size:12px;color:${P.ink2};font-variant-numeric:tabular-nums;font-weight:600">฿${(mo.amount||0).toLocaleString()}</div>
            ${typeof flPrintMemo==='function'?`<button onclick="flPrintMemo('${mo.id}')" style="background:none;border:1px solid ${P.line};color:${P.ink2};border-radius:8px;padding:3px 9px;font-size:10px;font-weight:500;cursor:pointer">🖨 Print</button>`:''}
          </div>`;
        }).join('')}
      </div>
    </div>`;
  };
  return `<div style="background:white;border:1px solid ${P.line};border-radius:14px;padding:18px 22px">
    ${grandTotalRow}
    ${renderGroup('pending', groups.pending)}
    ${renderGroup('approved', groups.approved)}
    ${renderGroup('received', groups.received)}
    ${renderGroup('paid', groups.paid)}
  </div>`;
}

// ── Lifecycle actions ──
function flProjStart(id){
  const p = flProjGetById(id);
  if(!p) return;
  if(p.status!=='planned'){ flShowToast('Project already started'); return; }
  p.status='inprogress';
  p.actualFrom = p.actualFrom || TODAY_STR;
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:'▶ Project started · boat status → unavailable', by:'user'});
  // Push boat log entry: unavailable
  const boat = BOATS.find(b=>b.id===p.boatId);
  if(boat){
    if(!boat.log) boat.log=[];
    boat.log.push({
      id:'sl_'+Date.now(),
      s:'unavailable',
      from: TODAY_STR,
      to: null,
      loc: p.vendor||'',
      note: `Project ${p.no} · ${p.name}`,
      reason: p.type==='drydock'?'dry_dock':'overhaul',
      projectId: p.id
    });
  }
  flSave(); save();
  flRenderProjects();
  flShowToast('Project started · boat removed from operation');
}

function flProjHold(id){
  const p = flProjGetById(id); if(!p) return;
  if(p.status!=='inprogress'){ flShowToast('Only In Progress projects can be put on hold'); return; }
  const reason = prompt('Reason for holding (e.g. รออะไหล่ · vendor ลา · weather):', p.holdReason||'');
  if(reason===null) return; // cancel
  if(!reason.trim()){ alert('Reason required'); return; }
  p.status = 'on_hold';
  p.holdReason = reason.trim();
  p.holdSince = TODAY_STR;
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`⏸ Project on hold · ${reason.trim()}`, by:'user'});
  flSave();
  flRenderProjects();
  flShowToast('Project paused');
}
function flProjResume(id){
  const p = flProjGetById(id); if(!p) return;
  if(p.status!=='on_hold'){ flShowToast('Only on-hold projects can be resumed'); return; }
  p.status = 'inprogress';
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`▶ Resumed${p.holdReason?` (was on hold: ${p.holdReason})`:''}`, by:'user'});
  // Clear hold meta (keep history in log)
  p.holdReason = null;
  p.holdSince = null;
  flSave();
  flRenderProjects();
  flShowToast('Project resumed');
}
function flProjCancel(id){
  const p = flProjGetById(id); if(!p) return;
  if(p.status==='completed'){ flShowToast('Completed projects cannot be cancelled'); return; }
  if(p.status==='cancelled'){ flShowToast('Already cancelled'); return; }
  const reason = prompt('Reason for cancelling:', '');
  if(reason===null) return;
  if(!reason.trim()){ alert('Reason required'); return; }
  const kids = flProjChildMJs(p.id);
  const openKids = kids.filter(m=>m.status!=='done');
  const wasInProgress = (p.status==='inprogress' || p.status==='on_hold');
  let unlinkMJs = false;
  if(openKids.length){
    unlinkMJs = confirm(`This project has ${openKids.length} open child MJ(s).\n\nUnlink them so they continue as standalone jobs?\n\n(OK = unlink · Cancel = keep linked but project will be cancelled)`);
  }
  if(unlinkMJs){
    openKids.forEach(m=>{
      m.parentProjectId = null;
      if(!m.progressLog) m.progressLog=[];
      m.progressLog.push({date:TODAY_STR, text:`Unlinked from cancelled project ${p.no}`, by:'user'});
    });
  }
  p.status = 'cancelled';
  p.cancelReason = reason.trim();
  p.cancelledOn = TODAY_STR;
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`✕ Project cancelled · ${reason.trim()}${unlinkMJs?` · ${openKids.length} MJ unlinked`:''}`, by:'user'});
  // If boat was in unavailable state for this project, close that log entry + return boat to available
  if(wasInProgress){
    const boat = BOATS.find(b=>b.id===p.boatId);
    if(boat && boat.log){
      boat.log.forEach(e=>{
        if(e.projectId===p.id && !e.to){
          e.to = TODAY_STR;
          e.note = (e.note||'')+' · project cancelled';
        }
      });
      boat.log.push({
        id:'sl_'+Date.now(),
        s:'available',
        from: TODAY_STR,
        to: null,
        note: `Returned · Project ${p.no} cancelled`
      });
    }
    save();
  }
  flSave();
  flRenderProjects();
  flShowToast(`Project ${p.no} cancelled`);
}
function flProjReopen(id){
  const p = flProjGetById(id); if(!p) return;
  if(p.status!=='cancelled'){ flShowToast('Only cancelled projects can be reopened'); return; }
  p.status = 'planned';
  p.cancelReason = null;
  p.cancelledOn = null;
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`↻ Reopened (back to planned)`, by:'user'});
  flSave();
  flRenderProjects();
  flShowToast('Project reopened · status = Scheduled');
}

function flProjMarkComplete(id){
  const p = flProjGetById(id);
  if(!p) return;
  if(p.status==='completed'){ flShowToast('Already completed'); return; }
  const kids = flProjChildMJs(p.id);
  const openKids = kids.filter(m=>m.status!=='done');
  const msg = openKids.length
    ? `Mark project complete?\n\nThis will:\n- Close ${openKids.length} open child MJ(s)\n- Set boat status → available\n- Set project status → completed\n\nContinue?`
    : `Mark project complete?\n\nThis will set boat status → available and project status → completed.`;
  if(!confirm(msg)) return;
  // Cascade close child MJs
  openKids.forEach(m=>{
    m.status='done';
    m.endDate = m.endDate || TODAY_STR;
    if(!m.progressLog) m.progressLog=[];
    m.progressLog.push({date:TODAY_STR, text:`✓ Auto-closed by parent project ${p.no} mark-complete`, by:'cascade'});
  });
  // Update project
  p.status='completed';
  p.actualTo = p.actualTo || TODAY_STR;
  if(!p.log) p.log=[];
  p.log.push({date:TODAY_STR, text:`✓ Project completed · cascade closed ${openKids.length} MJ(s) · boat → available`, by:'user'});
  // Update boat log: close the unavailable entry + add available entry
  const boat = BOATS.find(b=>b.id===p.boatId);
  if(boat && boat.log){
    boat.log.forEach(e=>{
      if(e.projectId===p.id && !e.to){
        e.to = TODAY_STR;
      }
    });
    boat.log.push({
      id:'sl_'+Date.now(),
      s:'available',
      from: TODAY_STR,
      to: null,
      note: `Returned from Project ${p.no}`
    });
  }
  flSave(); save();
  flRenderProjects();
  flShowToast(`Project ${p.no} completed · ${openKids.length} MJ auto-closed · boat returned`);
}

// ── Create MJ from project · prefills boat + scheduled type + dates + location ──
let _projCreateForId = null;
function flProjCreateMJ(projId){
  const p = flProjGetById(projId);
  if(!p){ alert('Project not found'); return; }
  _projCreateForId = projId;
  flOpenCreateJobModal();
  // Switch to "scheduled" type card · select via the actual onclick handler so all wiring fires
  const schedCard = document.querySelector('.job-type-card[data-type="scheduled"]');
  if(schedCard && typeof selectJobType==='function'){
    selectJobType('scheduled', schedCard);
  } else {
    _jobType = 'scheduled';
  }
  // Pre-fill fields
  const boatSel = document.getElementById('job-boat');
  if(boatSel) boatSel.value = p.boatId;
  const dateSel = document.getElementById('job-start-date');
  if(dateSel) dateSel.value = p.planFrom||TODAY_STR;
  const locSel = document.getElementById('job-location');
  if(locSel) locSel.value = p.vendor||'';
  const titleSel = document.getElementById('job-title');
  if(titleSel) titleSel.value = `${p.name} · sub-job`;
  // Refresh asset list now that boat is set
  if(typeof populateJobAssetList==='function') populateJobAssetList();
}

function flProjOpenNew(){ flProjOpenModal(null); }
function flProjOpenEdit(id){ flProjOpenModal(id); }
function flProjOpenModal(editId){
  // Populate boat dropdown · §boatOwn เรือบริษัทเท่านั้น (คงเรือเดิมของงานไว้ถ้าเคยผูกไว้แล้ว)
  const boatSel = document.getElementById('fl-proj-boat');
  if(boatSel){
    const _curB = editId ? ((flProjGetById(editId)||{}).boatId||'') : '';
    boatSel.innerHTML = '<option value="">— Select boat / เลือกเรือ —</option><option value="__none__">⚙ General · ไม่เกี่ยวกับเรือ</option>' +
      flBoatsForInstall(_curB).map(b=>`<option value="${b.id}">${flBoatInstallLabel(b)}</option>`).join('');
  }
  document.getElementById('fl-proj-edit-id').value = editId||'';
  if(editId){
    const p = flProjGetById(editId);
    if(!p){ alert('Project not found'); return; }
    document.getElementById('fl-proj-modal-title').textContent = `Edit Project · ${p.no}`;
    document.getElementById('fl-proj-modal-sub').textContent   = p.name;
    document.getElementById('fl-proj-name').value   = p.name||'';
    document.getElementById('fl-proj-boat').value   = p.boatId||'__none__';
    document.getElementById('fl-proj-type').value   = p.type||'drydock';
    document.getElementById('fl-proj-vendor').value = p.vendor||'';
    document.getElementById('fl-proj-from').value   = p.planFrom||'';
    document.getElementById('fl-proj-to').value     = p.planTo||'';
    document.getElementById('fl-proj-budget').value = p.plannedBudget||0;
    document.getElementById('fl-proj-notes').value  = p.notes||'';
    // Show baseline hint (read-only · for on-time KPI honesty)
    const baselineHint = document.getElementById('fl-proj-to-baseline');
    if(baselineHint){
      if(p.originalPlanTo && p.originalPlanTo !== p.planTo){
        baselineHint.innerHTML = `<span style="color:#94A3B8">Baseline:</span> <strong style="color:#475569">${p.originalPlanTo}</strong> <span style="color:#94A3B8">· locked · used for On-time KPI</span>`;
        baselineHint.style.display = 'block';
      } else if(p.originalPlanTo){
        baselineHint.innerHTML = `<span style="color:#94A3B8">Baseline locked at this date · used for On-time KPI</span>`;
        baselineHint.style.display = 'block';
      } else {
        baselineHint.style.display = 'none';
      }
    }
  } else {
    document.getElementById('fl-proj-modal-title').textContent = 'New Project';
    document.getElementById('fl-proj-modal-sub').textContent   = 'Dry dock · overhaul · or General (non-vessel) work';
    document.getElementById('fl-proj-name').value   = '';
    document.getElementById('fl-proj-boat').value   = '';
    document.getElementById('fl-proj-type').value   = 'drydock';
    document.getElementById('fl-proj-vendor').value = '';
    document.getElementById('fl-proj-from').value   = TODAY_STR;
    document.getElementById('fl-proj-to').value     = ''; // Leave open · user can set later
    document.getElementById('fl-proj-budget').value = '';
    document.getElementById('fl-proj-notes').value  = '';
    const baselineHint = document.getElementById('fl-proj-to-baseline');
    if(baselineHint) baselineHint.style.display = 'none';
  }
  openModal('fl-modal-project');
}
function flProjSaveModal(){
  const editId = document.getElementById('fl-proj-edit-id').value;
  const name   = document.getElementById('fl-proj-name').value.trim();
  const boatSelVal = document.getElementById('fl-proj-boat').value;
  const boatId = (boatSelVal==='__none__') ? null : boatSelVal;   // null = General · non-vessel project
  const type   = document.getElementById('fl-proj-type').value;
  const vendor = document.getElementById('fl-proj-vendor').value.trim();
  const planFrom = document.getElementById('fl-proj-from').value;
  const planTo   = document.getElementById('fl-proj-to').value;
  const budget = parseInt(document.getElementById('fl-proj-budget').value)||0;
  const notes  = document.getElementById('fl-proj-notes').value.trim();
  if(!name){ alert('Project name is required'); return; }
  if(!boatSelVal){ alert('Select a boat, or choose General (non-vessel project)'); return; }
  if(!planFrom){ alert('Planned start is required'); return; }
  // planTo optional · null = Open (no fixed end · ongoing)
  if(planTo && planTo<planFrom){ alert('Planned end must be after start'); return; }

  if(editId){
    const p = flProjGetById(editId);
    if(!p){ alert('Project disappeared'); return; }
    const oldBoat = p.boatId;
    const oldPlanTo = p.planTo;
    p.name=name; p.boatId=boatId; p.type=type; p.vendor=vendor;
    p.planFrom=planFrom; p.planTo=planTo||null; p.plannedBudget=budget; p.notes=notes;
    // originalPlanTo is BASELINE · never touched once set. Ensure it exists for older projects.
    if(p.originalPlanTo===undefined) p.originalPlanTo = oldPlanTo || null;
    if(!p.log) p.log=[];
    const planChanged = oldPlanTo !== p.planTo;
    p.log.push({date:TODAY_STR, text:`Project edited${oldBoat!==boatId?` · boat changed`:''}${planChanged?` · planTo ${oldPlanTo||'Open'} → ${p.planTo||'Open'}`:''}`, by:'user'});
    flSave();
    closeModal('fl-modal-project');
    flRenderProjects();
    flShowToast(`Project ${p.no} updated`);
    return;
  }
  // New
  const seq = (FL_PROJECTS.length+1).toString().padStart(3,'0');
  const yr = planFrom.slice(0,4);
  const _pt = planTo||null;
  const proj = {
    id: `proj_${yr}_${boatId||'gen'}_${seq}_${Math.random().toString(36).slice(2,6)}`,
    no: `PRJ-${seq}`,
    name, boatId, type, vendor,
    planFrom, planTo: _pt,
    originalPlanTo: _pt,  // BASELINE · snapshot at creation · never edited
    actualFrom: null, actualTo: null,
    status: 'planned',
    plannedBudget: budget,
    notes,
    log: [{date:TODAY_STR, text:'+ Project created', by:'user'}],
    createdAt: TODAY_STR,
    createdBy: 'user'
  };
  FL_PROJECTS.push(proj);
  flSave();
  closeModal('fl-modal-project');
  _projTab='planned';
  flRenderProjects();
  flShowToast(`Project ${proj.no} created`);
}

// ── MJ ↔ Project linking helpers (used in flRenderMaintDetailPink) ──
function flMaintLinkProjectPick(mjId){
  const m = FL_MAINT.find(x=>x.id===mjId);
  if(!m){ alert('MJ not found'); return; }
  if(m.type!=='scheduled'){
    alert('Only Scheduled MJs can be linked to a Project.\n\nCorrective / Preventive jobs are independent.');
    return;
  }
  const candidates = (FL_PROJECTS||[]).filter(p=>p.boatId===m.boatId && p.status!=='completed');
  if(!candidates.length){ alert('No open projects for this boat. Create one from the Projects page first.'); return; }
  const list = candidates.map((p,i)=>`${i+1}. ${p.no} · ${p.name} (${p.status})`).join('\n');
  const pick = prompt(`Link ${m.no||m.id} to which project?\n\n${list}\n\nEnter number:`);
  if(!pick) return;
  const proj = candidates[parseInt(pick)-1];
  if(!proj){ alert('Invalid choice'); return; }
  m.parentProjectId = proj.id;
  if(!proj.log) proj.log=[];
  proj.log.push({date:TODAY_STR, text:`+ Linked MJ ${m.no} · ${m.title||''}`, by:'user'});
  if(!m.progressLog) m.progressLog=[];
  m.progressLog.push({date:TODAY_STR, text:`🔗 Linked to project ${proj.no} · ${proj.name}`, by:'user'});
  flSave();
  flRenderMaintDetailPink();
  flShowToast(`Linked to ${proj.no}`);
}
function flMaintUnlinkProject(mjId){
  const m = FL_MAINT.find(x=>x.id===mjId);
  if(!m||!m.parentProjectId) return;
  const proj = (FL_PROJECTS||[]).find(p=>p.id===m.parentProjectId);
  if(!confirm(`Unlink ${m.no||m.id} from project ${proj?proj.no:''}?`)) return;
  const projNo = proj?proj.no:m.parentProjectId;
  if(proj){
    if(!proj.log) proj.log=[];
    proj.log.push({date:TODAY_STR, text:`− Unlinked MJ ${m.no}`, by:'user'});
  }
  m.parentProjectId = null;
  if(!m.progressLog) m.progressLog=[];
  m.progressLog.push({date:TODAY_STR, text:`🔗 Unlinked from project ${projNo}`, by:'user'});
  flSave();
  flRenderMaintDetailPink();
  flShowToast(`Unlinked from ${projNo}`);
}

let _selMaintId=null, _maintStFilter='all', _maintArchiveTab='active', _maintTypeFilter='all', _maintBoatFilter='all', _maintFilterExpand=false;

function flRenderMaint(){
  const wrap=document.getElementById('fl-maint-pink-wrap');
  if(!wrap)return;
  const dim={bg:'#F4F2EE',ink:'#1A1A1A',ink2:'#666',ink3:'#999',ink4:'#bbb',ink5:'#ccc',line:'rgba(0,0,0,.04)'};
  const SVG_PINK={accent:'#E03B7E',soft:'#FCE5EC',text:'#9F1B4F'};

  const all=FL_MAINT;
  const totalJobs=all.length;
  const cntPending=all.filter(m=>m.status==='pending').length;
  const cntInProgress=all.filter(m=>m.status==='inprogress').length;
  const cntDone=all.filter(m=>m.status==='done').length;
  const cntActive=cntInProgress;

  const yr=new Date(TODAY_STR).getFullYear();
  const ytdJobs=all.filter(m=>m.startDate&&new Date(m.startDate).getFullYear()===yr);
  const ytdSpend=ytdJobs.filter(m=>m.status==='done').reduce((s,m)=>s+(typeof flMaintCalcCost==='function'?flMaintCalcCost(m.id):0),0);
  const avgCost=cntDone?Math.round(ytdSpend/cntDone):0;
  const boatsServiced=new Set(all.map(m=>m.boatId).filter(Boolean)).size;

  const cntCorrective=all.filter(m=>m.type==='corrective').length;
  const cntPreventive=all.filter(m=>m.type==='preventive').length;
  const cntScheduled=all.filter(m=>m.type==='scheduled').length;

  const thisMonth=TODAY_STR.slice(0,7);
  const doneMonth=all.filter(m=>m.status==='done'&&(m.endDate||m.startDate||'').startsWith(thisMonth));
  const doneMonthCount=doneMonth.length;
  const doneMonthSpend=doneMonth.reduce((s,m)=>s+(typeof flMaintCalcCost==='function'?flMaintCalcCost(m.id):0),0);

  const todayD=new Date(TODAY_STR);
  const inProgJobs=all.filter(m=>m.status==='inprogress');
  const avgDaysOpen=inProgJobs.length?Math.round(inProgJobs.reduce((s,m)=>{
    if(!m.startDate)return s;
    return s+Math.max(0,Math.ceil((todayD-new Date(m.startDate))/86400000));
  },0)/inProgJobs.length):0;

  const headerBar=`<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px">
    <div style="display:flex;align-items:center;gap:6px">
      <div style="display:flex;align-items:center;gap:6px;background:white;border:1px solid ${dim.line};border-radius:20px;padding:3px 12px 3px 3px"><div style="width:24px;height:24px;border-radius:50%;background:#A32D2D;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">CR</div><span style="font-size:12px;font-weight:500">Corrective · ${cntCorrective}</span></div>
      <div style="display:flex;align-items:center;gap:6px;background:white;border:1px solid ${dim.line};border-radius:20px;padding:3px 12px 3px 3px"><div style="width:24px;height:24px;border-radius:50%;background:#BA7517;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">PV</div><span style="font-size:12px;font-weight:500">Preventive · ${cntPreventive}</span></div>
      <div style="display:flex;align-items:center;gap:6px;background:white;border:1px solid ${dim.line};border-radius:20px;padding:3px 12px 3px 3px"><div style="width:24px;height:24px;border-radius:50%;background:#185FA5;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">SC</div><span style="font-size:12px;font-weight:500">Scheduled · ${cntScheduled}</span></div>
      <div style="width:32px;height:32px;border-radius:50%;background:${dim.ink};color:white;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600">M</div>
    </div>
    <button onclick="flOpenCreateJobModal()" style="background:${dim.ink};color:white;border:none;border-radius:20px;padding:7px 16px;font-size:11px;font-weight:600;cursor:pointer">+ Create Job</button>
  </div>`;

  const kpiStrip=`<div style="display:grid;grid-template-columns:1.6fr 0.85fr 0.85fr 0.85fr 1fr;gap:8px;margin-bottom:14px;align-items:stretch">
    <div style="grid-column:1;align-self:end;padding-bottom:6px">
      <div style="font-size:13px;font-weight:500;color:${dim.ink4};margin-bottom:2px">Maintenance Jobs</div>
      <div style="display:flex;align-items:baseline;gap:8px;margin-bottom:8px;flex-wrap:wrap">
        <span style="font-size:42px;font-weight:700;letter-spacing:-1.5px;line-height:1">${totalJobs}</span>
        <span style="font-size:18px;color:${dim.ink3};font-weight:500">jobs</span>
        <span style="display:inline-flex;align-items:center;background:${SVG_PINK.accent};color:white;padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600">▴ ${cntActive} active</span>
        ${cntPending?`<span style="display:inline-flex;align-items:center;background:#FCEBEB;color:#A32D2D;padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600">${cntPending} pending</span>`:''}
      </div>
      <div style="font-size:11px;color:${dim.ink3}">YTD spend ฿${ytdSpend.toLocaleString()} · avg ฿${avgCost.toLocaleString()}/job · ${boatsServiced} boats serviced</div>
    </div>

    <div style="grid-column:2;background:white;border-radius:14px;padding:11px 13px;border:2px solid ${cntPending?'#A32D2D':dim.line}">
      <div style="font-size:10px;color:${dim.ink3}">Pending</div>
      <div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="background:#A32D2D;color:white;padding:2px 9px;border-radius:14px;font-size:14px;font-weight:700">${cntPending}</span><span style="font-size:11px;color:${dim.ink3};margin-left:2px">jobs</span></div>
      <div style="font-size:11px;color:#A32D2D;margin-top:7px;font-weight:600">awaiting start</div>
    </div>

    <div style="grid-column:3;background:white;border-radius:14px;padding:11px 13px;border:2px solid ${cntInProgress?'#BA7517':dim.line}">
      <div style="font-size:10px;color:${dim.ink3}">In progress</div>
      <div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="background:#BA7517;color:white;padding:2px 9px;border-radius:14px;font-size:14px;font-weight:700">${cntInProgress}</span><span style="font-size:11px;color:${dim.ink3};margin-left:2px">jobs</span></div>
      <div style="font-size:11px;color:#854F0B;margin-top:7px;font-weight:600">avg ${avgDaysOpen} days open</div>
    </div>

    <div style="grid-column:4;background:white;border-radius:14px;padding:11px 13px;border:1px solid ${dim.line}">
      <div style="font-size:10px;color:${dim.ink3}">Done this month</div>
      <div style="display:flex;align-items:baseline;gap:3px;margin-top:2px"><span style="font-size:18px;font-weight:700;line-height:1.2;color:#1D9E75">${doneMonthCount}</span><span style="font-size:11px;color:${dim.ink3};font-weight:500">jobs</span></div>
      <div style="font-size:11px;color:#0F6E56;margin-top:6px;font-weight:600">฿${doneMonthSpend.toLocaleString()} spent</div>
    </div>

    <div style="grid-column:5;background:${dim.ink};color:white;border-radius:14px;padding:11px 13px">
      <div style="font-size:10px;color:#aaa">By type</div>
      <div style="display:flex;flex-direction:column;gap:3px;margin-top:4px">
        <div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Corrective</span><span style="font-size:11px;font-weight:600;color:${cntCorrective?'#FF8FA8':'white'}">${cntCorrective} jobs</span></div>
        <div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Preventive</span><span style="font-size:11px;font-weight:600;color:white">${cntPreventive} jobs</span></div>
        <div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Scheduled</span><span style="font-size:11px;font-weight:600;color:white">${cntScheduled} jobs</span></div>
      </div>
    </div>
  </div>`;

  // Split jobs by tab: Active = pending/inprogress · Awaiting = done with awaitingInvoice flag · Archive = done
  const allActiveJobs = all.filter(m => m.status === 'pending' || m.status === 'inprogress');
  const allArchiveJobs = all.filter(m => m.status === 'done');
  const allAwaitingJobs = all.filter(m => {
    if(m.status !== 'done') return false;
    if(!m.awaitingInvoice) return false;  // ต้องติ๊ก "รอใบวางบิล" ตอนปิดงานเท่านั้น
    // Auto-clear ONLY when the supplier bill is settled = all linked memos are PAID.
    // (A memo merely existing / RECEIVED still means we're WAITING for the invoice → keep here.)
    const linkedMemos = (typeof FL_MEMOS !== 'undefined' ? FL_MEMOS : []).filter(memo => memo.maintId === m.id);
    if(linkedMemos.length > 0 && linkedMemos.every(mo => mo.status === 'paid')) return false;
    return true;
  });
  
  let jobs;
  if(_maintArchiveTab === 'awaiting'){
    jobs = [...allAwaitingJobs];
  } else if(_maintArchiveTab === 'archive'){
    jobs = [...allArchiveJobs];
  } else {
    jobs = [...allActiveJobs];
  }
  if(_maintStFilter!=='all') jobs=jobs.filter(m=>m.status===_maintStFilter);
  if(_maintTypeFilter!=='all') jobs=jobs.filter(m=>m.type===_maintTypeFilter);
  if(_maintBoatFilter!=='all') jobs=jobs.filter(m=>m.boatId===_maintBoatFilter);
  jobs.sort((a,b)=>(b.startDate||'').localeCompare(a.startDate||''));

  const STATUS_STYLE={
    pending:{bg:'#FCEBEB',color:'#A32D2D',label:'PENDING',stripe:'#A32D2D'},
    inprogress:{bg:'#FAEEDA',color:'#854F0B',label:'IN PROG',stripe:'#BA7517'},
    done:{bg:'#1D9E75',color:'white',label:'DONE',stripe:'#1D9E75'}
  };
  const TYPE_STYLE={
    corrective:{bg:'#FCEBEB',color:'#A32D2D',label:'CORRECTIVE'},
    preventive:{bg:'#FAEEDA',color:'#854F0B',label:'PREVENTIVE'},
    scheduled:{bg:'#E6F1FB',color:'#185FA5',label:'SCHEDULED'}
  };

  const MONTHS_EN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const fmtShortD=(s)=>{if(!s)return'';const d=new Date(s);return`${MONTHS_EN[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;};

  const buildJobRow=(m)=>{
    const isSel=_selMaintId===m.id;
    const b=getBoat(m.boatId);
    const ss=STATUS_STYLE[m.status]||STATUS_STYLE.pending;
    const ts=TYPE_STYLE[m.type]||{bg:'#F4F2EE',color:'#666',label:'JOB'};
    const bc = b && typeof getBoatColor==='function' ? getBoatColor(b.id) : null;
    const boatPill = b && bc ? `<span style="background:${bc.bg};color:${bc.text};padding:1px 7px;border-radius:7px;font-size:10px;font-weight:600">${b.name}</span>` : (b?b.name:'');
    const jobCost = typeof flMaintCalcCost==='function' ? flMaintCalcCost(m.id) : (m.cost||0);
    const fmtKR = (n) => { if(n >= 1000000) return (n/1000000).toFixed(1)+'M'; if(n >= 1000) return Math.round(n/1000)+'K'; return Math.round(n).toString(); };
    const costPill = jobCost > 0 ? `<span style="font-size:10px;font-weight:600;font-family:'DM Mono',monospace;color:${isSel?SVG_PINK.text:'#0F6E56'};background:${isSel?'transparent':'#E6F4ED'};padding:1px 6px;border-radius:6px">฿${fmtKR(jobCost)}</span>` : '';
    return`<div onclick="flSelMaint('${m.id}')" style="display:flex;gap:10px;padding:10px 8px;border-radius:8px;cursor:pointer;${isSel?`background:${SVG_PINK.soft};border:1px solid #F0C0D0;`:`border-top:0.5px solid ${dim.line};margin-top:2px;`}">
      <div style="width:3px;background:${ss.stripe};border-radius:2px;flex-shrink:0;align-self:stretch"></div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:5px;margin-bottom:3px;flex-wrap:wrap">
          <span style="font-size:10px;font-family:'DM Mono',monospace;color:${isSel?SVG_PINK.text:dim.ink3};font-weight:600">${m.no||'—'}</span>
          <span style="background:${ts.bg};color:${ts.color};padding:1px 6px;border-radius:7px;font-size:9px;font-weight:600">${ts.label}</span>
          ${boatPill}
          ${costPill}
        </div>
        <div style="font-size:12px;font-weight:${isSel?600:500};color:${dim.ink};overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${m.title||'—'}</div>
        <div style="font-size:10px;color:${isSel?SVG_PINK.text:dim.ink3};margin-top:2px;font-family:'DM Mono',monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${fmtShortD(m.startDate)}${m.location?' · '+m.location:''}</div>
      </div>
      <div style="display:flex;flex-direction:column;align-items:end;gap:4px;flex-shrink:0">
        <span style="background:${ss.bg};color:${ss.color};padding:1px 7px;border-radius:8px;font-size:9px;font-weight:600">${ss.label}</span>
        ${m.status!=='done'?`<span onclick="flMaintTogglePin('${m.id}',event)" title="${m.pinned?'Unpin':'Pin to top'}" style="cursor:pointer;font-size:13px;line-height:1;opacity:${m.pinned?'1':'.35'}">📌</span>`:''}
      </div>
    </div>`;
  };

  const fBtn=(val,label,color)=>{
    const isOn=_maintStFilter===val;
    return`<button onclick="maintFilterSt('${val}')" style="background:${isOn?dim.ink:'transparent'};color:${isOn?'white':(color||dim.ink2)};border:${isOn?'none':'1px solid rgba(0,0,0,.08)'};border-radius:12px;padding:4px 10px;font-size:10px;font-weight:${isOn?600:500};cursor:pointer">${label}</button>`;
  };

  // Tab buttons: Active / Awaiting / Archive
  const archBtn=(val,label,count,accent)=>{
    const isOn=_maintArchiveTab===val;
    const stripeColor = accent || SVG_PINK.accent;
    const badgeBg = isOn ? (accent ? '#FFF8E1' : SVG_PINK.soft) : dim.bg;
    const badgeColor = isOn ? (accent ? '#854F0B' : SVG_PINK.text) : dim.ink3;
    return`<button onclick="maintSetArchive('${val}')" style="background:${isOn?'white':'transparent'};color:${isOn?dim.ink:dim.ink3};border:none;border-bottom:${isOn?'2px solid '+stripeColor:'2px solid transparent'};padding:6px 12px;font-size:11px;font-weight:${isOn?600:500};cursor:pointer;border-radius:0;margin-bottom:-1px">${label} <span style="background:${badgeBg};color:${badgeColor};padding:1px 6px;border-radius:7px;font-size:9px;font-weight:600;margin-left:3px;font-family:'DM Mono',monospace">${count}</span></button>`;
  };

  const tabBar=`<div style="display:flex;border-bottom:1px solid ${dim.line};margin-bottom:8px;gap:0">
    ${archBtn('active','Active',allActiveJobs.length)}
    ${allAwaitingJobs.length > 0 ? archBtn('awaiting','📋 Awaiting Invoice',allAwaitingJobs.length,'#BA7517') : ''}
    ${archBtn('archive','Archive',allArchiveJobs.length)}
  </div>`;

  // Sub-status filter adapts to tab
  let subFilter;
  if(_maintArchiveTab === 'active'){
    subFilter = `${fBtn('all','All')}${fBtn('pending','Pending','#A32D2D')}${fBtn('inprogress','In Progress','#854F0B')}`;
  } else if(_maintArchiveTab === 'awaiting'){
    subFilter = `${fBtn('all','All')}`;
  } else {
    subFilter = `${fBtn('all','All')}${fBtn('done','Done','#0F6E56')}`;
  }

  // Type filter — based on jobs in current tab (before type/boat filters applied)
  const baseJobs = (_maintArchiveTab === 'awaiting') ? allAwaitingJobs : ((_maintArchiveTab === 'archive') ? allArchiveJobs : allActiveJobs);
  const typeCnt = {corrective:0, preventive:0, scheduled:0};
  baseJobs.forEach(j=>{ if(typeCnt[j.type]!==undefined) typeCnt[j.type]++; });
  const typeBtn = (val, label, color) => {
    const isOn = _maintTypeFilter === val;
    const count = val === 'all' ? baseJobs.length : (typeCnt[val] || 0);
    return `<button onclick="maintSetType('${val}')" style="background:${isOn?color||dim.ink:'transparent'};color:${isOn?'white':(color||dim.ink2)};border:${isOn?'none':'1px solid rgba(0,0,0,.08)'};border-radius:12px;padding:4px 9px;font-size:10px;font-weight:${isOn?600:500};cursor:pointer;display:inline-flex;align-items:center;gap:4px">${label}<span style="opacity:${isOn?'.85':'.6'};font-family:'DM Mono',monospace">${count}</span></button>`;
  };
  const typeFilter = `${typeBtn('all','All')}${typeBtn('corrective','Corrective','#A32D2D')}${typeBtn('preventive','Preventive','#185FA5')}${typeBtn('scheduled','Scheduled','#7C5BC4')}`;

  // Boat filter — list boats that have jobs (with cost summary)
  const boatJobCnt = {};
  const boatJobCost = {};
  baseJobs.forEach(j=>{ 
    if(j.boatId){
      boatJobCnt[j.boatId] = (boatJobCnt[j.boatId]||0) + 1;
      const c = typeof flMaintCalcCost==='function' ? flMaintCalcCost(j.id) : (j.cost||0);
      boatJobCost[j.boatId] = (boatJobCost[j.boatId]||0) + c;
    }
  });
  const boatsWithJobs = Object.keys(boatJobCnt).map(bid=>{
    const b = (typeof BOATS!=='undefined') ? BOATS.find(x=>x.id===bid) : null;
    return {id:bid, name:b?b.name:bid, count:boatJobCnt[bid], cost:boatJobCost[bid]||0};
  }).sort((a,b)=>b.count - a.count);
  const fmtK = (n) => {
    if(n >= 1000000) return (n/1000000).toFixed(1)+'M';
    if(n >= 1000) return Math.round(n/1000)+'K';
    return Math.round(n).toString();
  };
  const boatBtn = (val, label, count, cost) => {
    const isOn = _maintBoatFilter === val;
    if(val === 'all'){
      return `<button onclick="maintSetBoat('${val}')" style="background:${isOn?dim.ink:'transparent'};color:${isOn?'white':dim.ink2};border:${isOn?'none':'1px solid rgba(0,0,0,.08)'};border-radius:12px;padding:4px 9px;font-size:10px;font-weight:${isOn?600:500};cursor:pointer;display:inline-flex;align-items:center;gap:4px">${label}<span style="opacity:${isOn?'.85':'.6'};font-family:'DM Mono',monospace">${count}</span></button>`;
    }
    const c = (typeof getBoatColor==='function') ? getBoatColor(val) : {bg:'#F4F2EE',text:'#666'};
    const costPill = cost > 0 ? `<span style="opacity:${isOn?'.75':'.55'};font-family:'DM Mono',monospace;font-size:9px;font-weight:500;padding-left:5px;border-left:1px solid ${isOn?'rgba(255,255,255,.3)':'rgba(0,0,0,.1)'};margin-left:2px">฿${fmtK(cost)}</span>` : '';
    return `<button onclick="maintSetBoat('${val}')" style="background:${isOn?c.text:c.bg};color:${isOn?'white':c.text};border:${isOn?'none':'1px solid '+c.bg};border-radius:12px;padding:4px 9px;font-size:10px;font-weight:${isOn?600:500};cursor:pointer;display:inline-flex;align-items:center;gap:4px">${label}<span style="opacity:${isOn?'.85':'.65'};font-family:'DM Mono',monospace">${count}</span>${costPill}</button>`;
  };
  const boatFilter = `${boatBtn('all','All boats',baseJobs.length,null)}${boatsWithJobs.map(b=>boatBtn(b.id,b.name,b.count,b.cost)).join('')}`;

  // Active filter count (Type + Boat only — Status เห็นเสมอ ไม่นับ)
  const advFilterCnt = (_maintTypeFilter!=='all'?1:0) + (_maintBoatFilter!=='all'?1:0);
  const hasAnyFilter = _maintStFilter!=='all' || advFilterCnt > 0;

  const filterToggleBtn = `<button onclick="maintToggleFilterPanel()" style="background:${_maintFilterExpand||advFilterCnt?SVG_PINK.soft:'transparent'};color:${_maintFilterExpand||advFilterCnt?SVG_PINK.text:dim.ink3};border:1px solid ${_maintFilterExpand||advFilterCnt?'rgba(255,107,71,.3)':'rgba(0,0,0,.08)'};border-radius:12px;padding:4px 10px;font-size:10px;font-weight:${advFilterCnt?600:500};cursor:pointer;display:inline-flex;align-items:center;gap:5px;margin-left:auto">
    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>
    Filter${advFilterCnt?` <span style="background:${SVG_PINK.accent};color:white;border-radius:8px;padding:0 5px;font-size:9px;font-family:'DM Mono',monospace">${advFilterCnt}</span>`:''}
    <span style="display:inline-block;transition:transform .15s;transform:rotate(${_maintFilterExpand?'180':'0'}deg);font-size:8px">▼</span>
  </button>`;

  const resetBtn = hasAnyFilter ? `<button onclick="maintResetFilters()" style="background:transparent;border:none;color:${dim.ink3};padding:3px 6px;font-size:9px;cursor:pointer;text-decoration:underline">Clear all</button>` : '';

  // Collapsible panel: Type + Boat
  const advancedPanel = _maintFilterExpand ? `<div style="background:#FBFAF7;border-radius:10px;padding:10px 12px;margin-bottom:8px;border:1px solid rgba(0,0,0,.04)">
    <div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:6px;align-items:center">
      <span style="font-size:9px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em;font-weight:600;width:36px">Type</span>
      ${typeFilter}
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:4px;align-items:center">
      <span style="font-size:9px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em;font-weight:600;width:36px">Boat</span>
      ${boatFilter}
    </div>
  </div>` : '';

  // Split jobs into pinned + regular (only in active tab)
  let listHtml = '';
  if(jobs.length === 0){
    listHtml = `<div style="font-size:12px;color:${dim.ink3};text-align:center;padding:20px">No jobs match filter</div>`;
  } else if(_maintArchiveTab === 'active'){
    const pinnedJobs = jobs.filter(j=>j.pinned).sort((a,b)=>(b.pinnedAt||'').localeCompare(a.pinnedAt||''));
    const regularJobs = jobs.filter(j=>!j.pinned);
    let html = '';
    if(pinnedJobs.length){
      html += `<div style="background:#FBEAF0;border-radius:8px;padding:8px;margin-bottom:8px;border-left:3px solid #D4537E">
        <div style="display:flex;align-items:center;gap:5px;margin-bottom:6px;padding:0 4px">
          <span style="font-size:13px;color:#993556">📌</span>
          <span style="font-size:10px;font-weight:600;color:#993556;letter-spacing:.05em;text-transform:uppercase">Pinned</span>
          <span style="font-size:10px;color:#993556;opacity:.6;font-family:'DM Mono',monospace">${pinnedJobs.length}</span>
        </div>
        ${pinnedJobs.map(buildJobRow).join('')}
      </div>`;
    }
    if(regularJobs.length){
      if(pinnedJobs.length){
        html += `<div style="font-size:10px;font-weight:600;color:${dim.ink3};letter-spacing:.05em;text-transform:uppercase;padding:6px 4px 4px">Active</div>`;
      }
      html += regularJobs.map(buildJobRow).join('');
    }
    listHtml = html;
  } else {
    listHtml = jobs.map(buildJobRow).join('');
  }
  const listPanel=`<div style="background:white;border-radius:14px;padding:13px 14px;border:1px solid ${dim.line};max-height:calc(100vh - 360px);overflow-y:auto">
    <div style="display:flex;align-items:center;gap:6px;margin-bottom:10px;padding-bottom:8px;border-bottom:1px solid rgba(0,0,0,.06)">
      <span style="font-size:12px;font-weight:600;flex:1">Jobs</span>
      ${resetBtn}
      <span style="font-size:10px;color:${dim.ink3}">${jobs.length}/${totalJobs}</span>
    </div>
    ${tabBar}
    <div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:8px;align-items:center">
      ${subFilter}
      ${filterToggleBtn}
    </div>
    ${advancedPanel}
    ${listHtml}
  </div>`;

  const detailPanel=`<div id="fl-maint-detail-mount" style="background:white;border-radius:14px;border:1px solid ${dim.line};overflow:hidden;min-height:400px"></div>`;

  wrap.innerHTML=`${headerBar}${kpiStrip}<div style="display:grid;grid-template-columns:340px 1fr;gap:12px;align-items:start">${listPanel}${detailPanel}</div>`;

  flRenderMaintDetailPink();
}

function flSelMaint(id){_selMaintId=id;flRenderMaint();}
function maintFilterSt(v){_maintStFilter=v;flRenderMaint();}
function maintSetArchive(t){
  _maintArchiveTab=t;
  _maintStFilter='all'; // reset sub-filter on tab switch
  _maintTypeFilter='all';
  _maintBoatFilter='all';
  flRenderMaint();
}
function maintSetType(v){_maintTypeFilter=v;flRenderMaint();}
function maintSetBoat(v){_maintBoatFilter=v;flRenderMaint();}
function maintToggleFilterPanel(){_maintFilterExpand=!_maintFilterExpand;flRenderMaint();}
function maintResetFilters(){
  _maintStFilter='all'; _maintTypeFilter='all'; _maintBoatFilter='all';
  flRenderMaint();
}

// ── COST ANALYTICS PAGE ──
let _costTimeFilter='all'; // 'all' | 'ytd' | 'month' | 'last30'
function costSetFilter(v){_costTimeFilter=v;flRenderCostAnalytics();}

// §costV2 · หมวดของค่าใช้จ่าย · อิงจากอุปกรณ์ที่ใบงานไปแตะ (assets[].type)
var COST_CATS = [
  {k:'hull',      t:'เรือ',        c:'#5B7CB3'},
  {k:'engine',    t:'เครื่องยนต์', c:'#E03B7E'},
  {k:'gearbox',   t:'เกียร์',      c:'#BA7517'},
  {k:'propeller', t:'ใบจักร',      c:'#1D9E75'},
  {k:'other',     t:'อื่น ๆ',      c:'#9AA0A6'},
  // §memoToBoat · เงินของเรือที่ไม่ได้ผ่านใบงานซ่อม (memo ระบุเรือไว้ตรง ๆ)
  {k:'memo',      t:'memo ตรง',   c:'#8B5CF6'}
];
function costCat(k){ return COST_CATS.find(function(x){return x.k===k;}) || COST_CATS[4]; }

// §memoToBoat · ส่วนของ memo ที่ "ไม่ได้เข้าสต็อก" จึงคิดเป็นค่าใช้จ่ายของเรือได้เลย
//   item ที่มี invId = ของเข้าคลัง · จะถูกคิดอีกครั้งตอนเบิกเข้าใบงาน ต้องกันไว้
//   ไม่มีรายการเลย (เช่น memo ค่าแรงล้วน) = คิดได้เต็มใบ
function laMemoDirectShare(mo){
  var items=(mo&&mo.items)||[];
  if(!items.length) return 1;
  var line=function(i){ var q=(i.qty==null?1:+i.qty)||0, p=+((i.price!=null)?i.price:i.cost)||0;
                        return (i.amount!=null? (+i.amount||0) : q*p); };
  var sub=0, direct=0;
  items.forEach(function(i){ var v=line(i); sub+=v; if(!i.invId) direct+=v; });
  if(sub<=0) return items.every(function(i){ return !i.invId; }) ? 1 : 0;
  return Math.max(0, Math.min(1, direct/sub));
}
// §costV2 · รวมตัวเลขทั้งหน้าไว้ที่เดียว · ทุกแผงอ่านจากก้อนนี้ก้อนเดียว
//   จะได้ไม่มีทางที่การ์ดบนกับตารางล่างคิดคนละวิธีแล้วตัวเลขไม่ตรงกัน
function costAggregate(){
  var CNT=['paid','received','approved'];
  var calc=function(m){ return typeof flMaintCalcCost==='function'?flMaintCalcCost(m.id):(m.cost||0); };
  var todayD=new Date(TODAY_STR), yr=todayD.getFullYear();
  var ytdStr=yr+'-01-01', thisMonth=TODAY_STR.slice(0,7);
  var l30=new Date(todayD); l30.setDate(l30.getDate()-30);
  var l30Str=l30.toISOString().slice(0,10);
  // §total · นับงานที่ปิดแล้ว "และ" งานที่ยังทำอยู่ · งานที่ยกเลิกไม่นับ
  var pool=(typeof FL_MAINT!=='undefined'?FL_MAINT:[]).filter(function(m){
    return m.status==='done'||m.status==='inprogress'||m.status==='on_hold'; });
  var dOf=function(m){ return m.endDate||m.startDate||''; };
  var scoped=pool;
  if(_costTimeFilter==='ytd')        scoped=pool.filter(function(m){return dOf(m)>=ytdStr;});
  else if(_costTimeFilter==='month') scoped=pool.filter(function(m){return dOf(m).indexOf(thisMonth)===0;});
  else if(_costTimeFilter==='last30')scoped=pool.filter(function(m){return dOf(m)>=l30Str;});

  var A={done:0,proc:0,nDone:0,nProc:0,byCat:{},byType:{},boats:{},units:{},rows:[],all:[]};
  COST_CATS.forEach(function(c){ A.byCat[c.k]={done:0,proc:0,n:0}; });
  ['corrective','preventive','scheduled'].forEach(function(t){ A.byType[t]={done:0,proc:0,n:0}; });

  var build=function(m, intoRows){
    var c=calc(m), isDone=(m.status==='done');
    var as=(m.assets||[]);
    var keys = as.length ? as.map(function(a){ return costCat(a.type).k; }) : ['other'];
    var share = c/keys.length;
    var row={ id:m.id, no:m.no||m.id, boatId:m.boatId||'', title:m.title||'',
              type:m.type||'corrective', st:m.status, date:dOf(m), cost:c,
              cats:keys, done:isDone };
    // แยกให้เห็นว่าเงินมาจากอะไหล่ที่เบิก หรือจาก memo ที่อนุมัติ
    var covered=(typeof flMaintPartsCoveredByMemo==='function')?flMaintPartsCoveredByMemo(m):0;
    row.parts=(m.parts||[]).reduce(function(x,p){ return x+((p.qty||0)*(p.cost||0)); },0)-covered;
    row.memo=((typeof FL_MEMOS!=='undefined'?FL_MEMOS:[])||[]).filter(function(mo){
      return mo.maintId===m.id && CNT.indexOf(mo.status)>=0; }).reduce(function(x,mo){ return x+(mo.amount||0); },0);
    if(intoRows) A.rows.push(row);
    A.all.push(row);
    if(!intoRows) return;

    if(isDone){ A.done+=c; A.nDone++; } else { A.proc+=c; A.nProc++; }
    if(A.byType[row.type]){ A.byType[row.type][isDone?'done':'proc']+=c; A.byType[row.type].n++; }
    // §count · ใบงานที่แตะอุปกรณ์หลายชิ้นในหมวดเดียวกัน ต้องนับเป็น 1 ใบ ไม่ใช่ N ใบ
    //   (เงินยังหารเฉลี่ยตามชิ้นเหมือนเดิม ยอดรวมจึงไม่เปลี่ยน)
    var seenCat={};
    keys.forEach(function(k,ix){
      A.byCat[k][isDone?'done':'proc']+=share;
      if(!seenCat[k]){ seenCat[k]=1; A.byCat[k].n++; }
      if(m.boatId){
        var b=A.boats[m.boatId]=A.boats[m.boatId]||{id:m.boatId,name:(getBoat(m.boatId)||{}).name||m.boatId,done:0,proc:0,n:0,cats:{}};
        b.cats[k]=(b.cats[k]||0)+share;
      }
      var a=as[ix]; if(!a) return;
      var uid=a.engId||a.gbId||a.propId; if(!uid) return;
      var u=A.units[uid]=A.units[uid]||{id:uid,cat:k,boatId:m.boatId||'',
        boat:(getBoat(m.boatId)||{}).name||'', label:'', cost:0, n:0};
      if(!u.label) u.label=costUnitLabel(uid,k,a);
      u.cost+=share; u.n++;
    });
    if(m.boatId && A.boats[m.boatId]){ A.boats[m.boatId][isDone?'done':'proc']+=c; A.boats[m.boatId].n++; }
  };
  scoped.forEach(function(m){ build(m,true); });

  // §memoToBoat · memo ที่ระบุเรือแต่ไม่ผูกใบงาน · ลงเป็นค่าใช้จ่ายของเรือลำนั้น
  //   เอาเฉพาะส่วนที่ไม่ได้เข้าสต็อก จะได้ไม่ไปซ้ำกับตอนเบิกอะไหล่เข้าใบงาน
  var _cenLeft=[];
  ((typeof FL_MEMOS!=='undefined'?FL_MEMOS:[])||[]).forEach(function(mo){
    if(mo.maintId) return;
    if(CNT.indexOf(mo.status)<0) return;
    var amtAll=+mo.amount||0;
    var dt=mo.createdDate||mo.approvedDate||'';
    var inScope=true;
    if(_costTimeFilter==='ytd')        inScope = dt>=ytdStr;
    else if(_costTimeFilter==='month') inScope = dt.indexOf(thisMonth)===0;
    else if(_costTimeFilter==='last30')inScope = dt>=l30Str;
    var share = mo.boatId ? laMemoDirectShare(mo) : 0;
    var amt   = Math.round(amtAll*share);
    var rest  = amtAll-amt;
    if(rest>0.5 || !mo.boatId) _cenLeft.push({ mo:mo, amt: mo.boatId?rest:amtAll });
    if(!mo.boatId || amt<=0 || !inScope) return;
    var isPaid = (mo.status==='paid');
    var row={ id:mo.id, no:mo.no||mo.id, boatId:mo.boatId, title:mo.title||'',
              type:(mo.memoType||'memo'), st:(isPaid?'done':'inprogress'), date:dt,
              cost:amt, cats:['memo'], done:isPaid, parts:0, memo:amt, kind:'memo' };
    A.rows.push(row); A.all.push(row);
    if(isPaid){ A.done+=amt; A.nDone++; } else { A.proc+=amt; A.nProc++; }
    A.byCat.memo[isPaid?'done':'proc']+=amt; A.byCat.memo.n++;
    var b=A.boats[mo.boatId]=A.boats[mo.boatId]||{id:mo.boatId,name:(getBoat(mo.boatId)||{}).name||mo.boatId,done:0,proc:0,n:0,cats:{}};
    b.cats.memo=(b.cats.memo||0)+amt;
    b[isPaid?'done':'proc']+=amt; b.n++;
  });

  A.total=A.done+A.proc;
  A.boatList=Object.keys(A.boats).map(function(k){ var b=A.boats[k]; b.tot=b.done+b.proc; return b; })
    .sort(function(a,z){ return z.tot-a.tot; });
  A.unitList=Object.keys(A.units).map(function(k){ return A.units[k]; })
    .sort(function(a,z){ return z.cost-a.cost; }).slice(0,10);
  A.boatsServiced=A.boatList.length;
  A.nJobs=A.nDone+A.nProc;
  // §cen · เหลือเฉพาะที่ยังลงเรือลำไหนไม่ได้ · ไม่ระบุเรือ หรือเป็นของที่เข้าสต็อก
  //   (ส่วนที่ลงเรือได้ ถูกย้ายไปอยู่ในยอดของเรือแล้วด้านบน)
  A.central={ n:_cenLeft.length,
              amt:_cenLeft.reduce(function(x,e){ return x+e.amt; },0),
              list:_cenLeft.map(function(e){ return e.mo; }),
              amtOf:_cenLeft.reduce(function(m,e){ m[e.mo.id]=e.amt; return m; },{}) };
  return A;
}
// ชื่ออุปกรณ์ · เอาจาก label ของใบงานก่อน ถ้าไม่มีค่อยไปหาใน registry
function costUnitLabel(uid, catKey, asset){
  if(asset && asset.label) return asset.label;
  var pick=function(arr){ var x=(arr||[]).find(function(o){return o.id===uid;});
    return x?((x.serial||'')+(x.pos?' \u00b7 '+x.pos:'')):''; };
  var lb='';
  if(catKey==='engine')         lb=pick(typeof FL_ENGINES!=='undefined'?FL_ENGINES:[]);
  else if(catKey==='gearbox')   lb=pick(typeof FL_GEARBOXES!=='undefined'?FL_GEARBOXES:[]);
  else if(catKey==='propeller') lb=pick(typeof FL_PROPELLERS!=='undefined'?FL_PROPELLERS:[]);
  return lb||uid;
}

// ══ §dw · ลิ้นชักรายละเอียด ══════════════════════════════════════════════
var _costDw={rows:[],cat:'all',title:'',sub:'',kpis:[]};
function costDwOpen(title, sub, kpis, rows){
  _costDw={rows:rows||[], cat:'all', title:title, sub:sub, kpis:kpis||[]};
  var ov=document.getElementById('cost-dw-ov'), dw=document.getElementById('cost-dw');
  if(!ov){ ov=document.createElement('div'); ov.id='cost-dw-ov'; ov.onclick=costDwClose; document.body.appendChild(ov); }
  if(!dw){ dw=document.createElement('div'); dw.id='cost-dw'; document.body.appendChild(dw); }
  var esc=(typeof escapeHTML==='function')?escapeHTML:function(x){return String(x||'');};
  var present=COST_CATS.filter(function(c){ return (rows||[]).some(function(r){ return r.cats.indexOf(c.k)>=0; }); });
  dw.innerHTML=''
   +'<div class="cdh"><button class="x" onclick="costDwClose()">&times;</button>'
   +  '<h2>'+esc(title)+'</h2><div class="s">'+esc(sub)+'</div>'
   +  '<div class="cdk">'+(kpis||[]).map(function(k){
        return '<div><div class="k">'+esc(k[0])+'</div><div class="v"'+(k[2]?' style="color:'+k[2]+'"':'')+'>'+k[1]+'</div></div>'; }).join('')+'</div>'
   +'</div>'
   +'<div class="cdt"><button class="on" onclick="costDwTab(\'all\',this)">\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14</button>'
   +  present.map(function(c){ return '<button onclick="costDwTab(\''+c.k+'\',this)"><i style="background:'+c.c+'"></i>'+c.t+'</button>'; }).join('')
   +'</div><div class="cdb"><table id="cost-dw-tbl"></table></div>';
  costDwPaint();
  ov.classList.add('on'); dw.classList.add('on');
}
function costDwTab(k, el){
  _costDw.cat=k;
  if(el&&el.parentNode) Array.prototype.forEach.call(el.parentNode.children,function(b){ b.classList.remove('on'); });
  if(el) el.classList.add('on');
  costDwPaint();
}
function costDwClose(){
  var ov=document.getElementById('cost-dw-ov'), dw=document.getElementById('cost-dw');
  if(ov) ov.classList.remove('on'); if(dw) dw.classList.remove('on');
}
function costDwPaint(){
  var t=document.getElementById('cost-dw-tbl'); if(!t) return;
  var esc=(typeof escapeHTML==='function')?escapeHTML:function(x){return String(x||'');};
  var f=function(n){ return '\u0e3f'+Math.round(n||0).toLocaleString(); };
  var rs=_costDw.rows.filter(function(r){ return _costDw.cat==='all'||r.cats.indexOf(_costDw.cat)>=0; });
  rs=rs.slice().sort(function(a,z){ return z.cost-a.cost || String(z.date).localeCompare(String(a.date)); });
  var sum=rs.reduce(function(x,r){return x+r.cost;},0),
      sp =rs.reduce(function(x,r){return x+r.parts;},0),
      sm =rs.reduce(function(x,r){return x+r.memo;},0);
  t.innerHTML=''
   +'<thead><tr><th style="width:86px">\u0e43\u0e1a\u0e07\u0e32\u0e19 / memo</th><th style="width:96px">\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48</th><th>\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07</th>'
   +'<th style="width:104px">\u0e2b\u0e21\u0e27\u0e14</th><th style="width:86px">\u0e2a\u0e16\u0e32\u0e19\u0e30</th>'
   +'<th class="n" style="width:88px">\u0e2d\u0e30\u0e44\u0e2b\u0e25\u0e48</th><th class="n" style="width:88px">memo</th>'
   +'<th class="n" style="width:98px">\u0e23\u0e27\u0e21</th></tr></thead><tbody>'
   +(rs.length?rs.map(function(r){
      var bn=(getBoat(r.boatId)||{}).name||'\u2014';
      var cats=r.cats.map(function(k){ var c=costCat(k);
        return '<span class="cpill" style="background:'+c.c+'22;color:'+c.c+'">'+c.t+'</span>'; }).join(' ');
      return '<tr onclick="'+(r.kind==='memo'
        ? ('costDwGoMemo(\''+String(r.no).replace(/\'/g,'')+'\')')
        : ('costDwGoJob(\''+r.id+'\')'))+'">'
       +'<td style="font-family:\'DM Mono\',monospace;font-weight:600">'+esc(r.no)+'</td>'
       +'<td style="font-family:\'DM Mono\',monospace;color:#666">'+esc(r.date||'\u2014')+'</td>'
       +'<td><div style="font-weight:600;color:#1A1A1A">'+esc(r.title)+'</div>'
       +   '<div style="font-size:10px;color:#999">'+esc(bn)+' \u00b7 '+esc(r.type)+'</div></td>'
       +'<td>'+cats+'</td>'
       +'<td>'+(r.done?'<span class="cpill" style="background:#E7F3EE;color:#1D6E56">\u0e1b\u0e34\u0e14\u0e41\u0e25\u0e49\u0e27</span>'
                     :'<span class="cpill" style="background:#FFF1DC;color:#A05A1A">\u0e01\u0e33\u0e25\u0e31\u0e07\u0e17\u0e33</span>')+'</td>'
       +'<td class="n" style="color:#666">'+(r.parts?f(r.parts):'\u2014')+'</td>'
       +'<td class="n" style="color:#666">'+(r.memo?f(r.memo):'\u2014')+'</td>'
       +'<td class="n" style="font-weight:700;color:#9F1B4F">'+f(r.cost)+'</td></tr>';
     }).join('')
    :'<tr><td colspan="8" style="text-align:center;padding:34px;color:#999">\u0e44\u0e21\u0e48\u0e21\u0e35\u0e43\u0e1a\u0e07\u0e32\u0e19\u0e43\u0e19\u0e2b\u0e21\u0e27\u0e14\u0e19\u0e35\u0e49</td></tr>')
   +'</tbody><tfoot><tr><td colspan="5">\u0e23\u0e27\u0e21 '+rs.length+' \u0e43\u0e1a\u0e07\u0e32\u0e19</td>'
   +'<td class="n">'+f(sp)+'</td><td class="n">'+f(sm)+'</td>'
   +'<td class="n" style="color:#9F1B4F">'+f(sum)+'</td></tr></tfoot>';
}
// §memoToBoat · แถวที่มาจาก memo ไม่มีใบงานให้เปิด · พาไปหน้า memo แล้วค้นด้วยเลขที่ใบ
function costDwGoMemo(no){
  costDwClose();
  if(typeof _memoSearch!=='undefined') _memoSearch=no||'';
  var el=document.querySelector('[data-view="fl-inventory"]');
  if(el && typeof nav==='function') nav(el);
  if(typeof invSwitchTab==='function') invSwitchTab('memo');
  if(typeof flRenderInventory==='function') flRenderInventory();
}
function costDwGoJob(id){
  costDwClose();
  if(typeof _selMaintId!=='undefined') _selMaintId=id;
  var el=document.querySelector('[data-view="fl-maintenance"]');
  if(el && typeof nav==='function') nav(el);
}
function costOpenStatus(k){
  var A=costAggregate();
  var rs=A.rows.filter(function(r){ return k==='done'?r.done:!r.done; });
  var f=function(n){ return '\u0e3f'+Math.round(n||0).toLocaleString(); };
  costDwOpen(k==='done'?'\u0e07\u0e32\u0e19\u0e17\u0e35\u0e48\u0e1b\u0e34\u0e14\u0e41\u0e25\u0e49\u0e27':'\u0e07\u0e32\u0e19\u0e17\u0e35\u0e48\u0e01\u0e33\u0e25\u0e31\u0e07\u0e14\u0e33\u0e40\u0e19\u0e34\u0e19\u0e01\u0e32\u0e23',
    (k==='done'?'\u0e08\u0e48\u0e32\u0e22\u0e08\u0e23\u0e34\u0e07\u0e41\u0e25\u0e30\u0e1b\u0e34\u0e14\u0e07\u0e32\u0e19\u0e41\u0e25\u0e49\u0e27':'\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e1b\u0e34\u0e14\u0e07\u0e32\u0e19 \u00b7 \u0e22\u0e2d\u0e14\u0e2d\u0e32\u0e08\u0e40\u0e1e\u0e34\u0e48\u0e21\u0e44\u0e14\u0e49\u0e2d\u0e35\u0e01')+' \u00b7 '+rs.length+' \u0e43\u0e1a\u0e07\u0e32\u0e19',
    [['\u0e23\u0e27\u0e21',f(k==='done'?A.done:A.proc)],['\u0e08\u0e33\u0e19\u0e27\u0e19\u0e43\u0e1a\u0e07\u0e32\u0e19',(k==='done'?A.nDone:A.nProc)]], rs);
}
function costOpenCat(k){
  var A=costAggregate(), c=costCat(k), v=A.byCat[k]||{done:0,proc:0};
  var rs=A.rows.filter(function(r){ return r.cats.indexOf(k)>=0; });
  var f=function(n){ return '\u0e3f'+Math.round(n||0).toLocaleString(); };
  costDwOpen('\u0e2b\u0e21\u0e27\u0e14 \u00b7 '+c.t, '\u0e17\u0e38\u0e01\u0e25\u0e33 \u00b7 '+rs.length+' \u0e43\u0e1a\u0e07\u0e32\u0e19',
    [['\u0e23\u0e27\u0e21\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14',f(v.done+v.proc)],
     ['\u0e1b\u0e34\u0e14\u0e07\u0e32\u0e19\u0e41\u0e25\u0e49\u0e27',f(v.done)],
     ['\u0e01\u0e33\u0e25\u0e31\u0e07\u0e14\u0e33\u0e40\u0e19\u0e34\u0e19\u0e01\u0e32\u0e23',f(v.proc),'#A05A1A']], rs);
}
function costOpenBoat(id){
  var A=costAggregate(), b=A.boats[id]; if(!b) return;
  var rs=A.rows.filter(function(r){ return r.boatId===id; });
  var f=function(n){ return '\u0e3f'+Math.round(n||0).toLocaleString(); };
  costDwOpen(b.name, '\u0e04\u0e48\u0e32\u0e43\u0e0a\u0e49\u0e08\u0e48\u0e32\u0e22\u0e0b\u0e48\u0e2d\u0e21\u0e1a\u0e33\u0e23\u0e38\u0e07\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14 \u00b7 '+b.n+' \u0e43\u0e1a\u0e07\u0e32\u0e19',
    [['\u0e23\u0e27\u0e21\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14',f(b.tot)],
     ['\u0e1b\u0e34\u0e14\u0e07\u0e32\u0e19\u0e41\u0e25\u0e49\u0e27',f(b.done)],
     ['\u0e01\u0e33\u0e25\u0e31\u0e07\u0e14\u0e33\u0e40\u0e19\u0e34\u0e19\u0e01\u0e32\u0e23',f(b.proc),'#A05A1A'],
     ['% \u0e02\u0e2d\u0e07\u0e01\u0e2d\u0e07\u0e40\u0e23\u0e37\u0e2d',(A.total?Math.round(b.tot/A.total*100):0)+'%']], rs);
}
function costOpenUnit(id){
  var A=costAggregate(), u=A.units[id]; if(!u) return;
  var rs=A.rows.filter(function(r){ return r.boatId===u.boatId && r.cats.indexOf(u.cat)>=0; });
  var f=function(n){ return '\u0e3f'+Math.round(n||0).toLocaleString(); };
  costDwOpen(u.label, costCat(u.cat).t+(u.boat?' \u00b7 '+u.boat:'')+' \u00b7 '+u.n+' \u0e43\u0e1a\u0e07\u0e32\u0e19',
    [['\u0e23\u0e27\u0e21\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14',f(u.cost)],['\u0e08\u0e33\u0e19\u0e27\u0e19\u0e07\u0e32\u0e19',u.n]], rs);
}
function costOpenCentral(){
  var A=costAggregate();
  var esc=(typeof escapeHTML==='function')?escapeHTML:function(x){return String(x||'');};
  var f=function(n){ return '\u0e3f'+Math.round(n||0).toLocaleString(); };
  // memo กลุ่มนี้ไม่มีใบงาน จึงใช้ตารางของตัวเองแทนตารางใบงาน
  costDwOpen('\u0e04\u0e48\u0e32\u0e43\u0e0a\u0e49\u0e08\u0e48\u0e32\u0e22\u0e01\u0e25\u0e32\u0e07 / \u0e0b\u0e37\u0e49\u0e2d\u0e40\u0e02\u0e49\u0e32\u0e04\u0e25\u0e31\u0e07',
    'memo \u0e17\u0e35\u0e48\u0e2d\u0e19\u0e38\u0e21\u0e31\u0e15\u0e34/\u0e08\u0e48\u0e32\u0e22\u0e41\u0e25\u0e49\u0e27\u0e41\u0e15\u0e48\u0e44\u0e21\u0e48\u0e44\u0e14\u0e49\u0e1c\u0e39\u0e01\u0e43\u0e1a\u0e07\u0e32\u0e19\u0e0b\u0e48\u0e2d\u0e21 \u00b7 '+A.central.n+' \u0e43\u0e1a',
    [['\u0e23\u0e27\u0e21',f(A.central.amt)],['\u0e08\u0e33\u0e19\u0e27\u0e19 memo',A.central.n]], []);
  var t=document.getElementById('cost-dw-tbl'); if(!t) return;
  var tabs=document.querySelector('#cost-dw .cdt'); if(tabs) tabs.style.display='none';
  t.innerHTML='<thead><tr><th style="width:82px">memo</th><th style="width:96px">\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48</th><th>\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07</th>'
   +'<th style="width:96px">\u0e1b\u0e23\u0e30\u0e40\u0e20\u0e17</th><th style="width:86px">\u0e2a\u0e16\u0e32\u0e19\u0e30</th><th class="n" style="width:104px">\u0e22\u0e2d\u0e14</th></tr></thead><tbody>'
   +A.central.list.slice().sort(function(a,z){return (z.amount||0)-(a.amount||0);}).map(function(mo){
      var bn=mo.boatId?((getBoat(mo.boatId)||{}).name||mo.boatId):'\u2014';
      var shown=(A.central.amtOf&&A.central.amtOf[mo.id]!=null)?A.central.amtOf[mo.id]:(mo.amount||0);
      return '<tr onclick="costDwGoMemo(\''+String(mo.no||'').replace(/\'/g,'')+'\')">'
       +'<td style="font-family:\'DM Mono\',monospace;font-weight:600">'+esc(mo.no||'')+'</td>'
       +'<td style="font-family:\'DM Mono\',monospace;color:#666">'+esc(mo.createdDate||'\u2014')+'</td>'
       +'<td><div style="font-weight:600;color:#1A1A1A">'+esc(mo.title||'')+'</div>'
       +   '<div style="font-size:10px;color:#999">'+esc(bn)+'</div></td>'
       +'<td style="color:#666">'+esc(mo.memoType||'')+'</td>'
       +'<td style="color:#666">'+esc(mo.status||'')+'</td>'
       +'<td class="n" style="font-weight:700;color:#9F1B4F">'+f(shown)
       + ((Math.round(shown)!==Math.round(mo.amount||0))
           ? '<div style="font-size:9.5px;color:#999;font-weight:400">\u0e40\u0e15\u0e47\u0e21\u0e43\u0e1a '+f(mo.amount)+'</div>' : '')
       +'</td></tr>';
     }).join('')
   +'</tbody><tfoot><tr><td colspan="5">\u0e23\u0e27\u0e21 '+A.central.n+' memo</td>'
   +'<td class="n" style="color:#9F1B4F">'+f(A.central.amt)+'</td></tr></tfoot>';
}
document.addEventListener('keydown',function(e){ if(e.key==='Escape') costDwClose(); });

function flRenderCostAnalytics(){
  const wrap=document.getElementById('fl-cost-wrap');
  if(!wrap)return;
  const dim={bg:'#F4F2EE',ink:'#1A1A1A',ink2:'#666',ink3:'#999',ink4:'#bbb',line:'rgba(0,0,0,.06)'};
  const PK={accent:'#E03B7E',soft:'#FCE5EC',text:'#9F1B4F'};
  const PROC='#E0B24B';   // สีของ "ยังไม่ปิดงาน" · ใช้ชุดเดียวกันทั้งหน้า
  const esc=(typeof escapeHTML==='function')?escapeHTML:(x=>String(x||''));
  const f=(n)=>'\u0e3f'+(Math.round(n||0)).toLocaleString();
  const fs=(n)=>{ n=Math.round(n||0); if(!n)return'\u0e3f0';
    if(n>=1000000)return'\u0e3f'+(n/1000000).toFixed(1)+'M';
    if(n>=1000)return'\u0e3f'+Math.round(n/1000)+'k'; return'\u0e3f'+n; };
  const yr=new Date(TODAY_STR).getFullYear();
  const thisMonth=TODAY_STR.slice(0,7);
  const A=costAggregate();
  const TOT=A.total||0;
  const pctOf=(v)=>TOT?Math.round(v/TOT*100):0;

  // ── หัวหน้า + ตัวกรองเวลา ──
  const headerBar=`<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;gap:12px;flex-wrap:wrap">
    <div style="display:flex;align-items:center;gap:9px">
      <div style="width:32px;height:32px;border-radius:50%;background:${dim.ink};color:white;display:flex;align-items:center;justify-content:center">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="20" x2="12" y2="10"/><line x1="18" y1="20" x2="18" y2="4"/><line x1="6" y1="20" x2="6" y2="16"/></svg>
      </div>
    </div>
    <div style="background:white;border:1px solid ${dim.line};border-radius:24px;padding:2px;display:flex;flex-wrap:wrap">
      ${[['all','All time'],['ytd','YTD '+yr],['last30','Last 30 days'],['month','This month']].map(([k,lbl])=>{
        const on=_costTimeFilter===k;
        return `<button onclick="costSetFilter('${k}')" style="background:${on?dim.ink:'transparent'};color:${on?'white':dim.ink2};border:none;border-radius:14px;padding:5px 14px;font-size:11px;font-weight:${on?600:500};cursor:pointer;font-family:inherit">${lbl}</button>`;
      }).join('')}
    </div>
  </div>`;

  // ── §total · ยอดรวม แล้วแยกปิดแล้ว / กำลังทำ ──
  const legBox=(color,t1,val,t2,onclick)=>`<div onclick="${onclick}" style="flex:1;min-width:180px;border:1px solid ${dim.line};border-radius:12px;padding:10px 12px;display:flex;align-items:center;gap:10px;cursor:pointer;transition:.15s" onmouseover="this.style.background='${PK.soft}';this.style.borderColor='#f3c6d8'" onmouseout="this.style.background='transparent';this.style.borderColor='${dim.line}'">
      <span style="width:11px;height:11px;border-radius:4px;background:${color};flex:none"></span>
      <div style="min-width:0"><div style="font-size:11px;color:${dim.ink2};font-weight:600">${t1}</div>
        <div style="font-size:17px;font-weight:700;font-family:'DM Mono',monospace;line-height:1.15">${val}</div>
        <div style="font-size:10.5px;color:${dim.ink3}">${t2}</div></div>
      <span style="margin-left:auto;font-size:10px;color:${dim.ink3}">\u0e14\u0e39 \u203a</span></div>`;

  const totalCard=`<div style="background:white;border:1px solid ${dim.line};border-radius:14px;padding:15px 17px">
    <div style="font-size:13px;font-weight:500;color:${dim.ink4}">\u0e04\u0e48\u0e32\u0e43\u0e0a\u0e49\u0e08\u0e48\u0e32\u0e22\u0e0b\u0e48\u0e2d\u0e21\u0e1a\u0e33\u0e23\u0e38\u0e07\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14</div>
    <div style="display:flex;align-items:baseline;gap:9px;flex-wrap:wrap;margin:2px 0 3px">
      <b style="font-size:42px;font-weight:700;letter-spacing:-1.5px;line-height:1;font-family:'DM Mono',monospace">${fs(TOT)}</b>
      <span style="font-size:16px;color:${dim.ink3};font-weight:500">\u0e43\u0e19\u0e0a\u0e48\u0e27\u0e07\u0e17\u0e35\u0e48\u0e40\u0e25\u0e37\u0e2d\u0e01</span>
    </div>
    <div style="font-size:11.5px;color:${dim.ink3}">${A.boatsServiced} \u0e25\u0e33 \u00b7 ${A.nJobs} \u0e43\u0e1a\u0e07\u0e32\u0e19 \u00b7 \u0e40\u0e09\u0e25\u0e35\u0e48\u0e22 ${f(A.nJobs?TOT/A.nJobs:0)}/\u0e43\u0e1a</div>
    <div style="display:flex;height:13px;border-radius:7px;overflow:hidden;margin:14px 0 11px;background:#eee">
      <i style="display:block;height:100%;background:${dim.ink};width:${TOT?A.done/TOT*100:0}%"></i>
      <i style="display:block;height:100%;background:${PROC};width:${TOT?A.proc/TOT*100:0}%"></i>
    </div>
    <div style="display:flex;gap:9px;flex-wrap:wrap">
      ${legBox(dim.ink,'\u0e1b\u0e34\u0e14\u0e07\u0e32\u0e19\u0e41\u0e25\u0e49\u0e27 \u00b7 \u0e08\u0e48\u0e32\u0e22\u0e08\u0e23\u0e34\u0e07',f(A.done),A.nDone+' \u0e43\u0e1a\u0e07\u0e32\u0e19 \u00b7 '+pctOf(A.done)+'% \u0e02\u0e2d\u0e07\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14',"costOpenStatus('done')")}
      ${legBox(PROC,'\u0e01\u0e33\u0e25\u0e31\u0e07\u0e14\u0e33\u0e40\u0e19\u0e34\u0e19\u0e01\u0e32\u0e23 \u00b7 \u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e1b\u0e34\u0e14',f(A.proc),A.nProc+' \u0e43\u0e1a\u0e07\u0e32\u0e19 \u00b7 '+pctOf(A.proc)+'% \u0e02\u0e2d\u0e07\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14',"costOpenStatus('proc')")}
    </div>
  </div>`;

  // ── §cen · ค่าใช้จ่ายกลาง · แยกไว้ ไม่บวกเข้ายอดรวม ──
  const centralCard=`<div onclick="costOpenCentral()" style="background:white;border:1px solid ${dim.line};border-radius:14px;padding:15px 17px;cursor:pointer">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:9px;gap:8px">
      <b style="font-size:13px;font-weight:600">\u0e04\u0e48\u0e32\u0e43\u0e0a\u0e49\u0e08\u0e48\u0e32\u0e22\u0e01\u0e25\u0e32\u0e07 / \u0e0b\u0e37\u0e49\u0e2d\u0e40\u0e02\u0e49\u0e32\u0e04\u0e25\u0e31\u0e07</b>
      <span style="font-size:10px;color:${dim.ink3}">\u0e44\u0e21\u0e48\u0e23\u0e27\u0e21\u0e43\u0e19\u0e22\u0e2d\u0e14\u0e0b\u0e49\u0e32\u0e22 \u00b7 \u0e01\u0e14\u0e14\u0e39 \u203a</span>
    </div>
    <div style="font-size:25px;font-weight:700;font-family:'DM Mono',monospace;letter-spacing:-.7px">${f(A.central.amt)}</div>
    <div style="font-size:11px;color:${dim.ink3};margin-top:3px">${A.central.n} memo \u00b7 \u0e44\u0e21\u0e48\u0e23\u0e30\u0e1a\u0e38\u0e40\u0e23\u0e37\u0e2d \u0e2b\u0e23\u0e37\u0e2d\u0e40\u0e1b\u0e47\u0e19\u0e02\u0e2d\u0e07\u0e17\u0e35\u0e48\u0e40\u0e02\u0e49\u0e32\u0e2a\u0e15\u0e47\u0e2d\u0e01</div>
    <div style="background:#FFF6E5;border-radius:10px;padding:9px 11px;font-size:10.5px;color:#A05A1A;line-height:1.55;margin-top:10px">
      memo \u0e17\u0e35\u0e48<b>\u0e23\u0e30\u0e1a\u0e38\u0e40\u0e23\u0e37\u0e2d</b>\u0e44\u0e27\u0e49 \u0e16\u0e39\u0e01\u0e22\u0e49\u0e32\u0e22\u0e44\u0e1b\u0e23\u0e27\u0e21\u0e43\u0e19\u0e22\u0e2d\u0e14\u0e02\u0e2d\u0e07\u0e40\u0e23\u0e37\u0e2d\u0e25\u0e33\u0e19\u0e31\u0e49\u0e19\u0e41\u0e25\u0e49\u0e27 \u00b7 \u0e2b\u0e21\u0e27\u0e14 <b>memo \u0e15\u0e23\u0e07</b>
      \u0e17\u0e35\u0e48\u0e40\u0e2b\u0e25\u0e37\u0e2d\u0e15\u0e23\u0e07\u0e19\u0e35\u0e49\u0e04\u0e37\u0e2d\u0e43\u0e1a\u0e17\u0e35\u0e48\u0e44\u0e21\u0e48\u0e23\u0e30\u0e1a\u0e38\u0e40\u0e23\u0e37\u0e2d \u0e01\u0e31\u0e1a\u0e2d\u0e30\u0e44\u0e2b\u0e25\u0e48\u0e17\u0e35\u0e48<b>\u0e23\u0e31\u0e1a\u0e40\u0e02\u0e49\u0e32\u0e2a\u0e15\u0e47\u0e2d\u0e01</b>
      \u0e0b\u0e36\u0e48\u0e07\u0e08\u0e30\u0e16\u0e39\u0e01\u0e04\u0e34\u0e14\u0e40\u0e1b\u0e47\u0e19\u0e02\u0e2d\u0e07\u0e40\u0e23\u0e37\u0e2d\u0e2d\u0e22\u0e39\u0e48\u0e41\u0e25\u0e49\u0e27\u0e15\u0e2d\u0e19\u0e40\u0e1a\u0e34\u0e01\u0e2d\u0e2d\u0e01\u0e21\u0e32\u0e43\u0e0a\u0e49 \u0e08\u0e36\u0e07\u0e44\u0e21\u0e48\u0e1a\u0e27\u0e01\u0e0b\u0e49\u0e33\u0e15\u0e23\u0e07\u0e19\u0e35\u0e49
    </div>
  </div>`;

  // ── §cat · การ์ดหมวด ──
  const catCards=COST_CATS.map(c=>{
    const v=A.byCat[c.k]||{done:0,proc:0,n:0}, t=v.done+v.proc;
    return `<div onclick="costOpenCat('${c.k}')" style="background:white;border:1px solid ${dim.line};border-radius:14px;padding:12px 13px;cursor:pointer;transition:.15s" onmouseover="this.style.boxShadow='0 4px 14px rgba(0,0,0,.05)'" onmouseout="this.style.boxShadow='none'">
      <div style="display:flex;align-items:center;gap:7px;font-size:11.5px;font-weight:700"><i style="width:9px;height:9px;border-radius:3px;background:${c.c};flex:none"></i>${c.t}</div>
      <div style="font-size:20px;font-weight:700;font-family:'DM Mono',monospace;margin:7px 0 2px;letter-spacing:-.5px">${fs(t)}</div>
      <div style="font-size:10.5px;color:${dim.ink3}">${v.n} \u0e43\u0e1a\u0e07\u0e32\u0e19 \u00b7 ${pctOf(t)}% \u0e02\u0e2d\u0e07\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14</div>
      <div style="display:flex;height:5px;border-radius:3px;overflow:hidden;background:#eee;margin-top:9px">
        <i style="display:block;height:100%;background:${c.c};width:${t?v.done/t*100:0}%"></i>
        <i style="display:block;height:100%;background:${c.c}55;width:${t?v.proc/t*100:0}%"></i></div>
      <div style="font-size:10.5px;color:${dim.ink3};margin-top:5px">\u0e1b\u0e34\u0e14\u0e41\u0e25\u0e49\u0e27 ${fs(v.done)} \u00b7 \u0e04\u0e49\u0e32\u0e07 ${fs(v.proc)}</div>
    </div>`;
  }).join('');

  // ── กราฟรายเดือน · ซ้อนปิดแล้ว/กำลังทำ ──
  const MN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const months={}; const order=[];
  for(let i=11;i>=0;i--){ const d=new Date(TODAY_STR); d.setDate(1); d.setMonth(d.getMonth()-i);
    const k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
    months[k]={k,l:MN[d.getMonth()],y:d.getFullYear(),done:0,proc:0}; order.push(k); }
  A.all.forEach(r=>{ const k=(r.date||'').slice(0,7); if(months[k]) months[k][r.done?'done':'proc']+=r.cost; });
  const mxM=Math.max(1,...order.map(k=>months[k].done+months[k].proc));
  const H=120;
  const chartSection=`<div style="background:white;border:1px solid ${dim.line};border-radius:14px;padding:14px 16px;margin-bottom:12px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;gap:10px;flex-wrap:wrap">
      <span style="font-size:13px;font-weight:600">\u0e41\u0e19\u0e27\u0e42\u0e19\u0e49\u0e21\u0e23\u0e32\u0e22\u0e40\u0e14\u0e37\u0e2d\u0e19</span>
      <span style="font-size:10px;color:${dim.ink3}">12 \u0e40\u0e14\u0e37\u0e2d\u0e19\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14 \u00b7 \u0e17\u0e38\u0e01\u0e43\u0e1a\u0e07\u0e32\u0e19 \u00b7 \u0e40\u0e02\u0e49\u0e21 = \u0e1b\u0e34\u0e14\u0e41\u0e25\u0e49\u0e27 \u00b7 \u0e40\u0e2b\u0e25\u0e37\u0e2d\u0e07 = \u0e01\u0e33\u0e25\u0e31\u0e07\u0e14\u0e33\u0e40\u0e19\u0e34\u0e19\u0e01\u0e32\u0e23</span>
    </div>
    <div style="display:flex;align-items:flex-end;gap:6px;height:${H+52}px;padding:0 4px">
      ${order.map(k=>{ const m=months[k], t=m.done+m.proc, h=t?Math.max(4,t/mxM*H):2;
        const isCur=(k===thisMonth);
        return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:5px;min-width:0">
          <div style="font-size:9px;font-family:'DM Mono',monospace;color:${dim.ink3};min-height:12px;white-space:nowrap">${t?fs(t):''}</div>
          <div title="${t?f(t)+' \u00b7 \u0e1b\u0e34\u0e14\u0e41\u0e25\u0e49\u0e27 '+f(m.done)+' \u00b7 \u0e04\u0e49\u0e32\u0e07 '+f(m.proc):'\u0e44\u0e21\u0e48\u0e21\u0e35\u0e07\u0e32\u0e19'}" style="width:74%;height:${h}px;display:flex;flex-direction:column;justify-content:flex-end;border-radius:4px 4px 0 0;overflow:hidden">
            <i style="display:block;width:100%;background:${PROC};height:${t?m.proc/t*100:0}%"></i>
            <i style="display:block;width:100%;background:${t?dim.ink:'#cdc8c1'};height:${t?m.done/t*100:100}%"></i>
          </div>
          <div style="font-size:9px;color:${isCur?PK.text:dim.ink3};font-weight:${isCur?600:400};font-family:'DM Mono',monospace;text-align:center;line-height:1.3">${m.l}<br><span style="opacity:.65;font-size:8px">'${String(m.y).slice(-2)}</span></div>
        </div>`; }).join('')}
    </div>
  </div>`;

  // ── §boat · เรือ · แท่งแบ่งตามหมวด ──
  const boatRows=A.boatList.slice(0,12).map((b,i)=>{
    const t=b.tot||0;
    const segs=COST_CATS.filter(c=>(b.cats[c.k]||0)>0)
      .map(c=>`<i style="display:block;height:100%;background:${c.c};width:${t?b.cats[c.k]/t*100:0}%"></i>`).join('');
    const brk=COST_CATS.filter(c=>(b.cats[c.k]||0)>0)
      .map(c=>`<span style="display:inline-flex;align-items:center;gap:4px"><i style="width:7px;height:7px;border-radius:2px;background:${c.c};display:inline-block"></i>${c.t} ${fs(b.cats[c.k])}</span>`).join('');
    return `<div onclick="costOpenBoat('${b.id}')" style="padding:9px 0;border-bottom:.5px solid rgba(0,0,0,.05);cursor:pointer;border-radius:6px;transition:.12s" onmouseover="this.style.background='${PK.soft}'" onmouseout="this.style.background='transparent'">
      <div style="display:flex;align-items:center;gap:8px">
        <span style="font-size:11px;font-family:'DM Mono',monospace;color:${dim.ink3};width:22px;font-weight:600">#${i+1}</span>
        <span style="font-size:12.5px;font-weight:600;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(b.name)}</span>
        ${b.proc>0?`<span style="font-size:9px;font-weight:700;padding:1px 6px;border-radius:5px;background:#FFF1DC;color:#A05A1A;white-space:nowrap">\u0e04\u0e49\u0e32\u0e07 ${fs(b.proc)}</span>`:''}
        <span style="font-size:10px;color:${dim.ink3};font-family:'DM Mono',monospace">${b.n} \u0e07\u0e32\u0e19</span>
        <span style="font-size:12.5px;font-weight:700;font-family:'DM Mono',monospace;color:${PK.text};min-width:82px;text-align:right">${f(t)}</span>
        <span style="font-size:10px;color:${dim.ink3};font-family:'DM Mono',monospace;width:32px;text-align:right">${pctOf(t)}%</span>
      </div>
      <div style="display:flex;height:6px;border-radius:3px;overflow:hidden;background:rgba(0,0,0,.05);margin:6px 0 0 30px">${segs}</div>
      <div style="margin:5px 0 0 30px;font-size:10px;color:${dim.ink3};display:flex;gap:11px;flex-wrap:wrap">${brk}</div>
    </div>`;
  }).join('')||`<div style="font-size:11px;color:${dim.ink3};text-align:center;padding:30px">\u0e44\u0e21\u0e48\u0e21\u0e35\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e43\u0e19\u0e0a\u0e48\u0e27\u0e07\u0e19\u0e35\u0e49</div>`;

  const boatPanel=`<div style="background:white;border:1px solid ${dim.line};border-radius:14px;padding:14px 16px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;gap:8px">
      <span style="font-size:13px;font-weight:600">\u0e40\u0e23\u0e37\u0e2d\u0e17\u0e35\u0e48\u0e43\u0e0a\u0e49\u0e40\u0e07\u0e34\u0e19\u0e21\u0e32\u0e01\u0e17\u0e35\u0e48\u0e2a\u0e38\u0e14</span>
      <span style="font-size:10px;color:${dim.ink3}">\u0e23\u0e27\u0e21\u0e17\u0e38\u0e01\u0e04\u0e48\u0e32\u0e43\u0e0a\u0e49\u0e08\u0e48\u0e32\u0e22 \u00b7 \u0e01\u0e14\u0e40\u0e1e\u0e37\u0e48\u0e2d\u0e14\u0e39\u0e23\u0e32\u0e22\u0e25\u0e30\u0e40\u0e2d\u0e35\u0e22\u0e14</span>
    </div>
    <div>${boatRows}</div>
  </div>`;

  // ── §unit · อุปกรณ์ ──
  const unitRows=A.unitList.map((u,i)=>{
    const c=costCat(u.cat);
    return `<div onclick="costOpenUnit('${u.id}')" style="padding:9px 0;border-bottom:.5px solid rgba(0,0,0,.05);cursor:pointer;display:flex;align-items:center;gap:8px;border-radius:6px;transition:.12s" onmouseover="this.style.background='${PK.soft}'" onmouseout="this.style.background='transparent'">
      <span style="font-size:11px;font-family:'DM Mono',monospace;color:${dim.ink3};width:22px;font-weight:600">#${i+1}</span>
      <div style="flex:1;min-width:0">
        <div style="font-size:11.5px;font-family:'DM Mono',monospace;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(u.label)}</div>
        <div style="font-size:9.5px;color:${dim.ink3};display:flex;align-items:center;gap:5px;margin-top:2px">
          <i style="width:7px;height:7px;border-radius:2px;background:${c.c};display:inline-block"></i>${c.t}${u.boat?' \u00b7 '+esc(u.boat):''}</div>
      </div>
      <span style="font-size:9.5px;color:${dim.ink3};font-family:'DM Mono',monospace">${u.n} \u0e07\u0e32\u0e19</span>
      <span style="font-size:12.5px;font-weight:700;font-family:'DM Mono',monospace;color:${PK.text};min-width:82px;text-align:right">${f(u.cost)}</span>
    </div>`;
  }).join('')||`<div style="font-size:11px;color:${dim.ink3};text-align:center;padding:30px">\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e21\u0e35\u0e07\u0e32\u0e19\u0e17\u0e35\u0e48\u0e23\u0e30\u0e1a\u0e38\u0e2d\u0e38\u0e1b\u0e01\u0e23\u0e13\u0e4c</div>`;

  const unitPanel=`<div style="background:white;border:1px solid ${dim.line};border-radius:14px;padding:14px 16px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;gap:8px">
      <span style="font-size:13px;font-weight:600">\u0e2d\u0e38\u0e1b\u0e01\u0e23\u0e13\u0e4c\u0e17\u0e35\u0e48\u0e43\u0e0a\u0e49\u0e40\u0e07\u0e34\u0e19\u0e21\u0e32\u0e01\u0e17\u0e35\u0e48\u0e2a\u0e38\u0e14</span>
      <span style="font-size:10px;color:${dim.ink3}">\u0e40\u0e04\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e22\u0e19\u0e15\u0e4c \u00b7 \u0e40\u0e01\u0e35\u0e22\u0e23\u0e4c \u00b7 \u0e43\u0e1a\u0e08\u0e31\u0e01\u0e23</span>
    </div>
    <div>${unitRows}</div>
  </div>`;

  // ── แยกตามประเภทงาน (ยังต้องการอยู่ · ย้ายลงมาไว้ล่าง) ──
  const TYPE_META={corrective:{t:'Corrective \u00b7 \u0e0b\u0e48\u0e2d\u0e21\u0e40\u0e21\u0e37\u0e48\u0e2d\u0e40\u0e2a\u0e35\u0e22',c:'#A32D2D'},
                   preventive:{t:'Preventive \u00b7 \u0e1b\u0e49\u0e2d\u0e07\u0e01\u0e31\u0e19',c:'#BA7517'},
                   scheduled:{t:'Scheduled \u00b7 \u0e15\u0e32\u0e21\u0e41\u0e1c\u0e19',c:'#185FA5'}};
  const typePanel=`<div style="background:white;border:1px solid ${dim.line};border-radius:14px;padding:14px 16px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
      <span style="font-size:13px;font-weight:600">\u0e41\u0e22\u0e01\u0e15\u0e32\u0e21\u0e1b\u0e23\u0e30\u0e40\u0e20\u0e17\u0e07\u0e32\u0e19</span>
      <span style="font-size:10px;color:${dim.ink3}">\u0e23\u0e27\u0e21\u0e07\u0e32\u0e19\u0e17\u0e35\u0e48\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e1b\u0e34\u0e14</span>
    </div>
    ${['corrective','preventive','scheduled'].map(k=>{
      const v=A.byType[k], t=v.done+v.proc, m=TYPE_META[k];
      return `<div style="padding:8px 0;border-bottom:.5px solid rgba(0,0,0,.05)">
        <div style="display:flex;align-items:center;gap:9px">
          <span style="width:10px;height:10px;border-radius:3px;background:${m.c};flex:none"></span>
          <span style="flex:1;font-size:11.5px;font-weight:600">${m.t}</span>
          <span style="font-size:10px;color:${dim.ink3};font-family:'DM Mono',monospace">${v.n} \u0e07\u0e32\u0e19</span>
          <span style="font-size:12.5px;font-weight:700;font-family:'DM Mono',monospace;min-width:82px;text-align:right">${f(t)}</span>
        </div>
        <div style="display:flex;height:5px;border-radius:3px;overflow:hidden;background:#eee;margin:6px 0 0 19px">
          <i style="display:block;height:100%;background:${m.c};width:${t?v.done/t*100:0}%"></i>
          <i style="display:block;height:100%;background:${m.c}55;width:${t?v.proc/t*100:0}%"></i></div>
      </div>`; }).join('')}
  </div>`;

  // ── By outcome · เฉพาะงานที่ปิดแล้ว (งานที่ยังทำอยู่ยังไม่มีผลลัพธ์) ──
  const OUT_STYLE={success:{color:'#1D9E75',label:'Success'},limited:{color:'#BA7517',label:'Limited use'},
                   rework:{color:'#E03B7E',label:'Rework needed'},decommission:{color:'#1A1A1A',label:'Decommissioned'},
                   cancelled:{color:'#A32D2D',label:'Cancelled'}};
  const byOut={},byOutN={};
  A.rows.filter(r=>r.done).forEach(r=>{ const m=FL_MAINT.find(x=>x.id===r.id)||{};
    const o=m.outcome||'success'; byOut[o]=(byOut[o]||0)+r.cost; byOutN[o]=(byOutN[o]||0)+1; });
  const outRows=Object.keys(OUT_STYLE).filter(o=>byOutN[o]).map(o=>{
    const os=OUT_STYLE[o], cnt=byOutN[o], cost=byOut[o]||0;
    return `<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:.5px solid rgba(0,0,0,.05)">
      <span style="width:10px;height:10px;border-radius:50%;background:${os.color};flex:none"></span>
      <div style="flex:1"><div style="font-size:11.5px;font-weight:600">${os.label}</div>
        <div style="font-size:9.5px;color:${dim.ink3};margin-top:1px">\u0e40\u0e09\u0e25\u0e35\u0e48\u0e22 ${f(cnt?cost/cnt:0)}/\u0e07\u0e32\u0e19</div></div>
      <span style="font-size:10px;color:${dim.ink3};font-family:'DM Mono',monospace">${cnt}</span>
      <span style="font-size:12.5px;font-weight:700;font-family:'DM Mono',monospace;min-width:82px;text-align:right">${f(cost)}</span>
    </div>`; }).join('');
  const outcomePanel=outRows?`<div style="background:white;border:1px solid ${dim.line};border-radius:14px;padding:14px 16px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
      <span style="font-size:13px;font-weight:600">\u0e1c\u0e25\u0e25\u0e31\u0e1e\u0e18\u0e4c\u0e07\u0e32\u0e19\u0e0b\u0e48\u0e2d\u0e21</span>
      <span style="font-size:10px;color:${dim.ink3}">\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e07\u0e32\u0e19\u0e17\u0e35\u0e48\u0e1b\u0e34\u0e14\u0e41\u0e25\u0e49\u0e27</span>
    </div>${outRows}</div>`:'';

  // ── §dupAudit · แถบตรวจข้อมูลซ้ำ · ข้อมูลซ้ำทำให้ทุกยอดในหน้านี้บวมโดยไม่มีสัญญาณอะไรเลย ──
  let dupBar='';
  try{
    const DS=(typeof laDupScan==='function')?laDupScan():null;
    if(DS && (DS.nDup>0 || DS.nNo>0)){
      const mkLine=(x,isNo)=>`<div style="display:flex;align-items:center;gap:9px;padding:6px 0;border-top:1px solid rgba(160,90,26,.14)">
          <span style="flex:1;font-size:11.5px;font-weight:600">${x.label}${x.money?' <span style="font-size:9px;background:#FCE5EC;color:#9F1B4F;border-radius:5px;padding:1px 6px;font-weight:700">\u0e01\u0e23\u0e30\u0e17\u0e1a\u0e22\u0e2d\u0e14\u0e40\u0e07\u0e34\u0e19</span>':''}</span>
          <span style="font-size:11.5px;font-family:'DM Mono',monospace;font-weight:700">${x.extra} \u0e0b\u0e49\u0e33</span>
          <button onclick="costDupInspect('${x.k}')" style="border:1px solid #E0B24B;background:#fff;color:#7A4A00;border-radius:9px;padding:4px 11px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit">\u0e14\u0e39\u0e2b\u0e25\u0e31\u0e01\u0e10\u0e32\u0e19</button>
          ${x.clean?`<button onclick="costDupClean('${x.k}')" style="border:none;background:#A05A1A;color:#fff;border-radius:9px;padding:4px 12px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit">\u0e25\u0e49\u0e32\u0e07</button>`:''}
          ${isNo?`<span style="font-size:10px;color:#5B289A;opacity:.9">\u0e15\u0e31\u0e14\u0e2a\u0e34\u0e19\u0e17\u0e35\u0e25\u0e30\u0e43\u0e1a\u0e02\u0e49\u0e32\u0e07\u0e43\u0e19</span>`:''}
        </div>`;
      const all=DS.sets.concat(DS.nested).filter(x=>x.extra>0);
      const numsL=(DS.nums||[]).filter(x=>x.extra>0);
      const sureL=all.filter(x=>x.sure), maybeL=all.filter(x=>!x.sure);
      const lines=(sureL.length?`<div style="margin-top:9px;font-size:10px;font-weight:800;letter-spacing:.06em;color:#7A4A00;opacity:.75">\u0e0b\u0e49\u0e33\u0e41\u0e19\u0e48\u0e19\u0e2d\u0e19 \u00b7 \u0e17\u0e38\u0e01\u0e0a\u0e48\u0e2d\u0e07\u0e15\u0e23\u0e07\u0e01\u0e31\u0e19\u0e2b\u0e21\u0e14</div>`+sureL.map(mkLine).join(''):'')
        +(maybeL.length?`<div style="margin-top:11px;font-size:10px;font-weight:800;letter-spacing:.06em;color:#7A4A00;opacity:.75">\u0e19\u0e48\u0e32\u0e2a\u0e07\u0e2a\u0e31\u0e22 \u00b7 \u0e23\u0e30\u0e1a\u0e1a\u0e15\u0e31\u0e14\u0e2a\u0e34\u0e19\u0e41\u0e17\u0e19\u0e44\u0e21\u0e48\u0e44\u0e14\u0e49 \u0e40\u0e1b\u0e34\u0e14\u0e14\u0e39\u0e40\u0e2d\u0e07</div>`+maybeL.map(mkLine).join(''):'')
        +`<div style="margin-top:10px;padding-top:9px;border-top:1px solid rgba(160,90,26,.14);font-size:10.5px;line-height:1.6;opacity:.85">\u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e22\u0e48\u0e2d\u0e22 (\u0e1b\u0e23\u0e30\u0e27\u0e31\u0e15\u0e34\u0e40\u0e1a\u0e34\u0e01\u0e02\u0e2d\u0e07 \u00b7 \u0e2d\u0e30\u0e44\u0e2b\u0e25\u0e48\u0e43\u0e19\u0e43\u0e1a\u0e07\u0e32\u0e19 \u00b7 \u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e43\u0e19 memo \u00b7 \u0e01\u0e32\u0e23\u0e23\u0e31\u0e1a\u0e40\u0e07\u0e34\u0e19) \u0e15\u0e23\u0e27\u0e08\u0e08\u0e32\u0e01 id \u0e1b\u0e23\u0e30\u0e08\u0e33\u0e1a\u0e23\u0e23\u0e17\u0e31\u0e14\u0e40\u0e17\u0e48\u0e32\u0e19\u0e31\u0e49\u0e19 \u00b7 \u0e02\u0e2d\u0e07\u0e17\u0e35\u0e48\u0e1a\u0e31\u0e19\u0e17\u0e36\u0e01\u0e01\u0e48\u0e2d\u0e19\u0e2d\u0e31\u0e1b\u0e40\u0e14\u0e15\u0e19\u0e35\u0e49\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e21\u0e35 id \u0e08\u0e36\u0e07\u0e15\u0e23\u0e27\u0e08\u0e43\u0e2b\u0e49\u0e44\u0e21\u0e48\u0e44\u0e14\u0e49 \u2014 \u0e40\u0e1e\u0e23\u0e32\u0e30 \u0e40\u0e1a\u0e34\u0e01 \u2192 \u0e22\u0e01\u0e40\u0e25\u0e34\u0e01 \u2192 \u0e40\u0e1a\u0e34\u0e01\u0e43\u0e2b\u0e21\u0e48\u0e43\u0e19\u0e27\u0e31\u0e19\u0e40\u0e14\u0e35\u0e22\u0e27\u0e01\u0e31\u0e19 \u0e44\u0e14\u0e49\u0e1a\u0e23\u0e23\u0e17\u0e31\u0e14\u0e17\u0e35\u0e48\u0e40\u0e2b\u0e21\u0e37\u0e2d\u0e19\u0e01\u0e31\u0e19\u0e17\u0e38\u0e01\u0e0a\u0e48\u0e2d\u0e07\u0e42\u0e14\u0e22\u0e18\u0e23\u0e23\u0e21\u0e0a\u0e32\u0e15\u0e34</div>`
        +(numsL.length?`<div style="margin-top:11px;font-size:10px;font-weight:800;letter-spacing:.06em;color:#7A4A00;opacity:.75">\u0e40\u0e25\u0e02\u0e17\u0e35\u0e48\u0e40\u0e2d\u0e01\u0e2a\u0e32\u0e23\u0e0a\u0e19\u0e01\u0e31\u0e19 \u00b7 \u0e40\u0e1b\u0e47\u0e19\u0e04\u0e19\u0e25\u0e30\u0e43\u0e1a \u0e2b\u0e49\u0e32\u0e21\u0e25\u0e1a \u0e15\u0e49\u0e2d\u0e07\u0e2d\u0e2d\u0e01\u0e40\u0e25\u0e02\u0e43\u0e2b\u0e21\u0e48</div>`+numsL.map(x=>mkLine(x,true)).join(''):'');
      dupBar=`<div style="background:#FFF6E5;border:1px solid #EAD9B0;border-radius:14px;padding:14px 17px;margin-bottom:12px;color:#7A4A00">
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:6px">
          <b style="font-size:13px">&#9888; \u0e1e\u0e1a\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e0b\u0e49\u0e33 ${DS.nDup} \u0e23\u0e32\u0e22\u0e01\u0e32\u0e23</b>
          ${DS.nMoney>0?`<span style="font-size:11px;background:#FCE5EC;color:#9F1B4F;border-radius:8px;padding:2px 9px;font-weight:700">\u0e01\u0e23\u0e30\u0e17\u0e1a\u0e22\u0e2d\u0e14\u0e40\u0e07\u0e34\u0e19 ${DS.nMoney} \u0e23\u0e32\u0e22\u0e01\u0e32\u0e23</span>`:''}
          ${DS.nNo>0?`<span style="font-size:11px;background:#EDE7FB;color:#5B289A;border-radius:8px;padding:2px 9px;font-weight:700">\u0e40\u0e25\u0e02\u0e40\u0e2d\u0e01\u0e2a\u0e32\u0e23\u0e0a\u0e19\u0e01\u0e31\u0e19 ${DS.nNo} \u0e43\u0e1a</span>`:''}
          ${DS.nDup>0?`<button onclick="costDupCleanAll()" style="margin-left:auto;border:none;background:#A05A1A;color:#fff;border-radius:10px;padding:6px 14px;font-size:11.5px;font-weight:700;cursor:pointer;font-family:inherit">\u0e25\u0e49\u0e32\u0e07\u0e17\u0e35\u0e48\u0e25\u0e49\u0e32\u0e07\u0e44\u0e14\u0e49\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e21\u0e14</button>`:''}
        </div>
        <div style="font-size:11px;line-height:1.6;opacity:.9">\u0e01\u0e14 <b>\u0e14\u0e39\u0e2b\u0e25\u0e31\u0e01\u0e10\u0e32\u0e19</b> \u0e01\u0e48\u0e2d\u0e19\u0e40\u0e2a\u0e21\u0e2d \u0e08\u0e30\u0e40\u0e2b\u0e47\u0e19\u0e27\u0e48\u0e32\u0e23\u0e30\u0e1a\u0e1a\u0e08\u0e31\u0e1a\u0e04\u0e39\u0e48\u0e2d\u0e30\u0e44\u0e23\u0e44\u0e27\u0e49\u0e01\u0e31\u0e1a\u0e2d\u0e30\u0e44\u0e23 \u00b7 \u0e01\u0e32\u0e23\u0e25\u0e49\u0e32\u0e07\u0e08\u0e30\u0e40\u0e01\u0e47\u0e1a\u0e43\u0e1a\u0e17\u0e35\u0e48\u0e21\u0e35\u0e40\u0e19\u0e37\u0e49\u0e2d\u0e2b\u0e32\u0e21\u0e32\u0e01\u0e17\u0e35\u0e48\u0e2a\u0e38\u0e14\u0e44\u0e27\u0e49 \u0e41\u0e25\u0e30\u0e22\u0e49\u0e32\u0e22 memo / \u0e1b\u0e23\u0e30\u0e27\u0e31\u0e15\u0e34\u0e40\u0e1a\u0e34\u0e01\u0e2d\u0e30\u0e44\u0e2b\u0e25\u0e48 \u0e21\u0e32\u0e0a\u0e35\u0e49\u0e43\u0e1a\u0e17\u0e35\u0e48\u0e40\u0e01\u0e47\u0e1a\u0e44\u0e27\u0e49 \u0e40\u0e07\u0e34\u0e19\u0e08\u0e36\u0e07\u0e44\u0e21\u0e48\u0e2b\u0e32\u0e22</div>
        ${lines}
      </div>`;
    } else if(DS){
      dupBar=`<div style="display:flex;align-items:center;gap:8px;font-size:11.5px;color:#1D6E56;background:#F0F9F4;border:1px solid #CDE9DC;border-radius:12px;padding:8px 13px;margin-bottom:12px">
        &#10003; <span>\u0e15\u0e23\u0e27\u0e08\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e0b\u0e49\u0e33\u0e41\u0e25\u0e49\u0e27 \u00b7 \u0e44\u0e21\u0e48\u0e1e\u0e1a\u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e0b\u0e49\u0e33 \u00b7 \u0e22\u0e2d\u0e14\u0e43\u0e19\u0e2b\u0e19\u0e49\u0e32\u0e19\u0e35\u0e49\u0e40\u0e0a\u0e37\u0e48\u0e2d\u0e16\u0e37\u0e2d\u0e44\u0e14\u0e49</span></div>`;
    }
  }catch(e){ dupBar=''; }

  wrap.innerHTML=headerBar+dupBar
    +`<div style="display:grid;grid-template-columns:1.55fr 1fr;gap:12px;margin-bottom:12px" class="cost-top">${totalCard}${centralCard}</div>`
    +`<div style="display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:12px" class="cost-cats">${catCards}</div>`
    +chartSection
    +`<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px" class="cost-duo">${boatPanel}${unitPanel}</div>`
    +`<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px" class="cost-duo">${typePanel}${outcomePanel}</div>`;
}

