function insightIcon(key, size, color){
  const s = size || 16;
  const svg = INSIGHT_ICONS[key] || INSIGHT_ICONS.circle_filled;
  return svg.replace('<svg ', `<svg width="${s}" height="${s}" style="color:${color||'currentColor'};flex-shrink:0" `);
}

// ═══════════ FUEL INTELLIGENCE · view fl-fuel ═══════════
let _fuelMonth=(typeof TODAY_STR!=='undefined'?TODAY_STR:'2026-06-15').slice(0,7);
let _fuelExpand={};
function fuelToggleBoat(bid){ _fuelExpand[bid]=!_fuelExpand[bid]; const sy=window.scrollY; renderFuelIntel(); window.scrollTo(0,sy); }
function fuelMonthShift(n){ const p=_fuelMonth.split('-').map(Number); const d=new Date(p[0],p[1]-1+n,1); _fuelMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'); renderFuelIntel(); }
function _fuelBudgetGet(){ try{ const d=JSON.parse(localStorage.getItem(LS_KEY)||'{}'); return d.fleet_fuelbudget||{}; }catch(e){ return {}; } }
function fuelSetBudget(val){ try{ const d=JSON.parse(localStorage.getItem(LS_KEY)||'{}'); d.fleet_fuelbudget=d.fleet_fuelbudget||{}; const v=parseFloat(val); if(val===''||isNaN(v)) delete d.fleet_fuelbudget[_fuelMonth]; else d.fleet_fuelbudget[_fuelMonth]=v; localStorage.setItem(LS_KEY,JSON.stringify(d)); }catch(e){} renderFuelIntel(); }
function _fuelAgg(month){
  const out={fuel:0,cost:0,pax:0,tripDays:0,byBoat:{},byFam:{},missing:[],anomalies:[],weekly:{},priceMissing:false};
  Object.keys(FL_DAILY||{}).filter(ds=>ds.slice(0,7)===month).sort().forEach(ds=>{
    const day=FL_DAILY[ds]||{};
    Object.keys(day).forEach(bid=>{
      const b=getBoat(bid); if(!b||b.ownership==='charter'||b.retired) return;
      const bd=day[bid]||{}; const fuel=+bd.fuel||0;
      const info=(typeof flBoatBookingsFor==='function')?flBoatBookingsFor(bid,ds):{pax:0,routes:{}};
      const ran=(info.pax>0)||Object.keys(info.routes||{}).length>0||fuel>0; if(!ran) return;
      out.tripDays++;
      const pier=(typeof getBoatCurrentPier==='function')?getBoatCurrentPier(b):b.pier;
      const price=(typeof flFuelPriceForBoat==='function')?flFuelPriceForBoat(ds,b):((typeof flFuelPrice==='function')?flFuelPrice(ds,pier):null);   // per-boat price → pier default
      const cost=(fuel&&price!=null)?fuel*price:0; if(fuel>0&&price==null) out.priceMissing=true;
      let runH=0; (FL_ENGINES||[]).filter(e=>e.boatId===bid).forEach(e=>{ const v=bd.trips&&bd.trips.normal&&bd.trips.normal.engines?bd.trips.normal.engines[e.id]:null; const prev=(typeof flPrevMeter==='function')?flPrevMeter(e.id,ds):null; if(v!=null&&prev!=null){ const dlt=v-prev; if(dlt>runH) runH=dlt; } });
      const bb=out.byBoat[bid]=out.byBoat[bid]||{id:bid,name:b.name,fuel:0,cost:0,pax:0,runH:0,days:0,missing:0,fdays:[],routes:{}};
      bb.fuel+=fuel; bb.cost+=cost; bb.pax+=info.pax; bb.runH+=runH; bb.days++;
      if(fuel>0) bb.fdays.push(fuel); else { bb.missing++; out.missing.push({name:b.name,ds,route:((getRoute(Object.keys(info.routes||{})[0])||{}).name)||''}); }
      const rk=Object.keys(info.routes||{}); const nr=rk.length||1;
      rk.forEach(rid=>{ const fam=(typeof bkV2RouteFamily==='function')?bkV2RouteFamily(rid):null; const fid=(fam&&fam.id)||rid; const fnm=(fam&&fam.name)||((getRoute(rid)||{}).name)||rid; const ff=out.byFam[fid]=out.byFam[fid]||{name:fnm,fuel:0,cost:0,pax:0,rev:0}; const share=info.pax>0?(info.routes[rid]/info.pax):(1/nr); ff.fuel+=fuel*share; ff.cost+=cost*share; ff.pax+=info.routes[rid];
        const rnm=((getRoute(rid)||{}).name)||rid; const brk=bb.routes[rid]=bb.routes[rid]||{name:rnm,fuel:0,cost:0,pax:0,days:0}; brk.fuel+=fuel*share; brk.cost+=cost*share; brk.pax+=info.routes[rid]; brk.days++; });
      if(fuel>0 && rk.length===0){ const brk=bb.routes._none=bb.routes._none||{name:'ไม่ระบุเส้นทาง',fuel:0,cost:0,pax:0,days:0}; brk.fuel+=fuel; brk.cost+=cost; brk.days++; }
      out.fuel+=fuel; out.cost+=cost; out.pax+=info.pax;
      out.weekly['W'+Math.ceil((+ds.slice(8,10))/7)]=(out.weekly['W'+Math.ceil((+ds.slice(8,10))/7)]||0)+cost;
    });
  });
  Object.values(out.byBoat).forEach(bb=>{ if(bb.fdays.length>=3){ const avg=bb.fdays.reduce((s,x)=>s+x,0)/bb.fdays.length; } });
  Object.keys(out.byBoat).forEach(bid=>{ const bb=out.byBoat[bid]; if(bb.fdays.length>=3){ const avg=bb.fdays.reduce((s,x)=>s+x,0)/bb.fdays.length; Object.keys(FL_DAILY).filter(ds=>ds.slice(0,7)===month&&FL_DAILY[ds][bid]&&+FL_DAILY[ds][bid].fuel>avg*1.3).forEach(ds=>{ const f=+FL_DAILY[ds][bid].fuel; out.anomalies.push({name:bb.name,ds,fuel:Math.round(f),avg:Math.round(avg),pct:Math.round((f/avg-1)*100)}); }); } });
  out.anomalies.sort((a,b)=>b.pct-a.pct);
  (SB_BOOKINGS||[]).forEach(bk=>{ if(['cancelled','rejected','cancelled_weather'].includes(bk.status))return; const trs=(bk.trips||[]).filter(t=>(t.date||'').slice(0,7)===month); if(!trs.length)return; const tot=(typeof acctBookingTotal==='function')?acctBookingTotal(bk):(bk.total||0); trs.forEach(t=>{ const fam=(typeof bkV2RouteFamily==='function')?bkV2RouteFamily(t.routeId):null; const fid=(fam&&fam.id)||t.routeId; const fnm=(fam&&fam.name)||((getRoute(t.routeId)||{}).name)||t.routeId; const ff=out.byFam[fid]=out.byFam[fid]||{name:fnm,fuel:0,cost:0,pax:0,rev:0}; ff.rev+=(t.subtotal>0?t.subtotal:(tot/trs.length)); }); });
  return out;
}
// §fuelWk · ยอดรายลำ แยกรายสัปดาห์ · ตรรกะต่อวันเหมือน _fuelAgg เป๊ะ (ราคา · ชั่วโมงเครื่อง · เงื่อนไข "ออกจริง")
//   ตั้งใจไม่เรียก _fuelAgg ซ้ำ เพราะตัวนั้นวน SB_BOOKINGS ทั้งก้อนเพื่อคิดรายได้ ซึ่งไม่ได้ใช้ตรงนี้
//   และตารางรายเดือนต้องเรียกย้อนหลัง 6 เดือน
var _fuelWkMetric=0;   // 0=L/hr · 1=L/วัน · 2=L/pax · 3=฿
function fuelWkMetric(i){ _fuelWkMetric=+i||0; const sy=window.scrollY; renderFuelIntel(); window.scrollTo(0,sy); }
function _fuelWkAgg(month){
  const out={};
  Object.keys(FL_DAILY||{}).filter(ds=>ds.slice(0,7)===month).sort().forEach(ds=>{
    const day=FL_DAILY[ds]||{};
    Object.keys(day).forEach(bid=>{
      const b=getBoat(bid); if(!b||b.ownership==='charter'||b.retired) return;
      const bd=day[bid]||{}; const fuel=+bd.fuel||0;
      const info=(typeof flBoatBookingsFor==='function')?flBoatBookingsFor(bid,ds):{pax:0,routes:{}};
      const ran=(info.pax>0)||Object.keys(info.routes||{}).length>0||fuel>0; if(!ran) return;   // §nil · ไม่ออก = ไม่นับ ไม่ใช่ 0
      const pier=(typeof getBoatCurrentPier==='function')?getBoatCurrentPier(b):b.pier;
      const price=(typeof flFuelPriceForBoat==='function')?flFuelPriceForBoat(ds,b):((typeof flFuelPrice==='function')?flFuelPrice(ds,pier):null);
      const cost=(fuel&&price!=null)?fuel*price:0;
      let runH=0; (FL_ENGINES||[]).forEach(e=>{ if(e.boatId!==bid) return;
        const v=bd.trips&&bd.trips.normal&&bd.trips.normal.engines?bd.trips.normal.engines[e.id]:null;
        const prev=(typeof flPrevMeter==='function')?flPrevMeter(e.id,ds):null;
        if(v!=null&&prev!=null){ const dlt=v-prev; if(dlt>runH) runH=dlt; } });
      const rec=out[bid]||(out[bid]={id:bid,name:b.name,w:[null,null,null,null,null],tot:{fuel:0,cost:0,pax:0,days:0,runH:0}});
      const wi=Math.min(4,Math.max(0,Math.ceil((+ds.slice(8,10))/7)-1));   // W1..W5 · ตัดสัปดาห์แบบเดียวกับแท่งเดิม
      const w=rec.w[wi]||(rec.w[wi]={fuel:0,cost:0,pax:0,days:0,runH:0});
      w.fuel+=fuel; w.cost+=cost; w.pax+=info.pax; w.days++; w.runH+=runH;
      const t=rec.tot; t.fuel+=fuel; t.cost+=cost; t.pax+=info.pax; t.days++; t.runH+=runH;
    });
  });
  return out;
}
// ค่าของหนึ่งช่อง · null = คิดไม่ได้ (ไม่มีชั่วโมงเครื่อง / ไม่มี pax) ซึ่งต่างจาก 0
function _fuelWkVal(x,i){
  if(!x||!x.days) return null;
  if(i===0) return x.runH>0 ? x.fuel/x.runH : null;
  if(i===1) return x.fuel/x.days;
  if(i===2) return x.pax>0 ? x.fuel/x.pax : null;
  return x.cost;
}
function renderFuelIntel(){
  const wrap=document.getElementById('fl-fuel-wrap'); if(!wrap) return;
  const PK={accent:'#E03B7E',soft:'#FCE5EC',text:'#9F1B4F'}, ink3='#999', line='rgba(0,0,0,.07)';
  const fL=n=>Math.round(n).toLocaleString(), fB=n=>'฿'+Math.round(n).toLocaleString();
  const fBs=n=>n>=1e6?'฿'+(n/1e6).toFixed(2)+'M':n>=1000?'฿'+Math.round(n/1000)+'k':'฿'+Math.round(n);
  const a=_fuelAgg(_fuelMonth);
  const [yy,mm]=_fuelMonth.split('-').map(Number);
  const pm=new Date(yy,mm-2,1), pmS=pm.getFullYear()+'-'+String(pm.getMonth()+1).padStart(2,'0');
  const pa=_fuelAgg(pmS);
  const cpp=a.pax>0?a.cost/a.pax:0, pcpp=pa.pax>0?pa.cost/pa.pax:0;
  const mom=pcpp>0?Math.round((cpp/pcpp-1)*100):null;
  const THM=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][mm-1];
  const THM_LONG=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'][mm-1];
  const dim=new Date(yy,mm,0).getDate();
  const isCur=_fuelMonth===((typeof TODAY_STR!=='undefined'?TODAY_STR:'').slice(0,7));
  const elapsed=isCur?(+TODAY_STR.slice(8,10)):dim;
  const proj=elapsed>0?a.cost/elapsed*dim:a.cost;
  const budget=_fuelBudgetGet()[_fuelMonth]||null;
  const missN=a.missing.length, logged=a.tripDays>0?Math.round((a.tripDays-missN)/a.tripDays*100):100;
  const boats=Object.values(a.byBoat).sort((x,y)=>y.fuel-x.fuel);
  const top=boats[0];
  const eff=boats.filter(b=>b.runH>0).map(b=>({...b,lph:b.fuel/b.runH})).sort((x,y)=>x.lph-y.lph);
  const effMax=eff.length?Math.max(...eff.map(b=>b.lph)):1, effMed=eff.length?eff[Math.floor(eff.length/2)].lph:0;
  const dot=bid=>({}[bid])||'#888';
  const PAL=['#534AB7','#1D9E75','#185FA5','#BA7517','#A32D2D','#0F6E56','#993556','#D85A30'];
  const ci=(i)=>PAL[i%PAL.length];
  const fuelMax=Math.max(1,...boats.map(b=>b.fuel));
  const av=name=>{ const w=String(name).split(/\s+/); if(w.length>=2)return (w[0][0]+w[1][0]).toUpperCase(); if(/\d/.test(name))return ((String(name).match(/[A-Z]/)||[String(name)[0]])[0]+String(name).slice(-1)).toUpperCase(); return String(name).slice(0,2).toUpperCase(); };
  const avc=bid=>(typeof bkV2BoatAvatarColor==='function')?bkV2BoatAvatarColor(bid):'#185FA5';
  if(a.tripDays===0){ wrap.innerHTML=`<div style="text-align:center;color:${ink3};padding:60px 20px;font-size:13px"><div style="font-size:15px;font-weight:600;color:#666;margin-bottom:4px">ยังไม่มีข้อมูลน้ำมันเดือน ${THM} ${yy+543}</div>กรอกน้ำมันใน Daily Fleet Log ก่อน <button onclick="fuelMonthShift(-1)" style="margin-left:8px;background:#fff;border:1px solid #ddd;border-radius:8px;padding:4px 10px;cursor:pointer">‹ เดือนก่อน</button></div>`; return; }
  const grandMiss=boats.reduce((s,b)=>s+(b.missing||0),0);
  const boatRows=boats.map((b,i)=>{ const c=avc(b.id), bar=Math.round(b.fuel/fuelMax*100); const M="font-family:'DM Mono',monospace;text-align:right";
    const rts=Object.values(b.routes||{}).filter(r=>r.fuel>0||r.pax>0).sort((x,y)=>y.fuel-x.fuel);
    const open=!!_fuelExpand[b.id];
    const totalRow=`<tr onclick="fuelToggleBoat('${b.id}')" style="border-top:1px solid #E9E7DF;background:${open?'#F5F4EF':'#FAFAF6'};cursor:pointer">`
      +`<td style="text-align:left"><span style="display:inline-flex;align-items:center;gap:11px"><span style="width:32px;height:32px;border-radius:50%;background:${c};color:#fff;font-size:11px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;flex:none">${av(b.name)}</span><span style="display:inline-flex;flex-direction:column;line-height:1.3"><span style="font-family:'DM Sans';font-weight:600">${b.name}</span>${rts.length?`<span style="font-size:10.5px;color:#9a988e">${rts.length} เส้นทาง</span>`:''}</span><span style="color:#b9b7af;font-size:11px;display:inline-block;transform:rotate(${open?90:0}deg);margin-left:1px">▶</span></span></td>`
      +`<td style="${M}">${b.days}</td>`
      /* §คน/ลำ · ตารางนี้มี L/pax อยู่แล้ว แต่ไม่เคยโชว์ "pax" เลย — ดูไม่ออกว่าเรือวิ่งเต็มหรือวิ่งลม
         คน/ลำ = pax ÷ วันที่ออก (1 วัน = 1 เที่ยวของลำนั้น) · เทียบกับที่นั่งของเรือเป็น % ใต้ตัวเลข */
      +`<td style="${M}">${b.pax>0?fL(b.pax):'—'}</td>`
      +(function(){ const _cap=+((( (typeof getBoat==='function')?getBoat(b.id):null)||{}).cap)||0;
          const _avg=b.days?(b.pax/b.days):0;
          const _pct=(_cap>0&&_avg>0)?Math.round(_avg/_cap*100):null;
          const _col=(_pct==null)?'#b9b7af':(_pct>=80?'#3B6D11':(_pct>=50?'#854F0B':'#A32D2D'));
          return `<td style="${M}" title="${_cap?('ที่นั่ง '+_cap+' ที่ · เฉลี่ยเต็ม '+(_pct!=null?_pct+'%':'—')):'ยังไม่ได้ตั้งจำนวนที่นั่งของเรือลำนี้'}"><div>${_avg>0?Math.round(_avg):'—'}</div>${_pct!=null?`<div style="font-size:9.5px;font-weight:600;color:${_col};line-height:1.2;margin-top:1px">${_pct}%</div>`:''}</td>`; })()
      +`<td style="${M}"><div>${fL(b.fuel)}</div><div style="height:4px;background:${c}33;border-radius:2px;width:${Math.max(6,bar)}%;margin:5px 0 0 auto"></div></td>`
      +`<td style="${M}">${fL(b.cost)}</td>`
      +`<td style="${M}">${b.days?Math.round(b.fuel/b.days):'—'}</td>`
      +`<td style="${M}">${b.pax>0?(b.fuel/b.pax).toFixed(1):'—'}</td>`
      +`<td style="text-align:right">${b.missing?`<span style="background:#FCEBEB;color:#A32D2D;padding:2px 9px;border-radius:9px;font-size:11px;font-weight:600;font-family:'DM Mono',monospace">${b.missing}</span>`:`<span style="color:#cac8c0">0</span>`}</td>`
      +`</tr>`;
    const routeRows=open?rts.map(r=>`<tr style="border-top:0.5px solid ${line};background:#fff">`
      +`<td style="text-align:left;padding-left:55px"><span style="display:inline-flex;align-items:center;gap:8px;color:#555"><span style="width:6px;height:6px;border-radius:50%;background:${c}99;flex:none"></span>${r.name}</span></td>`
      +`<td style="${M};color:#999">${r.days||''}</td>`
      +`<td style="${M};color:#555">${r.pax>0?fL(r.pax):'—'}</td>`
      +`<td style="${M};color:#555">${(r.days&&r.pax>0)?Math.round(r.pax/r.days):'—'}</td>`
      +`<td style="${M};color:#555">${fL(r.fuel)}</td>`
      +`<td style="${M};color:#555">${fL(r.cost)}</td>`
      +`<td style="${M};color:#ccc">·</td>`
      +`<td style="${M};color:#555">${r.pax>0?(r.fuel/r.pax).toFixed(1):'—'}</td>`
      +`<td></td>`
      +`</tr>`).join(''):'';
    return totalRow+routeRows; }).join('');
  const grandRow=`<tr style="border-top:2px solid #DEDCD3;font-weight:700"><td style="text-align:left;padding-left:6px">รวมทั้งหมด</td><td style="text-align:right;font-family:'DM Mono',monospace">${a.tripDays}</td><td style="text-align:right;font-family:'DM Mono',monospace">${a.pax>0?fL(a.pax):'—'}</td><td style="text-align:right;font-family:'DM Mono',monospace">${(a.tripDays&&a.pax>0)?Math.round(a.pax/a.tripDays):'—'}</td><td style="text-align:right;font-family:'DM Mono',monospace">${fL(a.fuel)}</td><td style="text-align:right;font-family:'DM Mono',monospace">${fL(a.cost)}</td><td style="text-align:right;font-family:'DM Mono',monospace">${a.tripDays?Math.round(a.fuel/a.tripDays):'—'}</td><td style="text-align:right;font-family:'DM Mono',monospace">${a.pax>0?(a.fuel/a.pax).toFixed(1):'—'}</td><td style="text-align:right;font-family:'DM Mono',monospace;color:${grandMiss?'#A32D2D':'#cac8c0'}">${grandMiss}</td></tr>`;
  const effRows=eff.map((b,i)=>{ const w=Math.round(b.lph/effMax*100); const worst=b.lph>effMed*1.25&&i===eff.length-1; const best=i===0; const col=worst?'#E24B4A':(b.lph<=effMed?'#1D9E75':'#EF9F27'); return `<div style="display:flex;align-items:center;gap:10px;font-size:12.5px"><span style="width:84px;display:inline-flex;align-items:center;gap:6px"><span style="width:8px;height:8px;border-radius:50%;background:${avc(b.id)}"></span>${b.name}</span><div style="flex:1;height:8px;background:#F1EFE8;border-radius:99px;overflow:hidden"><div style="height:100%;width:${w}%;background:${col}"></div></div><span style="width:78px;text-align:right;font-family:'DM Mono',monospace;${worst?'color:#A32D2D;font-weight:600':''}">${b.lph.toFixed(1)} L/hr</span><span style="width:48px;font-size:10px;font-weight:600;color:${best?'#3B6D11':(worst?'#A32D2D':'#bbb')}">${best?'ดีสุด':(worst?'เปลือง ⚠':'')}</span></div>`; }).join('')||`<div style="font-size:11px;color:${ink3}">ยังไม่มีชั่วโมงเครื่อง (กรอกมิเตอร์ใน Daily Log)</div>`;
  const fams=Object.values(a.byFam).filter(f=>f.fuel>0||f.rev>0).sort((x,y)=>y.fuel-x.fuel);
  const famRows=fams.map(f=>{ const pctRev=f.rev>0?Math.round(f.cost/f.rev*100):null; const col=pctRev==null?'#999':(pctRev>=20?'#A32D2D':'#3B6D11'); const M="text-align:right;font-family:'DM Mono',monospace"; return `<tr style="border-top:0.5px solid ${line}"><td style="text-align:left;font-family:'DM Sans';font-weight:500">${f.name}</td><td style="${M}">${f.pax>0?(f.fuel/f.pax).toFixed(1):'—'}</td><td style="${M}">${f.pax>0?fB(f.cost/f.pax):'—'}</td><td style="${M};font-weight:600;color:${col}">${pctRev!=null?pctRev+'%':'—'}</td></tr>`; }).join('');
  const wks=Object.keys(a.weekly).sort(); const wkMax=Math.max(1,...wks.map(w=>a.weekly[w]));
  const wkBars=wks.map((w)=>{ const val=a.weekly[w]; const h=Math.round(val/wkMax*100); const peak=val===wkMax; return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:6px;height:100%"><span style="font-size:11px;color:#8a8a83;font-family:'DM Mono',monospace">${fBs(val)}</span><div style="width:100%;max-width:56px;height:${Math.max(8,Math.round(h*0.74))}px;background:${peak?'#D4537E':'#F4C0D1'};border-radius:6px 6px 0 0"></div></div>`; }).join('');
  const wkLabels=wks.map(w=>`<span style="flex:1;text-align:center;font-size:10.5px;color:${ink3}">${w}</span>`).join('');
  const anoms=a.anomalies.slice(0,3);
  const anomHtml=anoms.length?anoms.map((x,i)=>`${i?'<span style="width:1px;height:14px;background:#444"></span>':''}<span style="font-size:12.5px"><b>${x.name} · ${(+x.ds.slice(8,10))} ${THM}</b> <span style="color:#888">${fL(x.fuel)} L (เฉลี่ย ${fL(x.avg)}) +${x.pct}%</span></span>`).join(''):'<span style="font-size:12.5px;color:#9BCBA6">ไม่มีวันที่น้ำมันผิดปกติ</span>';
  const missList=a.missing.slice(0,6).map(m=>`<div style="display:flex;justify-content:space-between;align-items:center;font-size:12.5px;background:#FCEBEB;border-radius:8px;padding:7px 10px"><span><span style="font-weight:600;color:#A32D2D">${m.name}</span>${m.route?` <span style="color:#999">· ${m.route}</span>`:''}</span><span style="font-family:'DM Mono',monospace;color:#A32D2D">${(+m.ds.slice(8,10))} ${THM}</span></div>`).join('')||`<div style="font-size:12px;color:#3B6D11;padding:6px 2px">กรอกน้ำมันครบทุกวันแล้ว ✓</div>`;
  // ══ §fuelWk · รายสัปดาห์ + รายเดือน แยกรายลำ ══════════════════════════
  const MI=_fuelWkMetric;
  const MU=['L/hr','L/วัน','L/pax','฿'][MI];
  const MLAB=['L/ชม.เครื่อง','L/วัน','L/PAX','฿ รวม'];
  const wkA=_fuelWkAgg(_fuelMonth), wkP=_fuelWkAgg(pmS);
  const fmtM=(v)=>v==null?'—':(MI===3?Math.round(v).toLocaleString():(MI===1?Math.round(v).toLocaleString():v.toFixed(1)));
  // §self · เขียว = ดีกว่าฐานของลำตัวเอง · แดง = แย่กว่า ≥15% · ฿ ไม่ลงสี (§baht)
  const toneM=(cur,base)=>{ if(MI===3||!base||cur==null) return ['transparent','#1A1A1A'];
    const r=cur/base; return r<=0.95?['#E7F5EE','#0F6E56']:(r<1.15?['#FBF3E2','#8A5B00']:['#FCE9E9','#A32D2D']); };
  const wkRange=(i)=>{ const a1=i*7+1, b1=Math.min(dim,(i+1)*7); return a1+'–'+b1; };
  const wkBoats=Object.values(wkA).sort((x,y)=>y.tot.fuel-x.tot.fuel);
  // สัปดาห์ที่ยังมาไม่ถึงในเดือนปัจจุบัน · แสดงจาง ๆ ไม่ใช่ "ไม่ออก"
  const wkFuture=(i)=>isCur && (i*7+1)>elapsed;
  const wkRows=wkBoats.map(b=>{
    const base=_fuelWkVal((wkP[b.id]||{}).tot,MI);
    const cells=b.w.map((w,i)=>{
      if(!w) return `<td style="text-align:center"><span style="font-size:11px;color:${wkFuture(i)?'#DCD8D0':'#C7C3BB'}">${wkFuture(i)?'—':'ไม่ออก'}</span></td>`;
      const v=_fuelWkVal(w,MI), tc=toneM(v,base);
      return `<td style="text-align:center"><span style="display:inline-block;min-width:60px;border-radius:8px;padding:4px 8px;line-height:1.2;background:${tc[0]};color:${tc[1]}">`
        +`<span style="font-family:'DM Mono',monospace;font-size:12.5px">${fmtM(v)}</span>`
        +`<div style="font-size:9.5px;opacity:.72;margin-top:1px">${w.days} วัน${w.days===1?' <span style="background:rgba(0,0,0,.07);padding:0 3px;border-radius:3px;font-weight:700">n=1</span>':''}</div></span></td>`;
    }).join('');
    const cur=_fuelWkVal(b.tot,MI);
    const dl=(cur!=null&&base&&MI!==3)?((cur/base-1)*100):null;
    return `<tr><td style="text-align:left"><span style="display:flex;align-items:center;gap:9px">`
      +`<span style="width:26px;height:26px;border-radius:50%;background:${avc(b.id)};color:#fff;font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center;flex:none">${av(b.name)}</span>`
      +`<span style="font-weight:600;font-size:12.5px">${b.name}</span></span></td>`
      +`<td style="text-align:center;font-family:'DM Mono',monospace;color:#5a5a52">${MI===3?'—':fmtM(base)}</td>`
      +cells
      +`<td style="text-align:right">${dl==null?`<span style="color:${ink3}">—</span>`
        :(_dr=>`<span style="font-family:'DM Mono',monospace;font-weight:700;color:${dl<=-5?'#0F6E56':(dl<15?'#8A5B00':'#A32D2D')}">${_dr>0?'+':''}${_dr}%</span>`)(Math.round(dl)||0)}</td></tr>`;
  }).join('');
  const segBtn=(i)=>`<button onclick="fuelWkMetric(${i})" style="border:none;border-radius:7px;padding:5px 12px;font-size:11.5px;font-weight:600;cursor:pointer;font-family:inherit;${MI===i?'background:#1A1A1A;color:#fff':'background:transparent;color:#7a756e'}">${MLAB[i]}</button>`;
  // ทำไมยอดรวมทั้งกองเทียบกันไม่ได้ · บอกด้วยตัวเลขของเดือนที่กำลังดูอยู่จริง
  const wkMix=[0,1,2,3,4].map(i=>{ const n=wkBoats.filter(b=>b.w[i]).length, d=wkBoats.reduce((s,b)=>s+((b.w[i]||{}).days||0),0);
    return n?`W${i+1} ${n} ลำ/${d} วัน`:null; }).filter(Boolean).join(' &middot; ');
  const wkCard=`
    <div class="fi-card" style="padding:16px 18px;margin-bottom:12px">
      <div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:6px;flex-wrap:wrap">
        <div><div class="fi-sec"><span class="fi-tick"></span>รายสัปดาห์ &middot; แยกรายลำ</div>
          <div class="fi-mut" style="margin-left:12px;margin-top:3px">แต่ละลำเทียบกับฐานของตัวเอง (เฉลี่ย ${THM_prev(pmS)}) &middot; เขียว = ดีกว่าฐาน &middot; แดง = แย่กว่า &ge;15%</div></div>
        <div style="margin-left:auto;display:inline-flex;gap:3px;background:#F0EEE8;border-radius:9px;padding:3px">${[0,1,2,3].map(segBtn).join('')}</div>
      </div>
      <div style="font-size:11px;color:${ink3};background:#FAFAF7;border-radius:9px;padding:8px 11px;margin:8px 0 12px;line-height:1.5">
        เรือออกไม่เท่ากันในแต่ละสัปดาห์ (${wkMix||'—'}) &middot; ยอดรวมทั้งกองจึงเทียบกันตรง ๆ ไม่ได้ ตารางนี้เทียบรายลำและบอกจำนวนวันที่ค่านั้นคิดมาจากเสมอ
      </div>
      <table class="fi-tbl" style="font-size:12.5px"><thead><tr style="color:${ink3};font-size:10.5px">
        <th style="text-align:left">เรือ</th><th style="text-align:center">ฐาน ${THM_prev(pmS)}</th>
        ${[0,1,2,3,4].map(i=>`<th style="text-align:center">W${i+1}<div style="font-weight:400;color:#bbb">${wkRange(i)}</div></th>`).join('')}
        <th style="text-align:right">เดือนนี้ vs ฐาน</th></tr></thead>
        <tbody>${wkRows||`<tr><td colspan="8" style="text-align:center;color:${ink3};padding:18px">ยังไม่มีข้อมูล</td></tr>`}</tbody></table>
      <div style="font-size:11px;color:${ink3};margin-top:12px;padding-top:11px;border-top:1px solid #F5F3EF;line-height:1.55">
        <b>n=1</b> คือค่านั้นคิดจากวันเดียว &mdash; ขึ้นลงแรงเป็นเรื่องปกติ ต้องมีอย่างน้อย 3 วันจึงอ่านเป็นแนวโน้มได้<br>
        <b>ไม่ออก</b> ไม่ใช่ 0 &mdash; ลำที่ไม่ได้ออกไม่ถูกนับเข้าค่าเฉลี่ยใด ๆ${MI===3?'<br><b>฿ รวม</b> ไม่ลงสี &mdash; ยอดเงินขึ้นกับจำนวนวันที่ออก ไม่ใช่ประสิทธิภาพ':''}
      </div>
    </div>`;
  // ── รายเดือน · 6 เดือนล่าสุด · หน่วยเดียวกับที่เลือกอยู่ ──
  const moKeys=[]; for(let k=5;k>=0;k--){ const d0=new Date(yy,mm-1-k,1); moKeys.push(d0.getFullYear()+'-'+String(d0.getMonth()+1).padStart(2,'0')); }
  const moAgg=moKeys.map(k=>k===_fuelMonth?wkA:(k===pmS?wkP:_fuelWkAgg(k)));
  const moIds=[]; moAgg.forEach(g=>Object.keys(g).forEach(id=>{ if(moIds.indexOf(id)<0) moIds.push(id); }));
  moIds.sort((x,y)=>((wkA[y]||{tot:{fuel:0}}).tot.fuel)-((wkA[x]||{tot:{fuel:0}}).tot.fuel));
  const moRows=moIds.map(id=>{
    const vals=moAgg.map(g=>_fuelWkVal((g[id]||{}).tot,MI));
    const nm=(moAgg.find(g=>g[id])||{})[id].name;
    const mx=Math.max(1,...vals.filter(v=>v!=null));
    const base=vals[4];
    const tds=vals.map((v,i)=>{ const tc=(i===5)?toneM(v,base):['transparent','#1A1A1A'];
      return `<td style="text-align:center"><span style="display:inline-block;min-width:56px;border-radius:8px;padding:4px 7px;background:${tc[0]};color:${tc[1]};font-family:'DM Mono',monospace;font-size:12.5px">${fmtM(v)}</span></td>`; }).join('');
    const spark=vals.map((v,i)=>`<i style="display:block;width:6px;border-radius:1.5px;height:${v==null?3:Math.max(3,Math.round(v/mx*22))}px;background:${i===5?PK.accent:'#D9D5CC'}"></i>`).join('');
    return `<tr><td style="text-align:left"><span style="display:flex;align-items:center;gap:9px">`
      +`<span style="width:26px;height:26px;border-radius:50%;background:${avc(id)};color:#fff;font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center;flex:none">${av(nm)}</span>`
      +`<span style="font-weight:600;font-size:12.5px">${nm}</span></span></td>${tds}`
      +`<td style="text-align:right"><span style="display:inline-flex;align-items:flex-end;gap:2px;height:22px">${spark}</span></td></tr>`;
  }).join('');
  const moCard=`
    <div class="fi-card" style="padding:16px 18px;margin-bottom:12px">
      <div class="fi-sec" style="margin-bottom:4px"><span class="fi-tick"></span>รายเดือน &middot; แยกรายลำ <span class="fi-mut" style="font-weight:400">&middot; ${MLAB[MI]} &middot; หน่วยเดียวกับตารางบน</span></div>
      <div class="fi-mut" style="margin-left:12px;margin-bottom:12px">อ่านเป็นแถว (ลำนั้นเปลี่ยนไปยังไง) ไม่ใช่เป็นคอลัมน์ &mdash; เดือนที่ทั้งกองสูงขึ้นพร้อมกันมักแปลว่าออกทริปเยอะขึ้น</div>
      <table class="fi-tbl" style="font-size:12.5px"><thead><tr style="color:${ink3};font-size:10.5px">
        <th style="text-align:left">เรือ</th>
        ${moKeys.map(k=>{ const cu=k===_fuelMonth; return `<th style="text-align:center;${cu?'color:'+PK.text:''}">${THM_prev(k)}${cu&&isCur?`<div style="font-weight:400;color:#bbb">ถึง ${elapsed}</div>`:''}</th>`; }).join('')}
        <th style="text-align:right">แนวโน้ม</th></tr></thead>
        <tbody>${moRows||`<tr><td colspan="8" style="text-align:center;color:${ink3};padding:18px">ยังไม่มีข้อมูล</td></tr>`}</tbody></table>
    </div>`;

  wrap.innerHTML=`<style>
    #fl-fuel-wrap .fi-card{background:#fff;border-radius:16px;border:0.5px solid rgba(0,0,0,.06);box-shadow:0 1px 3px rgba(20,20,20,.045)}
    #fl-fuel-wrap .fi-kpi{border-radius:16px;box-shadow:0 1px 4px rgba(20,20,20,.07)}
    #fl-fuel-wrap table.fi-tbl{width:100%;border-collapse:collapse}
    #fl-fuel-wrap table.fi-tbl th{font-weight:500;padding:0 10px 9px}
    #fl-fuel-wrap table.fi-tbl td{padding:10px}
    #fl-fuel-wrap table.fi-tbl tbody tr:hover{background:#FAFAF7}
    #fl-fuel-wrap .fi-sec{font-size:13px;font-weight:600;color:#262626;display:flex;align-items:center;gap:8px}
    #fl-fuel-wrap .fi-tick{width:4px;height:15px;border-radius:2px;background:${PK.accent};display:inline-block;flex:none}
    #fl-fuel-wrap .fi-mut{font-size:11px;color:${ink3}}
  </style>
  <div style="font-family:'DM Sans',sans-serif;color:#1A1A1A">
    <div style="display:grid;grid-template-columns:1.5fr 1.15fr 0.85fr 0.85fr;gap:11px;align-items:stretch;margin-bottom:15px">
      <div style="align-self:end;padding-bottom:4px">
        <!-- §ป้ายเดือน · เดิมเป็นปุ่มเล็กสีเทา ‹ ก.ค. 2569 › กลืนไปกับพื้นหลัง คนอ่านตัวเลข ฿289,276
             โดยไม่ทันดูว่ามันคือเดือนไหน (ยิ่งพอกดลูกศรย้อนเดือนแล้วเดินจากหน้าจอไป ยิ่งอันตราย)
             ตอนนี้เป็นการ์ดสีชมพูของหน้านี้ · ชื่อเดือนเต็ม · บอกด้วยว่าข้อมูลนับถึงวันไหน -->
        <div style="display:inline-flex;align-items:center;gap:4px;background:${PK.soft};border:1px solid #F2B9CD;border-radius:13px;padding:5px 6px 5px 14px;margin-bottom:11px">
          <button onclick="fuelMonthShift(-1)" title="เดือนก่อนหน้า" style="background:none;border:none;width:24px;height:24px;cursor:pointer;font-size:16px;color:${PK.text};border-radius:50%;line-height:1;font-family:inherit">‹</button>
          <span style="display:inline-flex;flex-direction:column;align-items:center;line-height:1.15;padding:0 4px">
            <span style="font-size:15px;font-weight:700;color:${PK.text};white-space:nowrap;letter-spacing:-.2px">${THM_LONG} ${yy+543}</span>
            <span style="font-size:9.5px;font-weight:600;color:#C4739A;white-space:nowrap">${isCur?`ข้อมูลถึง ${elapsed} ${THM} · เดือนปัจจุบัน`:`ทั้งเดือน · ${dim} วัน`}</span>
          </span>
          <button onclick="fuelMonthShift(1)" title="เดือนถัดไป" style="background:none;border:none;width:24px;height:24px;cursor:pointer;font-size:16px;color:${PK.text};border-radius:50%;line-height:1;font-family:inherit">›</button>
          ${isCur?'':`<button onclick="_fuelMonth=(typeof TODAY_STR!=='undefined'?TODAY_STR:'').slice(0,7);renderFuelIntel()" title="กลับมาเดือนปัจจุบัน" style="background:#fff;border:1px solid #F2B9CD;color:${PK.text};border-radius:8px;padding:3px 9px;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;margin-left:2px;white-space:nowrap">วันนี้</button>`}
        </div>
        <div class="fi-mut" style="margin-bottom:5px">ต้นทุนน้ำมันรวม ${THM_LONG}</div>
        <div style="display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:9px"><span style="font-size:38px;font-weight:700;letter-spacing:-1px;line-height:1;font-family:'DM Mono',monospace;color:#1A1A1A">${fB(a.cost)}</span><span style="background:#D8EEBD;color:#2C5008;padding:3px 12px;border-radius:99px;font-size:11px;font-weight:600">${fL(a.fuel)} L</span><span style="background:#F1EFE8;color:#5F5E5A;padding:3px 12px;border-radius:99px;font-size:11px;font-weight:600">${a.tripDays} เที่ยว</span></div>
        <div class="fi-mut">คาดทั้งเดือน ${fB(proj)}${budget?` / งบ ${fB(budget)} <span style="color:${proj>budget?'#A32D2D':'#3B6D11'};font-weight:600">${proj>budget?'เกินงบ':'ในงบ'}</span>`:` · <span style="cursor:pointer;color:${PK.text}" onclick="var v=prompt('ตั้งงบน้ำมันเดือนนี้ (฿)','');if(v!==null)fuelSetBudget(v)">+ ตั้งงบ</span>`}${a.priceMissing?' · <span style="color:#BA7517">⚠ บางวันยังไม่ใส่ราคาน้ำมัน</span>':''}</div>
      </div>
      <div class="fi-kpi" style="background:#EAF3DE;color:#27500A;padding:13px 16px;border:0.5px solid #C0DD97">
        <div style="font-size:10.5px;color:#3B6D11">ต้นทุนน้ำมัน / pax</div>
        <div style="display:flex;align-items:baseline;gap:7px;margin-top:3px"><span style="font-size:25px;font-weight:700;line-height:1;font-family:'DM Mono',monospace;color:#173404">${cpp>0?fB(cpp):'—'}</span>${mom!=null?`<span style="font-size:13px;font-weight:700;color:${mom<=0?'#3B6D11':'#A32D2D'}">${mom<=0?'▼':'▲'} ${Math.abs(mom)}%</span>`:''}</div>
        <div style="font-size:10.5px;color:#4C7A1E;margin-top:6px">${mom!=null?(mom<=0?'ดีขึ้นจาก '+THM_prev(pmS)+' '+fB(pcpp):'แพงขึ้นจาก '+THM_prev(pmS)+' '+fB(pcpp)):'ยังไม่มีข้อมูลเดือนก่อนเทียบ'}</div>
      </div>
      <div class="fi-kpi" style="background:#1A1A1A;color:#fff;padding:13px 15px">
        <div style="display:flex;align-items:center;justify-content:space-between"><span style="font-size:10.5px;color:#aaa">ผิดปกติ</span><span style="color:#F09595;font-size:12px">⚠</span></div>
        <div style="display:flex;align-items:baseline;gap:4px;margin-top:3px"><span style="font-size:22px;font-weight:700;font-family:'DM Mono',monospace">${anoms.length}</span><span style="font-size:11px;color:#aaa">วัน</span></div>
        <div style="font-size:10.5px;color:#F09595;margin-top:7px">${anoms.length?'น้ำมันสูงผิดปกติ · เช็ครั่ว':'ปกติทั้งหมด'}</div>
      </div>
      <div class="fi-kpi" style="background:#fff;padding:13px 15px;border:1.5px solid ${PK.accent}">
        <div style="font-size:10.5px;color:${ink3}">ยังไม่เติม</div>
        <div style="display:flex;align-items:baseline;gap:5px;margin-top:3px"><span style="background:${PK.accent};color:#fff;padding:2px 10px;border-radius:99px;font-size:15px;font-weight:700;font-family:'DM Mono',monospace">${missN}</span><span style="font-size:11px;color:${ink3}">วัน</span></div>
        <div style="margin-top:8px"><span style="color:${PK.text};font-size:11px;font-weight:600">${logged}% logged</span></div>
      </div>
    </div>

    <div class="fi-card" style="padding:16px 18px;margin-bottom:12px">
      <div class="fi-sec" style="margin-bottom:13px"><span class="fi-tick"></span>แยกตามเรือ</div>
      <table class="fi-tbl" style="font-size:13px"><thead><tr style="color:${ink3};font-size:11px"><th style="text-align:left">เรือ</th><th style="text-align:right">วัน</th><th style="text-align:right">pax</th><th style="text-align:right" title="ผู้โดยสารเฉลี่ยต่อเที่ยว (pax ÷ วันที่ออก) · % คือเทียบกับที่นั่งของเรือลำนั้น">คน/ลำ</th><th style="text-align:right">น้ำมัน L</th><th style="text-align:right">฿</th><th style="text-align:right">L/วัน</th><th style="text-align:right">L/pax</th><th style="text-align:right">ขาด</th></tr></thead><tbody>${boatRows}${grandRow}</tbody></table>
    </div>

    <div class="fi-card" style="padding:16px 18px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><span class="fi-sec"><span class="fi-tick"></span>ประสิทธิภาพ · L ต่อชั่วโมงเครื่อง</span><span class="fi-mut">ยิ่งต่ำยิ่งประหยัด · ฐานจาก engine-hour</span></div>
      <div style="display:flex;flex-direction:column;gap:11px">${effRows}</div>
    </div>

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px">
      <div class="fi-card" style="padding:16px 18px">
        <div class="fi-sec" style="margin-bottom:13px"><span class="fi-tick"></span>แยกตามโปรแกรม · ต้นทุน vs รายได้</div>
        <table class="fi-tbl" style="font-size:12.5px"><thead><tr style="color:${ink3};font-size:10.5px"><th style="text-align:left">โปรแกรม</th><th style="text-align:right">L/pax</th><th style="text-align:right">฿/pax</th><th style="text-align:right">% รายได้</th></tr></thead><tbody>${famRows}</tbody></table>
      </div>
      <div class="fi-card" style="padding:16px 18px">
        <div class="fi-sec" style="margin-bottom:16px"><span class="fi-tick"></span>เทรนด์ค่าน้ำมันรายสัปดาห์</div>
        <div style="display:flex;align-items:flex-end;gap:12px;height:120px;border-bottom:1px solid #EDEBE3">${wkBars}</div>
        <div style="display:flex;gap:12px;margin-top:8px">${wkLabels}</div>
      </div>
    </div>

    ${wkCard}
    ${moCard}

    <div class="fi-kpi" style="background:#1A1A1A;border-radius:16px;padding:13px 18px;color:#fff;display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:12px">
      <span style="font-size:12px;font-weight:600;color:#F09595">◆ ต้องตรวจสอบ</span>${anomHtml}<span style="margin-left:auto;font-size:11px;color:#9BCBA6">รั่ว / หาย / กรอกผิด ?</span>
    </div>

    <div class="fi-card" style="padding:16px 18px">
      <div class="fi-sec" style="margin-bottom:13px"><span class="fi-tick"></span><span style="color:#A32D2D">⚠</span>วันที่เรือออกแต่ยังไม่เติมน้ำมัน${missN>6?` <span style="font-size:11px;color:${ink3};font-weight:400">(แสดง 6 จาก ${missN})</span>`:''}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${missList}</div>
    </div>
  </div>`;
}
function THM_prev(ms){ const m=+ms.split('-')[1]; return ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][m-1]; }

function flRenderInsights(){
  const wrap=document.getElementById('fl-insights-wrap');
  if(!wrap)return;
  const dim={bg:'#F4F2EE',ink:'#1A1A1A',ink2:'#666',ink3:'#999',ink4:'#bbb',ink5:'#ccc',line:'rgba(0,0,0,.04)',line2:'#f0f0f0'};
  const SVG_PINK={accent:'#E03B7E',soft:'#FCE5EC',text:'#9F1B4F'};
  const calcCost=(m)=>typeof flMaintCalcCost==='function'?flMaintCalcCost(m.id):(m.cost||0);
  const fmtShort=(n)=>{if(!n)return'฿0';if(n>=1000000)return'฿'+(n/1000000).toFixed(1)+'M';if(n>=1000)return'฿'+Math.round(n/1000)+'k';return'฿'+n;};
  const fmtFull=(n)=>'฿'+(Math.round(n||0)).toLocaleString();
  const MONTHS_EN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

  // ── Time filter setup ──
  const todayD=new Date(TODAY_STR);
  const yr=todayD.getFullYear(); const mo=todayD.getMonth();
  let startDate, endDate=TODAY_STR, periodLabel;
  if(_insightsTimeFilter==='month'){
    startDate=new Date(yr,mo,1).toISOString().slice(0,10);
    periodLabel='This Month';
  } else if(_insightsTimeFilter==='quarter'){
    const qStart=Math.floor(mo/3)*3;
    startDate=new Date(yr,qStart,1).toISOString().slice(0,10);
    periodLabel='This Quarter';
  } else if(_insightsTimeFilter==='ytd'){
    startDate=new Date(yr,0,1).toISOString().slice(0,10);
    periodLabel='YTD';
  } else {
    startDate=null; periodLabel='All Time';
  }
  const inPeriod=(d)=>{ if(!startDate) return true; return d && d>=startDate && d<=endDate; };
  const dateLabel=`${MONTHS_EN[mo]} ${todayD.getDate()}, ${yr}`;

  // ── Aggregate data ──
  const allJobs = FL_MAINT||[];
  const allIncs = FL_INCIDENTS||[];
  const allMemos = FL_MEMOS||[];
  const periodJobs = allJobs.filter(j=>inPeriod(j.startDate));
  const periodIncs = allIncs.filter(i=>inPeriod(i.date));
  const periodSpent = periodJobs.reduce((s,j)=>s+calcCost(j),0);
  const activeJobs = allJobs.filter(j=>j.status==='inprogress' || j.status==='pending');
  const boats = BOATS || [];
  const companyBoats = boats.filter(b=>b.ownership!=='charter' && !b.retired);
  const fixingCount = companyBoats.filter(b=>{
    const cur = typeof getCurStatus==='function' ? getCurStatus(b, TODAY_STR).s : 'available';
    return cur === 'fixing';
  }).length;
  const unavailableCount = companyBoats.filter(b=>{
    const cur = typeof getCurStatus==='function' ? getCurStatus(b, TODAY_STR).s : 'available';
    return cur === 'unavailable';
  }).length;
  // Strict available count — matches Fleet Dashboard logic
  const availableCount = companyBoats.filter(b=>{
    const cur = typeof getCurStatus==='function' ? getCurStatus(b, TODAY_STR).s : 'available';
    return cur === 'available';
  }).length;

  // Per-boat aggregation
  const boatStats = {};
  companyBoats.forEach(b=>{
    boatStats[b.id] = {
      id:b.id, name:b.name, pier:b.pier,
      jobs:0, jobsActive:0, cost:0, incidents:0,
      curStatus: typeof getCurStatus==='function' ? getCurStatus(b, TODAY_STR).s : 'available'
    };
  });
  periodJobs.forEach(j=>{
    const s = boatStats[j.boatId]; if(!s) return;
    s.jobs++;
    if(j.status==='inprogress' || j.status==='pending') s.jobsActive++;
    s.cost += calcCost(j);
  });
  periodIncs.forEach(i=>{
    const s = boatStats[i.boatId]; if(!s) return;
    s.incidents++;
  });

  const getHealth = (s) => {
    if(s.jobs >= 3 || s.cost >= 100000) return {level:'critical', icon:'critical', text:'Critical', color:'#A32D2D', bg:'#FBE9E9'};
    if(s.jobs >= 1) return {level:'watch', icon:'watch', text:'Watch', color:'#854F0B', bg:'#FAEEDA'};
    return {level:'healthy', icon:'healthy', text:'Healthy', color:'#0F6E56', bg:'#E6F4ED'};
  };

  if(typeof _insightsSort === 'undefined') window._insightsSort = 'cost';
  const sortMode = window._insightsSort || 'cost';
  const boatRows = Object.values(boatStats).sort((a,b)=>{
    if(sortMode==='cost') return b.cost - a.cost;
    if(sortMode==='incidents') return b.incidents - a.incidents;
    if(sortMode==='jobs') return b.jobs - a.jobs;
    if(sortMode==='name') return a.name.localeCompare(b.name);
    return 0;
  });

  // Most-attention boat (Tier 1 alert card)
  const alertBoat = boatRows.find(s=>s.cost>0 || s.jobs>0) || null;
  const alertB = alertBoat ? boats.find(b=>b.id===alertBoat.id) : null;
  const alertReason = alertBoat ? (alertBoat.jobs ? `${alertBoat.jobs} job${alertBoat.jobs>1?'s':''} · ${fmtShort(alertBoat.cost)}` : `${alertBoat.incidents} incidents`) : '';

  // Pier counts
  const tlBoats = companyBoats.filter(b=>(typeof getBoatCurrentPier==='function'?getBoatCurrentPier(b):b.pier)==='tublamu').length;
  const vpBoats = companyBoats.filter(b=>(typeof getBoatCurrentPier==='function'?getBoatCurrentPier(b):b.pier)==='panwa').length;
  const rnBoats = companyBoats.filter(b=>(typeof getBoatCurrentPier==='function'?getBoatCurrentPier(b):b.pier)==='ranong').length;

  // Memos pending
  const memosPending = allMemos.filter(m=>m.status==='pending_approval');
  const memosPendingAmt = memosPending.reduce((s,m)=>s+(m.amount||0),0);
  const memosReceived = allMemos.filter(m=>m.status==='received');
  const memosPaidAmt = memosReceived.reduce((s,m)=>s+(m.amount||0),0);

  // ──────── HEADER BAR (matching Dashboard) ────────
  const headerBar=`<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px">
    <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
      <div onclick="nav(document.querySelector('[data-view=fl-boatstatus]'))" style="display:flex;align-items:center;gap:6px;background:white;border:1px solid ${dim.line};border-radius:20px;padding:3px 12px 3px 3px;cursor:pointer"><div style="width:24px;height:24px;border-radius:50%;background:#185FA5;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">TL</div><span style="font-size:12px;font-weight:500">Tub Lamu · ${tlBoats}</span></div>
      <div onclick="nav(document.querySelector('[data-view=fl-boatstatus]'))" style="display:flex;align-items:center;gap:6px;background:white;border:1px solid ${dim.line};border-radius:20px;padding:3px 12px 3px 3px;cursor:pointer"><div style="width:24px;height:24px;border-radius:50%;background:#0F6E56;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">VP</div><span style="font-size:12px;font-weight:500">Visit Panwa · ${vpBoats}</span></div>
      ${rnBoats?`<div onclick="nav(document.querySelector('[data-view=fl-boatstatus]'))" style="display:flex;align-items:center;gap:6px;background:white;border:1px solid ${dim.line};border-radius:20px;padding:3px 12px 3px 3px;cursor:pointer"><div style="width:24px;height:24px;border-radius:50%;background:#BA7517;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">RN</div><span style="font-size:12px;font-weight:500">Ranong · ${rnBoats}</span></div>`:''}
      <div style="width:32px;height:32px;border-radius:50%;background:${dim.ink};color:white;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600">I</div>
    </div>
    <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
      <span style="font-size:12px;color:${dim.ink2}">${dateLabel}</span>
      <span style="color:${dim.ink5}">·</span>
      <div style="display:flex;gap:4px;background:white;border:1px solid ${dim.line};border-radius:18px;padding:2px">
        ${['month','Month','quarter','Q','ytd','YTD','all','All'].reduce((a,_,i,arr)=>{ if(i%2===0){a.push([arr[i],arr[i+1]]);} return a; }, []).map(([v,l])=>{
          const on=_insightsTimeFilter===v;
          return`<button onclick="insightsSetTime('${v}')" style="background:${on?dim.ink:'transparent'};color:${on?'white':dim.ink2};border:none;border-radius:14px;padding:4px 12px;font-size:11px;font-weight:${on?600:500};cursor:pointer">${l}</button>`;
        }).join('')}
      </div>
    </div>
  </div>`;

  // ──────── TIER 1: KPI Strip (Dashboard style + Hybrid accents) ────────
  // Layout: Fleet hero | High alert (forest green) | Maintenance (pink border) | Incidents | Spent
  const FOREST = '#1F4D2C', LIME = '#C8F47C', LIME_SOFT = '#E8F5D8', LIME_DARK = '#3B6D11';
  const kpiStrip=`<div style="display:grid;grid-template-columns:1.6fr 0.85fr 0.85fr 0.85fr 0.85fr;gap:8px;margin-bottom:14px;align-items:stretch">
    <div style="grid-column:1;align-self:end;padding-bottom:6px">
      <div style="font-size:13px;font-weight:500;color:${dim.ink4};margin-bottom:2px">Fleet · ${periodLabel}</div>
      <div style="display:flex;align-items:baseline;gap:8px;margin-bottom:8px;flex-wrap:wrap">
        <span style="font-size:42px;font-weight:700;letter-spacing:-1.5px;line-height:1">${companyBoats.length}</span>
        <span style="font-size:18px;color:${dim.ink3};font-weight:500">boats</span>
        <span style="display:inline-flex;align-items:center;background:${LIME};color:${FOREST};padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600">▴ ${availableCount} available</span>
        ${fixingCount?`<span style="display:inline-flex;align-items:center;background:#FAEEDA;color:#854F0B;padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600">${fixingCount} fixing</span>`:''}
        ${unavailableCount?`<span style="display:inline-flex;align-items:center;background:#FBE9E9;color:#A32D2D;padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600">${unavailableCount} unavailable</span>`:''}
      </div>
      <div style="font-size:11px;color:${dim.ink3}">${periodIncs.length} incidents · ${periodJobs.length} jobs · ${fmtShort(periodSpent)} spent · avg ${fmtShort(periodJobs.length?periodSpent/periodJobs.length:0)}/job</div>
    </div>

    <div ${alertB?`onclick="flGoToAsset('boats','${alertB.id}')"`:''} style="grid-column:2;background:${FOREST};color:white;border-radius:14px;padding:11px 13px;position:relative;${alertB?'cursor:pointer':''}">
      <div style="display:flex;align-items:center;justify-content:space-between"><span style="font-size:10px;color:#9BB89B">High alert</span><span style="color:${LIME};font-size:11px">◆</span></div>
      <div style="font-size:18px;font-weight:700;line-height:1.2;margin-top:2px">${alertB?alertB.name:'—'}</div>
      <div style="font-size:11px;color:#9BB89B;margin-top:6px">${alertReason||'no alerts'}</div>
      ${alertB?`<span style="position:absolute;bottom:11px;right:11px;color:${LIME};font-size:14px">›</span>`:''}
    </div>

    <div onclick="nav(document.querySelector('[data-view=fl-maintenance]'))" style="grid-column:3;background:white;border-radius:14px;padding:11px 13px;border:2px solid ${SVG_PINK.accent};cursor:pointer">
      <div style="font-size:10px;color:${dim.ink3}">Active Jobs</div>
      <div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="background:${SVG_PINK.accent};color:white;padding:2px 9px;border-radius:14px;font-size:14px;font-weight:700">${activeJobs.length}</span><span style="font-size:11px;color:${dim.ink3};margin-left:2px">in progress</span></div>
      <div style="display:flex;align-items:center;gap:3px;margin-top:7px"><span style="color:${SVG_PINK.text};font-size:11px;font-weight:600">${activeJobs.filter(j=>j.status==='pending').length} pending</span></div>
    </div>

    <div onclick="nav(document.querySelector('[data-view=fl-incident]'))" style="grid-column:4;background:white;border-radius:14px;padding:11px 13px;border:1px solid ${dim.line};cursor:pointer">
      <div style="font-size:10px;color:${dim.ink3}">Incidents</div>
      <div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="background:${dim.bg};color:${dim.ink};padding:2px 9px;border-radius:14px;font-size:14px;font-weight:700">${periodIncs.length}</span><span style="font-size:11px;color:${dim.ink3};margin-left:2px">${periodLabel.toLowerCase()}</span></div>
      <div style="display:flex;align-items:center;gap:3px;margin-top:7px"><span style="color:#A32D2D;font-size:11px;font-weight:600">${periodIncs.filter(i=>i.priority>=4).length} critical</span></div>
    </div>

    <div onclick="nav(document.querySelector('[data-view=fl-cost]'))" style="grid-column:5;background:white;border-radius:14px;padding:11px 13px;border:1px solid ${dim.line};cursor:pointer">
      <div style="font-size:10px;color:${dim.ink3}">Spent</div>
      <div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="font-size:18px;font-weight:700;line-height:1.2">${fmtShort(periodSpent)}</span></div>
      <div style="display:flex;align-items:center;gap:3px;margin-top:7px"><span style="color:#0F6E56;font-size:11px;font-weight:600">${periodJobs.length} jobs</span></div>
    </div>
  </div>`;

  // ──────── PILL ROW (Dashboard style) ────────
  const healthCriticalCnt = boatRows.filter(s=>getHealth(s).level==='critical').length;
  const healthWatchCnt = boatRows.filter(s=>getHealth(s).level==='watch').length;
  const healthHealthyCnt = boatRows.filter(s=>getHealth(s).level==='healthy').length;

  const pillRow=`<div style="display:flex;gap:6px;margin-bottom:14px;align-items:center;flex-wrap:wrap">
    <div style="flex:1;min-width:160px;background:white;border-radius:24px;padding:7px 14px;display:flex;align-items:center;gap:10px;border:1px solid ${dim.line}">
      <div style="width:24px;height:24px;border-radius:50%;background:#A32D2D;color:white;display:flex;align-items:center;justify-content:center">${insightIcon('critical', 13, 'white')}</div>
      <span style="font-size:12px;font-weight:600">Critical</span>
      <span style="margin-left:auto;font-size:11px;font-weight:500">${healthCriticalCnt} boat${healthCriticalCnt!==1?'s':''}</span>
      <span style="font-size:11px;color:${dim.ink3}">${companyBoats.length?((healthCriticalCnt/companyBoats.length)*100).toFixed(0):0}%</span>
    </div>
    <div style="flex:1;min-width:160px;background:white;border-radius:24px;padding:7px 14px;display:flex;align-items:center;gap:10px;border:1px solid ${dim.line}">
      <div style="width:24px;height:24px;border-radius:50%;background:#854F0B;color:white;display:flex;align-items:center;justify-content:center">${insightIcon('watch', 13, 'white')}</div>
      <span style="font-size:12px;font-weight:600">Watch</span>
      <span style="margin-left:auto;font-size:11px;font-weight:500">${healthWatchCnt} boat${healthWatchCnt!==1?'s':''}</span>
      <span style="font-size:11px;color:${dim.ink3}">${companyBoats.length?((healthWatchCnt/companyBoats.length)*100).toFixed(0):0}%</span>
    </div>
    <div style="flex:1;min-width:160px;background:${LIME_SOFT};border-radius:24px;padding:7px 14px;display:flex;align-items:center;gap:10px;border:1px solid #C8E29A">
      <div style="width:24px;height:24px;border-radius:50%;background:${FOREST};color:${LIME};display:flex;align-items:center;justify-content:center">${insightIcon('healthy', 13)}</div>
      <span style="font-size:12px;font-weight:600;color:${FOREST}">Healthy</span>
      <span style="margin-left:auto;font-size:11px;font-weight:500;color:${FOREST}">${healthHealthyCnt} boat${healthHealthyCnt!==1?'s':''}</span>
      <span style="font-size:11px;color:${LIME_DARK}">${companyBoats.length?((healthHealthyCnt/companyBoats.length)*100).toFixed(0):0}%</span>
    </div>
    <div onclick="nav(document.querySelector('[data-view=fl-inventory]'))" style="flex:1;min-width:180px;background:white;border-radius:24px;padding:7px 14px;display:flex;align-items:center;gap:10px;border:1px solid ${dim.line};cursor:pointer">
      <div style="width:24px;height:24px;border-radius:50%;background:${SVG_PINK.accent};color:white;display:flex;align-items:center;justify-content:center">${insightIcon('memo', 13, 'white')}</div>
      <span style="font-size:12px;font-weight:600">Memos pending</span>
      <span style="margin-left:auto;font-size:11px;font-weight:500">${memosPending.length} memos</span>
      <span style="font-size:11px;color:${dim.ink3}">${fmtShort(memosPendingAmt)}</span>
    </div>
  </div>`;

  // ──────── TIER 2: Boat Health Scorecard (Dashboard card style) ────────
  // Boat avatar helpers (matching Boat Status page pattern)
  const boatAvatarColor=(b)=>{
    const bc = typeof getBoatColor==='function' ? getBoatColor(b.id) : null;
    if(bc) return bc.text; // use boat-color palette
    const palette=['#185FA5','#534AB7','#1D9E75','#BA7517','#A32D2D','#0F6E56','#7F77DD','#D85A30','#993556','#185FA5'];
    const i=companyBoats.findIndex(x=>x.id===b.id);
    return palette[i%palette.length>=0?(i%palette.length):0];
  };
  const boatInitials=(name)=>{
    const w=name.split(/\s+/);
    if(w.length>=2)return (w[0][0]+w[1][0]).toUpperCase();
    if(name.length>=2&&/\d/.test(name))return (name.match(/[A-Z]/g)?.[0]||name[0])+name.slice(-1);
    return name.slice(0,2).toUpperCase();
  };

  const sortBtn = (v, l) => {
    const on = sortMode === v;
    return `<button onclick="window._insightsSort='${v}';flRenderInsights()" style="background:${on?dim.ink:'transparent'};color:${on?'white':dim.ink2};border:${on?'none':'1px solid rgba(0,0,0,.08)'};border-radius:14px;padding:4px 11px;font-size:11px;font-weight:${on?600:500};cursor:pointer">${l}</button>`;
  };
  const scoreRow = (s, idx) => {
    const h = getHealth(s);
    const b = boats.find(x=>x.id===s.id);
    const c = b ? boatAvatarColor(b) : '#666';
    const init = boatInitials(s.name);
    const fixingPill = s.curStatus==='fixing' ? `<span style="background:#FAEEDA;color:#854F0B;padding:1px 6px;border-radius:6px;font-size:9px;font-weight:600;font-family:'DM Mono',monospace">FIXING</span>` : '';
    return `<div onclick="flGoToAsset('boats','${s.id}')" style="display:flex;align-items:center;gap:11px;padding:11px 16px;border-bottom:1px solid ${dim.line2};cursor:pointer;transition:background .1s" onmouseover="this.style.background='#FBFAF7'" onmouseout="this.style.background='white'">
      <span style="font-size:11px;font-family:'DM Mono',monospace;color:${dim.ink4};width:18px">${(idx+1).toString().padStart(2,'0')}</span>
      <div style="width:34px;height:34px;border-radius:50%;background:${c};color:white;font-size:11px;display:flex;align-items:center;justify-content:center;font-weight:700;flex-shrink:0;letter-spacing:.5px">${init}</div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:2px">
          <span style="font-size:13px;font-weight:600;color:${dim.ink}">${s.name}</span>
          <span style="font-size:10px;color:${dim.ink3};font-family:'DM Mono',monospace">${s.pier==='tublamu'?'Tub Lamu':s.pier==='panwa'?'Visit Panwa':s.pier==='ranong'?'Ranong':'—'}</span>
        </div>
        <div style="display:flex;gap:12px;align-items:center">
          <span style="font-size:10px;color:${dim.ink2}"><strong style="font-family:'DM Mono',monospace;color:${dim.ink};font-size:12px">${s.jobs}</strong> jobs</span>
          <span style="color:${dim.ink5}">·</span>
          <span style="font-size:10px;color:${dim.ink2}"><strong style="font-family:'DM Mono',monospace;color:${dim.ink};font-size:12px">${s.incidents}</strong> incidents</span>
          <span style="color:${dim.ink5}">·</span>
          <span style="font-size:11px;font-weight:700;font-family:'DM Mono',monospace;color:${s.cost>0?'#0F6E56':dim.ink4}">${fmtShort(s.cost)}</span>
        </div>
      </div>
      ${fixingPill}
      <span style="background:${h.bg};color:${h.color};padding:2px 9px;border-radius:8px;font-size:10px;font-weight:600;display:inline-flex;align-items:center;gap:5px">${insightIcon(h.icon, 11)}${h.text}</span>
      <span style="color:${dim.ink5};font-size:14px">›</span>
    </div>`;
  };
  // ──────── TIER 2: 3-card Boat Health Scorecard ────────
  // Smart default sort per status:
  //   Critical → cost desc (most attention first)
  //   Watch    → jobs desc (active concerns first)
  //   Healthy  → name asc (predictable, alphabetical)
  const allBoatRows = Object.values(boatStats);
  const criticalRows = allBoatRows.filter(s => getHealth(s).level === 'critical').sort((a,b) => b.cost - a.cost);
  const watchRows    = allBoatRows.filter(s => getHealth(s).level === 'watch').sort((a,b) => b.jobs - a.jobs || b.cost - a.cost);
  const healthyRows  = allBoatRows.filter(s => getHealth(s).level === 'healthy').sort((a,b) => a.name.localeCompare(b.name));

  // Compact row used inside status cards
  const compactScoreRow = (s, idx) => {
    const h = getHealth(s);
    const b = boats.find(x=>x.id===s.id);
    const c = b ? boatAvatarColor(b) : '#666';
    const init = boatInitials(s.name);
    const fixingPill = s.curStatus==='fixing' ? `<span style="background:#FAEEDA;color:#854F0B;padding:1px 5px;border-radius:5px;font-size:8px;font-weight:600;font-family:'DM Mono',monospace">FIX</span>` : '';
    return `<div onclick="flGoToAsset('boats','${s.id}')" style="display:flex;align-items:center;gap:9px;padding:9px 4px;border-bottom:1px solid ${dim.line2};cursor:pointer;transition:background .1s" onmouseover="this.style.background='#FBFAF7'" onmouseout="this.style.background='transparent'">
      <div style="width:28px;height:28px;border-radius:50%;background:${c};color:white;font-size:9px;display:flex;align-items:center;justify-content:center;font-weight:700;letter-spacing:.3px;flex-shrink:0">${init}</div>
      <div style="flex:1;min-width:0">
        <div style="font-size:12px;font-weight:600;color:${dim.ink};overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${s.name}</div>
        <div style="font-size:9px;color:${dim.ink3};margin-top:1px"><strong style="font-family:'DM Mono',monospace;color:${dim.ink2}">${s.jobs}</strong> jobs · <strong style="font-family:'DM Mono',monospace;color:${dim.ink2}">${s.incidents}</strong> inc</div>
      </div>
      ${fixingPill}
      <span style="font-size:11px;font-weight:700;font-family:'DM Mono',monospace;color:${s.cost>0?'#0F6E56':dim.ink4};flex-shrink:0">${s.cost>0?fmtShort(s.cost):'฿0'}</span>
    </div>`;
  };

  // Render rows with all boats (no limit)
  const renderRowsList = (rows) => {
    if(rows.length === 0) return `<div style="padding:24px 12px;text-align:center;font-size:11px;color:${dim.ink3}">No boats in this status</div>`;
    return rows.map(compactScoreRow).join('');
  };

  // For healthy with many boats — show as avatar cloud (all boats)
  const healthyAvatarCloud = (rows) => {
    if(rows.length === 0) return `<div style="padding:24px 12px;text-align:center;font-size:11px;color:${dim.ink3}">No healthy boats</div>`;
    const avatars = rows.map(s => {
      const b = boats.find(x=>x.id===s.id);
      const c = b ? boatAvatarColor(b) : '#666';
      const init = boatInitials(s.name);
      return `<div title="${s.name}" onclick="flGoToAsset('boats','${s.id}')" style="width:32px;height:32px;border-radius:50%;background:${c};color:white;font-size:10px;display:flex;align-items:center;justify-content:center;font-weight:700;letter-spacing:.3px;cursor:pointer;flex-shrink:0">${init}</div>`;
    }).join('');
    return `<div style="padding:8px 4px 4px">
      <div style="display:flex;flex-wrap:wrap;gap:6px;justify-content:center">${avatars}</div>
      <p style="margin:14px 0 0;font-size:11px;color:${dim.ink2};text-align:center;line-height:1.4">All boats with zero issues this month</p>
      <div style="text-align:center;padding-top:10px;margin-top:10px;border-top:1px solid ${dim.line2}"><a onclick="nav(document.querySelector('[data-view=fl-boatstatus]'))" style="color:${FOREST};font-size:11px;font-weight:600;cursor:pointer">View boat status →</a></div>
    </div>`;
  };

  // Card builder
  const statusCard = (label, color, rows, mode) => {
    const pct = allBoatRows.length > 0 ? Math.round((rows.length / allBoatRows.length) * 100) : 0;
    let body;
    if(mode === 'cloud'){
      body = healthyAvatarCloud(rows);
    } else {
      body = renderRowsList(rows);
    }
    return `<div style="background:white;border-radius:18px;padding:16px 18px;border-top:3px solid ${color};display:flex;flex-direction:column">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;padding-bottom:10px;border-bottom:1px solid ${dim.line2}">
        <span style="background:${color};color:white;padding:3px 10px;border-radius:9px;font-size:9px;font-weight:700;letter-spacing:.08em">${label}</span>
        <span style="font-size:11px;color:${dim.ink2};font-weight:500">${rows.length} boat${rows.length!==1?'s':''}</span>
        <span style="font-size:10px;color:${dim.ink3};margin-left:auto;font-family:'DM Mono',monospace">${pct}%</span>
      </div>
      <div style="flex:1">${body}</div>
    </div>`;
  };

  const scorecardPanel = `<div style="margin-bottom:14px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;padding:0 4px">
      <div>
        <p style="margin:0;font-size:14px;font-weight:600;color:${dim.ink}">Boat Health Scorecard</p>
        <p style="margin:2px 0 0;font-size:10px;color:${dim.ink3}">Per-boat performance · ${periodLabel}</p>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;align-items:stretch">
      ${statusCard('CRITICAL', '#A32D2D', criticalRows, 'list')}
      ${statusCard('WATCH', '#854F0B', watchRows, 'list')}
      ${statusCard('HEALTHY', '#0F6E56', healthyRows, 'list')}
    </div>
  </div>`;

  // ──────── TIER 3: Charts ────────
  const months = [];
  for(let i=5;i>=0;i--){
    const d = new Date(yr, mo-i, 1);
    const dYr = d.getFullYear();
    const dMo = d.getMonth();
    const key = `${dYr}-${String(dMo+1).padStart(2,'0')}`;
    const label = MONTHS_EN[dMo];
    months.push({key,label, cost:0, incidents:0});
  }
  allJobs.forEach(j=>{
    if(!j.startDate) return;
    const k = j.startDate.slice(0,7);
    const m = months.find(x=>x.key===k);
    if(m) m.cost += calcCost(j);
  });
  allIncs.forEach(i=>{
    if(!i.date) return;
    const k = i.date.slice(0,7);
    const m = months.find(x=>x.key===k);
    if(m) m.incidents++;
  });
  const maxCost = Math.max(...months.map(m=>m.cost), 1);
  const maxInc = Math.max(...months.map(m=>m.incidents), 1);

  // Calculate delta chip (current vs prev month)
  const curMonth = months[months.length-1];
  const prevMonth = months[months.length-2];
  const costDelta = (prevMonth && prevMonth.cost > 0) ? Math.round(((curMonth.cost - prevMonth.cost) / prevMonth.cost) * 100) : null;
  const incDelta = (prevMonth && prevMonth.incidents > 0) ? Math.round(((curMonth.incidents - prevMonth.incidents) / prevMonth.incidents) * 100) : null;

  // Cost trend bars (for forest hero card — bars are translucent lime)
  const costBars = months.map((m,i)=>{
    const h = (m.cost/maxCost)*100;
    const isLast = i === months.length-1;
    const opacityVal = 0.12 + (i / months.length) * 0.13; // fade in
    return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:6px">
      <div style="font-size:9px;font-family:'DM Mono',monospace;color:${isLast?LIME:'#6B8B6B'};height:14px;font-weight:${isLast?600:400}">${m.cost?fmtShort(m.cost):''}</div>
      <div style="width:100%;display:flex;align-items:flex-end;justify-content:center;height:100px">
        <div style="width:70%;height:${Math.max(h,m.cost?3:0)}px;background:${isLast?LIME:'rgba(200,244,124,'+opacityVal+')'};border-radius:5px 5px 0 0;transition:height .2s"></div>
      </div>
      <div style="font-size:10px;color:${isLast?'white':'#9BB89B'};font-weight:${isLast?600:500}">${m.label}</div>
    </div>`;
  }).join('');

  // Incidents bars (for white card — red shades)
  const incBars = months.map((m,i)=>{
    const h = (m.incidents/maxInc)*100;
    const isLast = i === months.length-1;
    return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:6px">
      <div style="font-size:9px;font-family:'DM Mono',monospace;color:${isLast?'#A32D2D':dim.ink3};height:14px;font-weight:${isLast?600:400}">${m.incidents||''}</div>
      <div style="width:100%;display:flex;align-items:flex-end;justify-content:center;height:100px">
        <div style="width:70%;height:${Math.max(h,m.incidents?3:0)}px;background:${isLast?'#A32D2D':'#FBE9E9'};border-radius:5px 5px 0 0;border:${isLast?'none':'1px solid #F5C8C8'};transition:height .2s"></div>
      </div>
      <div style="font-size:10px;color:${isLast?dim.ink:dim.ink3};font-weight:${isLast?600:500}">${m.label}</div>
    </div>`;
  }).join('');

  // Caption messages (auto-generated context)
  let costCaption = '';
  if(curMonth.cost > 0){
    const topMonthBoat = Object.entries(boatStats).filter(([,s])=>s.cost>0).sort((a,b)=>b[1].cost - a[1].cost)[0];
    costCaption = topMonthBoat ? `${curMonth.label} driven by ${topMonthBoat[1].name} · ${fmtShort(topMonthBoat[1].cost)} (${Math.round(topMonthBoat[1].cost/curMonth.cost*100)}%)` : '';
  }
  let incCaption = '';
  if(curMonth.incidents > 0 && incDelta && incDelta >= 100){
    incCaption = `Sharp rise this month · Investigate operating conditions`;
  } else if(curMonth.incidents === 0){
    incCaption = `Zero incidents this month — great work`;
  } else if(curMonth.incidents > 0){
    incCaption = `${curMonth.incidents} incident${curMonth.incidents>1?'s':''} this month`;
  }

  // Cost trend card (forest green hero)
  // Cost trend card (Project Overview pattern — full width, timeline style)
  const MONTHS_UP = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
  const monthLabelsUp = months.map(m=>{
    const moIdx = parseInt(m.key.slice(5,7), 10) - 1;
    return MONTHS_UP[moIdx];
  });
  
  // Find top boat contribution to current month
  const curTopBoatEntry = Object.entries(boatStats).filter(([,s])=>s.cost>0).sort((a,b)=>b[1].cost - a[1].cost)[0];
  const curBoatPct = curMonth.cost > 0 && curTopBoatEntry ? Math.round(curTopBoatEntry[1].cost / curMonth.cost * 100) : 0;
  const curBoatObj = curTopBoatEntry ? boats.find(b=>b.id===curTopBoatEntry[0]) : null;
  const curBoatColor = curBoatObj ? boatAvatarColor(curBoatObj) : '#666';
  const curBoatInit = curBoatObj ? boatInitials(curBoatObj.name) : '';
  
  // Progress bar width relative to max month
  const curBarPct = maxCost > 0 ? Math.max((curMonth.cost / maxCost) * 100, 5) : 0;
  
  // Dot positions for past 5 months
  const dotPositions = months.slice(0, -1).map((m, i) => {
    const leftPct = 4 + (i * (74 / Math.max(months.length - 1, 1)));
    return { leftPct, label: monthLabelsUp[i], value: m.cost };
  });

  const costTrendCard = `<div style="background:${FOREST};color:white;border-radius:24px;padding:28px 30px;margin-bottom:14px;position:relative;overflow:hidden">
    <div style="margin-bottom:6px">
      <p style="margin:0;font-size:18px;font-weight:600;color:white">Cost trend</p>
      <p style="margin:4px 0 0;font-size:12px;color:#B8D4B8;line-height:1.5">Last 6 months of fleet maintenance spending${curBoatObj?` · ${monthLabelsUp[monthLabelsUp.length-1]} driven by ${curBoatObj.name}`:''}</p>
    </div>

    <div style="display:flex;justify-content:space-between;align-items:center;margin-top:32px;margin-bottom:10px">
      ${monthLabelsUp.map((lbl,i)=>{
        const isLast = i === monthLabelsUp.length - 1;
        return `<span style="font-size:10px;color:${isLast?'white':'#9BB89B'};letter-spacing:.1em;font-weight:600">${lbl}</span>`;
      }).join('')}
    </div>

    <div style="position:relative;height:32px;background:rgba(255,255,255,.08);border-radius:16px;margin:0 0 30px">
      <div style="width:${curBarPct}%;height:100%;background:${LIME};border-radius:16px;display:flex;align-items:center;justify-content:flex-end;padding-right:4px;min-width:${curBoatObj?'190px':'40px'};box-sizing:border-box">
        ${curBoatObj?`<div style="background:white;border-radius:14px;padding:4px 12px 4px 4px;display:flex;align-items:center;gap:8px;box-shadow:0 2px 6px rgba(0,0,0,.1)">
          <div style="width:22px;height:22px;border-radius:50%;background:${curBoatColor};color:white;display:flex;align-items:center;justify-content:center;font-size:8px;font-weight:700;letter-spacing:.3px">${curBoatInit}</div>
          <div>
            <div style="font-size:11px;font-weight:600;color:#1A1A1A;line-height:1">${curBoatObj.name} · ${fmtShort(curTopBoatEntry[1].cost)}</div>
            <div style="font-size:9px;color:#666;line-height:1;margin-top:2px">${curBoatPct}% of spend</div>
          </div>
        </div>`:''}
      </div>
    </div>

    <div style="position:relative;height:30px">
      ${dotPositions.map(d=>`
        <div style="position:absolute;left:${d.leftPct}%;top:-30px;width:1px;height:30px;background:rgba(155,184,155,.3)"></div>
        <div style="position:absolute;left:${d.leftPct}%;top:0;display:flex;align-items:center;gap:8px;transform:translateX(-3px)"><div style="width:5px;height:5px;border-radius:50%;background:${LIME}"></div><span style="font-size:10px;color:#9BB89B">${d.value?fmtShort(d.value):'฿0'}</span></div>
      `).join('')}
    </div>

    <div style="position:absolute;bottom:24px;right:30px;display:flex;gap:8px">
      <div style="background:rgba(255,255,255,.06);border:1px solid rgba(155,184,155,.2);border-radius:10px;padding:8px 12px;min-width:74px">
        <p style="margin:0;font-size:9px;color:#9BB89B;letter-spacing:.1em;font-weight:600">CURRENT</p>
        <p style="margin:3px 0 0;font-size:13px;font-weight:600;color:white;font-family:'DM Mono',monospace">${fmtShort(curMonth.cost)}</p>
      </div>
      ${costDelta !== null ? `<div style="background:rgba(255,255,255,.06);border:1px solid rgba(155,184,155,.2);border-radius:10px;padding:8px 12px;min-width:74px">
        <p style="margin:0;font-size:9px;color:#9BB89B;letter-spacing:.1em;font-weight:600">CHANGE</p>
        <p style="margin:3px 0 0;font-size:13px;font-weight:600;color:${costDelta>=0?LIME:'#FBE9E9'};font-family:'DM Mono',monospace">${costDelta>=0?'▴':'▾'} ${Math.abs(costDelta)}%</p>
      </div>`:''}
    </div>
  </div>`;

  // Incidents card (white with chart + footer chip — Notifications style)
  const incidentsCard = `<div style="background:white;border-radius:24px;padding:22px 24px">
    <p style="margin:0 0 16px;font-size:15px;font-weight:600;color:${dim.ink}">Incidents per month</p>
    <div style="display:flex;align-items:flex-end;gap:7px;height:100px;margin-bottom:0">${incBars}</div>
    <div style="display:flex;align-items:center;justify-content:space-between;padding-top:14px;border-top:1px solid #f1eee8;margin-top:14px">
      <span style="font-size:11px;color:${dim.ink2}">${curMonth.incidents} incident${curMonth.incidents!==1?'s':''} this month${incCaption?' · '+incCaption.replace(/this month/i,'').replace(/^\s*·\s*/,'').trim():''}</span>
      ${incDelta !== null ? `<span style="background:${incDelta>0?'#FBE9E9':'#E6F4ED'};color:${incDelta>0?'#A32D2D':'#0F6E56'};padding:3px 10px;border-radius:10px;font-size:10px;font-weight:600">${incDelta>=0?'▴':'▾'} ${Math.abs(incDelta)}%</span>`:''}
    </div>
  </div>`;

  const chartCard = (title, content) => `<div style="background:white;border-radius:24px;padding:22px 24px">
    <p style="margin:0 0 18px;font-size:15px;font-weight:600;color:${dim.ink}">${title}</p>
    ${content}
  </div>`;

  // Cost by supplier — smart extraction
  // Priority 1: mo.supplier (explicit field, most accurate)
  // Priority 2: linked inventory items → supplier field
  // Priority 3: regex on refNote — find segment that looks like company name
  const extractSupplier = (mo) => {
    // Priority 1: explicit supplier field
    if(mo.supplier && mo.supplier.trim()) return mo.supplier.trim();
    
    // Priority 2: items linked to inventory → majority supplier
    if(mo.items && mo.items.length > 0 && FL_INVENTORY){
      const supplierCounts = {};
      mo.items.forEach(it => {
        if(it.invId){
          const inv = FL_INVENTORY.find(x=>x.id===it.invId);
          if(inv && inv.supplier){
            supplierCounts[inv.supplier] = (supplierCounts[inv.supplier]||0) + 1;
          }
        }
      });
      const top = Object.entries(supplierCounts).sort((a,b)=>b[1]-a[1])[0];
      if(top) return top[0];
    }
    
    // Priority 3: regex on refNote (legacy)
    if(mo.refNote){
      const segments = mo.refNote.split('·').map(s=>s.trim());
      const companyRegex = /\b(Marine|Mall|Co\.?\s*Ltd|Co\.|Ltd|Suzuki|Honda|Yamaha|Megazip|บจ\.|บริษัท|Hilltribe|Industries|Hardware|Parts|Service|Materials|Trading)\b/i;
      for(const seg of segments){
        if(companyRegex.test(seg)){
          return seg.replace(/^อ้างอิง\s*/i,'').replace(/\s+(IV\S+|SO\S+|QT\S+|IN\S*|CO\d+|\d{2}\/\d{2}\/\d{4}).*$/i,'').trim();
        }
      }
      const dateOrDocRegex = /^(\d{2}\/\d{2}\/\d{4}|[A-Z]{2,3}[-\s]?\d{4,}|CO\d+|Tax Invoice|Invoice|IV\d+|SO\s?\d+|QT[-\s]?\d+)$/i;
      for(const seg of segments){
        const cleaned = seg.replace(/^อ้างอิง\s*/i,'').trim();
        if(!dateOrDocRegex.test(cleaned) && cleaned.length > 3){
          return cleaned;
        }
      }
    }
    return 'Other';
  };

  // Cost by supplier — memo-centric (approved+ in period)
  // Conditions to appear in this chart:
  //   1. memo.createdDate within selected period (Month/Quarter/YTD/All)
  //   2. memo.status is one of: approved, ordered, received, paid
  //      (Excludes: created, pending_approval, rejected, cancelled)
  //   3. Includes BOTH vessel-scope and general-scope memos
  const APPROVED_STATUSES = ['approved','ordered','received','paid'];
  const supplierMap = {};
  allMemos.forEach(mo=>{
    if(!mo.createdDate || !inPeriod(mo.createdDate)) return;
    if(!APPROVED_STATUSES.includes(mo.status)) return;
    const sup = extractSupplier(mo);
    supplierMap[sup] = (supplierMap[sup]||0) + (mo.amount||0);
  });
  const supplierRows = Object.entries(supplierMap).sort((a,b)=>b[1]-a[1]).slice(0,5);
  const totalSup = supplierRows.reduce((s,[,v])=>s+v, 0) || 1;
  const supplierBars = supplierRows.length ? supplierRows.map(([name,amt])=>{
    const pct = (amt/totalSup)*100;
    return `<div style="margin-bottom:14px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
        <span style="font-size:12px;color:${dim.ink};max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:500">${name}</span>
        <span style="font-size:12px;font-weight:700;font-family:'DM Mono',monospace;color:${dim.ink}">${fmtShort(amt)}</span>
      </div>
      <div style="background:#F4F2EE;border-radius:8px;height:8px;overflow:hidden">
        <div style="width:${pct}%;height:100%;background:linear-gradient(90deg,${LIME_SOFT},${FOREST});border-radius:8px;transition:width .3s"></div>
      </div>
    </div>`;
  }).join('') : `<div style="font-size:11px;color:${dim.ink3};text-align:center;padding:20px">No data in period</div>`;

  // Cost by type
  const typeMap = {corrective:0, preventive:0, scheduled:0};
  periodJobs.forEach(j=>{ if(typeMap[j.type]!==undefined) typeMap[j.type] += calcCost(j); });
  const totalType = Object.values(typeMap).reduce((s,v)=>s+v, 0) || 1;
  const TYPE_COLOR = {corrective:'#A32D2D', preventive:'#185FA5', scheduled:'#7C5BC4'};
  const TYPE_LABEL = {corrective:'Corrective', preventive:'Preventive', scheduled:'Scheduled'};
  const typeBars = Object.entries(typeMap).map(([k,v])=>{
    const pct = (v/totalType)*100;
    return `<div style="margin-bottom:14px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
        <span style="font-size:12px;color:${dim.ink};font-weight:500">${TYPE_LABEL[k]}</span>
        <span style="font-size:12px;font-weight:700;font-family:'DM Mono',monospace;color:${dim.ink}">${fmtShort(v)}</span>
      </div>
      <div style="background:#F4F2EE;border-radius:8px;height:8px;overflow:hidden">
        <div style="width:${pct}%;height:100%;background:${TYPE_COLOR[k]};border-radius:8px;opacity:.85;transition:width .3s"></div>
      </div>
    </div>`;
  }).join('');

  // Type caption — pattern detection
  let typeCaption = '';
  if(typeMap.corrective > 0 && typeMap.preventive === 0 && typeMap.scheduled === 0){
    typeCaption = '100% reactive cost · Consider preventive maintenance program';
  } else if(typeMap.preventive > typeMap.corrective){
    typeCaption = 'Preventive > Corrective · Healthy maintenance discipline';
  }

  // Build healthy boats wins card (Visual Vault style)
  const healthyBoats_v2 = Object.values(boatStats).filter(s=>s.jobs===0 && s.curStatus==='available');
  const healthyCount = healthyBoats_v2.length;
  const healthyNames = healthyBoats_v2.slice(0,3).map(s=>s.name).join(', ');
  const healthyRest = healthyBoats_v2.length > 3 ? `, +${healthyBoats_v2.length-3} more` : '';
  
  // Get 3 colors from top healthy boats for stacked cards
  const stackBoats = healthyBoats_v2.slice(0,3).map(s=>{
    const b = boats.find(x=>x.id===s.id);
    return b ? boatAvatarColor(b) : '#185FA5';
  });
  while(stackBoats.length < 3) stackBoats.push('#185FA5');
  
  const winsIllustrationCard = `<div style="background:white;border-radius:24px;padding:22px 24px;display:flex;flex-direction:column;align-items:center;text-align:center">
    <div style="position:relative;width:100px;height:80px;margin-bottom:12px">
      <div style="position:absolute;left:0;top:8px;width:50px;height:60px;border-radius:8px;background:${stackBoats[0]};transform:rotate(-12deg);box-shadow:0 4px 12px rgba(0,0,0,.1)"></div>
      <div style="position:absolute;left:22px;top:4px;width:50px;height:60px;border-radius:8px;background:${stackBoats[1]};box-shadow:0 4px 12px rgba(0,0,0,.1)"></div>
      <div style="position:absolute;left:44px;top:0;width:50px;height:60px;border-radius:8px;background:${stackBoats[2]};transform:rotate(8deg);box-shadow:0 4px 12px rgba(0,0,0,.1)"></div>
      <div style="position:absolute;left:14px;top:24px;width:72px;height:48px;border-radius:10px;background:${LIME};display:flex;align-items:center;justify-content:center;box-shadow:0 6px 16px rgba(31,77,44,.2)">
        <span style="font-size:18px;font-weight:700;color:${FOREST}">${healthyCount}</span>
      </div>
    </div>
    <p style="margin:8px 0 0;font-size:11px;color:${LIME_DARK};letter-spacing:.05em;text-transform:uppercase;font-weight:600">${healthyCount} boat${healthyCount!==1?'s':''} healthy</p>
    <p style="margin:6px 0 0;font-size:18px;font-weight:600;color:${FOREST}">Healthy Fleet</p>
    <p style="margin:8px 0 14px;font-size:11px;color:${dim.ink2};line-height:1.5">A curated list of boats with zero issues this month: ${healthyNames}${healthyRest}.</p>
    <button onclick="nav(document.querySelector('[data-view=fl-boatstatus]'))" style="background:${FOREST};color:white;border:none;border-radius:18px;padding:9px 20px;font-size:12px;font-weight:600;cursor:pointer;width:100%">View all healthy boats</button>
  </div>`;
  
  // Build upcoming card (Scheduling pattern)
  let upcomingCard = '';
  if(typeof flEngHours==='function' && FL_ENGINES){
    const upcomingList = [];
    FL_ENGINES.forEach(e=>{
      if(!e.serviceInterval || !e.boatId) return;
      const _ss=flEngServiceState(e);
      const hoursUntil=_ss.left;   // relative to the last logged service (oil change), not pure modulo
      if(hoursUntil!=null && hoursUntil <= e.serviceInterval * 0.2){   // within 20% of interval OR overdue (negative)
        const b = boats.find(x=>x.id===e.boatId);
        if(b) upcomingList.push({b, hoursUntil, interval: e.serviceInterval, engine: e});
      }
    });
    upcomingList.sort((a,b)=>a.hoursUntil-b.hoursUntil);
    
    if(upcomingList.length > 0){
      const top = upcomingList[0];
      const tbColor = boatAvatarColor(top.b);
      const tbInit = boatInitials(top.b.name);
      upcomingCard = `<div style="background:white;border-radius:24px;padding:22px 24px">
        <div style="display:flex;align-items:start;justify-content:space-between;margin-bottom:14px">
          <div>
            <p style="margin:0;font-size:15px;font-weight:600;color:${dim.ink}">Upcoming</p>
            <p style="margin:4px 0 0;font-size:11px;color:${dim.ink2};line-height:1.4">${upcomingList.length} service${upcomingList.length>1?'s':''} need scheduling this week</p>
          </div>
          <div style="text-align:right">
            <p style="margin:0;font-size:9px;color:${top.hoursUntil<0?'#A32D2D':'#854F0B'};letter-spacing:.1em;font-weight:600">${top.hoursUntil<0?'OVERDUE':'SOON'}</p>
            <p style="margin:3px 0 0;font-size:20px;font-weight:700;color:${top.hoursUntil<0?'#A32D2D':dim.ink}">${top.hoursUntil<0?('+'+Math.abs(top.hoursUntil).toFixed(0)):top.hoursUntil.toFixed(0)}hr</p>
          </div>
        </div>
        <div style="background:linear-gradient(135deg,${LIME_SOFT} 0%,${LIME} 100%);border-radius:14px;padding:24px 16px;text-align:center;margin-bottom:14px">
          <div style="display:inline-flex;width:50px;height:50px;border-radius:50%;background:${FOREST};color:${LIME};align-items:center;justify-content:center;font-size:13px;font-weight:700;letter-spacing:.5px;margin-bottom:8px">${tbInit}</div>
          <p style="margin:6px 0 0;font-size:14px;font-weight:600;color:${FOREST}">${top.b.name} · Engine service</p>
          <p style="margin:4px 0 0;font-size:11px;color:${LIME_DARK}">${top.hoursUntil<0?('overdue by ~'+Math.abs(top.hoursUntil).toFixed(0)+'hr'):('~'+top.hoursUntil.toFixed(0)+'hr until next service')} (${top.interval}hr interval)</p>
        </div>
        <div style="text-align:center"><a onclick="flGoToAsset('boats','${top.b.id}')" style="color:${FOREST};font-size:13px;font-weight:600;cursor:pointer;text-decoration:none">Mark this service →</a></div>
      </div>`;
    }
  }
  if(!upcomingCard){
    // Fallback if no upcoming services
    upcomingCard = `<div style="background:white;border-radius:24px;padding:22px 24px">
      <p style="margin:0;font-size:15px;font-weight:600;color:${dim.ink}">Upcoming</p>
      <p style="margin:4px 0 0;font-size:11px;color:${dim.ink2};line-height:1.4">No services scheduled in the near term</p>
      <div style="background:${LIME_SOFT};border-radius:14px;padding:24px 16px;text-align:center;margin-top:14px">
        <p style="margin:0;font-size:13px;color:${FOREST};font-weight:600">All engines within service interval ✓</p>
      </div>
    </div>`;
  }

  // Count approved memos in period for context caption
  const approvedMemosInPeriod = allMemos.filter(mo => 
    mo.createdDate && inPeriod(mo.createdDate) && APPROVED_STATUSES.includes(mo.status)
  );
  const supplierCaption = approvedMemosInPeriod.length > 0
    ? `${approvedMemosInPeriod.length} approved memo${approvedMemosInPeriod.length>1?'s':''} · ${supplierRows.length} supplier${supplierRows.length>1?'s':''}`
    : `No approved memos in ${periodLabel.toLowerCase()}`;

  const chartsPanel = `${costTrendCard}
  <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;margin-bottom:16px">
    ${incidentsCard}
    ${chartCard('Cost by supplier', supplierBars + `<p style="margin:14px 0 0;font-size:11px;color:${dim.ink3};line-height:1.5">${supplierCaption}</p>`)}
    ${winsIllustrationCard}
  </div>
  <div style="display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin-bottom:16px">
    ${chartCard('Cost by job type', typeBars + (typeCaption ? `<p style="margin:16px 0 0;font-size:11px;color:${dim.ink2};line-height:1.5">${typeCaption}</p>` : ''))}
    ${upcomingCard}
  </div>`;

  // ──────── TIER 4: Smart Recommendations ────────
  const insights = [];
  
  // 💸 AWAITING INVOICES — Closed MJs flagged "awaiting invoice" only (semantic = "รอใบบิล")
  if(FL_MAINT && FL_MEMOS){
    const awaitingItems = [];
    
    FL_MAINT.forEach(m => {
      if(m.status !== 'done') return;
      if(!m.awaitingInvoice) return;  // ต้องติ๊ก "รอใบวางบิล" เท่านั้น
      const linkedMemos = FL_MEMOS.filter(memo => memo.maintId === m.id);
      if(linkedMemos.length > 0) return;  // ถ้ามี memo แล้ว → ออกจาก list
      
      const boat = boats.find(b=>b.id===m.boatId);
      const closeDate = m.endDate ? new Date(m.endDate) : new Date();
      const daysSince = Math.floor((new Date(TODAY_STR) - closeDate) / 86400000);
      awaitingItems.push({
        mj: m, boat, type:'no_memo',
        amt: 0, daysSince, memoCount: 0, supplier: ''
      });
    });
    
    if(awaitingItems.length > 0){
      awaitingItems.sort((a,b)=>b.daysSince-a.daysSince);
      const top = awaitingItems[0];
      
      insights.push({
        icon:'urgent', color:'#9F1B4F', bg:'#FCE6EF',
        title: 'Awaiting Invoice',
        subtitle: `${awaitingItems.length} closed jobs · no memo yet`,
        detail: `${top.mj.no} · ${top.boat?.name||'?'} · ${top.daysSince} days ago`,
        cta: 'Manage memos',
        ctaLink: 'View jobs →',
        statLabel: 'WAITING',
        stat: `${awaitingItems.length}`,
        type: 'unpaid_invoices',
        meta: { items: awaitingItems.slice(0,5), total: 0, count: awaitingItems.length, type:'unpaid_invoices' },
        metaLine: `${awaitingItems.length} jobs · no memo yet`,
        priority: 1
      });
    }
  }

  // ⏰ UPCOMING — Engines approaching service interval
  if(typeof flEngHours==='function' && FL_ENGINES){
    const upcomingService = [];
    FL_ENGINES.forEach(e=>{
      if(!e.serviceInterval || !e.boatId) return;
      const curH = flEngHours(e.id) || (e.baseHours || 0);
      const remainder = curH % e.serviceInterval;
      const hoursUntil = e.serviceInterval - remainder;
      if(hoursUntil <= e.serviceInterval * 0.2 && hoursUntil > 0){
        const b = boats.find(x=>x.id===e.boatId);
        upcomingService.push({
          boatObj: b,
          boatName: b ? b.name : '?',
          engineSerial: e.serial,
          engineModel: e.model || '',
          hoursUntil: Math.round(hoursUntil),
          currentHours: Math.round(curH),
          interval: e.serviceInterval
        });
      }
    });
    if(upcomingService.length > 0){
      const byBoat = {};
      upcomingService.forEach(u=>{ if(!byBoat[u.boatName]) byBoat[u.boatName]=[]; byBoat[u.boatName].push(u); });
      const topBoats = Object.entries(byBoat).slice(0,2);
      topBoats.forEach(([boatName, list])=>{
        const minHr = Math.min(...list.map(u=>u.hoursUntil));
        const top = list.find(u=>u.hoursUntil===minHr);
        insights.push({
          icon:'clock', color:'#185FA5', bg:'#E6F1FB',
          title: 'Engine service',
          subtitle: `${boatName} ใกล้ครบ service${list.length>1?` (${list.length} เครื่อง)`:''}`,
          detail:`เหลือ ~${minHr}hr ก่อนถึงรอบ ${list[0].interval}hr · ${list.map(u=>u.engineSerial).slice(0,2).join(', ')}${list.length>2?'...':''}`,
          stat: `${minHr} hr`,
          statLabel: 'SOON',
          meta: { type:'upcoming', boat: top.boatObj, hoursUntil: minHr, currentHours: top.currentHours, interval: top.interval, engineModel: top.engineModel },
          category: 'Upcoming',
          metaLine: `${list[0].interval}hr interval`,
          ctaLink: 'Schedule →'
        });
      });
    }
  }

  // 📄 BOAT DOCS — expiring or expired licenses/certificates
  if(boats && boats.length > 0){
    const docAlerts = [];
    boats.forEach(b => {
      if(b.retired || b.ownership==='charter') return;
      if(!b.docs || !Array.isArray(b.docs)) return;
      b.docs.forEach(d => {
        if(!d.exp) return;
        const expD = new Date(d.exp);
        if(isNaN(expD.getTime())) return;
        const daysUntil = Math.floor((expD - todayD) / 86400000);
        let severity = null;
        if(daysUntil < 0) severity = 'expired';
        else if(daysUntil <= 14) severity = 'critical';
        else if(daysUntil <= 60) severity = 'warning';
        else return;
        docAlerts.push({boat: b, doc: d, daysUntil, severity});
      });
    });
    if(docAlerts.length > 0){
      docAlerts.sort((a,b) => a.daysUntil - b.daysUntil);
      const expired = docAlerts.filter(a => a.severity==='expired').length;
      const critical = docAlerts.filter(a => a.severity==='critical').length;
      const warning = docAlerts.filter(a => a.severity==='warning').length;
      const top = docAlerts[0];
      const isUrgent = expired > 0 || critical > 0;
      const color = expired>0?'#A32D2D':critical>0?'#854F0B':'#185FA5';
      const bg = expired>0?'#FBE9E9':critical>0?'#FAEEDA':'#E6F1FB';
      const statLabel = expired>0?'EXPIRED':critical>0?'≤14d':'≤60d';
      const title = expired>0?'Documents expired':critical>0?'Documents expiring soon':'Documents upcoming';
      const topLabel = top.daysUntil<0 ? `หมดอายุแล้ว ${Math.abs(top.daysUntil)}d` :
                       top.daysUntil===0 ? 'วันนี้' :
                       `เหลือ ${top.daysUntil}d`;
      const breakdown = [
        expired ? `${expired} expired` : '',
        critical ? `${critical} ≤14d` : '',
        warning ? `${warning} ≤60d` : ''
      ].filter(Boolean).join(' · ');
      insights.push({
        icon: 'docs',
        color, bg,
        title,
        subtitle: `${docAlerts.length} เอกสารต้องต่ออายุ`,
        detail: `${top.boat.name} · ${top.doc.name} · ${topLabel}${docAlerts.length>1?` · +${docAlerts.length-1} อื่น`:''}`,
        stat: `${docAlerts.length}`,
        statLabel,
        meta: { type:'docs', items: docAlerts.slice(0,5), count: docAlerts.length, expired, critical, warning },
        category: 'Documents',
        metaLine: breakdown,
        ctaLink: 'View boats →',
        priority: isUrgent ? 0 : 2
      });
    }
  }

  // 📊 AVG TIME TO CLOSE — comparison with previous period
  const closedJobs = allJobs.filter(j=>j.status==='done' && j.startDate && j.endDate);
  if(closedJobs.length >= 3){
    const calcDays = (j) => Math.floor((new Date(j.endDate) - new Date(j.startDate))/86400000);
    const recentClosed = closedJobs.filter(j=>inPeriod(j.endDate));
    const oldClosed = closedJobs.filter(j=>!inPeriod(j.endDate));
    if(recentClosed.length > 0){
      const avgRecent = recentClosed.reduce((s,j)=>s+calcDays(j),0)/recentClosed.length;
      const avgOld = oldClosed.length>0 ? oldClosed.reduce((s,j)=>s+calcDays(j),0)/oldClosed.length : null;
      const isImproved = avgOld!==null && avgRecent < avgOld;
      const trend = avgOld!==null ? (avgRecent < avgOld ? '↓ improved' : avgRecent > avgOld ? '↑ slower' : '→ same') : '';
      const pctChange = avgOld!==null ? Math.round(Math.abs((avgRecent - avgOld) / avgOld) * 100) : 0;
      insights.push({
        icon:'chart_bar', color: isImproved ? '#0F6E56' : '#185FA5', 
        bg: isImproved ? '#E6F4ED' : '#E6F1FB',
        title:'Closing speed',
        subtitle: 'ปิดงานเร็ว/ช้า',
        detail: avgOld!==null
          ? `${recentClosed.length} jobs ปิดใน ${periodLabel.toLowerCase()} · ก่อนหน้านี้ ${Math.round(avgOld)} d · ${trend}`
          : `${recentClosed.length} jobs ปิดใน ${periodLabel.toLowerCase()}`,
        stat: `${Math.round(avgRecent)} d`,
        statLabel: isImproved ? `↓ ${pctChange}%` : avgOld!==null ? `↑ ${pctChange}%` : '',
        meta: { type:'avg_close', avgRecent: Math.round(avgRecent), avgOld: avgOld!==null ? Math.round(avgOld) : null, count: recentClosed.length, isImproved },
        category: 'Improvement',
        metaLine: `based on ${recentClosed.length} jobs`,
        ctaLink: 'View details →'
      });
    }
  }

  // ✓ MEMO APPROVAL RATE
  if(allMemos.length >= 3){
    const totalMemos = allMemos.length;
    const approvedOrAbove = allMemos.filter(m=>['approved','ordered','received','paid'].includes(m.status)).length;
    const pendingCnt = allMemos.filter(m=>m.status==='pending_approval').length;
    const approvalRate = Math.round((approvedOrAbove/totalMemos)*100);
    insights.push({
      icon:'trend_up', color: approvalRate>=80?'#0F6E56':approvalRate>=50?'#854F0B':'#A32D2D',
      bg: approvalRate>=80?'#E6F4ED':approvalRate>=50?'#FAEEDA':'#FBE9E9',
      title:'Approval rate',
      subtitle: 'Memo workflow',
      detail:`${approvedOrAbove}/${totalMemos} memos approved${pendingCnt>0?` · ${pendingCnt} ยังรออนุมัติ`:' · ครบทุกใบ'}`,
      stat: `${approvalRate}%`,
      statLabel: approvalRate>=80 ? 'EXCELLENT' : approvalRate>=50 ? 'OK' : 'LOW',
      meta: { type:'approval_rate', rate: approvalRate, approved: approvedOrAbove, total: totalMemos, pending: pendingCnt },
      category: 'Approval rate',
      metaLine: pendingCnt>0 ? `${pendingCnt} pending` : 'ครบทุกใบ',
      ctaLink: 'View memos →'
    });
  }

  // 💡 Pattern: boats with 2+ incidents
  Object.values(boatStats).filter(s=>s.incidents>=2).forEach(s=>{
    const b = boats.find(x=>x.id===s.id);
    // Get incident dates for this boat
    const boatIncs = allIncs.filter(i=>i.boatId===s.id && inPeriod(i.date)).slice(0,5);
    insights.push({
      icon:'pattern', color:'#185FA5', bg:'#E6F1FB',
      title:'Recurring incidents',
      subtitle: 'ทบทวน operating',
      detail:`${s.name} มี ${s.incidents} incidents · เกิดในช่วง ${periodLabel.toLowerCase()} — ทบทวน operating conditions`,
      stat: `${s.incidents}x`,
      statLabel: 'PATTERN',
      meta: { type:'pattern', boat: b, incidentCount: s.incidents, incidentDates: boatIncs.map(i=>i.date) },
      category: 'Pattern',
      metaLine: boatIncs.length>0 ? boatIncs.map(i=>i.title || '?').slice(0,2).join(' · ') : `${s.incidents} incidents`,
      ctaLink: 'View incidents →'
    });
  });

  // 🚨 Urgent: long-running jobs
  const longRunning = allJobs.filter(j=>{
    if(j.status!=='inprogress' || !j.startDate) return false;
    return Math.floor((todayD - new Date(j.startDate)) / 86400000) >= 14;
  });
  longRunning.forEach(j=>{
    const days = Math.floor((todayD - new Date(j.startDate)) / 86400000);
    const b = boats.find(x=>x.id===j.boatId);
    insights.push({
      icon:'urgent', color:'#A32D2D', bg:'#FBE9E9',
      title:'Long-running job',
      subtitle: `${j.no} ยังไม่ปิด · เกินค่าเฉลี่ย`,
      detail:`${b?b.name:'?'} — ${j.title}`,
      stat: `${days} d`,
      statLabel: 'URGENT',
      meta: { type:'urgent', boat: b, job: j, days, jobTitle: j.title, location: j.location || j.atShop || '' },
      category: 'Urgent',
      metaLine: `เปิด ${j.startDate.slice(5).split('-').reverse().join('/')}`,
      ctaLink: 'View job →'
    });
  });

  // 💸 Cost concentration
  if(boatRows.length>0 && boatRows[0].cost > periodSpent*0.5 && periodSpent > 0){
    const topBoat = boats.find(x=>x.id===boatRows[0].id);
    const pct = Math.round(boatRows[0].cost/periodSpent*100);
    insights.push({
      icon:'cost', color:'#854F0B', bg:'#FAEEDA',
      title:'Cost concentration',
      subtitle: 'เรือเดียวกินงบเดือนนี้',
      detail:`${boatRows[0].name} ใช้เงิน ${pct}% · ${fmtFull(boatRows[0].cost)} จากทั้งหมด ${fmtFull(periodSpent)}`,
      stat: fmtShort(boatRows[0].cost),
      statLabel: `${pct}%`,
      meta: { type:'cost', boat: topBoat, boatName: boatRows[0].name, cost: boatRows[0].cost, total: periodSpent, pct },
      category: 'Cost concentration',
      metaLine: `Fire recovery · ongoing`,
      ctaLink: 'View boat →'
    });
  }

  // 📋 Pending memos
  if(memosPending.length>0){
    insights.push({
      icon:'memo', color:'#854F0B', bg:'#FAEEDA',
      title:'Pending approvals',
      subtitle: 'รออนุมัติ',
      detail:`${memosPending.length} memos รออนุมัติ · รวม ${fmtShort(memosPendingAmt)}`,
      stat: `${memosPending.length}`,
      statLabel: fmtShort(memosPendingAmt),
      meta: { type:'memo', count: memosPending.length, amount: memosPendingAmt, memos: memosPending.slice(0,3).map(m=>m.no) },
      category: 'Pending action',
      metaLine: memosPending.slice(0,3).map(m=>m.no).join(', '),
      ctaLink: 'View memos →'
    });
  }

  // ✅ Healthy boats
  const healthyBoats = Object.values(boatStats).filter(s=>s.jobs===0 && s.curStatus==='available');
  if(healthyBoats.length>0){
    insights.push({
      icon:'check', color:'#0F6E56', bg:'#E6F4ED',
      title:'Healthy fleet',
      subtitle: 'No issues this month',
      detail:`${healthyBoats.length} เรือ healthy · ${healthyBoats.slice(0,5).map(s=>s.name).join(', ')}${healthyBoats.length>5?`, +${healthyBoats.length-5} more`:''}`,
      stat: `${healthyBoats.length}`,
      statLabel: 'HEALTHY',
      meta: { type:'wins', count: healthyBoats.length, boats: healthyBoats.slice(0,3).map(s=>{ const b = boats.find(x=>x.id===s.id); return b ? boatAvatarColor(b) : '#185FA5'; }) },
      category: 'Wins',
      metaLine: `${healthyBoats.length} boats`,
      ctaLink: 'View all →'
    });
  }

  if(insights.length===0){
    insights.push({
      icon:'sparkle', color:'#0F6E56', bg:'#E6F4ED',
      title:'ระบบราบรื่น',
      subtitle: 'ไม่มีจุดที่ต้องสังเกต',
      detail:'ทุกเรือมีสถานะปกติ · ไม่มี long-running jobs · ไม่มี cost spike',
      stat: '✓',
      statLabel: 'ALL CLEAR',
      meta: { type:'all_clear' },
      category: 'Status',
      metaLine: 'ระบบราบรื่น',
      ctaLink: 'View dashboard →'
    });
  }

  // Categorize insights by icon key
  const urgentInsights = insights.filter(i=>['urgent','cost','docs'].includes(i.icon));
  const upcomingInsights = insights.filter(i=>['clock'].includes(i.icon));
  const patternInsights = insights.filter(i=>['pattern','chart_bar','trend_up','memo'].includes(i.icon));
  const winInsights = insights.filter(i=>['check','sparkle'].includes(i.icon));

  // Premium insight card (compact)
  const insightCard = (i) => `<div style="background:#FBFAF7;border-radius:12px;padding:14px 16px;border-left:3px solid ${i.color};display:flex;gap:11px;align-items:flex-start">
    <div style="width:30px;height:30px;border-radius:50%;background:${i.bg};color:${i.color};display:flex;align-items:center;justify-content:center;flex-shrink:0">${insightIcon(i.icon, 15)}</div>
    <div style="flex:1;min-width:0">
      <p style="margin:0;font-size:10px;color:${i.color};font-weight:600;letter-spacing:.05em;text-transform:uppercase">${i.category||'Insight'}</p>
      <p style="margin:3px 0 0;font-size:13px;font-weight:600;color:${dim.ink};line-height:1.3">${i.title}</p>
      <p style="margin:3px 0 0;font-size:10px;color:${dim.ink3};line-height:1.4">${i.detail}</p>
    </div>
  </div>`;

  // Hero urgent card (forest green)
  const heroUrgentCard = (i) => `<div style="background:${FOREST};color:white;border-radius:14px;padding:18px 20px;margin-bottom:14px;position:relative;overflow:hidden">
    <div style="display:flex;align-items:start;gap:14px">
      <div style="width:36px;height:36px;border-radius:50%;background:rgba(200,244,124,.15);color:${LIME};display:flex;align-items:center;justify-content:center;flex-shrink:0">${insightIcon(i.icon, 16)}</div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;flex-wrap:wrap">
          <span style="background:${LIME};color:${FOREST};padding:2px 8px;border-radius:10px;font-size:9px;font-weight:700;letter-spacing:.05em">URGENT</span>
          <span style="font-size:10px;color:#9BB89B">${urgentInsights.length} item${urgentInsights.length>1?'s':''} need${urgentInsights.length===1?'s':''} attention</span>
        </div>
        <p style="margin:6px 0 4px;font-size:15px;font-weight:600;color:white;line-height:1.3">${i.title}</p>
        <p style="margin:0;font-size:12px;color:#B8D4B8;line-height:1.4">${i.detail}</p>
      </div>
      <button onclick="document.getElementById('fl-insights-recs')?.scrollIntoView({behavior:'smooth'})" style="background:${LIME};color:${FOREST};border:none;border-radius:14px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer;align-self:center;flex-shrink:0">View all</button>
    </div>
  </div>`;

  // Annotate insights with category labels
  urgentInsights.forEach(i=>{ i.category = i.icon==='cost' ? 'Cost concentration' : i.icon==='docs' ? 'Documents' : 'Urgent'; });
  upcomingInsights.forEach(i=>{ i.category = 'Upcoming'; });
  patternInsights.forEach(i=>{
    if(i.icon==='chart_bar') i.category = 'Improvement';
    else if(i.icon==='trend_up') i.category = 'Approval rate';
    else if(i.icon==='memo') i.category = 'Pending action';
    else i.category = 'Pattern';
  });

  // Wins card (lime soft, full-width)
  const winsCard = winInsights.length > 0 ? `<div style="background:${LIME_SOFT};border-radius:14px;padding:16px 20px;border:1px solid #C8E29A;display:flex;align-items:center;gap:14px">
    <div style="width:40px;height:40px;border-radius:50%;background:${FOREST};color:${LIME};display:flex;align-items:center;justify-content:center;flex-shrink:0">${insightIcon(winInsights[0].icon, 18)}</div>
    <div style="flex:1;min-width:0">
      <p style="margin:0;font-size:10px;color:${LIME_DARK};font-weight:600;letter-spacing:.05em;text-transform:uppercase">Wins</p>
      <p style="margin:3px 0 0;font-size:15px;font-weight:600;color:${FOREST};line-height:1.3">${winInsights[0].title}</p>
      <p style="margin:3px 0 0;font-size:11px;color:#5A7A3A;line-height:1.4">${winInsights[0].detail}</p>
    </div>
    ${winInsights.length > 1 ? `<span style="background:white;color:${FOREST};padding:4px 10px;border-radius:10px;font-size:10px;font-weight:600">+${winInsights.length - 1} more</span>` : ''}
  </div>` : '';

  // Non-urgent compact insights (upcoming + patterns)
  const compactInsights = [...upcomingInsights, ...patternInsights];
  // Use 2nd+ urgent as compact if there are multiple
  const secondaryUrgent = urgentInsights.slice(1);
  const allCompact = [...secondaryUrgent, ...compactInsights];

  // ════ Hero visuals — each insight type gets a custom illustration (compact) ════
  const heroVisual = (i) => {
    const m = i.meta || {};
    const bgGrad = {
      urgent:`linear-gradient(135deg,#FBE9E9 0%,#F5C8C8 100%)`,
      cost:`linear-gradient(135deg,#FAEEDA 0%,#F0D9A8 100%)`,
      unpaid_invoices:`linear-gradient(135deg,#FCE6EF 0%,#F5BCD2 100%)`,
      pattern:`linear-gradient(135deg,#E6F1FB 0%,#C8DDF0 100%)`,
      upcoming:`linear-gradient(135deg,${LIME_SOFT} 0%,${LIME} 100%)`,
      avg_close:`linear-gradient(135deg,#E6F4ED 0%,#A8D6BD 100%)`,
      approval_rate:`linear-gradient(135deg,#E6F4ED 0%,#A8D6BD 100%)`,
      memo:`linear-gradient(135deg,#FAEEDA 0%,#F0D9A8 100%)`,
      docs:`linear-gradient(135deg,#FBE9E9 0%,#F0D5D5 100%)`,
      wins:`linear-gradient(135deg,${LIME_SOFT} 0%,${LIME} 100%)`,
      all_clear:`linear-gradient(135deg,${LIME_SOFT} 0%,${LIME} 100%)`
    }[m.type] || `linear-gradient(135deg,${dim.bg} 0%,#E5DFD3 100%)`;

    // Unpaid invoices — show money icon + amount
    if(m.type === 'unpaid_invoices'){
      const amt = m.total || 0;
      const cntBadge = m.count || 0;
      const showAmt = amt > 0;
      return `<div style="background:${bgGrad};border-radius:10px;padding:18px 12px;text-align:center;margin:10px 0;position:relative;overflow:hidden;min-height:90px">
        <div style="display:inline-flex;width:44px;height:44px;border-radius:50%;background:#9F1B4F;color:white;align-items:center;justify-content:center;font-size:20px;box-shadow:0 3px 8px rgba(159,27,79,.25)">📋</div>
        <p style="margin:6px 0 0;font-size:13px;font-weight:700;color:#9F1B4F">${showAmt ? '฿' + Math.round(amt/1000) + 'k' : cntBadge + ' jobs'}</p>
        <p style="margin:2px 0 0;font-size:9px;font-weight:500;color:#9F1B4F;opacity:.7">awaiting invoice</p>
        <div style="position:absolute;top:6px;right:6px;background:#9F1B4F;color:white;padding:2px 6px;border-radius:6px;font-size:8px;font-weight:700;font-family:'DM Mono',monospace">${cntBadge}</div>
      </div>`;
    }

    if(m.type === 'urgent' && m.boat){
      const c = boatAvatarColor(m.boat);
      const init = boatInitials(m.boat.name);
      return `<div style="background:${bgGrad};border-radius:10px;padding:18px 12px;text-align:center;margin:10px 0;position:relative;overflow:hidden;min-height:90px">
        <div style="display:inline-flex;width:42px;height:42px;border-radius:50%;background:${c};color:white;align-items:center;justify-content:center;font-size:11px;font-weight:700;letter-spacing:.5px;box-shadow:0 3px 8px rgba(0,0,0,.15)">${init}</div>
        <p style="margin:6px 0 0;font-size:11px;font-weight:600;color:${dim.ink};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${m.boat.name}</p>
        <div style="position:absolute;top:6px;right:6px;background:#A32D2D;color:white;padding:2px 6px;border-radius:6px;font-size:8px;font-weight:700;font-family:'DM Mono',monospace">${m.days}D</div>
      </div>`;
    }

    if(m.type === 'cost'){
      const pct = m.pct;
      const dash = Math.round((pct / 100) * 88);
      return `<div style="background:${bgGrad};border-radius:10px;padding:14px;text-align:center;margin:10px 0;min-height:90px">
        <div style="position:relative;width:60px;height:60px;margin:0 auto">
          <svg viewBox="0 0 36 36" style="transform:rotate(-90deg)">
            <circle cx="18" cy="18" r="14" fill="none" stroke="rgba(255,255,255,.6)" stroke-width="5"/>
            <circle cx="18" cy="18" r="14" fill="none" stroke="${m.boat ? boatAvatarColor(m.boat) : '#854F0B'}" stroke-width="5" stroke-dasharray="${dash},${88-dash}" stroke-linecap="round"/>
          </svg>
          <div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);text-align:center">
            <p style="margin:0;font-size:14px;font-weight:700;color:#854F0B">${pct}%</p>
          </div>
        </div>
      </div>`;
    }

    if(m.type === 'pattern' && m.boat){
      const c = boatAvatarColor(m.boat);
      const init = boatInitials(m.boat.name);
      const dots = Math.min(m.incidentCount, 5);
      const dotsHtml = Array(dots).fill(0).map((_,idx)=>`<div style="width:6px;height:6px;border-radius:50%;background:#A32D2D"></div>${idx<dots-1?'<div style="width:14px;height:1px;background:#999"></div>':''}`).join('');
      return `<div style="background:${bgGrad};border-radius:10px;padding:14px 10px;text-align:center;margin:10px 0;min-height:90px">
        <div style="display:inline-flex;width:36px;height:36px;border-radius:50%;background:${c};color:white;align-items:center;justify-content:center;font-size:10px;font-weight:700;letter-spacing:.5px">${init}</div>
        <p style="margin:6px 0 0;font-size:11px;font-weight:600;color:${dim.ink};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${m.boat.name}</p>
        <div style="display:flex;align-items:center;justify-content:center;gap:4px;margin-top:6px">${dotsHtml}</div>
      </div>`;
    }

    if(m.type === 'upcoming' && m.boat){
      const init = boatInitials(m.boat.name);
      const usedPct = m.currentHours > 0 ? Math.min(((m.currentHours % m.interval) / m.interval) * 100, 100) : 0;
      return `<div style="background:${bgGrad};border-radius:10px;padding:14px 10px;text-align:center;margin:10px 0;min-height:90px">
        <div style="display:inline-flex;width:36px;height:36px;border-radius:50%;background:${FOREST};color:${LIME};align-items:center;justify-content:center;font-size:10px;font-weight:700;letter-spacing:.5px">${init}</div>
        <p style="margin:6px 0 0;font-size:11px;font-weight:600;color:${FOREST};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${m.boat.name}</p>
        <div style="margin-top:8px;background:rgba(31,77,44,.15);border-radius:4px;height:5px;overflow:hidden">
          <div style="width:${usedPct}%;height:100%;background:${FOREST};border-radius:4px"></div>
        </div>
        <p style="margin:4px 0 0;font-size:8px;color:${LIME_DARK};font-family:'DM Mono',monospace">${m.currentHours % m.interval}/${m.interval}hr</p>
      </div>`;
    }

    if(m.type === 'avg_close'){
      const beforeBar = m.avgOld !== null ? (m.avgOld / Math.max(m.avgOld, m.avgRecent)) * 36 : 36;
      const nowBar = (m.avgRecent / Math.max(m.avgOld || m.avgRecent, m.avgRecent)) * 36;
      return `<div style="background:${bgGrad};border-radius:10px;padding:14px 10px;text-align:center;margin:10px 0;min-height:90px">
        <div style="display:flex;align-items:flex-end;justify-content:center;gap:6px;height:46px;margin-bottom:4px">
          ${m.avgOld !== null ? `<div style="width:14px;height:${beforeBar}px;background:rgba(255,255,255,.6);border-radius:3px 3px 0 0;position:relative"><span style="position:absolute;top:-12px;left:50%;transform:translateX(-50%);font-size:8px;font-weight:600;color:${dim.ink2};font-family:'DM Mono',monospace">${m.avgOld}d</span></div>` : ''}
          <div style="width:14px;height:${nowBar}px;background:${m.isImproved?'#0F6E56':'#185FA5'};border-radius:3px 3px 0 0;position:relative"><span style="position:absolute;top:-12px;left:50%;transform:translateX(-50%);font-size:8px;font-weight:600;color:${FOREST};font-family:'DM Mono',monospace">${m.avgRecent}d</span></div>
        </div>
        <div style="display:flex;justify-content:center;gap:10px;font-size:8px;color:${LIME_DARK};font-weight:600">
          ${m.avgOld !== null ? '<span>Before</span>' : ''}<span>Now</span>
        </div>
      </div>`;
    }

    if(m.type === 'approval_rate'){
      const dash = Math.round((m.rate / 100) * 88);
      const ringColor = m.rate >= 80 ? '#0F6E56' : m.rate >= 50 ? '#854F0B' : '#A32D2D';
      return `<div style="background:${bgGrad};border-radius:10px;padding:14px;text-align:center;margin:10px 0;min-height:90px">
        <div style="position:relative;width:54px;height:54px;margin:0 auto">
          <svg viewBox="0 0 36 36" style="transform:rotate(-90deg)">
            <circle cx="18" cy="18" r="14" fill="none" stroke="rgba(255,255,255,.6)" stroke-width="5"/>
            <circle cx="18" cy="18" r="14" fill="none" stroke="${ringColor}" stroke-width="5" stroke-dasharray="${dash},${88-dash}" stroke-linecap="round"/>
          </svg>
          <div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);text-align:center">
            <p style="margin:0;font-size:10px;font-weight:700;color:${ringColor}">${m.approved}/${m.total}</p>
          </div>
        </div>
      </div>`;
    }

    if(m.type === 'memo'){
      return `<div style="background:${bgGrad};border-radius:10px;padding:14px;text-align:center;margin:10px 0;min-height:90px">
        <div style="display:inline-flex;width:36px;height:36px;border-radius:50%;background:#854F0B;color:white;align-items:center;justify-content:center">${insightIcon('memo', 16, 'white')}</div>
        <p style="margin:6px 0 0;font-size:13px;font-weight:700;color:#854F0B;font-family:'DM Mono',monospace">${m.count}</p>
        <p style="margin:1px 0 0;font-size:9px;color:#854F0B;font-weight:600">${fmtShort(m.amount)}</p>
      </div>`;
    }

    if(m.type === 'wins'){
      const stack = m.boats || ['#185FA5','#0F6E56','#7B2D63'];
      return `<div style="background:${bgGrad};border-radius:10px;padding:14px;text-align:center;margin:10px 0;min-height:90px">
        <div style="position:relative;width:74px;height:54px;margin:0 auto">
          <div style="position:absolute;left:0;top:6px;width:30px;height:42px;border-radius:6px;background:${stack[0]};transform:rotate(-12deg);box-shadow:0 3px 8px rgba(0,0,0,.1)"></div>
          <div style="position:absolute;left:16px;top:3px;width:30px;height:42px;border-radius:6px;background:${stack[1]||stack[0]};box-shadow:0 3px 8px rgba(0,0,0,.1)"></div>
          <div style="position:absolute;left:32px;top:0;width:30px;height:42px;border-radius:6px;background:${stack[2]||stack[0]};transform:rotate(8deg);box-shadow:0 3px 8px rgba(0,0,0,.1)"></div>
          <div style="position:absolute;left:14px;top:14px;width:46px;height:34px;border-radius:6px;background:${LIME};display:flex;align-items:center;justify-content:center;box-shadow:0 4px 12px rgba(31,77,44,.2)">
            <span style="font-size:13px;font-weight:700;color:${FOREST}">${m.count}</span>
          </div>
        </div>
      </div>`;
    }

    if(m.type === 'all_clear'){
      return `<div style="background:${bgGrad};border-radius:10px;padding:20px 14px;text-align:center;margin:10px 0;min-height:90px">
        <div style="display:inline-flex;width:36px;height:36px;border-radius:50%;background:${FOREST};color:${LIME};align-items:center;justify-content:center">${insightIcon('sparkle', 16)}</div>
      </div>`;
    }

    // Fallback
    return `<div style="background:${bgGrad};border-radius:10px;padding:20px 14px;text-align:center;margin:10px 0;min-height:90px">
      <div style="display:inline-flex;width:36px;height:36px;border-radius:50%;background:${i.color};color:white;align-items:center;justify-content:center">${insightIcon(i.icon, 16, 'white')}</div>
    </div>`;
  };

  // Scheduling-style recommendation card (compact, fixed size)
  const recCard = (i) => {
    const statColor = i.color;
    // Determine click action based on meta.type
    let onclickAttr = '';
    let cursorStyle = '';
    if(i.meta){
      const t = i.meta.type;
      if(t === 'urgent' && i.meta.job){
        // Long-running job → go to job detail
        onclickAttr = `onclick="flGoToMaint('${i.meta.job.id}')"`;
        cursorStyle = 'cursor:pointer';
      } else if(t === 'cost' && i.meta.boat){
        onclickAttr = `onclick="flGoToAsset('boats','${i.meta.boat.id}')"`;
        cursorStyle = 'cursor:pointer';
      } else if(t === 'pattern_incidents' && i.meta.boat){
        onclickAttr = `onclick="flGoToAsset('boats','${i.meta.boat.id}')"`;
        cursorStyle = 'cursor:pointer';
      } else if(t === 'upcoming' && i.meta.boat){
        onclickAttr = `onclick="flGoToAsset('boats','${i.meta.boat.id}')"`;
        cursorStyle = 'cursor:pointer';
      } else if(t === 'unpaid_invoices'){
        // Go to maintenance tab · awaiting filter
        onclickAttr = `onclick="flGoToAwaitingInvoice()"`;
        cursorStyle = 'cursor:pointer';
      } else if(t === 'approval_rate' || t === 'memo'){
        // Go to memorandum tab
        onclickAttr = `onclick="flGoToMemoTab()"`;
        cursorStyle = 'cursor:pointer';
      } else if(t === 'avg_close' || t === 'wins'){
        onclickAttr = `onclick="flGoToMaintTab()"`;
        cursorStyle = 'cursor:pointer';
      }
    }
    return `<div ${onclickAttr} style="background:white;border-radius:18px;padding:16px 16px 12px;display:flex;flex-direction:column;box-sizing:border-box;min-height:260px;${cursorStyle};transition:transform .15s, box-shadow .15s" ${cursorStyle?`onmouseover="this.style.transform='translateY(-2px)';this.style.boxShadow='0 4px 12px rgba(0,0,0,.08)'" onmouseout="this.style.transform='';this.style.boxShadow=''"`:''}>
      <div style="display:flex;align-items:start;justify-content:space-between;margin-bottom:4px;gap:8px;min-height:36px">
        <div style="flex:1;min-width:0">
          <p style="margin:0;font-size:12px;font-weight:600;color:${dim.ink};line-height:1.2;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${i.title}</p>
          <p style="margin:3px 0 0;font-size:10px;color:${dim.ink2};line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${i.subtitle || ''}</p>
        </div>
        <div style="text-align:right;flex-shrink:0">
          <p style="margin:0;font-size:8px;color:${statColor};letter-spacing:.08em;font-weight:600">${i.statLabel || ''}</p>
          <p style="margin:2px 0 0;font-size:15px;font-weight:700;color:${dim.ink};line-height:1;font-family:'DM Mono',monospace">${i.stat || ''}</p>
        </div>
      </div>
      ${heroVisual(i)}
      <div style="flex:1;display:flex;flex-direction:column;justify-content:flex-end">
        <p style="margin:0 0 3px;font-size:10px;font-weight:600;color:${dim.ink};text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${i.detail.split('·')[0].trim()}</p>
        <p style="margin:0 0 10px;font-size:9px;color:${dim.ink2};text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${i.metaLine || ''}</p>
        <div style="text-align:center;padding-top:6px;border-top:1px solid #f1eee8"><a style="color:${FOREST};font-size:11px;font-weight:600;cursor:pointer;text-decoration:none">${i.ctaLink || 'View →'}</a></div>
      </div>
    </div>`;
  };

  // All insights split into groups (keep existing card design)
  const allRecs = [...urgentInsights, ...upcomingInsights, ...patternInsights];

  // Render section header with count
  const sectionHeader = (label, count, color, subtitle) => `
    <div style="display:flex;align-items:center;gap:8px;margin:18px 0 10px;padding:0 4px">
      <div style="width:6px;height:6px;border-radius:50%;background:${color};flex-shrink:0"></div>
      <p style="margin:0;font-size:11px;font-weight:600;color:${color};text-transform:uppercase;letter-spacing:.05em">${label} <span style="opacity:.6">· ${count}</span></p>
      <p style="margin:0;font-size:10px;color:${dim.ink3};flex:1">${subtitle}</p>
    </div>`;

  const recommendationsPanel = allRecs.length > 0 ? `<div id="fl-insights-recs">
    <div style="display:flex;align-items:start;justify-content:space-between;margin-bottom:6px;padding:0 4px">
      <p style="margin:0;font-size:16px;font-weight:600;color:${dim.ink}">Smart Recommendations</p>
      <button style="background:${FOREST};color:white;border:none;border-radius:16px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer">Generate report</button>
    </div>
    ${urgentInsights.length > 0 ? sectionHeader('Urgent', urgentInsights.length, '#A32D2D', 'รีบจัดการ') + 
      `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px">${urgentInsights.map(recCard).join('')}</div>` : ''}
    ${upcomingInsights.length > 0 ? sectionHeader('Upcoming', upcomingInsights.length, '#854F0B', 'เตรียมตัว') + 
      `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px">${upcomingInsights.map(recCard).join('')}</div>` : ''}
    ${patternInsights.length > 0 ? sectionHeader('Patterns & Wins', patternInsights.length, '#0F6E56', 'ทบทวน · ทำต่อ') + 
      `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px">${patternInsights.map(recCard).join('')}</div>` : ''}
  </div>` : '';

  // ──────── AI SUGGESTION BANNER (auto-selected top insight) ────────
  let topInsight = null;
  if(urgentInsights.length > 0) topInsight = urgentInsights[0];
  else if(upcomingInsights.length > 0) topInsight = upcomingInsights[0];
  else if(patternInsights.length > 0) topInsight = patternInsights[0];
  const aiSuggestionBanner = topInsight ? `<div style="background:#1F1F1F;color:white;border-radius:14px;padding:12px 16px;margin-bottom:14px;display:flex;align-items:center;gap:14px;flex-wrap:wrap">
    <span style="color:${LIME};font-size:14px;flex-shrink:0">◆</span>
    <span style="font-size:11px;color:${LIME};font-weight:600;flex-shrink:0;letter-spacing:.05em;text-transform:uppercase">AI Suggestion</span>
    <span style="font-size:12px;color:#D8D5C8;flex:1;min-width:200px;line-height:1.4"><strong style="color:white">${topInsight.title}</strong> · ${topInsight.detail}</span>
    <button onclick="document.getElementById('fl-insights-recs')?.scrollIntoView({behavior:'smooth'})" style="background:${LIME};color:${FOREST};border:none;border-radius:14px;padding:5px 14px;font-size:11px;font-weight:600;cursor:pointer">View all</button>
  </div>` : '';

  wrap.innerHTML = `${headerBar}${kpiStrip}${pillRow}${aiSuggestionBanner}${scorecardPanel}${chartsPanel}${recommendationsPanel}`;
}

// Progress-timeline inner HTML (shared by full render + surgical refresh on withdraw/remove)
function _flMaintTimelineInner(m){
  const dim={ink3:'#999'};
  const SVG_PINK={accent:'#E03B7E'};
  const log=m.progressLog||[];
  return log.length?[...log].reverse().map((l,i,arr)=>{
    const isLast=i===arr.length-1;
    const isFirst=i===0;
    return`<div style="display:flex;gap:10px;${isLast?'':'margin-bottom:10px'};position:relative">
      ${!isLast?`<div style="position:absolute;left:3.5px;top:11px;bottom:-10px;width:1px;background:rgba(0,0,0,.08)"></div>`:''}
      <div style="width:8px;height:8px;border-radius:50%;background:${isFirst?SVG_PINK.accent:'#1D9E75'};flex-shrink:0;margin-top:3px;z-index:1"></div>
      <div style="flex:1;min-width:0">
        <div style="font-size:11px;font-weight:500">${l.text||''}</div>
        <div style="font-size:9px;color:${dim.ink3};margin-top:1px;font-family:'DM Mono',monospace">${l.date||''}${l.by?' · '+l.by:''}</div>
      </div>
    </div>`;
  }).join(''):`<div style="font-size:11px;color:${dim.ink3};text-align:center;padding:14px">No progress logged</div>`;
}
// Parts-withdrawn list + subtotal inner HTML (shared by full render + surgical refresh)
// §mjLateParts · job ที่เปิดโหมดแก้อะไหล่ย้อนหลังอยู่ (ทีละงาน · ปิดเองเมื่อสลับงาน)
var _flMaintLateEdit='';
function flMaintCanEditParts(m){ return !!m && (m.status!=='done' || _flMaintLateEdit===m.id); }
function flMaintLateEditOn(jobId){
  const m=(typeof FL_MAINT!=='undefined'?FL_MAINT:[]).find(x=>x.id===jobId); if(!m) return;
  if(!confirm('งาน '+(m.no||'')+' ปิดไปแล้ว\n\nการเบิก/คืนอะไหล่ตอนนี้จะไปเปลี่ยนต้นทุนของงานที่ปิดแล้ว และหักสต็อกคลังจริง\nทุกรายการจะถูกบันทึกว่าเป็นการแก้ย้อนหลัง\n\nเปิดโหมดแก้ไขย้อนหลัง?')) return;
  _flMaintLateEdit=jobId;
  if(typeof flRenderMaintDetailPink==='function') flRenderMaintDetailPink();
}
function flMaintLateEditOff(){
  _flMaintLateEdit='';
  if(typeof flRenderMaintDetailPink==='function') flRenderMaintDetailPink();
}
function _flMaintPartsInner(m){
  const dim={ink2:'#666',ink3:'#999'};
  const SVG_PINK={text:'#9F1B4F'};
  const parts=m.parts||[];
  const partsTotal=parts.reduce((s,p)=>s+(p.qty||0)*(p.cost||0),0);
  const _partRows=parts.map((p,i)=>({p,i})).sort((a,b)=>{
    const da=a.p.date||'', db=b.p.date||'';
    return da!==db ? (da<db?-1:1) : (a.i-b.i);
  });
  let _partLastDate;
  const partsHtml=parts.length?_partRows.map(({p,i},idx)=>{
    const last=idx===_partRows.length-1;
    const pDate=p.date||'';
    let divider='';
    if(pDate!==_partLastDate){
      _partLastDate=pDate;
      divider=`<div style="padding:6px 14px;background:#FBFAF7;font-size:9px;font-weight:700;color:${dim.ink3};letter-spacing:.3px;border-bottom:0.5px solid rgba(0,0,0,.06)">📅 ${pDate||'ไม่ระบุวันที่'}</div>`;
    }
    return divider+`<div style="display:flex;gap:8px;padding:10px 14px;align-items:center;${last?'':'border-bottom:0.5px solid rgba(0,0,0,.06)'}">
      <div style="flex:1;min-width:0">
        <div style="font-size:11px;font-weight:500">${p.name||'—'}</div>
        <div style="font-size:9px;color:${dim.ink3};font-family:'DM Mono',monospace">${p.qty} ${p.unit||''} × ฿${(p.cost||0).toLocaleString()}${p.location?' · '+p.location:''}</div>
      </div>
      <span style="font-size:11px;font-weight:700;font-family:'DM Mono',monospace;color:${SVG_PINK.text}">฿${((p.qty||0)*(p.cost||0)).toLocaleString()}</span>
      ${p.late?`<span title="เพิ่มหลังปิดงาน${p.lateBy?(' · โดย '+p.lateBy):''}" style="background:#FBF6EE;color:#8A5B00;border:0.5px solid #EBDCC2;border-radius:7px;padding:1px 6px;font-size:8.5px;font-weight:700;flex-shrink:0;white-space:nowrap">ย้อนหลัง</span>`:''}
      ${flMaintCanEditParts(m)?`<button onclick="flMaintRemovePart('${m.id}',${i})" style="background:transparent;border:1px solid rgba(0,0,0,.08);border-radius:8px;padding:3px 8px;font-size:9px;color:#A32D2D;cursor:pointer;flex-shrink:0">×</button>`:''}
    </div>`;
  }).join(''):`<div style="font-size:11px;color:${dim.ink3};text-align:center;padding:14px">No parts withdrawn</div>`;
  return `<div style="background:#FBFAF7;border-radius:10px;overflow:hidden">${partsHtml}</div>`
    + (parts.length?`<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 4px;margin-top:4px">
      <span style="font-size:11px;color:${dim.ink2};font-weight:500">Subtotal parts</span>
      <span style="font-size:13px;font-weight:700;font-family:'DM Mono',monospace">฿${partsTotal.toLocaleString()}</span>
    </div>`:'')
    // §costDoubleCount · อะไหล่ที่ซื้อผ่าน memo ของงานนี้ จ่ายเงินไปแล้วตอนตั้ง memo
    // ถ้าไม่บอกตรงนี้ คนอ่านจะงงว่าทำไมยอดรวมงานไม่เท่ากับ Subtotal parts + memo
    + (function(){ const cov=(typeof flMaintPartsCoveredByMemo==='function')?flMaintPartsCoveredByMemo(m):0;
        return cov>0?`<div style="display:flex;align-items:flex-start;gap:6px;padding:7px 10px;margin-top:2px;background:#FBF6EE;border:0.5px solid #EBDCC2;border-radius:8px">
          <span style="font-size:11px;line-height:1.5;color:#8A5B00">ในนี้ <b style="font-family:'DM Mono',monospace">฿${cov.toLocaleString()}</b> เป็นอะไหล่ที่ซื้อผ่าน memo ของงานนี้ — จ่ายเงินไปแล้วตอนตั้ง memo จึงไม่ถูกนับซ้ำในต้นทุนงาน</span>
        </div>`:''; })();
}
// Surgically refresh ONLY the parts list + subtotal + timeline + count badge — WITHOUT
// re-rendering the whole detail mount. This keeps the +Withdraw button (and the part picker)
// alive, so the page never jumps to the top after a withdraw / return.
function flMaintRefreshParts(jobId){
  const m=(typeof FL_MAINT!=='undefined'?FL_MAINT:[]).find(x=>x.id===jobId);
  if(!m) return;
  const pl=document.getElementById('maint-parts-list-'+jobId);
  const tb=document.getElementById('maint-timeline-body-'+jobId);
  // if focus sits inside a region we're about to replace (e.g. a × remove button), blur it first
  const ae=document.activeElement;
  if(ae && ((pl&&pl.contains(ae))||(tb&&tb.contains(ae))) && ae.blur) ae.blur();
  if(pl) pl.innerHTML=_flMaintPartsInner(m);
  if(tb) tb.innerHTML=_flMaintTimelineInner(m);
  const pc=document.getElementById('maint-parts-count-'+jobId); if(pc) pc.textContent=(m.parts||[]).length;
  // reset the part picker for the next withdraw
  const s=document.getElementById('maint-inv-sel-'+jobId); if(s) s.value='';
  const q=document.getElementById('maint-inv-qty-'+jobId); if(q) q.value='1';
}

function flRenderMaintDetailPink(){
  const mount=document.getElementById('fl-maint-detail-mount');
  if(!mount)return;
  const dim={bg:'#F4F2EE',ink:'#1A1A1A',ink2:'#666',ink3:'#999',ink4:'#bbb',ink5:'#ccc',line:'rgba(0,0,0,.04)'};
  const SVG_PINK={accent:'#E03B7E',soft:'#FCE5EC',text:'#9F1B4F'};

  if(!_selMaintId){
    mount.innerHTML=`<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:400px;padding:40px;color:${dim.ink3};gap:10px;text-align:center">
      <div style="font-size:28px;opacity:.25;letter-spacing:.1em">MAINTENANCE</div>
      <div style="font-size:13px;color:${dim.ink2};font-weight:500">Select a maintenance job to see details</div>
      <div style="font-size:11px;color:${dim.ink3}">Click on the job list to see assets, progress, parts, and memos</div>
    </div>`;
    return;
  }

  const m=FL_MAINT.find(x=>x.id===_selMaintId);
  if(!m){mount.innerHTML='';return;}

  const b=getBoat(m.boatId);
  const inc=m.incidentId?FL_INCIDENTS.find(i=>i.id===m.incidentId):null;
  const STATUS_STYLE={
    pending:{bg:'#FCEBEB',color:'#A32D2D',label:'PENDING',accent:'#A32D2D'},
    inprogress:{bg:'#FAEEDA',color:'#854F0B',label:'IN PROGRESS',accent:'#BA7517'},
    done:{bg:'#1D9E75',color:'white',label:'DONE',accent:'#1D9E75'}
  };
  const TYPE_LABEL={corrective:'Corrective',preventive:'Preventive',scheduled:'Scheduled'};
  const TYPE_COLOR={corrective:'#A32D2D',preventive:'#BA7517',scheduled:'#185FA5'};
  const ss=STATUS_STYLE[m.status]||STATUS_STYLE.pending;

  const MONTHS_EN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const fmtD=(s)=>{if(!s)return'—';const d=new Date(s);return`${MONTHS_EN[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;};

  const noLast3=(m.no||'').slice(-3).padStart(3,'0');
  const noPrefix=(m.no||'MJ').replace(/[-\d]+$/,'')||'MJ';
  const OUT_STYLE={
    success:{bg:'#1D9E75',color:'white',label:'สำเร็จ',icon:'✓'},
    limited:{bg:'#FAEEDA',color:'#854F0B',label:'ใช้งานจำกัด',icon:'⚠'},
    rework:{bg:'#FCE5EC',color:'#9F1B4F',label:'ต้องซ่อมซ้ำ',icon:'↻'},
    decommission:{bg:'#1A1A1A',color:'white',label:'ปลดระวาง',icon:'✕'},
    cancelled:{bg:'#FCEBEB',color:'#A32D2D',label:'ยกเลิก',icon:'⊘'}
  };
  const outBadge=(m.status==='done'&&m.outcome&&m.outcome!=='success')?(()=>{
    const o=OUT_STYLE[m.outcome]||OUT_STYLE.success;
    return ` <span style="background:${o.bg};color:${o.color};padding:2px 9px;border-radius:11px;font-size:10px;font-weight:600;letter-spacing:.04em">${o.icon} ${o.label}</span>`;
  })():'';

  const headerStrip=`<div style="padding:16px 20px;border-bottom:1px solid rgba(0,0,0,.06);background:linear-gradient(to right,#FFF5EC 0%,#FBEAF0 60%,#F5DDE6 100%)">
    <div style="display:flex;align-items:center;gap:10px">
      <div style="width:50px;height:50px;border-radius:12px;background:${ss.accent};color:white;display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0;font-family:'DM Mono',monospace">
        <span style="font-size:9px;opacity:.85">${noPrefix}</span>
        <span style="font-size:13px;font-weight:700;line-height:1">${noLast3}</span>
      </div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <span style="font-size:20px;font-weight:700">${m.title||'—'}</span>
          <span style="background:${ss.bg};color:${ss.color};padding:2px 9px;border-radius:11px;font-size:10px;font-weight:600;letter-spacing:.04em">${ss.label}</span>${outBadge}
        </div>
        <div style="font-size:11px;color:${dim.ink2};margin-top:3px">${b?b.name+' · '+(b.type||'')+' · ':''}${TYPE_LABEL[m.type]||'Job'}${m.startDate?' · '+fmtD(m.startDate):''}${m.endDate?' → '+fmtD(m.endDate):' → ongoing'}${m.location?' · '+m.location:''}</div>
      </div>
      <div style="display:flex;gap:6px;flex-shrink:0">
        ${m.status!=='done'?`<button onclick="flMaintTogglePin('${m.id}',event)" title="${m.pinned?'Unpin':'Pin to top'}" style="background:${m.pinned?'#FBEAF0':'white'};color:${m.pinned?'#993556':dim.ink2};border:1px solid ${m.pinned?'#F4C0D1':'rgba(0,0,0,.12)'};border-radius:20px;padding:7px 10px;font-size:11px;font-weight:600;cursor:pointer">📌${m.pinned?' Pinned':''}</button>`:''}
        ${m.status==='pending'?`<button onclick="flMaintStart('${m.id}')" style="background:${SVG_PINK.accent};color:white;border:none;border-radius:20px;padding:7px 14px;font-size:11px;font-weight:600;cursor:pointer">▶ Start</button>`:''}
        ${m.status==='inprogress'?`<button onclick="flMaintOpenCloseModal('${m.id}')" style="background:#1D9E75;color:white;border:none;border-radius:20px;padding:7px 14px;font-size:11px;font-weight:600;cursor:pointer">✓ Close</button>`:''}
      </div>
    </div>
    ${m.closeNote?`<div style="margin-top:10px;padding:8px 12px;background:rgba(255,255,255,.6);border-radius:8px;font-size:11px;color:${dim.ink2};border-left:3px solid ${(OUT_STYLE[m.outcome]||OUT_STYLE.success).bg}"><span style="font-weight:600;color:${dim.ink}">Close note: </span>${m.closeNote}</div>`:''}
  </div>`;

  const cost=typeof flMaintCalcCost==='function'?flMaintCalcCost(m.id):0;
  const days=m.startDate&&m.endDate?Math.max(1,Math.ceil((new Date(m.endDate)-new Date(m.startDate))/86400000)):null;
  const PIER_LBL={tublamu:'Tub Lamu',panwa:'Visit Panwa',ranong:'Ranong'};
  const statCards=`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">
    <div style="background:${dim.bg};border-radius:10px;padding:10px 12px">
      <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em">Boat</div>
      <div style="font-size:14px;font-weight:700;margin-top:2px;color:#185FA5">${b?b.name:'—'}</div>
      <div style="font-size:10px;color:${dim.ink2}">${b?(b.type||'')+(b.pier?' · '+(PIER_LBL[b.pier]||b.pier):''):''}</div>
    </div>
    <div style="background:${dim.bg};border-radius:10px;padding:10px 12px">
      <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em">Type</div>
      <div style="font-size:14px;font-weight:700;margin-top:2px;color:${TYPE_COLOR[m.type]||'#666'}">${TYPE_LABEL[m.type]||'—'}</div>
      <div style="font-size:10px;color:${dim.ink2}">${m.type==='corrective'?'unplanned':m.type==='preventive'?'scheduled svc':m.type==='scheduled'?'planned':''}</div>
    </div>
    <div style="background:${dim.bg};border-radius:10px;padding:10px 12px">
      <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em">Duration</div>
      <div style="font-size:18px;font-weight:700;font-family:'DM Mono',monospace;margin-top:2px">${days!=null?days:'—'}</div>
      <div style="font-size:10px;color:${dim.ink2}">${days!=null?(days===1?'day':'days'):'ongoing'}</div>
    </div>
    <div style="background:${dim.bg};border-radius:10px;padding:10px 12px">
      <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em">${m.status==='done'?'Total cost':'Estimated cost'}</div>
      <div style="font-size:18px;font-weight:700;font-family:'DM Mono',monospace;margin-top:2px;color:${SVG_PINK.text}">฿${cost.toLocaleString()}</div>
      <div style="font-size:10px;color:${dim.ink2}">parts + labor</div>
    </div>
  </div>`;

  const incBanner=inc?`<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:#E6F1FB;border:1px solid #b5d4f4;border-radius:10px;cursor:pointer" onclick="nav(document.querySelector('[data-view=fl-incident]'));setTimeout(()=>{if(typeof flSelIncident==='function')flSelIncident('${inc.id}')},100)">
    <div style="width:8px;height:8px;border-radius:50%;background:#185FA5;flex-shrink:0"></div>
    <span style="font-size:11px;color:#185FA5;font-weight:500;flex:1">Linked Incident: <strong>${inc.no}</strong> · ${inc.title}${inc.date?' · '+fmtD(inc.date):''}</span>
    <span style="color:#185FA5;font-size:14px">›</span>
  </div>`:'';

  const descSection=m.detail?`<div>
    <div style="font-size:13px;font-weight:600;margin-bottom:8px">Description</div>
    <div style="background:#FBFAF7;border-radius:10px;padding:12px 14px;font-size:11px;color:${dim.ink2};line-height:1.5">${m.detail}</div>
  </div>`:'';

  // Parent Project section — only for Scheduled MJs (drydock/overhaul packages)
  // Corrective/preventive jobs are independent and never roll up into a project
  let parentProjSection = '';
  if(m.type==='scheduled'){
    const parentProj = m.parentProjectId ? (FL_PROJECTS||[]).find(p=>p.id===m.parentProjectId) : null;
    const sameboatProjects = (FL_PROJECTS||[]).filter(p=>p.boatId===m.boatId && p.status!=='completed');
    parentProjSection = `<div>
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;justify-content:space-between">
        <span style="font-size:13px;font-weight:600">Parent Project <span style="font-size:10px;color:${dim.ink3};font-weight:400">· scheduled only</span></span>
        ${parentProj
          ? `<button onclick="flMaintUnlinkProject('${m.id}')" style="background:transparent;border:1px solid #FCEBEB;color:#A32D2D;border-radius:14px;padding:4px 10px;font-size:10px;font-weight:500;cursor:pointer">Unlink</button>`
          : (sameboatProjects.length?`<button onclick="flMaintLinkProjectPick('${m.id}')" style="background:#1B2A4E;color:white;border:none;border-radius:14px;padding:4px 12px;font-size:10px;font-weight:600;cursor:pointer">+ Link to project</button>`:'')
        }
      </div>
      <div style="background:#FBFAF7;border-radius:10px;padding:12px 14px;font-size:11px;color:${dim.ink2}">
        ${parentProj
          ? `<div style="display:flex;align-items:center;gap:10px;cursor:pointer" onclick="_selProjId='${parentProj.id}';nav(document.querySelector('[data-view=\\'fl-projects\\']'))">
              <div style="width:32px;height:32px;border-radius:8px;background:#1B2A4E;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">${parentProj.type==='drydock'?'DD':'OV'}</div>
              <div style="flex:1">
                <div style="font-size:12px;font-weight:700;color:#1B2A4E">${parentProj.name}</div>
                <div style="font-size:10px;color:${dim.ink3};margin-top:1px">${parentProj.no} · ${parentProj.planFrom||'—'} → ${parentProj.planTo||'ongoing'} · ${parentProj.status}</div>
              </div>
              <span style="font-size:10px;color:#1B2A4E;font-weight:600">View →</span>
            </div>`
          : (sameboatProjects.length
              ? `<span style="color:${dim.ink3}">Not linked. ${sameboatProjects.length} open project(s) on this boat — click + Link above.</span>`
              : `<span style="color:${dim.ink3}">No open projects for this boat. Create one from <strong>Projects</strong> page first.</span>`)
        }
      </div>
    </div>`;
  }

  // Boat Status during Job section (editable)
  const BOAT_STATUS_STYLE={
    available:{bg:'#E6F4ED',color:'#0F6E56',dot:'#1D9E75',label:'Available',sub:'เรือยังออกได้'},
    fixing:{bg:'#FDF6E9',color:'#854F0B',dot:'#BA7517',label:'Fixing',sub:'อยู่ระหว่างซ่อม'},
    unavailable:{bg:'#FBE9E9',color:'#A32D2D',dot:'#A32D2D',label:'Unavailable',sub:'หยุดให้บริการ'}
  };
  const curBoatSt = m.boatStatus || (m.setFixing===false ? 'available' : 'fixing');
  const bss = BOAT_STATUS_STYLE[curBoatSt] || BOAT_STATUS_STYLE.fixing;
  const boatStatusSection = (m.status !== 'done') ? `<div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;justify-content:space-between">
      <span style="font-size:13px;font-weight:600">⚙️ Boat Status during Job</span>
      <button onclick="flOpenEditBoatStatus('${m.id}')" style="background:${dim.bg};border:none;border-radius:14px;padding:5px 12px;font-size:10px;color:${dim.ink2};cursor:pointer">Change</button>
    </div>
    <div style="background:${bss.bg};border-radius:10px;padding:10px 14px;display:flex;align-items:center;gap:10px;border:1px solid ${bss.color}33">
      <div style="width:10px;height:10px;border-radius:50%;background:${bss.dot};flex-shrink:0"></div>
      <div style="flex:1;min-width:0">
        <div style="font-size:12px;font-weight:600;color:${bss.color}">${bss.label}</div>
        <div style="font-size:10px;color:${dim.ink3}">${bss.sub}${m.boatStatusReason?' · '+m.boatStatusReason:''}</div>
      </div>
    </div>
    <div style="margin-top:10px">
      <div style="font-size:13px;font-weight:600;margin-bottom:6px">📍 สถานที่ซ่อม / ส่งเครื่องไปที่</div>
      <div style="display:flex;gap:6px">
        <input id="fl-maint-reploc-${m.id}" list="fl-maint-reploc-dl" value="${(m.location||'').replace(/"/g,'&quot;')}" placeholder="เช่น Thai Marine / อู่ซ่อม / คลัง Tub Lamu" style="flex:1;padding:7px 9px;border:1px solid rgba(0,0,0,.1);border-radius:8px;font-size:12px;box-sizing:border-box">
        <datalist id="fl-maint-reploc-dl"><option>อู่ซ่อม</option><option>คลังกลาง</option><option>คลัง Tub Lamu</option><option>คลัง Visit Panwa</option></datalist>
        <button onclick="flMaintSetRepairLoc('${m.id}')" style="background:#0F6E56;color:#fff;border:none;border-radius:8px;padding:7px 14px;font-size:11px;font-weight:600;cursor:pointer;white-space:nowrap">บันทึก</button>
      </div>
      <div style="font-size:10px;color:${dim.ink3};margin-top:4px">อัปเดตที่นี่ → เครื่องที่ถอดไปซ่อมในงานนี้จะตามไปด้วยอัตโนมัติ</div>
    </div>
  </div>` : '';

  const assets=m.assets||[];
  const ASSET_STATUS={fixing:{bg:'#FAEEDA',color:'#854F0B',label:'FIXING'},spare:{bg:'#F4F2EE',color:'#666',label:'SPARE'},removed:{bg:'#FCEBEB',color:'#A32D2D',label:'REMOVED'},ok:{bg:'#1D9E75',color:'white',label:'OK'},check:{bg:'#F4F2EE',color:'#666',label:'CHECK'}};
  const ASSET_TYPE_BG={engine:'#185FA5',gearbox:'#185FA5',propeller:'#185FA5',hull:'#666'};
  const TYPE_LBL={engine:'Engine',gearbox:'Gearbox',propeller:'Propeller',hull:'Hull'};
  const assetRows=assets.map((a,idx)=>{
    const as=ASSET_STATUS[a.status]||ASSET_STATUS.check;
    const posLbl=a.type==='engine'?'EN':a.type==='gearbox'?'GB':a.type==='propeller'?'PR':'HU';
    const posBg=ASSET_TYPE_BG[a.type]||'#666';
    return`<div style="background:#FBFAF7;border-radius:10px;padding:10px 14px;display:flex;align-items:center;gap:10px">
      <span style="font-size:9px;font-weight:700;color:white;background:${posBg};padding:2px 7px;border-radius:5px;font-family:'DM Mono',monospace;flex-shrink:0">${posLbl}</span>
      <div style="flex:1;min-width:0">
        <div style="font-size:11px;font-weight:600">${TYPE_LBL[a.type]||'Asset'} · ${a.label||'—'}</div>
        ${a.detail?`<div style="font-size:10px;color:${dim.ink3};margin-top:1px">${a.detail}</div>`:''}
      </div>
      <span style="background:${as.bg};color:${as.color};padding:1px 7px;border-radius:8px;font-size:9px;font-weight:600;flex-shrink:0">${as.label}</span>
      ${(m.status==='inprogress' && a.engId)?`<button onclick="flMaintSwapEngine('${m.id}',${idx})" style="background:#E6F4ED;border:1px solid #BBE0CE;border-radius:8px;padding:3px 8px;font-size:9px;color:#0F6E56;font-weight:600;cursor:pointer;flex-shrink:0" title="ดึงเครื่องนี้ออก · เกียร์/ใบจักรคาเรือ · เอาเครื่องใหม่มาใส่">↔ สลับเครื่อง</button>`:''}
      ${(m.status!=='done' && (a.gbId||a.propId))?`<button onclick="flMaintStashOpen('${m.id}',${idx})" style="background:#EEF3F8;border:1px solid #CFE0EF;border-radius:8px;padding:3px 8px;font-size:9px;color:#185FA5;font-weight:600;cursor:pointer;flex-shrink:0" title="ถอดออกไปเก็บเป็น Spare (ไม่ส่งซ่อม)">📦 ถอดเก็บ</button>`:''}
      ${m.status!=='done'?`<button onclick="flMaintRemoveAsset('${m.id}',${idx})" style="background:transparent;border:1px solid rgba(0,0,0,.08);border-radius:8px;padding:3px 8px;font-size:9px;color:#A32D2D;cursor:pointer;flex-shrink:0">×</button>`:''}
    </div>`;
  }).join('');
  const assetSection=`<div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;justify-content:space-between;flex-wrap:wrap">
      <span style="font-size:13px;font-weight:600">Affected assets <span style="color:${dim.ink3};font-weight:400">${assets.length}</span></span>
      ${m.status!=='done'?`<div style="display:flex;gap:6px">
        ${(m.type==='preventive'||m.type==='scheduled')?`<button onclick="flMaintAutoAddEngines('${m.id}')" style="background:${SVG_PINK.accent};color:white;border:none;border-radius:14px;padding:5px 12px;font-size:10px;font-weight:600;cursor:pointer">+ All engines</button>`:''}
        ${(m.assets||[]).filter(a=>a.engId).length>=2?`<button onclick="flSplitExistingJob('${m.id}')" style="background:#E6F1FB;color:#185FA5;border:none;border-radius:14px;padding:5px 12px;font-size:10px;font-weight:600;cursor:pointer" title="แตกเครื่องในงานนี้ออกเป็น 1 งาน/เครื่อง">⎘ แยกงานนี้</button>`:''}
        <button onclick="flMaintAddAssetPrompt('${m.id}')" style="background:${dim.bg};border:none;border-radius:14px;padding:5px 12px;font-size:10px;color:${dim.ink2};cursor:pointer">+ Add asset</button>
      </div>`:(((m.assets||[]).some(a=>a.engId||a.gbId) && (m.type==='scheduled'||/น้ำมัน|ถ่าย|เซอร์วิส|service|oil|svc|เกียร์|gear/i.test((m.title||'')+' '+(m.detail||''))))?`<button onclick="flMaintServiceResetManual('${m.id}')" style="background:#E9F7EF;color:#0F6E56;border:1px solid #C4E6D5;border-radius:14px;padding:5px 12px;font-size:10px;font-weight:600;cursor:pointer" title="ตั้งชั่วโมงเริ่มรอบถ่ายน้ำมันใหม่ให้เครื่องในงานนี้ (สำหรับจ็อบที่ปิดไปแล้ว)">↻ รีเซ็ตรอบเซอร์วิส</button>`:'')}
    </div>
    ${assets.length?`<div style="display:flex;flex-direction:column;gap:8px">${assetRows}</div>`:`<div style="font-size:11px;color:${dim.ink3};text-align:center;padding:14px;background:#FBFAF7;border-radius:10px">No assets linked</div>`}
  </div>`;

  const timelineSection=`<div>
    <div style="font-size:13px;font-weight:600;margin-bottom:8px">Progress timeline</div>
    <div id="maint-timeline-body-${m.id}" style="background:#FBFAF7;border-radius:10px;padding:12px 14px">${_flMaintTimelineInner(m)}</div>
    ${m.status!=='done'?`<div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap">
      <input id="maint-log-text-${m.id}" placeholder="Add progress note..." style="flex:1;min-width:160px;background:#FBFAF7;border:1px solid rgba(0,0,0,.06);border-radius:10px;padding:8px 12px;font-size:11px;outline:none;font-family:inherit"/>
      <input type="date" id="maint-log-date-${m.id}" value="${TODAY_STR}" style="width:120px;background:#FBFAF7;border:1px solid rgba(0,0,0,.06);border-radius:10px;padding:8px 10px;font-size:11px;outline:none;font-family:inherit;color:${dim.ink2}"/>
      <input id="maint-log-by-${m.id}" placeholder="By..." style="width:80px;background:#FBFAF7;border:1px solid rgba(0,0,0,.06);border-radius:10px;padding:8px 12px;font-size:11px;outline:none;font-family:inherit"/>
      <button onclick="flMaintAddLog('${m.id}')" style="background:${SVG_PINK.accent};color:white;border:none;border-radius:10px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer">Log</button>
    </div>`:''}
  </div>`;

  const parts=m.parts||[];
  // Searchable parts list — type to filter (datalist). label->id map for lookup.
  const _wdItems=(typeof FL_INVENTORY!=='undefined'?FL_INVENTORY:[]).filter(x=>x.qty>0);
  const _wdSeen={}; window._maintInvLabelMap={};
  const invOpts=_wdItems.map(x=>{
    let label=x.name+(x.partNo?` · ${x.partNo}`:'');
    if(_wdSeen[label]) label+=` #${x.id}`;
    _wdSeen[label]=true; window._maintInvLabelMap[label]=x.id;
    return `<option value="${label.replace(/"/g,'&quot;')}"></option>`;
  }).join('');
  const withdrawForm=flMaintCanEditParts(m)?`<div style="display:flex;gap:6px;margin-top:8px;align-items:center;flex-wrap:wrap">
      <input list="maint-inv-list-${m.id}" id="maint-inv-sel-${m.id}" onchange="flMaintFillLoc('${m.id}')" autocomplete="off" placeholder="พิมพ์ชื่ออะไหล่ / Part No..." style="flex:1 1 160px;background:#FBFAF7;border:1px solid rgba(0,0,0,.06);border-radius:10px;padding:8px 10px;font-size:11px;outline:none;font-family:inherit;min-width:0"/>
      <datalist id="maint-inv-list-${m.id}">${invOpts}</datalist>
      <select id="maint-inv-loc-${m.id}" style="flex:1 1 130px;background:#FBFAF7;border:1px solid rgba(0,0,0,.06);border-radius:10px;padding:8px 10px;font-size:11px;outline:none;font-family:inherit;min-width:0">
        <option value="">— Select warehouse —</option>
      </select>
      <input type="number" id="maint-inv-qty-${m.id}" value="1" min="1" style="width:54px;background:#FBFAF7;border:1px solid rgba(0,0,0,.06);border-radius:10px;padding:8px 8px;font-size:11px;outline:none;font-family:inherit;text-align:center"/>
      <button onclick="flMaintAddPart('${m.id}')" style="background:${SVG_PINK.accent};color:white;border:none;border-radius:10px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer;flex-shrink:0">+ Withdraw</button>
    </div>`:'';
  const partsSection=`<div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;justify-content:space-between">
      <span style="font-size:13px;font-weight:600">Parts withdrawn <span id="maint-parts-count-${m.id}" style="color:${dim.ink3};font-weight:400">${parts.length}</span></span>
    </div>
    <div id="maint-parts-list-${m.id}">${_flMaintPartsInner(m)}</div>
    ${/* §mjLateParts · งานปิดแล้วยังลงอะไหล่ที่ลืมได้ · แต่ต้องกดเปิดโหมดก่อน */''}
    ${(m.status==='done' && _flMaintLateEdit===m.id)?`<div style="display:flex;align-items:flex-start;gap:7px;padding:8px 11px;margin-top:8px;background:#FBF6EE;border:0.5px solid #EBDCC2;border-radius:8px">
      <span style="font-size:10.5px;line-height:1.55;color:#8A5B00;flex:1">⚠ <b>งานนี้ปิดไปแล้ว</b> — การเบิก/คืนตอนนี้จะหักสต็อกจริงและเปลี่ยนต้นทุนของงานที่ปิดแล้ว · ทุกรายการจะติดป้าย “ย้อนหลัง” และบันทึกลง log</span>
      <button onclick="flMaintLateEditOff()" style="background:#fff;border:1px solid #EBDCC2;color:#8A5B00;border-radius:8px;padding:4px 10px;font-size:10px;font-weight:700;cursor:pointer;flex-shrink:0;font-family:inherit">เสร็จแล้ว</button>
    </div>`:''}
    ${withdrawForm}
    ${(m.status==='done' && _flMaintLateEdit!==m.id)?`<div style="display:flex;justify-content:flex-end;margin-top:8px">
      <button onclick="flMaintLateEditOn('${m.id}')" title="ปิดงานไปแล้วแต่ลืมลงอะไหล่ที่เบิกไปใช้จริง" style="background:transparent;border:1px solid rgba(0,0,0,.12);color:#666;border-radius:14px;padding:5px 12px;font-size:10px;font-weight:600;cursor:pointer;font-family:inherit">&#9998; แก้ไขอะไหล่ย้อนหลัง</button>
    </div>`:''}
  </div>`;

  const memos=FL_MEMOS.filter(mo=>mo.maintId===m.id);
  const MEMO_STATUS={created:{bg:'#F4F2EE',color:'#666',label:'CREATED'},pending_approval:{bg:'#FAEEDA',color:'#854F0B',label:'PENDING'},approved:{bg:'#E6F1FB',color:'#185FA5',label:'APPROVED'},ordered:{bg:'#E6F1FB',color:'#185FA5',label:'ORDERED'},received:{bg:'#1D9E75',color:'white',label:'RECEIVED'},paid:{bg:'#1D9E75',color:'white',label:'PAID'},cancelled:{bg:'#FCEBEB',color:'#A32D2D',label:'CANCELLED'}};
  const memoHtml=memos.length?memos.map((mo,i)=>{
    const last=i===memos.length-1;
    const ms=MEMO_STATUS[mo.status]||MEMO_STATUS.created;
    const isPaid=mo.status==='paid'||mo.status==='received'||mo.status==='approved';
    const isCancelled=mo.status==='cancelled';
    return`<div onclick="flViewMemo('${mo.id}')" title="เปิดดู / แก้ไข / ยกเลิก" style="display:flex;gap:8px;padding:10px 14px;align-items:center;cursor:pointer;${isCancelled?'opacity:.55;':''}${last?'':'border-bottom:0.5px solid rgba(0,0,0,.06)'}">
      <div style="flex:1;min-width:0">
        <div style="font-size:11px;font-weight:600;font-family:'DM Mono',monospace;${isCancelled?'text-decoration:line-through':''}">${mo.no||'—'} · ${mo.title||''}</div>
        ${mo.proposer?`<div style="font-size:9px;color:${dim.ink3};margin-top:1px">By ${mo.proposer}</div>`:''}
      </div>
      <span style="font-size:11px;font-weight:700;font-family:'DM Mono',monospace;color:${isPaid?'#0F6E56':SVG_PINK.text}">฿${(mo.amount||0).toLocaleString()}</span>
      <span style="background:${ms.bg};color:${ms.color};padding:1px 7px;border-radius:8px;font-size:9px;font-weight:600">${ms.label}</span>
      <button onclick="event.stopPropagation();flPrintMemo('${mo.id}')" style="background:${dim.bg};border:none;border-radius:8px;padding:4px 8px;font-size:9px;color:${dim.ink2};cursor:pointer;flex-shrink:0">Print</button>
    </div>`;
  }).join(''):`<div style="font-size:11px;color:${dim.ink3};text-align:center;padding:14px">No memos linked</div>`;
  const canAddMemo = m.status !== 'done' || m.awaitingInvoice;
  const memoButton = (() => {
    if(!canAddMemo) return '';
    if(m.status === 'done' && m.awaitingInvoice){
      // Closed job awaiting invoice — special button styling
      return `<button onclick="flMaintCreateMemo('${m.id}')" style="background:#FFF8E1;border:1px solid #F0D58C;color:#854F0B;border-radius:14px;padding:5px 12px;font-size:10px;font-weight:600;cursor:pointer">📋 + Add Memo (awaiting invoice)</button>`;
    }
    if(parts.length){
      return `<div style="display:flex;gap:6px;align-items:center">`
        + `<button onclick="flMaintCreateMemo('${m.id}')" style="background:${SVG_PINK.accent};color:white;border:none;border-radius:14px;padding:5px 12px;font-size:10px;font-weight:600;cursor:pointer">+ Create memo from parts</button>`
        + `<button onclick="flMaintCreateMemo('${m.id}', true)" style="background:${SVG_PINK.accent};color:white;border:none;border-radius:14px;padding:5px 12px;font-size:10px;font-weight:600;cursor:pointer" title="สร้าง memo · กรอกรายการเอง (ไม่ดึงจาก parts)">+ Memo</button>`
        + `</div>`;
    }
    return `<button onclick="flMaintCreateMemo('${m.id}')" style="background:${dim.bg};border:none;border-radius:14px;padding:5px 12px;font-size:10px;color:${dim.ink2};cursor:pointer">+ Create memo</button>`;
  })();
  
  const memoSection=`<div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;justify-content:space-between">
      <span style="font-size:13px;font-weight:600">Linked memos <span style="color:${dim.ink3};font-weight:400">${memos.length}</span></span>
      ${memoButton}
    </div>
    <div style="background:#FBFAF7;border-radius:10px;overflow:hidden">${memoHtml}</div>
  </div>`;

  const deleteSection=m.status!=='done'?`<div style="display:flex;justify-content:flex-end">
    <button onclick="flDeleteMaint('${m.id}')" style="background:transparent;border:1px solid #FCEBEB;color:#A32D2D;border-radius:14px;padding:5px 12px;font-size:10px;font-weight:500;cursor:pointer">Delete job</button>
  </div>`:'';

  mount.innerHTML=`${headerStrip}<div style="padding:16px 20px;display:flex;flex-direction:column;gap:14px;max-height:calc(100vh - 280px);overflow-y:auto">
    ${statCards}
    ${incBanner}
    ${descSection}
    ${parentProjSection}
    ${boatStatusSection}
    ${assetSection}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">${timelineSection}${partsSection}</div>
    ${memoSection}
    ${deleteSection}
  </div>`;
}

function flRenderMaintDetail(id){
  if(typeof flRenderMaintDetailPink==='function')flRenderMaintDetailPink();
}

// Re-render the MJ detail WITHOUT losing scroll position (used by withdraw / return-part etc.
// which would otherwise jump the page to the top). Preserves both window scroll and the
// nearest scrollable ancestor of the detail mount.
function _flWithDetailScroll(fn){
  var mt=document.getElementById('fl-maint-detail-mount');
  var sc=null, el=mt;
  while(el){
    try{ var cs=getComputedStyle(el); if(/(auto|scroll)/.test(cs.overflowY) && el.scrollHeight>el.clientHeight+2){ sc=el; break; } }catch(e){}
    el=el.parentElement;
  }
  // The real cause of the "jump to top": the button/input the user just clicked lives inside
  // the mount and still has focus; replacing innerHTML removes the focused element, and the
  // browser scrolls. Blur first so no focus-removal scroll happens, then re-render.
  try{ if(document.activeElement && mt && mt.contains(document.activeElement) && document.activeElement.blur) document.activeElement.blur(); }catch(e){}
  var winY=window.scrollY||window.pageYOffset||0, scTop=sc?sc.scrollTop:0;
  var restore=function(){ try{ if(sc) sc.scrollTop=scTop; window.scrollTo(0,winY); }catch(e){} };
  try{ fn(); }finally{
    restore();                              // sync (in case nothing else moves it)
    requestAnimationFrame(restore);         // after layout
    setTimeout(restore,0);                  // defensive: after any deferred focus/anchor adjust
  }
}


function flMaintAutoAddEngines(jobId){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m)return;
  if(!m.assets)m.assets=[];
  const engs=(typeof FL_ENGINES!=='undefined'?FL_ENGINES:[]).filter(e=>e.boatId===m.boatId);
  if(!engs.length){alert('เรือนี้ไม่มีเครื่องยนต์');return;}
  const existingEngIds=new Set(m.assets.filter(a=>a.engId).map(a=>a.engId));
  const toAdd=engs.filter(e=>!existingEngIds.has(e.id));
  if(!toAdd.length){alert('เครื่องยนต์ทั้งหมดอยู่ในรายการแล้ว');return;}
  // ≥2 engines would be added → ask: combine into this job, or split 1-job-per-engine
  if(toAdd.length>=2){ flOpenEngChoiceModal(jobId, toAdd.length); return; }
  // single engine → just add to this job
  flEngAddAllToJob(jobId);
}

// Original behaviour: add every (not-yet-listed) engine to this one job
function flEngAddAllToJob(jobId){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m)return;
  if(!m.assets)m.assets=[];
  const engs=(typeof FL_ENGINES!=='undefined'?FL_ENGINES:[]).filter(e=>e.boatId===m.boatId);
  const existingEngIds=new Set(m.assets.filter(a=>a.engId).map(a=>a.engId));
  let added=0;
  engs.forEach(e=>{
    if(existingEngIds.has(e.id))return;
    m.assets.push({type:'engine',engId:e.id,label:`${e.serial} · ${e.pos||''}`,detail:`${e.brand||''} ${e.model||''}`.trim(),status:'fixing'});
    added++;
  });
  if(!added){alert('เครื่องยนต์ทั้งหมดอยู่ในรายการแล้ว');return;}
  if(!m.progressLog)m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`+ เพิ่มเครื่องยนต์ทั้งหมด ${added} ตัว`,by:'ระบบ'});
  flSave();flRenderMaintDetail(jobId);
}

// ── Engine add choice modal (combine vs split per engine) ──
function flOpenEngChoiceModal(jobId, n){
  window._flEngChoiceJobId=jobId;
  const m=FL_MAINT.find(x=>x.id===jobId);
  const c1=document.getElementById('fl-ec-count'); if(c1)c1.textContent=n;
  const c2=document.getElementById('fl-ec-count-2'); if(c2)c2.textContent=n;
  const pv=document.getElementById('fl-ec-preview');
  if(pv && m){
    const engs=(typeof FL_ENGINES!=='undefined'?FL_ENGINES:[]).filter(e=>e.boatId===m.boatId);
    const existingEngIds=new Set((m.assets||[]).filter(a=>a.engId).map(a=>a.engId));
    const toAdd=engs.filter(e=>!existingEngIds.has(e.id));
    pv.innerHTML='<strong>Engines:</strong> '+toAdd.map(e=>`<span style="display:inline-block;background:#fff;border:1px solid #F0C8B0;padding:2px 8px;border-radius:7px;margin:2px;font-family:'DM Mono',monospace;font-size:10px">${e.serial} · ${e.pos||''}</span>`).join('');
  }
  openModal('fl-modal-eng-choice');
}

function flChooseEngMode(mode){
  const jobId=window._flEngChoiceJobId; window._flEngChoiceJobId=null;
  closeModal('fl-modal-eng-choice');
  if(!jobId)return;
  if(mode==='single'){ flEngAddAllToJob(jobId); return; }
  flEngSplitIntoJobs(jobId);
}

// Split: 1 job per engine, cloned from the open job, kept under the same parent project
function flEngSplitIntoJobs(jobId){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m)return;
  if(!m.assets)m.assets=[];
  const engs=(typeof FL_ENGINES!=='undefined'?FL_ENGINES:[]).filter(e=>e.boatId===m.boatId);
  const existingEngIds=new Set(m.assets.filter(a=>a.engId).map(a=>a.engId));
  const toAdd=engs.filter(e=>!existingEngIds.has(e.id));
  if(!toAdd.length){alert('เครื่องยนต์ทั้งหมดอยู่ในรายการแล้ว');return;}
  const mkAsset=e=>({type:'engine',engId:e.id,label:`${e.serial} · ${e.pos||''}`,detail:`${e.brand||''} ${e.model||''}`.trim(),status:'fixing'});
  const baseTitle=m.title||'';
  const hasOwnEngine=m.assets.some(a=>a.engId);
  const proj=(typeof FL_PROJECTS!=='undefined'?FL_PROJECTS:[]).find(p=>p.id===m.parentProjectId);
  let _no = FL_MAINT.length ? Math.max(0,...FL_MAINT.map(x=>parseInt(String(x.no||'').replace(/^MJ-/,''))||0)) : 0;
  const created=[];
  toAdd.forEach((e,idx)=>{
    const suffix=`${e.serial}${e.pos?' · '+e.pos:''}`;
    if(idx===0 && !hasOwnEngine){
      // reuse the open job as the first engine's job
      m.assets.push(mkAsset(e));
      m.title=`${baseTitle} — ${suffix}`;
      if(!m.progressLog)m.progressLog=[];
      m.progressLog.push({date:TODAY_STR,text:`+ Split per engine · this job = ${suffix}`,by:'ระบบ'});
      created.push(m);
      return;
    }
    _no++;
    const jobNo='MJ-'+String(_no).padStart(3,'0');
    const nj={
      id:LA_UID('mj')+idx,no:jobNo,boatId:m.boatId,type:m.type,
      title:`${baseTitle} — ${suffix}`,
      detail:m.detail||'',location:m.location||'',
      status:'pending',startDate:m.startDate,endDate:null,cost:0,
      incidentId:m.incidentId||null,assets:[mkAsset(e)],
      boatStatus:m.boatStatus||'fixing',boatStatusReason:m.boatStatusReason||'',
      setFixing:m.setFixing,
      progressLog:[{date:TODAY_STR,text:`+ Split from ${m.no} · ${suffix}`,by:'ระบบ'}]
    };
    if(m.parentProjectId){
      nj.parentProjectId=m.parentProjectId;
      nj.progressLog.push({date:TODAY_STR,text:`+ Created under project ${proj?proj.no:m.parentProjectId}`,by:'ระบบ'});
    }
    if(typeof flAssertUniqueNo==='function') flAssertUniqueNo(FL_MAINT,jobNo,'MJ');
    FL_MAINT.unshift(nj);
    created.push(nj);
  });
  if(proj){
    if(!proj.log)proj.log=[];
    proj.log.push({date:TODAY_STR,text:`+ Split engines → ${created.map(j=>j.no).join(', ')}`,by:'user'});
  }
  flSave();
  flRenderMaintDetail(jobId);
  if(typeof flShowToast==='function') flShowToast(`แยกเป็น ${created.length} งาน (1 งาน/เครื่อง)`);
}

// Split a job that ALREADY holds ≥2 engines — engine[0] stays, rest become new MJs (no manual removal)
function flSplitExistingJob(jobId){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m||!Array.isArray(m.assets))return;
  const engAssets=m.assets.filter(a=>a.engId);
  if(engAssets.length<2){alert('งานนี้มีเครื่องยนต์น้อยกว่า 2 ตัว · ไม่ต้องแยก');return;}
  const nonEng=m.assets.filter(a=>!a.engId);  // gearbox/propeller/hull stay on the first job
  const _ENG=(typeof FL_ENGINES!=='undefined'?FL_ENGINES:[]);
  const engOf=a=>a.engId?_ENG.find(e=>e.id===a.engId):null;
  const suffixOf=a=>{const e=engOf(a);return e?`${e.serial}${e.pos?' · '+e.pos:''}`:(a.label||'Engine');};
  if(!confirm(`แยกงาน ${m.no} ออกเป็น ${engAssets.length} งาน (1 งาน/เครื่อง)?\n\nเครื่องแรกอยู่ในงานนี้ · อีก ${engAssets.length-1} เครื่องสร้างเป็น MJ ใหม่ใต้ project เดิม\n(กด OK เพื่อแยก · Cancel เพื่อยกเลิก)`)) return;
  const baseTitle=(m.title||'').replace(/\s+—\s+.*$/,'');  // strip any prior " — suffix"
  const proj=(typeof FL_PROJECTS!=='undefined'?FL_PROJECTS:[]).find(p=>p.id===m.parentProjectId);
  let _no = FL_MAINT.length ? Math.max(0,...FL_MAINT.map(x=>parseInt(String(x.no||'').replace(/^MJ-/,''))||0)) : 0;
  const created=[];
  const keep=engAssets[0];
  // first engine stays on this job (keep non-engine assets here too)
  m.assets=[keep, ...nonEng];
  m.title=`${baseTitle} — ${suffixOf(keep)}`;
  if(!m.progressLog)m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`+ Split job · this job = ${suffixOf(keep)}`,by:'ระบบ'});
  created.push(m);
  // remaining engines → new cloned jobs
  engAssets.slice(1).forEach((a,idx)=>{
    const suffix=suffixOf(a);
    _no++;
    const jobNo='MJ-'+String(_no).padStart(3,'0');
    const nj={
      id:LA_UID('mj')+idx,no:jobNo,boatId:m.boatId,type:m.type,
      title:`${baseTitle} — ${suffix}`,
      detail:m.detail||'',location:m.location||'',
      status:'pending',startDate:m.startDate,endDate:null,cost:0,
      incidentId:m.incidentId||null,
      assets:[{type:'engine',engId:a.engId,label:a.label||suffix,detail:a.detail||'',status:a.status||'fixing'}],
      boatStatus:m.boatStatus||'fixing',boatStatusReason:m.boatStatusReason||'',
      setFixing:m.setFixing,
      progressLog:[{date:TODAY_STR,text:`+ Split from ${m.no} · ${suffix}`,by:'ระบบ'}]
    };
    if(m.parentProjectId){
      nj.parentProjectId=m.parentProjectId;
      nj.progressLog.push({date:TODAY_STR,text:`+ Created under project ${proj?proj.no:m.parentProjectId}`,by:'ระบบ'});
    }
    if(typeof flAssertUniqueNo==='function') flAssertUniqueNo(FL_MAINT,jobNo,'MJ');
    FL_MAINT.unshift(nj);
    created.push(nj);
  });
  if(proj){
    if(!proj.log)proj.log=[];
    proj.log.push({date:TODAY_STR,text:`+ Split ${m.no} → ${created.slice(1).map(j=>j.no).join(', ')}`,by:'user'});
  }
  flSave();
  flRenderMaintDetail(jobId);
  if(typeof flShowToast==='function') flShowToast(`แยกเป็น ${created.length} งาน (1 งาน/เครื่อง)`);
}

// ── Stash gearbox/propeller as Spare (removed & stored · NOT a repair job) ──
const FL_STASH_LOCS=[
  {key:'pier:tublamu',label:'คลัง Tub Lamu'},
  {key:'pier:panwa',label:'คลัง Visit Panwa'},
  {key:'pier:central',label:'คลังกลาง'},
  {key:'shop:honda-phuket',label:'อู่ Honda Phuket'},
  {key:'shop:suzuki-phuket',label:'อู่ Suzuki Phuket'},
  {key:'shop:prop-shop-phuket',label:'ร้านใบจักร Phuket'}
];
// shared: mutate a gearbox/propeller record into stored-Spare state
function _flStashPartRecord(rec,isGb,locKey,locLabel,srcNo,note){
  const origin=isGb?(rec.note||rec.pos||'') : (rec.note||'');
  rec.status='spare';
  rec.spareLocation=locKey;
  if(isGb) rec.engineId=null;   // gearbox detaches from its engine
  else     rec.gearboxId=null;  // propeller detaches from its gearbox
  if(!rec.log) rec.log=[];
  rec.log.push({date:TODAY_STR,type:'remove',desc:`ถอดเก็บจาก Job ${srcNo}${origin?' · '+origin:''} → ${locLabel}${note?' · '+note:''}`});
}
function flMaintStashOpen(jobId,idx){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m||!m.assets)return;
  const a=m.assets[idx];if(!a||!(a.gbId||a.propId)){alert('ถอดเก็บได้เฉพาะเกียร์/ใบจักร');return;}
  window._flStash={jobId,idx};
  const isGb=!!a.gbId;
  const rec=isGb?(typeof flGetGb==='function'?flGetGb(a.gbId):(FL_GEARBOXES||[]).find(g=>g.id===a.gbId))
                :(FL_PROPELLERS||[]).find(p=>p.id===a.propId);
  const nm=document.getElementById('fl-stash-name');
  if(nm) nm.textContent=`${isGb?'เกียร์':'ใบจักร'} · ${(rec&&rec.serial)||a.label||'—'}`;
  const sel=document.getElementById('fl-stash-loc');
  if(sel) sel.innerHTML=FL_STASH_LOCS.map(l=>`<option value="${l.key}">${l.label}</option>`).join('');
  const note=document.getElementById('fl-stash-note'); if(note) note.value='';
  openModal('fl-modal-stash');
}
function flMaintStashConfirm(){
  const st=window._flStash;window._flStash=null;
  if(!st){closeModal('fl-modal-stash');return;}
  const m=FL_MAINT.find(x=>x.id===st.jobId);if(!m||!m.assets){closeModal('fl-modal-stash');return;}
  const a=m.assets[st.idx];if(!a){closeModal('fl-modal-stash');return;}
  const sel=document.getElementById('fl-stash-loc');
  const locKey=sel?sel.value:'pier:central';
  const locLabel=(FL_STASH_LOCS.find(l=>l.key===locKey)||{}).label||locKey;
  const note=(document.getElementById('fl-stash-note')?.value||'').trim();
  const isGb=!!a.gbId;
  const rec=isGb?(typeof flGetGb==='function'?flGetGb(a.gbId):(FL_GEARBOXES||[]).find(g=>g.id===a.gbId))
                :(FL_PROPELLERS||[]).find(p=>p.id===a.propId);
  if(!rec){alert('ไม่พบข้อมูลชิ้นส่วน');closeModal('fl-modal-stash');return;}
  _flStashPartRecord(rec,isGb,locKey,locLabel,m.no,note);
  // remove from the repair job + log on the job
  const lbl=a.label||(rec.serial||'');
  m.assets.splice(st.idx,1);
  if(!m.progressLog)m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`📦 ถอด${isGb?'เกียร์':'ใบจักร'} ${lbl} ไปเก็บที่ ${locLabel}${note?' · '+note:''}`,by:'ระบบ'});
  flSave();
  closeModal('fl-modal-stash');
  flRenderMaintDetail(st.jobId);
  if(typeof flShowToast==='function') flShowToast(`ถอดเก็บ ${lbl} → ${locLabel}`);
}

function flMaintAddAssetPrompt(jobId){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m)return;
  const choice=prompt('เพิ่ม asset ประเภทไหน?\n\n  e = engine (เครื่องยนต์)\n  g = gearbox (เกียร์)\n  p = propeller (ใบจักร)\n  h = hull (ตัวเรือ)','e');
  if(!choice)return;
  const c=choice.toLowerCase().trim();
  const type=c.startsWith('e')?'engine':c.startsWith('g')?'gearbox':c.startsWith('p')?'propeller':c.startsWith('h')?'hull':null;
  if(!type){alert('ประเภทไม่ถูกต้อง');return;}
  if(type==='hull'){
    const lbl=prompt('รายการซ่อมตัวเรือ:','');
    if(!lbl)return;
    if(!m.assets)m.assets=[];
    m.assets.push({type:'hull',label:lbl,detail:'',status:'fixing'});
    flSave();flRenderMaintDetail(jobId);
    return;
  }
  // engine/gearbox/propeller — pick from boat's assets
  const list=type==='engine'?FL_ENGINES.filter(e=>e.boatId===m.boatId):
             type==='gearbox'?FL_GEARBOXES.filter(g=>g.boatId===m.boatId):
             FL_PROPELLERS.filter(p=>{
               const gb=FL_GEARBOXES.find(g=>g.id===p.gearboxId);
               return gb&&gb.boatId===m.boatId;
             });
  if(!list.length){alert(`ไม่มี ${type} ในเรือนี้`);return;}
  const opts=list.map((x,i)=>`${i+1}. ${x.serial}${x.pos?' ('+x.pos+')':''}`).join('\n');
  const pickStr=prompt(`เลือก ${type}:\n${opts}\n\n(พิมพ์เลข):`,'1');
  if(!pickStr)return;
  const idx=parseInt(pickStr)-1;
  if(isNaN(idx)||idx<0||idx>=list.length){alert('เลือกไม่ถูกต้อง');return;}
  const x=list[idx];
  if(!m.assets)m.assets=[];
  const aid=type==='engine'?'engId':type==='gearbox'?'gbId':'propId';
  m.assets.push({type,[aid]:x.id,label:`${x.serial}${x.pos?' · '+x.pos:''}`,detail:`${x.brand||''} ${x.model||''}`.trim(),status:'fixing'});
  flSave();flRenderMaintDetail(jobId);
}

function flCreateMaintFromInc(incId){
  const inc=FL_INCIDENTS.find(x=>x.id===incId);if(!inc)return;
  const navEl=document.querySelector('[data-view="fl-maintenance"]');
  if(navEl) nav(navEl);
  setTimeout(()=>flOpenCreateJobModal(incId),100);
}

// ── Job Choice Modal (single vs split per asset) ──
function flOpenJobChoiceModal(inc){
  const N = (inc.damagedAssets||[]).length;
  const cntEl = document.getElementById('fl-jc-count');
  const cntEl2 = document.getElementById('fl-jc-count-2');
  if(cntEl) cntEl.textContent = N;
  if(cntEl2) cntEl2.textContent = N;
  // Preview of assets
  const _ENG=typeof FL_ENGINES!=='undefined'?FL_ENGINES:[];
  const _GB=typeof FL_GEARBOXES!=='undefined'?FL_GEARBOXES:[];
  const _PR=typeof FL_PROPELLERS!=='undefined'?FL_PROPELLERS:[];
  const labelFor=(a)=>{
    if(a.type==='engine'){const e=a.id?_ENG.find(x=>x.id===a.id):null;return e?e.serial+' · '+(e.pos||''):(a.label||'Engine');}
    if(a.type==='gearbox'){const g=a.id?_GB.find(x=>x.id===a.id):null;return g?g.serial+(g.note?' · '+g.note:''):(a.label||'Gearbox');}
    if(a.type==='propeller'){const p=a.id?_PR.find(x=>x.id===a.id):null;return p?p.serial+(p.note?' · '+p.note:''):(a.label||'Propeller');}
    return a.label||'Hull';
  };
  const preview = document.getElementById('fl-jc-assets-preview');
  if(preview){
    const list = (inc.damagedAssets||[]).map(a => `<span style="display:inline-block;background:#fff;border:1px solid #F0C8B0;padding:2px 8px;border-radius:7px;margin:2px;font-family:'DM Mono',monospace;font-size:10px">${labelFor(a)}</span>`).join('');
    preview.innerHTML = `<strong>Affected assets:</strong> ${list}`;
  }
  openModal('fl-modal-job-choice');
}

function flChooseJobMode(mode){
  // mode = 'single' or 'split'
  window._flJobMode = mode;
  closeModal('fl-modal-job-choice');
  // Re-call save, which will now skip the modal and use the chosen mode
  flSaveCreateJob();
}

function flMaintAddLog(jobId){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m)return;
  const text=document.getElementById('maint-log-text-'+jobId)?.value.trim();
  if(!text)return;
  const by=document.getElementById('maint-log-by-'+jobId)?.value.trim()||'';
  // Read date from input (default to TODAY if empty)
  const dateInput=document.getElementById('maint-log-date-'+jobId);
  const date=(dateInput && dateInput.value) ? dateInput.value : TODAY_STR;
  if(!m.progressLog) m.progressLog=[];
  // Store createdAt (audit trail) — distinct from user-input date
  const entry={date, text, by};
  if(date !== TODAY_STR) entry.createdAt = TODAY_STR;  // backdated indicator
  m.progressLog.push(entry);
  // also push to linked incident
  flPushLog(jobId,text,by,date);
  flSave();flRenderMaintDetail(jobId);
}

// ── Auto-log helper: push log to linked Incident ──
function flPushLog(mjId, text, by, date){
  const mj=FL_MAINT.find(x=>x.id===mjId);if(!mj)return;
  // find linked incident
  const inc=FL_INCIDENTS.find(i=>i.maintId===mjId||i.id===mj.incidentId);
  if(!inc)return;
  if(!inc.progressLog) inc.progressLog=[];
  const logDate = date || TODAY_STR;
  const entry={date:logDate,text,by:by||'ระบบ'};
  if(logDate !== TODAY_STR) entry.createdAt = TODAY_STR;
  inc.progressLog.push(entry);
}

// ── Pin/Unpin Maintenance Job ──
function flMaintTogglePin(id, event){
  if(event) event.stopPropagation();
  const m = FL_MAINT.find(x=>x.id===id);
  if(!m) return;
  if(m.pinned){
    m.pinned = false;
    m.pinnedAt = null;
    flShowToast(`Unpinned: ${m.no}`);
  } else {
    m.pinned = true;
    m.pinnedAt = TODAY_STR;
    flShowToast(`📌 Pinned: ${m.no}`);
  }
  flSave();
  if(typeof flRenderMaint==='function') flRenderMaint();
  if(typeof flRenderMaintDetail==='function' && _selMaintId===id) flRenderMaintDetail(id);
}

// Mounted (not-yet-spare) gearbox/propeller across this job's engine assets
function _flMountedGearProp(m){
  const out=[]; const seenGb=new Set(), seenP=new Set();
  (m.assets||[]).filter(a=>a.type==='engine'&&a.engId).forEach(a=>{
    (FL_GEARBOXES||[]).filter(g=>g.engineId===a.engId && g.status!=='spare').forEach(gb=>{
      if(!seenGb.has(gb.id)){seenGb.add(gb.id);out.push({isGb:true,id:gb.id,label:`เกียร์ · ${gb.serial||''}${gb.note?' · '+gb.note:''}`});}
      (FL_PROPELLERS||[]).filter(p=>p.gearboxId===gb.id && p.status!=='spare').forEach(p=>{
        if(!seenP.has(p.id)){seenP.add(p.id);out.push({isGb:false,id:p.id,label:`ใบจักร · ${p.serial||''}${p.note?' · '+p.note:''}`});}
      });
    });
  });
  return out;
}
// Start guard: when starting an engine repair that has a mounted gearbox/propeller, ask what to do with them.
// Fires for ANY job type (scheduled/preventive/corrective) whose engine asset carries a gearbox/propeller —
// so an engine SWAP can keep the gearbox+propeller on the boat (new engine adopts them).
function flMaintStart(id){
  const m=FL_MAINT.find(x=>x.id===id);if(!m)return;
  const engAssets=(m.assets||[]).filter(a=>a.type==='engine'&&a.engId);
  const parts=_flMountedGearProp(m);
  if(engAssets.length && parts.length){ flStartGearOpen(id,parts); return; }
  _flMaintStartProceed(id);
}
function flStartGearOpen(id,parts){
  const m=FL_MAINT.find(x=>x.id===id)||{};
  window._flStartGear={jobId:id,parts,boatId:m.boatId};
  const cnt=document.getElementById('fl-sg-count'); if(cnt)cnt.textContent=parts.length;
  const list=document.getElementById('fl-sg-list');
  if(list) list.innerHTML=parts.map(p=>`<span style="display:inline-block;background:#fff;border:1px solid #CFE0EF;padding:2px 8px;border-radius:7px;margin:2px;font-size:10px">${p.label}</span>`).join('');
  const sel=document.getElementById('fl-sg-loc'); if(sel) sel.innerHTML=FL_STASH_LOCS.map(l=>`<option value="${l.key}">${l.label}</option>`).join('');
  // reset to stage 1
  const s1=document.getElementById('fl-sg-stage1'), s2=document.getElementById('fl-sg-stage2');
  if(s1)s1.style.display=''; if(s2){s2.style.display='none';s2.innerHTML='';}
  openModal('fl-modal-start-gear');
}
// keep (in-place) / stash-to-spare — original behaviour
function flStartGearChoice(mode){
  const ctx=window._flStartGear; window._flStartGear=null;
  closeModal('fl-modal-start-gear');
  if(!ctx) return;
  const m=FL_MAINT.find(x=>x.id===ctx.jobId); if(!m) return;
  if(mode==='stash'){
    const sel=document.getElementById('fl-sg-loc');
    const locKey=sel?sel.value:'pier:central';
    const locLabel=(FL_STASH_LOCS.find(l=>l.key===locKey)||{}).label||locKey;
    let n=0;
    ctx.parts.forEach(pt=>{
      const rec=pt.isGb?(FL_GEARBOXES||[]).find(g=>g.id===pt.id):(FL_PROPELLERS||[]).find(p=>p.id===pt.id);
      if(!rec)return;
      _flStashPartRecord(rec,pt.isGb,locKey,locLabel,m.no,'');
      n++;
    });
    if(!m.progressLog)m.progressLog=[];
    m.progressLog.push({date:TODAY_STR,text:`📦 ถอดเกียร์/ใบจักร ${n} ชิ้น ไปเก็บที่ ${locLabel} (ตอนเริ่มซ่อม)`,by:'ระบบ'});
  }
  _flMaintStartProceed(ctx.jobId);
}
// SWAP path: detach gearbox/propeller from the outgoing engine → they stay on the boat ("คาเรือ" · onBoatId),
// outgoing engine goes off-boat + fixing, then pick a replacement engine that adopts the waiting gearbox.
function flStartGearSwap(){
  const ctx=window._flStartGear; if(!ctx) return;
  const m=FL_MAINT.find(x=>x.id===ctx.jobId); if(!m) return;
  const engAssets=(m.assets||[]).filter(a=>a.type==='engine'&&a.engId && (!ctx.onlyEngId || a.engId===ctx.onlyEngId));
  ctx.swaps=[];
  engAssets.forEach(a=>{
    const e=flGetEng(a.engId); const pos=e?e.pos:'';
    (FL_GEARBOXES||[]).filter(g=>g.engineId===a.engId).forEach(g=>{
      g.onBoatId=m.boatId; g.onBoatPos=pos; g.engineId=null;
      if(!Array.isArray(g.log))g.log=[];
      g.log.push({type:'detach',date:TODAY_STR,text:`คาเรือ รอเครื่อง · ${(getBoat(m.boatId)||{}).name||''} ${flPosLabel(pos)} · ${m.no}`});
    });
    if(e){ e.boatId=null; e.status='fixing'; if(!Array.isArray(e.log))e.log=[]; e.log.push({type:'remove',date:TODAY_STR,text:`ถอดไปซ่อม · ${m.no}`}); }
    ctx.swaps.push({oldEngId:a.engId, pos:pos, filled:false});
  });
  if(!m.progressLog)m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`▶ เริ่มซ่อม · ถอดเครื่อง ${engAssets.length} ตัว (เกียร์/ใบจักรคาเรือไว้ รอเครื่องใหม่)`,by:'ระบบ'});
  ctx.swap=true;
  if(typeof flSave==='function') flSave();
  flStartSwapRenderPicker();
}
// Render the replacement-engine picker (one outstanding position at a time) inside the same modal
function flStartSwapRenderPicker(){
  const ctx=window._flStartGear; if(!ctx) return;
  const next=(ctx.swaps||[]).find(s=>!s.filled);
  const s1=document.getElementById('fl-sg-stage1'), s2=document.getElementById('fl-sg-stage2');
  if(!next){ flStartSwapFinish(); return; }
  const m=FL_MAINT.find(x=>x.id===ctx.jobId)||{};
  const boat=getBoat(ctx.boatId)||{};
  const outIds=(ctx.swaps||[]).map(s=>s.oldEngId);
  const cands=(FL_ENGINES||[]).filter(e=>!outIds.includes(e.id) && e.boatId!==ctx.boatId && e.status!=='broken');
  cands.sort((a,b)=>(a.boatId?1:0)-(b.boatId?1:0) || String(a.serial).localeCompare(String(b.serial)));
  const opts=cands.map(e=>{ const b=e.boatId?getBoat(e.boatId):null; const loc=b?`${b.name} ${flPosLabel(e.pos)}`:'Spare'; return `<option value="${e.id}">${e.serial} · ${e.brand||''} ${e.model||''} · ${loc}${b?' (Donor)':''}</option>`; }).join('');
  const remain=(ctx.swaps||[]).filter(s=>!s.filled).length;
  const outEng=flGetEng(next.oldEngId)||{};
  const ENG_LOCS=['อู่ซ่อม','คลังกลาง','คลัง Tub Lamu','คลัง Visit Panwa'];
  const curLoc=outEng.spareLocation||m.location||'อู่ซ่อม';
  const locOpts=ENG_LOCS.map(l=>`<option${l===curLoc?' selected':''}>${l}</option>`).join('')+(ENG_LOCS.includes(curLoc)?'':`<option selected>${curLoc}</option>`);
  if(s1)s1.style.display='none';
  if(s2){
    s2.style.display='';
    s2.innerHTML=`
      <div style="background:#FFF8EC;border:1px solid #F0DBB0;border-radius:8px;padding:10px 12px;margin-bottom:12px;font-size:11px;color:#854F0B;line-height:1.6">
        เกียร์ + ใบจักร <b>คาเรือไว้แล้ว</b> ที่ ${boat.name||''} · ${flPosLabel(next.pos)}<br>เลือกเครื่องที่จะมาใส่แทน — เครื่องที่ย้ายมา <b>จะไม่ลากเกียร์/ใบจักรของตัวเองมาด้วย</b>
      </div>
      <div class="form-row" style="margin-bottom:10px"><label class="form-label">เครื่องที่ถอด (${outEng.serial||''}) · ส่งซ่อม/เก็บที่</label><select id="fl-sg-engloc" style="width:100%">${locOpts}</select></div>
      <div class="form-row"><label class="form-label">เครื่องที่จะใส่ · ตำแหน่ง ${flPosLabel(next.pos)}${remain>1?` (เหลืออีก ${remain-1})`:''}</label>
        ${cands.length?`<select id="fl-sg-neweng" style="width:100%">${opts}</select>`:`<div style="font-size:11px;color:#A32D2D;padding:6px 0">ไม่มีเครื่องว่าง/Donor ให้เลือก — กด "ยังไม่ใส่ตอนนี้" แล้วค่อยใส่ที่หลัง</div>`}
      </div>
      <div style="display:flex;gap:8px;margin-top:10px">
        ${cands.length?`<button onclick="flStartSwapInstall()" style="flex:1;background:#0F6E56;color:#fff;border:none;border-radius:10px;padding:12px;font-weight:600;font-size:12px;cursor:pointer">ใส่เครื่องนี้</button>`:''}
        <button onclick="flStartSwapSkip()" style="${cands.length?'':'flex:1;'}background:#fff;border:1.5px solid var(--border);border-radius:10px;padding:12px;font-weight:600;font-size:12px;cursor:pointer;color:var(--ink-soft)">ยังไม่ใส่ตอนนี้</button>
      </div>`;
  }
}
function flStartSwapInstall(){
  const ctx=window._flStartGear; if(!ctx) return;
  const next=(ctx.swaps||[]).find(s=>!s.filled); if(!next) return;
  const m=FL_MAINT.find(x=>x.id===ctx.jobId)||{};
  const sel=document.getElementById('fl-sg-neweng'); const engId=sel?sel.value:null;
  const eNew=flGetEng(engId); if(!eNew){ alert('Please select an engine'); return; }
  // record where the pulled (outgoing) engine is sent for repair / stored
  const _elc=(document.getElementById('fl-sg-engloc')||{}).value;
  const oldE=flGetEng(next.oldEngId);
  if(oldE&&_elc){ oldE.spareLocation=_elc; if(!Array.isArray(oldE.log))oldE.log=[]; oldE.log.push({type:'move',date:TODAY_STR,text:`ส่งซ่อม/เก็บที่ ${_elc} · ${m.no}`}); }
  if(_elc && m && m.id){ m.location=_elc; }  // keep the job's location in sync
  const srcBoat=eNew.boatId, srcPos=eNew.pos;
  // shed the incoming engine's OWN gearbox/propeller → they stay on the source boat (คาเรือ) or go spare
  (FL_GEARBOXES||[]).filter(g=>g.engineId===eNew.id).forEach(g=>{
    if(srcBoat){ g.onBoatId=srcBoat; g.onBoatPos=srcPos; } else { g.onBoatId=null; g.onBoatPos=null; if(g.status!=='spare')g.status='spare'; }
    g.engineId=null;
    if(!Array.isArray(g.log))g.log=[];
    g.log.push({type:'detach',date:TODAY_STR,text: srcBoat?`คาเรือ ${(getBoat(srcBoat)||{}).name||''} (เครื่องย้ายออก) · ${m.no}`:`ไปสแปร์ (เครื่องย้ายออก) · ${m.no}`});
  });
  // install replacement engine at this boat/position
  // The hour meter travels with the engine and is continuous → no need to freeze hours or reset a baseline on swap.
  //   (flEngHours = baseHours + (latest − first meter reading) works across boats automatically.)
  eNew.boatId=ctx.boatId; eNew.pos=next.pos; if(eNew.status==='spare'||!eNew.status) eNew.status='ready';
  if(!Array.isArray(eNew.log))eNew.log=[];
  eNew.log.push({type:'install',date:TODAY_STR,text:`ติดตั้งที่ ${(getBoat(ctx.boatId)||{}).name||''} ${flPosLabel(next.pos)} · ${m.no}`});
  // the waiting gearbox at this position adopts the new engine (propeller follows the gearbox)
  (FL_GEARBOXES||[]).filter(g=>g.onBoatId===ctx.boatId && g.onBoatPos===next.pos && !g.engineId).forEach(g=>{
    g.engineId=eNew.id; g.onBoatId=null; g.onBoatPos=null; if(g.status==='spare')g.status='ready';
    if(!Array.isArray(g.log))g.log=[];
    g.log.push({type:'attach',date:TODAY_STR,text:`เกาะเครื่องใหม่ ${eNew.serial} · ${m.no}`});
  });
  next.filled=true;
  if(!m.progressLog)m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`🔧 ใส่เครื่อง ${eNew.serial} แทนที่ ${flPosLabel(next.pos)}`,by:'ระบบ'});
  if(typeof flSave==='function') flSave();
  flStartSwapRenderPicker();
}
function flStartSwapSkip(){
  const ctx=window._flStartGear;
  if(ctx){
    const _elc=(document.getElementById('fl-sg-engloc')||{}).value;
    (ctx.swaps||[]).filter(s=>!s.filled).forEach(s=>{ s.filled='skipped'; const oe=flGetEng(s.oldEngId); if(oe&&_elc){ oe.spareLocation=_elc; if(!Array.isArray(oe.log))oe.log=[]; oe.log.push({type:'move',date:TODAY_STR,text:`ส่งซ่อม/เก็บที่ ${_elc}`}); } });
  }
  flStartSwapFinish();
}
function flStartSwapFinish(){
  const ctx=window._flStartGear; window._flStartGear=null;
  closeModal('fl-modal-start-gear');
  if(!ctx) return;
  if(typeof flSave==='function') flSave();
  // re-entry (swap from an already-started job) → just refresh the detail; otherwise run the normal Start
  if(ctx.reentry){ if(typeof flRenderMaintDetail==='function') flRenderMaintDetail(ctx.jobId); }
  else { _flMaintStartProceed(ctx.jobId); }
}
// Set/edit the repair location on the job detail → syncs to engines pulled off-boat for this job
function flMaintSetRepairLoc(jobId){
  const m=FL_MAINT.find(x=>x.id===jobId); if(!m) return;
  const inp=document.getElementById('fl-maint-reploc-'+jobId);
  const val=inp?inp.value.trim():'';
  m.location=val;
  let n=0;
  (m.assets||[]).filter(a=>a.engId).forEach(a=>{ const e=flGetEng(a.engId); if(e && (!e.boatId || e.status==='fixing')){ if(val){ e.spareLocation=val; if(!Array.isArray(e.log))e.log=[]; e.log.push({type:'move',date:TODAY_STR,text:`สถานที่ซ่อม → ${val} · ${m.no}`}); n++; } } });
  if(!m.progressLog)m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`📍 ตั้งสถานที่ซ่อม: ${val||'-'}${n?` (อัปเดตเครื่อง ${n} ตัว)`:''}`,by:'ระบบ'});
  if(typeof flSave==='function') flSave();
  if(typeof flRenderMaintDetail==='function') flRenderMaintDetail(jobId);
}
// Swap/pull an engine from an ALREADY-started job (re-entry · not only at Start) — engine row button
function flMaintSwapEngine(jobId, idx){
  const m=FL_MAINT.find(x=>x.id===jobId); if(!m) return;
  const a=(m.assets||[])[idx]; if(!a||!a.engId){ alert('This asset is not an engine'); return; }
  const parts=[];
  (FL_GEARBOXES||[]).filter(g=>g.engineId===a.engId).forEach(gb=>{
    parts.push({isGb:true,id:gb.id,label:`เกียร์ · ${gb.serial||''}${gb.note?' · '+gb.note:''}`});
    (FL_PROPELLERS||[]).filter(p=>p.gearboxId===gb.id).forEach(p=>parts.push({isGb:false,id:p.id,label:`ใบจักร · ${p.serial||''}`}));
  });
  window._flStartGear={jobId:jobId, parts:parts, boatId:m.boatId, reentry:true, onlyEngId:a.engId};
  const cnt=document.getElementById('fl-sg-count'); if(cnt)cnt.textContent=parts.length;
  const list=document.getElementById('fl-sg-list'); if(list) list.innerHTML=parts.map(p=>`<span style="display:inline-block;background:#fff;border:1px solid #CFE0EF;padding:2px 8px;border-radius:7px;margin:2px;font-size:10px">${p.label}</span>`).join('');
  const sel=document.getElementById('fl-sg-loc'); if(sel) sel.innerHTML=FL_STASH_LOCS.map(l=>`<option value="${l.key}">${l.label}</option>`).join('');
  const s1=document.getElementById('fl-sg-stage1'), s2=document.getElementById('fl-sg-stage2');
  if(s1)s1.style.display=''; if(s2){s2.style.display='none';s2.innerHTML='';}
  openModal('fl-modal-start-gear');
  flStartGearSwap(); // go straight to the swap → replacement-engine picker
}
// next calendar day (local · safe from UTC shift)
function _flDayAfter(ds){ const d=new Date(ds+'T12:00:00'); if(isNaN(d)) return ds; d.setDate(d.getDate()+1); const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),dd=String(d.getDate()).padStart(2,'0'); return `${y}-${m}-${dd}`; }
// did this boat already run a trip on a date? (Boat-Op TRIPS or a confirmed sales booking) — so an evening repair doesn't block the morning it already operated
function _flBoatRanOn(boatId, ds){
  if(typeof TRIPS!=='undefined' && TRIPS[ds] && TRIPS[ds][boatId] && TRIPS[ds][boatId].route) return true;
  if(typeof SB_BOOKINGS!=='undefined' && Array.isArray(SB_BOOKINGS)){
    return SB_BOOKINGS.some(bk=>{ if(['cancelled','rejected','cancelled_weather'].includes(bk.status)) return false; if(bkOpsRead(bk,ds).boatId!==boatId) return false; return (bk.trips||[]).some(t=>(t.date||'')===ds); });
  }
  return false;
}
function _flMaintStartProceed(id){
  const m=FL_MAINT.find(x=>x.id===id);if(!m)return;
  m.status='inprogress';
  const b=getBoat(m.boatId);
  // Determine target boat status (new field, fallback to legacy setFixing)
  const targetStatus = m.boatStatus || (m.setFixing===false ? 'available' : 'fixing');
  const targetReason = m.boatStatusReason || '';
  // Only push boat log if status is NOT available
  if(b && targetStatus !== 'available'){
    const cur=getCurStatus(b,TODAY_STR);
    // ⚠ If the boat already ran a trip today (e.g. ran in the morning, reported a fault in the evening),
    //   start the "not available" period TOMORROW so today still counts as operated. Editable afterwards.
    const _ranToday = _flBoatRanOn(b.id, TODAY_STR);
    const _fixFrom = _ranToday ? _flDayAfter(TODAY_STR) : TODAY_STR;
    if(typeof autoClosePrevLog==='function') autoClosePrevLog(b,TODAY_STR);
    b.log.push({
      id:'sl'+Date.now(),
      s:targetStatus,
      from:_fixFrom,to:null,
      loc:m.location||cur.loc||'',
      note:`Maintenance Job ${m.no}${_ranToday?' · วิ่งวันนี้แล้ว · เริ่มไม่พร้อม '+_fixFrom:''}`,
      reason: targetReason
    });
    renderBoats();
  }
  // Only cascade asset status to 'fixing' if boatStatus = fixing
  const cascadeAssetFixing = (targetStatus === 'fixing');

  // log "เริ่มซ่อม" to each affected asset (only set asset status if cascadeAssetFixing)
  (m.assets||[]).forEach(a=>{
    if(a.type==='engine'&&a.engId){
      const eng=flGetEng(a.engId);
      if(eng){
        if(!eng.log)eng.log=[];
        eng.log.push({date:TODAY_STR,type:'service-start',
          desc:`▶ เริ่มซ่อม · ${m.no} · ${m.title}${m.location?' @ '+m.location:''}`,
          detail:a.detail||m.detail||'',hours:flEngHours(eng.id)});
        if(cascadeAssetFixing) eng.status='fixing';
      }
    }
    if(a.type==='gearbox'&&a.gbId){
      const gb=FL_GEARBOXES.find(g=>g.id===a.gbId);
      if(gb){
        if(!gb.log)gb.log=[];
        gb.log.push({date:TODAY_STR,type:'service-start',
          desc:`▶ เริ่มซ่อม · ${m.no} · ${m.title}`,detail:a.detail||''});
        if(cascadeAssetFixing) gb.status='fixing';
      }
    }
    if(a.type==='propeller'&&a.propId){
      const p=FL_PROPELLERS.find(x=>x.id===a.propId);
      if(p){
        if(!p.log)p.log=[];
        p.log.push({date:TODAY_STR,type:'service-start',
          desc:`▶ เริ่มซ่อม · ${m.no} · ${m.title}`,detail:a.detail||''});
        if(cascadeAssetFixing) p.status='fixing';
      }
    }
  });

  const statusLabel = targetStatus==='fixing'?'Fixing':targetStatus==='unavailable'?'Unavailable':'Available';
  flPushLog(m.id,`▶ เริ่มงาน ${m.no} · ${m.title}${m.location?' → '+m.location:''}${b?' · '+b.name+' = '+statusLabel:''}`);
  if(!m.progressLog) m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`▶ Start Job · ${b?b.name+' = '+statusLabel:''}${m.location?' → '+m.location:''}`,by:'ระบบ'});
  flSave();flRenderMaint();
}

function flMaintOpenCloseModal(id){
  const m=FL_MAINT.find(x=>x.id===id);if(!m)return;
  _maintCloseCtx={jobId:id,outcome:'success'};
  document.getElementById('maint-close-job-no').textContent=m.no||'';
  document.getElementById('maint-close-job-title').textContent=m.title||'';
  document.getElementById('maint-close-note').value='';
  // Reset awaiting invoice checkbox
  const cbAwait = document.getElementById('maint-close-await-invoice');
  if(cbAwait) cbAwait.checked = false;
  // reset outcome pills
  document.querySelectorAll('#maint-close-outcome-pills .outcome-pill').forEach((el,i)=>el.classList.toggle('on',i===0));
  openModal('fl-modal-maint-close');
}

let _maintCloseCtx={jobId:null,outcome:'success'};
function flMaintCloseSelectOutcome(val){
  _maintCloseCtx.outcome=val;
  document.querySelectorAll('#maint-close-outcome-pills .outcome-pill').forEach(p=>p.classList.toggle('on',p.dataset.outcome===val));
}

function flMaintCloseConfirm(){
  const {jobId,outcome}=_maintCloseCtx;
  if(!jobId)return;
  const note=document.getElementById('maint-close-note').value.trim();
  const awaitInvoice = !!document.getElementById('maint-close-await-invoice')?.checked;
  closeModal('fl-modal-maint-close');
  flMaintClose(jobId,outcome,note,awaitInvoice);
}

function flMaintClose(id,outcome,note,awaitInvoice){
  const m=FL_MAINT.find(x=>x.id===id);if(!m)return;
  outcome=outcome||'success'; note=note||'';
  m.status='done';m.endDate=TODAY_STR;
  m.outcome=outcome;
  if(note) m.closeNote=note;
  if(awaitInvoice) m.awaitingInvoice = true;
  const b=getBoat(m.boatId);
  const totalCost=flMaintCalcCost(id);

  // Outcome metadata
  const OUTCOME={
    success:    {label:'สำเร็จ',         engStatus:'ready',  gbStatus:'ready',  prStatus:'active',     boatStatus:'available', icon:'✓', tag:''},
    limited:    {label:'ใช้งานจำกัด',     engStatus:'limited',gbStatus:'limited',prStatus:'limited',    boatStatus:'available', icon:'⚠', tag:' · ใช้งานจำกัด'},
    rework:     {label:'ต้องซ่อมซ้ำ',     engStatus:'fixing', gbStatus:'fixing', prStatus:'fixing',     boatStatus:'fixing',    icon:'↻', tag:' · ต้องซ่อมซ้ำ'},
    decommission:{label:'ปลดระวาง',       engStatus:'broken', gbStatus:'broken', prStatus:'broken',     boatStatus:'available', icon:'✕', tag:' · ปลดระวาง'},
    cancelled:  {label:'ยกเลิก',          engStatus:null,     gbStatus:null,     prStatus:null,         boatStatus:'available', icon:'⊘', tag:' · ยกเลิก Job'}
  };
  const out=OUTCOME[outcome]||OUTCOME.success;
  const noteTxt=note?` · "${note}"`:'';

  // restore boat status + log repair to boat history
  if(b){
    const cur=getCurStatus(b,TODAY_STR);
    // Auto-close any open log entries (e.g. fixing from Start Job) before pushing new entry
    if(typeof autoClosePrevLog==='function') autoClosePrevLog(b,TODAY_STR);
    
    // Check if there are OTHER active MJs for this boat (still inprogress)
    const otherActiveMjs = FL_MAINT.filter(x => 
      x.id !== m.id && 
      x.boatId === b.id && 
      x.status === 'inprogress'
    );
    
    let finalBoatStatus = out.boatStatus;
    let finalNote = `ปิด Job ${m.no}${out.tag}`;
    let finalReason = '';
    let skipBoatLog = false;  // flag: ถ้า MJ นี้ไม่เคยแตะ boat status → ไม่ต้อง log การเปลี่ยน

    // ─── เคารพเจตนาเดิมของ MJ ───
    // ถ้า MJ มี setFixing:false (เรือยังใช้งานได้ระหว่างซ่อม) → ตอนปิดก็ไม่ควร force boat status
    // ปลดระวาง = ปลด "อะไหล่ตัวนั้น" (broken) เท่านั้น · ไม่ไปยุ่งสถานะเรือ (เรืออาจมีเครื่องอื่นใช้ได้)
    if(m.setFixing===false){
      // เก็บ boat status ปัจจุบันไว้ (ไม่ override)
      finalBoatStatus = cur.s || 'available';
      finalReason = cur.reason || '';
      // ถ้า status ปัจจุบันเหมือนกับ status ใหม่ → ไม่ต้อง log ใหม่ (เพราะไม่เปลี่ยน)
      if(cur.s === finalBoatStatus){
        skipBoatLog = true;
      }
      finalNote = `ปิด Job ${m.no}${out.tag} · ไม่แตะสถานะเรือ (Job นี้ทำขนานกับการใช้งาน)`;
    } else if(otherActiveMjs.length > 0){
      // Pick the "strictest" status among remaining MJs
      // unavailable > fixing > available
      const others = otherActiveMjs.map(mj => ({
        status: mj.boatStatus || (mj.setFixing===false ? 'available' : 'fixing'),
        reason: mj.boatStatusReason || '',
        no: mj.no, mj: mj
      }));
      // Priority: unavailable > fixing > available
      const hasUnavail = others.find(o => o.status === 'unavailable');
      const hasFixing = others.find(o => o.status === 'fixing');
      const carryOver = hasUnavail || hasFixing || others[0];
      finalBoatStatus = carryOver.status;
      finalReason = carryOver.reason;
      finalNote = `ปิด Job ${m.no}${out.tag} · ยังคงสถานะ ${finalBoatStatus==='fixing'?'Fixing':finalBoatStatus==='unavailable'?'Unavailable':'Available'} จาก Job ${carryOver.no}`;
    }
    
    if(!skipBoatLog){
      b.log.push({
        id:'sl'+Date.now(),
        s:finalBoatStatus,
        from:TODAY_STR, to:null,
        loc:cur.loc||'',
        note:finalNote,
        reason:finalReason
      });
    }
    if(!b.repairHistory) b.repairHistory=[];
    b.repairHistory.push({
      date:TODAY_STR,jobNo:m.no,title:m.title,detail:m.detail||'',
      type:m.type,location:m.location||'',cost:totalCost,
      assets:(m.assets||[]).map(a=>a.label),startDate:m.startDate,endDate:TODAY_STR,
      outcome,closeNote:note
    });
  }

  // log repair details to each asset (apply status based on outcome)
  (m.assets||[]).forEach(a=>{
    if(a.type==='engine'&&a.engId){
      const eng=flGetEng(a.engId);
      if(eng){
        if(!eng.log)eng.log=[];
        eng.log.push({date:TODAY_STR,type:outcome==='cancelled'?'service-cancelled':outcome==='rework'?'rework':'repair',
          desc:`${out.icon} ${out.label} · ${m.no} · ${m.title}${m.location?' @ '+m.location:''}${noteTxt}`,
          detail:m.detail||'',cost:totalCost,hours:flEngHours(eng.id),outcome});
        if(out.engStatus) eng.status=out.engStatus;
        else if(eng.status==='fixing') eng.status='ready';
        // ปลดระวางเครื่อง → ถอดเกียร์ (+ใบจักรที่ติดกับเกียร์) ออกจากเครื่องที่ตายแล้ว
        // เกียร์/ใบจักรมีงานของตัวเอง → ให้ไปตามสถานะ/งานของมันเอง ไม่ผูกกับเครื่องปลดระวาง
        if(outcome==='decommission'){ eng.retired=true; eng.retiredDate=TODAY_STR; eng.retiredReason=note||''; }
        if(outcome==='decommission' && typeof FL_GEARBOXES!=='undefined'){
          FL_GEARBOXES.forEach(gb=>{ if(gb.engineId===eng.id){
            gb.engineId=null;
            if(!gb.log)gb.log=[]; gb.log.push({date:TODAY_STR,type:'remove',desc:`✕ ถอดออกจากเครื่องปลดระวาง · ${m.no} (${a.label})`});
            if(typeof FL_PROPELLERS!=='undefined') FL_PROPELLERS.forEach(pr=>{ if(pr.gearboxId===gb.id){ if(!pr.log)pr.log=[]; pr.log.push({date:TODAY_STR,type:'note',desc:`เครื่องปลดระวาง · ${m.no} · เกียร์ถูกถอดออก`}); } });
          }});
        }
      }
    }
    if(a.type==='gearbox'&&a.gbId){
      const gb=FL_GEARBOXES.find(g=>g.id===a.gbId);
      if(gb){
        const linkedEng=flGetEng(gb.engineId);
        const installH=linkedEng?flEngHours(linkedEng.id):0;
        if(!gb.log)gb.log=[];
        gb.log.push({date:TODAY_STR,type:outcome==='cancelled'?'service-cancelled':outcome==='rework'?'rework':'install',
          desc:`${out.icon} ${out.label} · Job ${m.no}${noteTxt}`,
          engineHours:installH,outcome});
        if(outcome==='success'||outcome==='limited') gb.installHours=installH;
        if(out.gbStatus) gb.status=out.gbStatus;
        else if(gb.status==='fixing') gb.status='ready';
      }
    }
    if(a.type==='propeller'&&a.propId){
      const p=FL_PROPELLERS.find(x=>x.id===a.propId);
      if(p){
        if(!p.log)p.log=[];
        p.log.push({date:TODAY_STR,type:outcome==='cancelled'?'service-cancelled':outcome==='rework'?'rework':'install',
          desc:`${out.icon} ${out.label} · Job ${m.no}${noteTxt}`,outcome});
        if(out.prStatus) p.status=out.prStatus;
        else if(p.status==='fixing') p.status='active';
      }
    }
    if(a.type==='gearbox'&&!a.gbId){
      const gb=FL_GEARBOXES.find(g=>g.serial===a.label||a.label.startsWith(g.serial));
      if(gb){
        if(!gb.log)gb.log=[];
        gb.log.push({date:TODAY_STR,type:'repair',desc:`${out.icon} ${out.label} · ${m.no} · ${m.title}${noteTxt}`,cost:totalCost,outcome});
        if(out.gbStatus) gb.status=out.gbStatus;
        else if(gb.status==='fixing') gb.status='ready';
      }
    }
  });

  flPushLog(m.id,`${out.icon} ปิด Job ${m.no} · ${out.label} · ฿${totalCost.toLocaleString()}${noteTxt}${b?' · '+b.name+' = '+out.boatStatus:''}`);
  if(!m.progressLog)m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`${out.icon} ปิด Job · ${out.label} · ฿${totalCost.toLocaleString()}${noteTxt}${b?' · '+b.name+' = '+out.boatStatus:''}`,by:'ระบบ'});

  // ── Auto-close linked INC ถ้า MJ ทั้งหมดของ INC นั้น done แล้ว (ยกเว้น outcome=cancelled) ──
  if(m.incidentId && outcome !== 'cancelled'){
    const inc = FL_INCIDENTS.find(i=>i.id===m.incidentId);
    if(inc && inc.status !== 'closed'){
      const allLinkedMjs = FL_MAINT.filter(x => x.incidentId === inc.id);
      const allDone = allLinkedMjs.every(x => x.status === 'done' || x.id === m.id);
      if(allDone){
        inc.status = 'closed';
        inc.closedDate = TODAY_STR;
        if(!Array.isArray(inc.progressLog)) inc.progressLog = [];
        inc.progressLog.push({
          date:TODAY_STR,
          text:`✓ ปิด Incident · MJ ${m.no} ${out.label}${noteTxt}`,
          by:'ระบบ'
        });
      }
    }
  }

  // If this is an engine service (oil change) → offer to reset the service-hour baseline for its engines
  if(typeof flMaintServiceReset==='function') flMaintServiceReset(m, outcome);

  flSave();flRenderMaint();renderBoats();flRenderEngList&&flRenderEngList();

  // NOTE: decommission = ปลด "อะไหล่ตัวที่อยู่ใน Job นี้" (broken) เท่านั้น — ไม่ auto-prompt ปลดระวางเรือ
  // ถ้าต้องการปลดระวางทั้งลำ ทำได้จากหน้ารายละเอียดเรือ (flRetireBoat) โดยตรง
}

function flRetireBoat(boatId,reason){
  const b=getBoat(boatId);if(!b)return;
  b.retired=true;
  b.retiredDate=TODAY_STR;
  b.retiredReason=reason||'';
  if(!b.log)b.log=[];
  b.log.push({id:'sl'+Date.now(),s:'retired',from:TODAY_STR,to:null,loc:'',note:`ปลดระวางเรือ${reason?' · '+reason:''}`});
  flSave();renderBoats();flRenderBoatDetailPink&&flRenderBoatDetailPink();
  alert(`✓ เรือ ${b.name} ถูก Mark เป็น Retired แล้ว\nวันที่: ${TODAY_STR}`);
}

function flUnretireBoat(boatId){
  const b=getBoat(boatId);if(!b)return;
  if(!confirm(`กู้คืนเรือ ${b.name} กลับมาใช้งาน?`))return;
  b.retired=false;
  b.unretiredDate=TODAY_STR;
  if(!b.log)b.log=[];
  b.log.push({id:'sl'+Date.now(),s:'available',from:TODAY_STR,to:null,loc:'',note:`กู้คืนเรือกลับมาใช้งาน`});
  flSave();renderBoats();flRenderBoatDetailPink&&flRenderBoatDetailPink();
}

function flMaintAddAsset(jobId,type){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m)return;
  if(!m.assets)m.assets=[];
  let label='',detail='',engId=null,gbId=null,propId=null;
  const dtlEl=document.getElementById(`asset-dtl-${jobId}-${type}`);
  detail=dtlEl?.value.trim()||'';

  if(type==='engine'){
    const sel=document.getElementById(`asset-sel-${jobId}-${type}`);
    const eid=sel?.value;if(!eid){alert('กรุณาเลือกเครื่องยนต์');return;}
    const eng=flGetEng(eid);if(!eng)return;
    engId=eng.id;
    const curH=flEngHours(eng.id);
    label=`${eng.serial} · ${eng.pos||'Spare'}`;
    detail=detail||`${eng.brand} ${eng.model}`;
    if(!eng.log)eng.log=[];
    eng.log.push({date:TODAY_STR,type:'status',desc:`ถอดเพื่อซ่อม · Job ${m.no} · ${getBoat(eng.boatId)?.name||'?'} (${eng.pos})`,hours:curH});
    eng.status='fixing';
    flPushLog(m.id,`🔧 ถอดเครื่องยนต์ ${eng.serial} (${eng.pos}) → Fixing · ${curH}h`);
    if(!m.progressLog)m.progressLog=[];
    m.progressLog.push({date:TODAY_STR,text:`🔧 ถอดเครื่องยนต์ ${eng.serial} (${eng.pos}) → Fixing · เครื่อง ${curH}h`,by:'ระบบ'});

  } else {
    const sel=document.getElementById(`asset-sel-${jobId}-${type}`);
    const lblEl=document.getElementById(`asset-lbl-${jobId}-${type}`);
    if(sel){
      const selId=sel.value;if(!selId){alert('กรุณาเลือก');return;}
      if(type==='gearbox'){
        const gb=FL_GEARBOXES.find(g=>g.id===selId);if(!gb)return;
        gbId=gb.id;
        const linkedEng=flGetEng(gb.engineId);
        const removeH=linkedEng?flEngHours(linkedEng.id):0;
        const usedH=Math.max(0,removeH-(gb.installHours||gb.baseHours||0));
        label=gb.serial;
        detail=detail||`${gb.brand} ${gb.model}${gb.shaftLength?' · '+gb.shaftLength:''}${gb.rotation?' · '+gb.rotation:''}`;
        if(!gb.log)gb.log=[];
        gb.log.push({date:TODAY_STR,type:'remove',
          desc:`ถอดเพื่อซ่อม · Job ${m.no} · ${getBoat(m.boatId)?.name||''}`,
          engineHours:removeH,usedHours:usedH});
        gb.status='fixing';
        flPushLog(m.id,`⚙️ ถอดเกียร์ ${gb.serial} → Fixing · เครื่อง ${removeH}h · เกียร์ใช้งาน ${usedH}h`);
        if(!m.progressLog)m.progressLog=[];
        m.progressLog.push({date:TODAY_STR,text:`⚙️ ถอดเกียร์ ${gb.serial} · เครื่อง ${removeH}h · เกียร์ ${usedH}h`,by:'ระบบ'});

      } else if(type==='propeller'){
        const p=FL_PROPELLERS.find(x=>x.id===selId);if(!p)return;
        propId=p.id;
        label=p.serial;detail=detail||`${p.brand} ${p.size} · ${p.blades} blade · ${p.material}`;
        if(!p.log)p.log=[];
        p.log.push({date:TODAY_STR,type:'remove',desc:`ถอดเพื่อซ่อม · Job ${m.no}`});
        p.status='fixing';
        flPushLog(m.id,`🌀 ถอดใบจักร ${p.serial} → Fixing`);
        if(!m.progressLog)m.progressLog=[];
        m.progressLog.push({date:TODAY_STR,text:`🌀 ถอดใบจักร ${p.serial} → Fixing`,by:'ระบบ'});
      }
    } else {
      label=lblEl?.value.trim()||'';
      if(!label){alert('กรุณากรอกชื่อ/รายละเอียด');return;}
      const typeLabel={gearbox:'เกียร์',propeller:'ใบจักร',hull:'ตัวเรือ'}[type]||type;
      flPushLog(m.id,`+ เพิ่ม ${typeLabel}: ${label}${detail?' — '+detail:''}`);
      if(!m.progressLog)m.progressLog=[];
      m.progressLog.push({date:TODAY_STR,text:`+ เพิ่ม ${typeLabel}: ${label}${detail?' — '+detail:''}`,by:'ระบบ'});
    }
  }

  m.assets.push({type,label,detail,engId,gbId,propId,status:'fixing',addDate:TODAY_STR});
  flSave();flRenderMaintDetail(jobId);flRenderEngList&&flRenderEngList();
}

function flMaintRemoveAsset(jobId,idx){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m||!m.assets)return;
  const a=m.assets[idx];
  if(a.engId){
    const eng=flGetEng(a.engId);
    if(eng){if(!eng.log)eng.log=[];eng.log.push({date:TODAY_STR,type:'status',desc:`ถอดออกจาก Job ${m.no}`,hours:flEngHours(eng.id)});}
    flPushLog(m.id,`− ลบ asset: ${a.label} ออกจาก Job`);
  }
  m.assets.splice(idx,1);
  flSave();flRenderMaintDetail(jobId);
}

// §costDoubleCount (2026-07-30) · ต้นทุนงานซ่อมเคยนับเงินก้อนเดียวสองรอบ
//   เส้นทางปกติของอะไหล่คือ  ตั้ง memo ขออนุมัติซื้อ → รับของเข้าคลัง → เบิกออกมาใช้กับงาน
//   สูตรเดิมบวก partsCost (มูลค่าที่เบิก) + memoCost (เงินที่จ่ายซื้อ) ทั้งที่เป็นของก้อนเดียวกัน
//   MJ-070 เกียร์มีน้ำเข้า · MO-089 มีอะไหล่ 21 รายการ · เบิกจากคลัง 21 รายการ · ชื่อตรงกันครบ 21/21
//   → ฿49,434 + ฿53,703.94 = ฿103,138 ทั้งที่จ่ายจริง ฿53,703.94
//   สแกนทั้งระบบพบ 18 งาน ยอดเกินจริงรวม ฿271,041 (YTD spend เกือบเท่าตัว)
//   กติกาที่ตกลง: นับจาก memo ที่อนุมัติแล้วเป็นหลัก (เป็นเงินที่จ่ายจริง รวม VAT/ส่วนลด)
//   อะไหล่ที่เบิกจะนับก็ต่อเมื่อ "ไม่ได้มาจาก memo ของงานนี้" เช่นเบิกของเก่าในคลังที่ซื้อไว้นานแล้ว
//   จับคู่ด้วยชื่อที่ normalize แล้วแบบตรงตัวเท่านั้น (ตรวจข้อมูลจริง 196/197 รายการเข้าเงื่อนไขนี้
//   ไม่มีเคสที่ต้องเดา) — ไม่ใช้ substring เพราะชื่อสั้นอย่าง "Key" จะไปชนของอื่นแล้วหักเกิน
function _flCostNorm(s){ return String(s||'').toLowerCase().replace(/[\s,\.\-_()\/]/g,''); }
function flMaintCalcCost(id){
  const m=FL_MAINT.find(x=>x.id===id);if(!m)return 0;
  const CNT=['paid','received','approved'];
  const memos=(FL_MEMOS||[]).filter(mo=>mo.maintId===id && CNT.indexOf(mo.status)>=0);
  const memoCost=memos.reduce((s,mo)=>s+(mo.amount||0),0);
  const paidNames=new Set();
  memos.forEach(mo=>{ if(String(mo.memoType||'')!=='parts') return;
    (mo.items||[]).forEach(i=>{ const n=_flCostNorm(i.name||i.desc||i.title); if(n) paidNames.add(n); }); });
  const partsCost=(m.parts||[]).reduce((s,p)=>{
    const n=_flCostNorm(p.name);
    if(n && paidNames.has(n)) return s;          // จ่ายไปแล้วผ่าน memo ของงานนี้ · นับซ้ำไม่ได้
    return s+((p.qty||0)*(p.cost||0));
  },0);
  const total=partsCost+memoCost;
  m.cost=total; // keep cost synced
  return total;
}
// มูลค่าอะไหล่ที่เบิก ซึ่งถูกหักออกเพราะจ่ายผ่าน memo ไปแล้ว · ใช้อธิบายในหน้าจอ
function flMaintPartsCoveredByMemo(m){
  if(!m) return 0;
  const CNT=['paid','received','approved'];
  const paidNames=new Set();
  (FL_MEMOS||[]).filter(mo=>mo.maintId===m.id && CNT.indexOf(mo.status)>=0 && String(mo.memoType||'')==='parts')
    .forEach(mo=>(mo.items||[]).forEach(i=>{ const n=_flCostNorm(i.name||i.desc||i.title); if(n) paidNames.add(n); }));
  return (m.parts||[]).reduce((s,p)=>{
    const n=_flCostNorm(p.name);
    return (n && paidNames.has(n)) ? s+((p.qty||0)*(p.cost||0)) : s;
  },0);
}

// Fill the warehouse dropdown based on the selected part's stocks[]
function flMaintFillLoc(jobId){
  const sel=document.getElementById('maint-inv-sel-'+jobId);
  const locSel=document.getElementById('maint-inv-loc-'+jobId);
  if(!sel||!locSel) return;
  const invId=(window._maintInvLabelMap||{})[sel.value];
  const inv=invId?FL_INVENTORY.find(x=>x.id===invId):null;
  if(!inv){ locSel.innerHTML='<option value="">— Select warehouse —</option>'; return; }
  invSyncLegacy(inv);
  const stocks=(inv.stocks||[]).filter(s=>(s.qty||0)>0);
  if(stocks.length===0){ locSel.innerHTML='<option value="">(no stock in any warehouse)</option>'; return; }
  locSel.innerHTML='<option value="">— Select warehouse —</option>'+
    stocks.map(s=>`<option value="${(s.location||'').replace(/"/g,'&quot;')}">${s.location} (${s.qty} ${inv.unit||''})</option>`).join('');
}

function flMaintAddPart(jobId){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m)return;
  const sel=document.getElementById('maint-inv-sel-'+jobId);
  const locSel=document.getElementById('maint-inv-loc-'+jobId);
  const qtyEl=document.getElementById('maint-inv-qty-'+jobId);
  const invId=(window._maintInvLabelMap||{})[sel?.value];if(!invId){alert('กรุณาเลือกอะไหล่จากรายการ (พิมพ์แล้วเลือกจากที่ขึ้นมา)');return;}
  const location=locSel?.value;if(!location){alert('กรุณาเลือกคลังก่อน');return;}
  const qty=parseInt(qtyEl?.value)||1;
  const inv=FL_INVENTORY.find(x=>x.id===invId);if(!inv)return;
  invSyncLegacy(inv);
  const avail=invQtyAt(inv,location);
  if(qty>avail){alert(`คลังนี้เหลือ ${avail} ${inv.unit||''} เท่านั้น`);return;}
  // deduct from the chosen warehouse's stock entry
  if(!invRemoveAt(inv,location,qty)){alert('หักสต็อกไม่สำเร็จ');return;}
  // log to inventory history
  if(!inv.history) inv.history=[];
  inv.history.push({id:(typeof LA_UID==='function'?LA_UID('h'):'h'+Math.random().toString(36).slice(2)),date:TODAY_STR,type:'withdraw',qty,location,note:`เบิกใช้งาน ${m.no||''} · ${m.title||''} · @ ${location}`+(m.status==='done'?' · ลงย้อนหลัง (งานปิดแล้ว)':''),by:'ระบบ',jobId:m.id});   // §dupNoId
  // add to job parts (merge by part + location)
  if(!m.parts) m.parts=[];
  // §mjLateParts · งานปิดแล้ว = ลงย้อนหลัง · ติดธงไว้ให้แยกออกจากของที่เบิกตอนทำงานจริง
  const _late=(m.status==='done');
  const _lateBy=_late?((typeof laBy==='function'?laBy():'')||(typeof ckMe==='function'?ckMe():'')||''):'';
  const _lateTag=_late?' · ลงย้อนหลังหลังปิดงาน':'';
  const existing=m.parts.find(p=>p.invId===invId && p.location===location && p.date===TODAY_STR && !p.late===!_late);
  if(existing){existing.qty+=qty;}
  else{m.parts.push(Object.assign({id:(typeof LA_UID==='function'?LA_UID('p'):'p'+Math.random().toString(36).slice(2)),invId,name:inv.name,qty,unit:inv.unit,cost:inv.cost,location,date:TODAY_STR}, _late?{late:true,lateBy:_lateBy}:{}));}   // §dupNoId
  flPushLog(jobId,`📦 เบิก ${inv.name} ${qty} ${inv.unit} · ${location} (฿${(qty*inv.cost).toLocaleString()})${_lateTag}`);
  if(!m.progressLog) m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`📦 เบิก ${inv.name} ${qty} ${inv.unit} · ${location} (฿${(qty*inv.cost).toLocaleString()})${_lateTag}`,by:_lateBy||'ระบบ'});
  flMaintCalcCost(jobId); // sync m.cost
  flSave();
  flMaintRefreshParts(jobId); // surgical update · keeps +Withdraw button alive → no scroll jump
}

function flMaintRemovePart(jobId,idx){
  const m=FL_MAINT.find(x=>x.id===jobId);if(!m||!m.parts)return;
  const p=m.parts[idx];
  // return to inventory — to the SAME warehouse it was withdrawn from
  const inv=FL_INVENTORY.find(x=>x.id===p.invId);
  if(inv){
    invSyncLegacy(inv);
    const retLoc=p.location||inv.primaryLocation||inv.location||'คลัง Tub Lamu';
    invAddAt(inv,retLoc,p.qty);
    if(!inv.history) inv.history=[];
    inv.history.push({id:(typeof LA_UID==='function'?LA_UID('h'):'h'+Math.random().toString(36).slice(2)),date:TODAY_STR,type:'receive',qty:p.qty,location:retLoc,note:`คืนสต็อก (ยกเลิกเบิก ${m.no||''}) · @ ${retLoc}`,by:'ระบบ',jobId:m.id});   // §dupNoId
  }
  // §mjLateParts · คืนตอนงานปิดแล้ว = การแก้ย้อนหลังเหมือนกัน · ต้องเห็นใน log
  const _lateR=(m.status==='done')?' · แก้ย้อนหลังหลังปิดงาน':'';
  flPushLog(jobId,`↩ คืนอะไหล่ ${p.name} ${p.qty} ${p.unit} กลับสต็อก${_lateR}`);
  if(!m.progressLog) m.progressLog=[];
  m.progressLog.push({date:TODAY_STR,text:`↩ ยกเลิกเบิก ${p.name} ${p.qty} ${p.unit||''} (คืนสต็อก)${_lateR}`,by:'ระบบ'});
  m.parts.splice(idx,1);
  flMaintCalcCost(jobId); // sync m.cost
  flSave();
  flMaintRefreshParts(jobId); // surgical update · no full re-render → no scroll jump
}

function flMaintUpdateCost(id,val){
  const m=FL_MAINT.find(x=>x.id===id);if(!m)return;
  m.cost=parseFloat(val)||0;flSave();
}

// ── Open memo modal · linked to Project directly (not MJ) ──
let _memoProjectId = null;
function flProjAddMemo(projId){
  const p = flProjGetById(projId);
  if(!p){ alert('Project not found'); return; }
  _memoProjectId = projId;
  _memoMaintId = null;  // clear MJ context
  const boat = BOATS.find(b=>b.id===p.boatId);
  document.getElementById('memo-subject').value = `${p.name} · overhead`;
  const _dE = document.getElementById('memo-date'); if(_dE) _dE.value = TODAY_STR;
  document.getElementById('memo-from').value = 'ท่าเรือภูเก็ต';
  document.getElementById('memo-proposer').value = '';
  const _supE = document.getElementById('memo-supplier'); if(_supE) _supE.value = p.vendor||'';
  if(typeof memoPopulateSupplierList==='function') memoPopulateSupplierList();
  const _ne1 = document.getElementById('memo-note'); if(_ne1) _ne1.value = '';
  document.getElementById('memo-to').value = 'กรรมการผู้จัดการ';
  document.getElementById('memo-ref-box').innerHTML = `
    <div style="font-size:10px;color:var(--ink-soft)">อ้างอิง Project · Overhead</div>
    <div style="font-size:12px;font-weight:500">${p.no} · ${p.name}</div>
    <div style="font-size:10px;color:var(--ink-soft)">${boat?boat.name:'?'} · ${p.planFrom||'?'} → ${p.planTo||'Open'}</div>`;
  _memoItems = [];
  _memoMode = 'quick';
  if(typeof memoSelectType==='function') memoSelectType('labor');
  if(typeof memoSelectScope==='function') memoSelectScope('vessel'); // scope still vessel since boat-related
  if(typeof memoSelectMode==='function') memoSelectMode('quick');
  if(typeof memoRenderItems==='function') memoRenderItems();
  openModal('fl-modal-memo');
}

function flMaintCreateMemo(id, blank){
  _memoEditId=null;   // fresh create — never inherit a prior edit session
  _memoMaintId=id;
  _memoProjectId=null; // ensure project context cleared when creating from MJ
  const m=FL_MAINT.find(x=>x.id===id);if(!m)return;
  const b=getBoat(m.boatId);
  // auto-fill
  document.getElementById('memo-subject').value=m.title;
  const _dE=document.getElementById('memo-date');if(_dE) _dE.value=TODAY_STR;
  document.getElementById('memo-from').value='ท่าเรือภูเก็ต';
  document.getElementById('memo-proposer').value='';
  const _supE=document.getElementById('memo-supplier');if(_supE)_supE.value='';
  memoPopulateSupplierList();
  const _ne1=document.getElementById('memo-note');if(_ne1)_ne1.value='';
  document.getElementById('memo-to').value='กรรมการผู้จัดการ';
  document.getElementById('memo-ref-box').innerHTML=`
    <div style="font-size:10px;color:var(--ink-soft)">อ้างอิง Job</div>
    <div style="font-size:12px;font-weight:500">${m.no} · ${m.title}</div>
    <div style="font-size:10px;color:var(--ink-soft)">${b?b.name:''} · ${flFmtShort(m.startDate)}</div>`;
  // pre-fill items from parts (all parts category) · blank=true → start with no items (manual entry)
  _memoItems = blank ? [] : (m.parts||[]).map(p=>({name:p.name,qty:p.qty,unit:p.unit,price:p.cost,fromInventory:true,category:'parts'}));
  _memoMode='quick';
  memoSelectType('parts');memoSelectScope('vessel');
  memoSelectMode('quick');
  memoRenderItems();
  openModal('fl-modal-memo');
}

function flDeleteMaint(id){
  if(!confirm('ลบ Job นี้?'))return;
  FL_MAINT=FL_MAINT.filter(m=>m.id!==id);
  _selMaintId=null;
  flSave();flRenderMaint();
  document.getElementById('fl-maint-detail').innerHTML='<div class="fl-empty-detail" style="background:var(--white);border:1px solid var(--border);border-radius:var(--r);padding:40px;text-align:center;color:var(--ink-soft)">เลือก Job เพื่อดูรายละเอียด</div>';
}

function flUpdateMaint(id,status){
  const m=FL_MAINT.find(x=>x.id===id);if(!m)return;
  if(status==='inprogress') flMaintStart(id);
  else if(status==='done') flMaintClose(id);
  else {m.status=status;flSave();flRenderMaint();}
}

// ── Create Job Modal ──
let _jobType='corrective';
// Default boat status per MJ type
function _defaultBoatStatusForType(type){
  if(type === 'corrective') return {s:'fixing', reason:''};
  if(type === 'scheduled')  return {s:'unavailable', reason:'scheduled_maint'};
  if(type === 'preventive') return {s:'available', reason:''};
  return {s:'fixing', reason:''};
}

function selectJobType(type,el){
  _jobType=type;
  document.querySelectorAll('.job-type-card').forEach(c=>c.classList.remove('on'));
  el.classList.add('on');
  // Smart default boat status based on type
  const def = _defaultBoatStatusForType(type);
  selectJobStatusByValue(def.s);
  const reasonSel = document.getElementById('job-status-reason');
  if(reasonSel && def.reason) reasonSel.value = def.reason;
  // Show/hide asset picker (preventive/scheduled need it)
  const assetRow = document.getElementById('job-asset-row');
  if(assetRow){
    assetRow.style.display = (type==='preventive' || type==='scheduled') ? '' : 'none';
    if(type==='preventive' || type==='scheduled') populateJobAssetList();
  }
}

// Populate asset checkboxes based on current boat
function populateJobAssetList(){
  const list = document.getElementById('job-asset-list');
  if(!list) return;
  const boatId = document.getElementById('job-boat')?.value;
  if(!boatId){
    list.innerHTML = '<div style="font-size:11px;color:#999;text-align:center;padding:8px">เลือกเรือก่อน · จะแสดง engines/gearboxes/propellers</div>';
    return;
  }
  const engs = (typeof FL_ENGINES!=='undefined'?FL_ENGINES:[]).filter(e=>e.boatId===boatId);
  const gbs = (typeof FL_GEARBOXES!=='undefined'?FL_GEARBOXES:[]).filter(g=>g.boatId===boatId||engs.some(e=>e.id===g.engineId));
  const props = (typeof FL_PROPELLERS!=='undefined'?FL_PROPELLERS:[]).filter(p=>p.boatId===boatId);
  let html = '';
  if(engs.length){
    html += '<div style="font-size:10px;font-weight:600;color:#666;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Engines</div>';
    engs.forEach(e=>{
      html += `<label style="display:flex;align-items:center;gap:8px;padding:5px 0;font-size:11px;cursor:pointer">
        <input type="checkbox" class="job-asset-eng-cb" value="${e.id}" data-label="${e.serial} · ${e.pos||''}">
        ${e.serial} · ${e.pos||''}
      </label>`;
    });
  }
  if(gbs.length){
    html += '<div style="font-size:10px;font-weight:600;color:#666;text-transform:uppercase;letter-spacing:.05em;margin:8px 0 6px">Gearboxes</div>';
    gbs.forEach(g=>{
      html += `<label style="display:flex;align-items:center;gap:8px;padding:5px 0;font-size:11px;cursor:pointer">
        <input type="checkbox" class="job-asset-gb-cb" value="${g.id}" data-label="${g.serial}${g.note?' · '+g.note:''}">
        ${g.serial}${g.note?' · '+g.note:''}
      </label>`;
    });
  }
  if(props.length){
    html += '<div style="font-size:10px;font-weight:600;color:#666;text-transform:uppercase;letter-spacing:.05em;margin:8px 0 6px">Propellers</div>';
    props.forEach(p=>{
      html += `<label style="display:flex;align-items:center;gap:8px;padding:5px 0;font-size:11px;cursor:pointer">
        <input type="checkbox" class="job-asset-prop-cb" value="${p.id}" data-label="${p.serial}${p.note?' · '+p.note:''}">
        ${p.serial}${p.note?' · '+p.note:''}
      </label>`;
    });
  }
  if(!html) html = '<div style="font-size:11px;color:#999;text-align:center;padding:8px">ไม่มี engines/gearboxes/propellers ในเรือนี้</div>';
  list.innerHTML = html;
}

// Picker for boat status during job
let _jobBoatStatus = 'fixing';
function selectJobStatus(st, el){
  _jobBoatStatus = st;
  document.querySelectorAll('.job-st-opt').forEach(c=>{
    c.classList.remove('on');
    c.style.background = 'white';
    c.style.borderColor = 'rgba(0,0,0,.08)';
  });
  el.classList.add('on');
  if(st==='fixing'){ el.style.background='#FDF6E9'; el.style.borderColor='#BA7517'; }
  if(st==='unavailable'){ el.style.background='#FBE9E9'; el.style.borderColor='#A32D2D'; }
  if(st==='available'){ el.style.background='#E6F4ED'; el.style.borderColor='#0F6E56'; }
  const reasonRow = document.getElementById('job-status-reason-row');
  if(reasonRow) reasonRow.style.display = (st==='unavailable') ? '' : 'none';
}

// Programmatic select by value (no element)
function selectJobStatusByValue(st){
  const el = document.querySelector(`.job-st-opt[data-st="${st}"]`);
  if(el) selectJobStatus(st, el);
}

function flOpenCreateJobModal(incId){
  _jobType='corrective';
  document.querySelectorAll('.job-type-card').forEach((c,i)=>c.classList.toggle('on',i===0));
  document.getElementById('job-start-date').value=TODAY_STR;
  document.getElementById('job-title').value='';
  document.getElementById('job-detail').value='';
  document.getElementById('job-location').value='';
  // Set default boat status (corrective → fixing)
  selectJobStatusByValue('fixing');
  const reasonSel = document.getElementById('job-status-reason');
  if(reasonSel) reasonSel.value = '';
  const boatSel=document.getElementById('job-boat');
  boatSel.innerHTML='<option value="">— เลือกเรือ —</option>'+BOATS.filter(b=>b.ownership!=='charter'&&!b.retired).map(b=>`<option value="${b.id}">${b.name}</option>`).join('');
  // Wire change → refresh asset list if preventive/scheduled
  boatSel.onchange = function(){
    if(_jobType==='preventive' || _jobType==='scheduled') populateJobAssetList();
  };
  // Reset asset row + hull input
  const assetRow = document.getElementById('job-asset-row');
  if(assetRow) assetRow.style.display = (_jobType==='preventive' || _jobType==='scheduled') ? '' : 'none';
  const hullInput = document.getElementById('job-asset-hull');
  if(hullInput) hullInput.value = '';
  const incSel=document.getElementById('job-incident');
  incSel.innerHTML='<option value="">— ไม่มี —</option>'+FL_INCIDENTS.filter(i=>!i.maintId||i.id===incId).map(i=>`<option value="${i.id}" ${i.id===incId?'selected':''}>${i.no} · ${i.title}</option>`).join('');
  if(incId){
    const inc=FL_INCIDENTS.find(x=>x.id===incId);
    if(inc){
      boatSel.value=inc.boatId;
      document.getElementById('job-title').value=inc.title;
      document.getElementById('job-detail').value=inc.detail||'';
      _jobType='corrective';
    }
  }
  openModal('fl-modal-create-job');
}
function flSaveCreateJob(){
  const boatId=document.getElementById('job-boat').value;
  const title=document.getElementById('job-title').value.trim();
  const startDate=document.getElementById('job-start-date').value;
  if(!boatId||!title){alert('กรุณาเลือกเรือและกรอกชื่องาน');return;}

  // check for existing active job on same boat
  const activeJobs=FL_MAINT.filter(m=>m.boatId===boatId&&m.status!=='done');
  if(activeJobs.length>0){
    const b=getBoat(boatId);
    const jobList=activeJobs.map(m=>`• ${m.no} (${m.status==='inprogress'?'In Progress':'Pending'})`).join('\n');
    if(!confirm(`เรือ ${b?b.name:''} มี Job ที่ยังเปิดอยู่:\n${jobList}\n\nต้องการสร้าง Job ใหม่เพิ่มหรือไม่?\n(กด OK เพื่อสร้าง · Cancel เพื่อยกเลิก)`)) return;
  }

  const incId=document.getElementById('job-incident').value||null;

  // ─── OPTION B: 1 asset in incident = 1 job ───
  // If INC has ≥2 assets, ask the user via Job Choice modal (deferred via _flJobMode)
  if(incId){
    try {
      const inc=FL_INCIDENTS.find(x=>x.id===incId);
      if(inc&&inc.damagedAssets&&inc.damagedAssets.length>1 && !window._flJobMode){
        // First pass — show modal & wait for choice
        flOpenJobChoiceModal(inc);
        return;
      }
      // Asset label helpers (used by split path)
      const _ENG=typeof FL_ENGINES!=='undefined'?FL_ENGINES:[];
      const _GB=typeof FL_GEARBOXES!=='undefined'?FL_GEARBOXES:[];
      const _PR=typeof FL_PROPELLERS!=='undefined'?FL_PROPELLERS:[];
      const labelFor=(a)=>{
        if(a.type==='engine'){const e=a.id?_ENG.find(x=>x.id===a.id):null;return e?e.serial+' · '+(e.pos||''):(a.label||'Engine');}
        if(a.type==='gearbox'){const g=a.id?_GB.find(x=>x.id===a.id):null;return g?g.serial+(g.note?' · '+g.note:''):(a.label||'Gearbox');}
        if(a.type==='propeller'){const p=a.id?_PR.find(x=>x.id===a.id):null;return p?p.serial+(p.note?' · '+p.note:''):(a.label||'Propeller');}
        return a.label||'Hull';
      };
      const typeLabel={engine:'Engine',gearbox:'Gearbox',propeller:'Propeller',hull:'Hull'};
      const chosenMode = window._flJobMode;  // 'single' or 'split'
      window._flJobMode = null;  // reset for next time

      if(inc&&inc.damagedAssets&&inc.damagedAssets.length>1 && chosenMode==='split'){
        const N=inc.damagedAssets.length;
        const baseTitle=title;
        const detail=document.getElementById('job-detail').value.trim();
        const location=document.getElementById('job-location').value.trim();
        const setFixing=document.getElementById('job-fixing').checked;
        const createdJobs=[];

        // Pre-compute max no. once (multi-asset case · each iter increments)
        let _mjBaseNo = FL_MAINT.length
          ? Math.max(0, ...FL_MAINT.map(m => parseInt(String(m.no||'').replace(/^MJ-/,'')) || 0))
          : 0;

        inc.damagedAssets.forEach((a,idx)=>{
          _mjBaseNo++;
          const jobNo='MJ-'+String(_mjBaseNo).padStart(3,'0');
          const subtitle=`${typeLabel[a.type]||'Asset'} ${labelFor(a)}`;
          const aid=a.type==='engine'?'engId':a.type==='gearbox'?'gbId':a.type==='propeller'?'propId':null;
          const jobAsset={type:a.type,label:a.label||labelFor(a),detail:a.note||a.detail||'',status:'fixing'};
          if(aid&&a.id) jobAsset[aid]=a.id;
          const mj={
            id:LA_UID('mj')+idx,no:jobNo,boatId,type:_jobType,
            title:`${baseTitle} — ${subtitle}`,
            detail,location,status:'pending',startDate,endDate:null,cost:0,
            incidentId:incId,assets:[jobAsset],progressLog:[],setFixing
          };
          flAssertUniqueNo(FL_MAINT, jobNo, 'MJ');
          FL_MAINT.unshift(mj);
          createdJobs.push(mj);
        });

        inc.maintId=createdJobs[0].id;
        inc.relatedMaintIds=createdJobs.map(j=>j.id);
        if(!inc.progressLog) inc.progressLog=[];
        inc.progressLog.push({date:TODAY_STR,text:`+ สร้าง ${createdJobs.length} jobs: ${createdJobs.map(j=>j.no).join(', ')}`,by:'ระบบ'});

        flSave();closeModal('fl-modal-create-job');
        _selMaintId=createdJobs[0].id;flRenderMaint();
        return;
      }
    } catch(err){
      console.error('[Option B 1-asset-per-job error]',err);
      // fall through to single-job path
    }
  }

  // ─── Single job path (Option A or no incident) ───
  // ใช้ max(MJ-XXX) + 1 (ไม่ใช่ length+1) เพื่อป้องกันเลขซ้ำเมื่อมีงานถูกลบไป
  // หรือเมื่อ sequence มี gap (เช่น MJ-009..018 ขาดไปแล้ว · max ยังเป็น MJ-027)
  const _mjMaxNo = FL_MAINT.length
    ? Math.max(0, ...FL_MAINT.map(m => parseInt(String(m.no||'').replace(/^MJ-/,'')) || 0))
    : 0;
  const no='MJ-'+String(_mjMaxNo+1).padStart(3,'0');
  // Copy damaged assets from incident if linked (single unit case)
  let initialAssets=[];
  if(incId){
    const inc=FL_INCIDENTS.find(x=>x.id===incId);
    if(inc&&inc.damagedAssets){
      initialAssets=inc.damagedAssets.map(a=>{
        const aid=a.type==='engine'?'engId':a.type==='gearbox'?'gbId':a.type==='propeller'?'propId':null;
        const obj={type:a.type,label:a.label||'',detail:a.note||a.detail||'',status:'fixing'};
        if(aid&&a.id) obj[aid]=a.id;
        return obj;
      });
    }
  }
  // Preventive/Scheduled jobs: user selects assets manually (no auto-add)
  if(!incId && (_jobType==='preventive' || _jobType==='scheduled')){
    // Asset status mirrors boatStatus: available→ready (just checking), fixing/unavailable→fixing
    const autoAssetStatus = (_jobBoatStatus === 'available') ? 'ready' : 'fixing';
    // Read engine checkboxes
    document.querySelectorAll('.job-asset-eng-cb:checked').forEach(cb=>{
      const id = cb.value;
      const label = cb.getAttribute('data-label') || '';
      initialAssets.push({type:'engine', engId:id, label, detail:'', status:autoAssetStatus});
    });
    // Read gearbox checkboxes
    document.querySelectorAll('.job-asset-gb-cb:checked').forEach(cb=>{
      const id = cb.value;
      const label = cb.getAttribute('data-label') || '';
      initialAssets.push({type:'gearbox', gbId:id, label, detail:'', status:autoAssetStatus});
    });
    // Read propeller checkboxes
    document.querySelectorAll('.job-asset-prop-cb:checked').forEach(cb=>{
      const id = cb.value;
      const label = cb.getAttribute('data-label') || '';
      initialAssets.push({type:'propeller', propId:id, label, detail:'', status:autoAssetStatus});
    });
    // Read hull input (free text · comma-separated)
    const hullRaw = document.getElementById('job-asset-hull')?.value.trim() || '';
    if(hullRaw){
      hullRaw.split(',').map(s=>s.trim()).filter(Boolean).forEach(label=>{
        initialAssets.push({type:'hull', label, detail:'', status:autoAssetStatus});
      });
    }
  }
  // Validate reason if unavailable
  if(_jobBoatStatus === 'unavailable'){
    const reason = document.getElementById('job-status-reason')?.value || '';
    if(!reason){alert('กรุณาเลือกเหตุผลที่ไม่พร้อมใช้งาน');return;}
  }
  const mj={
    id:LA_UID('mj'),no,boatId,type:_jobType,title,
    detail:document.getElementById('job-detail').value.trim(),
    location:document.getElementById('job-location').value.trim(),
    status:'pending',startDate,endDate:null,cost:0,
    incidentId:incId,assets:initialAssets,progressLog:[],
    // Boat status during job
    boatStatus: _jobBoatStatus || 'fixing',
    boatStatusReason: (_jobBoatStatus==='unavailable') ? (document.getElementById('job-status-reason')?.value || '') : '',
    // Legacy compat: setFixing true only if boatStatus is fixing or unavailable
    setFixing: (_jobBoatStatus === 'fixing' || _jobBoatStatus === 'unavailable')
  };
  flAssertUniqueNo(FL_MAINT, no, 'MJ');
  // Link to parent project if creation was triggered from project detail
  if(_projCreateForId){
    mj.parentProjectId = _projCreateForId;
    const _proj = (FL_PROJECTS||[]).find(p=>p.id===_projCreateForId);
    if(_proj){
      if(!_proj.log) _proj.log=[];
      _proj.log.push({date:TODAY_STR, text:`+ Created MJ ${mj.no} · ${mj.title}`, by:'user'});
    }
    mj.progressLog = mj.progressLog||[];
    mj.progressLog.push({date:TODAY_STR, text:`+ Created under project ${_proj?_proj.no:_projCreateForId}`, by:'user'});
  }
  FL_MAINT.unshift(mj);
  if(incId){
    const inc=FL_INCIDENTS.find(x=>x.id===incId);
    if(inc){
      inc.maintId=mj.id;
      if(!inc.progressLog) inc.progressLog=[];
      inc.progressLog.push({date:TODAY_STR,text:`+ สร้าง Job ${mj.no} · ${mj.title}${mj.location?' → '+mj.location:''}`,by:'ระบบ'});
    }
  }
  flSave();closeModal('fl-modal-create-job');
  // If created under a project, return to project detail instead of MJ view
  if(_projCreateForId){
    const pid = _projCreateForId;
    _projCreateForId = null;
    _selProjId = pid;
    if(typeof flRenderProjects==='function') flRenderProjects();
    flShowToast(`Created ${mj.no} under project`);
    return;
  }
  _selMaintId=mj.id;flRenderMaint();
}

// ── INCIDENT ──
let _incStFilter='all', _selIncId=null, _incArchiveTab='active';

function flRenderIncident(){
  const wrap=document.getElementById('fl-inc-pink-wrap');
  if(!wrap)return;
  const dim={bg:'#F4F2EE',ink:'#1A1A1A',ink2:'#666',ink3:'#999',ink4:'#bbb',ink5:'#ccc',line:'rgba(0,0,0,.04)'};
  const SVG_PINK={accent:'#E03B7E',soft:'#FCE5EC',text:'#9F1B4F'};

  const all=FL_INCIDENTS||[];
  const totalInc=all.length;

  // Effective status from linked maint
  const effStatus=(inc)=>{
    // Direct status override — for Quick Fix or any INC manually marked resolved without an MJ
    if(inc.status==='resolved') return 'resolved';
    const mj=inc.maintId?FL_MAINT.find(m=>m.id===inc.maintId):null;
    if(!mj)return 'open';
    if(mj.status==='pending')return 'pending';
    if(mj.status==='inprogress')return 'inprogress';
    return 'resolved';
  };

  const cntOpen=all.filter(x=>effStatus(x)==='open').length;
  const cntPending=all.filter(x=>effStatus(x)==='pending').length;
  const cntInProgress=all.filter(x=>effStatus(x)==='inprogress').length;
  const cntResolved=all.filter(x=>effStatus(x)==='resolved').length;
  const cntActive=cntOpen+cntPending+cntInProgress;
  const cntUnlinked=all.filter(x=>!x.maintId).length;

  // Severity counts
  const cntCritical=all.filter(x=>x.severity==='critical').length;
  const cntMajor=all.filter(x=>x.severity==='major').length;
  const cntMinor=all.filter(x=>x.severity==='minor'||(!x.severity)).length;

  // Boats affected, jobs created, damage total
  const boatsAffected=new Set(all.map(x=>x.boatId).filter(Boolean)).size;
  const jobsCreated=all.filter(x=>x.maintId).length;
  const damageTotal=all.reduce((s,x)=>s+(x.damageCharge||0),0);

  // Avg fix days for resolved
  const todayD=new Date(TODAY_STR);
  const resolvedIncs=all.filter(x=>{
    const mj=x.maintId?FL_MAINT.find(m=>m.id===x.maintId):null;
    return mj&&mj.status==='done';
  });
  const avgFixDays=resolvedIncs.length?Math.round(resolvedIncs.reduce((s,x)=>{
    const mj=FL_MAINT.find(m=>m.id===x.maintId);
    if(!mj?.endDate||!x.date)return s;
    return s+Math.max(1,Math.ceil((new Date(mj.endDate)-new Date(x.date))/86400000));
  },0)/resolvedIncs.length):0;

  // Header bar
  const headerBar=`<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px">
    <div style="display:flex;align-items:center;gap:6px">
      <div style="display:flex;align-items:center;gap:6px;background:white;border:1px solid ${dim.line};border-radius:20px;padding:3px 12px 3px 3px"><div style="width:24px;height:24px;border-radius:50%;background:#A32D2D;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">CR</div><span style="font-size:12px;font-weight:500">Critical · ${cntCritical}</span></div>
      <div style="display:flex;align-items:center;gap:6px;background:white;border:1px solid ${dim.line};border-radius:20px;padding:3px 12px 3px 3px"><div style="width:24px;height:24px;border-radius:50%;background:#BA7517;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">MJ</div><span style="font-size:12px;font-weight:500">Major · ${cntMajor}</span></div>
      <div style="display:flex;align-items:center;gap:6px;background:white;border:1px solid ${dim.line};border-radius:20px;padding:3px 12px 3px 3px"><div style="width:24px;height:24px;border-radius:50%;background:#666;color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">MN</div><span style="font-size:12px;font-weight:500">Minor · ${cntMinor}</span></div>
      <div style="width:32px;height:32px;border-radius:50%;background:${dim.ink};color:white;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600">J</div>
    </div>
    <div style="display:flex;gap:6px">
      <button onclick="flOpenAddIncidentModal()" style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:20px;padding:5px 14px;font-size:11px;font-weight:500;cursor:pointer">+ Log Incident</button>
      <button onclick="flOpenCreateJobModal()" style="background:${dim.ink};color:white;border:none;border-radius:20px;padding:7px 16px;font-size:11px;font-weight:600;cursor:pointer">+ Create Job</button>
    </div>
  </div>`;

  // KPI strip
  const kpiStrip=`<div style="display:grid;grid-template-columns:1.6fr 0.85fr 0.85fr 0.85fr 1fr;gap:8px;margin-bottom:14px;align-items:stretch">
    <div style="grid-column:1;align-self:end;padding-bottom:6px">
      <div style="font-size:13px;font-weight:500;color:${dim.ink4};margin-bottom:2px">Job Assignments</div>
      <div style="display:flex;align-items:baseline;gap:8px;margin-bottom:8px;flex-wrap:wrap">
        <span style="font-size:42px;font-weight:700;letter-spacing:-1.5px;line-height:1">${totalInc}</span>
        <span style="font-size:18px;color:${dim.ink3};font-weight:500">incidents</span>
        <span style="display:inline-flex;align-items:center;background:#A32D2D;color:white;padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600">▴ ${cntActive} active</span>
        ${cntUnlinked?`<span style="display:inline-flex;align-items:center;background:${SVG_PINK.soft};color:${SVG_PINK.text};padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600">${cntUnlinked} unlinked</span>`:''}
      </div>
      <div style="font-size:11px;color:${dim.ink3}">${boatsAffected} boats affected · ${jobsCreated} jobs created · ฿${damageTotal.toLocaleString()} total damage</div>
    </div>

    <div style="grid-column:2;background:white;border-radius:14px;padding:11px 13px;border:2px solid ${cntOpen?'#A32D2D':dim.line}">
      <div style="font-size:10px;color:${dim.ink3}">Open</div>
      <div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="background:#A32D2D;color:white;padding:2px 9px;border-radius:14px;font-size:14px;font-weight:700">${cntOpen}</span><span style="font-size:11px;color:${dim.ink3};margin-left:2px">no job</span></div>
      <div style="font-size:11px;color:#A32D2D;margin-top:7px;font-weight:600">need attention</div>
    </div>

    <div style="grid-column:3;background:white;border-radius:14px;padding:11px 13px;border:2px solid ${(cntPending+cntInProgress)?'#BA7517':dim.line}">
      <div style="font-size:10px;color:${dim.ink3}">In progress</div>
      <div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="background:#BA7517;color:white;padding:2px 9px;border-radius:14px;font-size:14px;font-weight:700">${cntPending+cntInProgress}</span><span style="font-size:11px;color:${dim.ink3};margin-left:2px">active</span></div>
      <div style="font-size:11px;color:#854F0B;margin-top:7px;font-weight:600">linked to jobs</div>
    </div>

    <div style="grid-column:4;background:white;border-radius:14px;padding:11px 13px;border:1px solid ${dim.line}">
      <div style="font-size:10px;color:${dim.ink3}">Resolved</div>
      <div style="display:flex;align-items:baseline;gap:3px;margin-top:2px"><span style="font-size:18px;font-weight:700;line-height:1.2;color:#1D9E75">${cntResolved}</span><span style="font-size:11px;color:${dim.ink3};font-weight:500">closed</span></div>
      <div style="font-size:11px;color:#0F6E56;margin-top:6px;font-weight:600">avg ${avgFixDays} days fix</div>
    </div>

    <div style="grid-column:5;background:${dim.ink};color:white;border-radius:14px;padding:11px 13px">
      <div style="font-size:10px;color:#aaa">By severity</div>
      <div style="display:flex;flex-direction:column;gap:3px;margin-top:4px">
        <div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Critical</span><span style="font-size:11px;font-weight:600;color:${cntCritical?'#FF8FA8':'white'}">${cntCritical} incidents</span></div>
        <div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Major</span><span style="font-size:11px;font-weight:600;color:white">${cntMajor} incidents</span></div>
        <div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Minor</span><span style="font-size:11px;font-weight:600;color:white">${cntMinor} incidents</span></div>
      </div>
    </div>
  </div>`;

  // Split incidents by tab: Active = open/pending/inprogress · Archive = resolved
  const allActiveInc = all.filter(x => effStatus(x) !== 'resolved');
  const allArchiveInc = all.filter(x => effStatus(x) === 'resolved');

  // Filter incidents
  let incs = (_incArchiveTab === 'archive') ? [...allArchiveInc] : [...allActiveInc];
  if(_incStFilter==='open')incs=incs.filter(x=>effStatus(x)==='open');
  else if(_incStFilter==='inprogress')incs=incs.filter(x=>{const e=effStatus(x);return e==='pending'||e==='inprogress';});
  else if(_incStFilter==='resolved')incs=incs.filter(x=>effStatus(x)==='resolved');
  incs.sort((a,b)=>(b.date||'').localeCompare(a.date||''));

  const SEV_STYLE={
    critical:{bg:'#FCEBEB',color:'#A32D2D',label:'CRITICAL',accent:'#A32D2D'},
    major:{bg:'#FAEEDA',color:'#854F0B',label:'MAJOR',accent:'#BA7517'},
    minor:{bg:'#F4F2EE',color:'#666',label:'MINOR',accent:'#666'}
  };
  const ST_STYLE={
    open:{bg:'#FCEBEB',color:'#A32D2D',label:'OPEN',stripe:'#A32D2D'},
    pending:{bg:'#FAEEDA',color:'#854F0B',label:'PENDING',stripe:'#BA7517'},
    inprogress:{bg:'#FAEEDA',color:'#854F0B',label:'IN PROG',stripe:'#BA7517'},
    resolved:{bg:'#1D9E75',color:'white',label:'RESOLVED',stripe:'#1D9E75'}
  };

  const MONTHS_EN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const fmtShortD=(s)=>{if(!s)return'';const d=new Date(s);return`${MONTHS_EN[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;};

  const buildIncRow=(inc)=>{
    const isSel=_selIncId===inc.id;
    const b=getBoat(inc.boatId);
    const mj=inc.maintId?FL_MAINT.find(m=>m.id===inc.maintId):null;
    const sev=SEV_STYLE[inc.severity||'minor']||SEV_STYLE.minor;
    const st=effStatus(inc);
    const ss=ST_STYLE[st]||ST_STYLE.open;
    const prio=inc.priority||0;
    const assetCount=(inc.damagedAssets||[]).length;
    const isResolved=st==='resolved';
    return`<div onclick="flShowInc('${inc.id}')" style="display:flex;gap:10px;padding:10px 8px;border-radius:8px;cursor:pointer;${isSel?`background:${SVG_PINK.soft};border:1px solid #F0C0D0;`:`border-top:0.5px solid ${dim.line};margin-top:2px;`}${isResolved&&!isSel?'opacity:.7;':''}">
      <div style="width:3px;background:${ss.stripe};border-radius:2px;flex-shrink:0;align-self:stretch"></div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:5px;margin-bottom:2px;flex-wrap:wrap">
          <span style="font-size:10px;font-family:'DM Mono',monospace;color:${isSel?SVG_PINK.text:dim.ink3};font-weight:600">${inc.no||'—'}</span>
          <span style="background:${sev.bg};color:${sev.color};padding:1px 6px;border-radius:7px;font-size:9px;font-weight:600">${sev.label}</span>
          ${mj?`<span style="font-size:9px;color:#185FA5">→ ${mj.no}${mj.status==='done'?' ✓':''}</span>`:''}
        </div>
        <div style="font-size:12px;font-weight:${isSel?600:500};color:${dim.ink};overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${b?b.name+' — ':''}${inc.title||'—'}</div>
        <div style="font-size:10px;color:${isSel?SVG_PINK.text:dim.ink3};margin-top:2px;font-family:'DM Mono',monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${fmtShortD(inc.date)}${inc.time?' '+inc.time:''}${assetCount?' · '+assetCount+' asset'+(assetCount>1?'s':''):''}</div>
      </div>
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:3px;flex-shrink:0">
        <span style="background:${ss.bg};color:${ss.color};padding:1px 7px;border-radius:8px;font-size:9px;font-weight:600">${ss.label}</span>
        <div style="display:flex;gap:1px">${Array.from({length:5},(_,i)=>`<span style="display:inline-block;width:5px;height:5px;border-radius:50%;background:${i<prio?'#E24B4A':'#E5E1DA'}"></span>`).join('')}</div>
      </div>
    </div>`;
  };

  const fBtn=(val,label,color)=>{
    const isOn=_incStFilter===val;
    return`<button onclick="incFilterSt('${val}')" style="background:${isOn?dim.ink:'transparent'};color:${isOn?'white':(color||dim.ink2)};border:${isOn?'none':'1px solid rgba(0,0,0,.08)'};border-radius:12px;padding:4px 10px;font-size:10px;font-weight:${isOn?600:500};cursor:pointer">${label}</button>`;
  };

  // Tab buttons: Active / Archive
  const archBtn=(val,label,count)=>{
    const isOn=_incArchiveTab===val;
    return`<button onclick="incSetArchive('${val}')" style="background:${isOn?'white':'transparent'};color:${isOn?dim.ink:dim.ink3};border:none;border-bottom:${isOn?'2px solid '+SVG_PINK.accent:'2px solid transparent'};padding:6px 12px;font-size:11px;font-weight:${isOn?600:500};cursor:pointer;border-radius:0;margin-bottom:-1px">${label} <span style="background:${isOn?SVG_PINK.soft:dim.bg};color:${isOn?SVG_PINK.text:dim.ink3};padding:1px 6px;border-radius:7px;font-size:9px;font-weight:600;margin-left:3px;font-family:'DM Mono',monospace">${count}</span></button>`;
  };

  const tabBar=`<div style="display:flex;border-bottom:1px solid ${dim.line};margin-bottom:8px;gap:0">
    ${archBtn('active','Active',allActiveInc.length)}
    ${archBtn('archive','Archive',allArchiveInc.length)}
  </div>`;

  // Sub-status filter adapts to tab
  let subFilter;
  if(_incArchiveTab === 'active'){
    subFilter = `${fBtn('all','All')}${fBtn('open','Open','#A32D2D')}${fBtn('inprogress','In Progress','#854F0B')}`;
  } else {
    subFilter = `${fBtn('all','All')}${fBtn('resolved','Resolved','#0F6E56')}`;
  }

  const listHtml=incs.length?incs.map(buildIncRow).join(''):`<div style="font-size:12px;color:${dim.ink3};text-align:center;padding:20px">No incidents match filter</div>`;
  const listPanel=`<div style="background:white;border-radius:14px;padding:13px 14px;border:1px solid ${dim.line};max-height:calc(100vh - 360px);overflow-y:auto">
    <div style="display:flex;align-items:center;gap:6px;margin-bottom:10px;padding-bottom:8px;border-bottom:1px solid rgba(0,0,0,.06)">
      <span style="font-size:12px;font-weight:600;flex:1">Incidents</span>
      <span style="font-size:10px;color:${dim.ink3}">${incs.length}/${totalInc}</span>
    </div>
    ${tabBar}
    <div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:8px">
      ${subFilter}
    </div>
    ${listHtml}
  </div>`;

  const detailPanel=`<div id="fl-inc-detail-mount" style="background:white;border-radius:14px;border:1px solid ${dim.line};overflow:hidden;min-height:400px"></div>`;

  wrap.innerHTML=`${headerBar}${kpiStrip}<div style="display:grid;grid-template-columns:380px 1fr;gap:12px;align-items:start">${listPanel}${detailPanel}</div>`;

  flRenderIncDetailPink();
}

function incFilterSt(v){_incStFilter=v;flRenderIncident();}
function incSetArchive(t){
  _incArchiveTab=t;
  _incStFilter='all';
  flRenderIncident();
}

function flShowInc(id){_selIncId=id;flRenderIncident();}
function flSelIncident(id){_selIncId=id;flRenderIncident();}
function flDeleteIncident(id){
  const inc=FL_INCIDENTS.find(x=>x.id===id);
  if(!inc)return;
  const linked=inc.maintId?FL_MAINT.find(m=>m.id===inc.maintId):null;
  let msg='Delete incident '+(inc.no||id)+' permanently? This cannot be undone.';
  if(linked) msg='Incident '+(inc.no||id)+' is linked to job '+(linked.no||'')+'. Deleting the incident will NOT delete the job. Continue?';
  if(!confirm(msg))return;
  const idx=FL_INCIDENTS.findIndex(x=>x.id===id);
  if(idx>=0)FL_INCIDENTS.splice(idx,1);
  if(_selIncId===id)_selIncId=null;
  flSave();
  flRenderIncident();
}

function flRenderIncDetailPink(){
  const mount=document.getElementById('fl-inc-detail-mount');
  if(!mount)return;
  const dim={bg:'#F4F2EE',ink:'#1A1A1A',ink2:'#666',ink3:'#999',ink4:'#bbb',ink5:'#ccc',line:'rgba(0,0,0,.04)'};
  const SVG_PINK={accent:'#E03B7E',soft:'#FCE5EC',text:'#9F1B4F'};

  if(!_selIncId){
    mount.innerHTML=`<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:400px;padding:40px;color:${dim.ink3};gap:10px;text-align:center">
      <div style="font-size:28px;opacity:.25;letter-spacing:.1em">INCIDENT</div>
      <div style="font-size:13px;color:${dim.ink2};font-weight:500">Select an incident to see details</div>
      <div style="font-size:11px;color:${dim.ink3}">Click on the list to see assets, progress, and assignment</div>
    </div>`;
    return;
  }

  const inc=FL_INCIDENTS.find(x=>x.id===_selIncId);
  if(!inc){mount.innerHTML='';return;}

  const b=getBoat(inc.boatId);
  const mj=inc.maintId?FL_MAINT.find(m=>m.id===inc.maintId):null;
  const SEV_STYLE={
    critical:{bg:'#FCEBEB',color:'#A32D2D',label:'CRITICAL',accent:'#A32D2D'},
    major:{bg:'#FAEEDA',color:'#854F0B',label:'MAJOR',accent:'#BA7517'},
    minor:{bg:'#F4F2EE',color:'#666',label:'MINOR',accent:'#666'}
  };
  const ST_STYLE={
    open:{bg:'#FCEBEB',color:'#A32D2D',label:'OPEN'},
    pending:{bg:'#FAEEDA',color:'#854F0B',label:'PENDING JOB'},
    inprogress:{bg:'#FAEEDA',color:'#854F0B',label:'IN PROGRESS'},
    resolved:{bg:'#1D9E75',color:'white',label:'RESOLVED'}
  };
  const sev=SEV_STYLE[inc.severity||'minor']||SEV_STYLE.minor;

  let st='open';
  // Quick Fix / manually-resolved INC (status set on the inc itself, no MJ needed) takes precedence
  if(inc.status==='resolved'){
    st='resolved';
  } else if(mj){
    if(mj.status==='pending')st='pending';
    else if(mj.status==='inprogress')st='inprogress';
    else if(mj.status==='done')st='resolved';
  }
  const ss=ST_STYLE[st]||ST_STYLE.open;

  const MONTHS_EN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const fmtD=(s)=>{if(!s)return'—';const d=new Date(s);return`${MONTHS_EN[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;};

  const noLast3=(inc.no||'').slice(-3).padStart(3,'0');
  const noPrefix=(inc.no||'INC').replace(/[-\d]+$/,'')||'INC';

  // Header strip
  const headerStrip=`<div style="padding:16px 20px;border-bottom:1px solid rgba(0,0,0,.06);background:linear-gradient(to right,#FFF5EC 0%,#FBEAF0 60%,#F5DDE6 100%)">
    <div style="display:flex;align-items:center;gap:10px">
      <div style="width:50px;height:50px;border-radius:12px;background:${sev.accent};color:white;display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0;font-family:'DM Mono',monospace">
        <span style="font-size:9px;opacity:.85">${noPrefix}</span>
        <span style="font-size:13px;font-weight:700;line-height:1">${noLast3}</span>
      </div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <span style="font-size:20px;font-weight:700">${inc.title||'—'}</span>
          <span style="background:${ss.bg};color:${ss.color};padding:2px 9px;border-radius:11px;font-size:10px;font-weight:600;letter-spacing:.04em">${ss.label}</span>
          <span style="background:${sev.accent};color:white;padding:2px 9px;border-radius:11px;font-size:10px;font-weight:600">${sev.label}</span>
        </div>
        <div style="font-size:11px;color:${dim.ink2};margin-top:3px">${b?b.name+' · '+(b.type||'')+' · ':''}${fmtD(inc.date)}${inc.time?' '+inc.time:''}${mj?' · '+mj.no:' · No job linked'}</div>
      </div>
      <div style="display:flex;gap:6px;flex-shrink:0">
        ${(!mj && !inc.quickFix)?`<button onclick="flCreateMaintFromInc('${inc.id}')" style="background:${SVG_PINK.accent};color:white;border:none;border-radius:20px;padding:7px 14px;font-size:11px;font-weight:600;cursor:pointer">→ Create Job</button>`:''}
        <button onclick="flOpenAddIncidentModal('${inc.id}')" style="background:${dim.ink};color:white;border:none;border-radius:20px;padding:7px 14px;font-size:11px;font-weight:600;cursor:pointer">Edit</button>
        <button onclick="flDeleteIncident('${inc.id}')" title="ลบ Incident ถาวร" style="background:white;color:#C0392B;border:1px solid #E2B6B0;border-radius:20px;padding:7px 14px;font-size:11px;font-weight:600;cursor:pointer">ลบ</button>
      </div>
    </div>
  </div>`;

  // 4 stat cards
  const prio=inc.priority||0;
  const PIER_LBL={tublamu:'Tub Lamu',panwa:'Visit Panwa',ranong:'Ranong'};
  const dueD=inc.dueDate?new Date(inc.dueDate):null;
  const today=new Date(TODAY_STR);
  const daysLeft=dueD?Math.ceil((dueD-today)/86400000):null;
  const dueColor=daysLeft==null?dim.ink:daysLeft<0?'#A32D2D':daysLeft<=2?'#A32D2D':daysLeft<=7?'#BA7517':dim.ink;
  const dueText=daysLeft==null?'—':daysLeft<0?`${Math.abs(daysLeft)} days late`:daysLeft===0?'today':`${daysLeft} days left`;
  const prioLbl=prio>=4?'urgent':prio>=3?'high':prio>=2?'medium':prio>=1?'low':'—';
  const statCards=`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">
    <div style="background:${dim.bg};border-radius:10px;padding:10px 12px">
      <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em">Boat</div>
      <div style="font-size:14px;font-weight:700;margin-top:2px;color:#185FA5">${b?b.name:'—'}</div>
      <div style="font-size:10px;color:${dim.ink2}">${b?(b.type||'')+(b.pier?' · '+(PIER_LBL[b.pier]||b.pier):''):''}</div>
    </div>
    <div style="background:${dim.bg};border-radius:10px;padding:10px 12px">
      <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em">Priority</div>
      <div style="display:flex;gap:2px;margin-top:5px;align-items:center">
        ${Array.from({length:5},(_,i)=>`<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${i<prio?'#E24B4A':'#E5E1DA'}"></span>`).join('')}
        <span style="font-size:10px;color:${prio>=4?'#A32D2D':dim.ink2};margin-left:4px;font-weight:600">${prio}/5</span>
      </div>
      <div style="font-size:10px;color:${dim.ink2};margin-top:3px">${prioLbl}</div>
    </div>
    <div style="background:${dim.bg};border-radius:10px;padding:10px 12px">
      <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em">Due date</div>
      <div style="font-size:14px;font-weight:700;font-family:'DM Mono',monospace;margin-top:2px;color:${dueColor}">${dueD?fmtD(inc.dueDate).replace(/, \d+$/,''):'—'}</div>
      <div style="font-size:10px;color:${dueColor}">${dueText}</div>
    </div>
    <div style="background:${dim.bg};border-radius:10px;padding:10px 12px">
      <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em">Damage charge</div>
      <div style="font-size:18px;font-weight:700;font-family:'DM Mono',monospace;margin-top:2px;color:${SVG_PINK.text}">฿${(inc.damageCharge||0).toLocaleString()}</div>
      <div style="font-size:10px;color:${dim.ink2}">est. repair</div>
    </div>
  </div>`;

  // Warning banner if no job, or list of related jobs
  const relatedJobs=(inc.relatedMaintIds||[]).map(id=>FL_MAINT.find(m=>m.id===id)).filter(Boolean);
  const hasMultiple=relatedJobs.length>1;
  let warningBanner;
  if(!mj && inc.quickFix){
    // Quick Fix incidents intentionally have no MJ — show a green confirmation instead of red warning
    warningBanner=`<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:#E1F5EE;border:1px solid #9FE1CB;border-radius:10px">
      <div style="width:8px;height:8px;border-radius:50%;background:#0F6E56;flex-shrink:0"></div>
      <span style="font-size:11px;color:#0F6E56;font-weight:500;flex:1">⚡ <strong>Quick Fix — resolved same-day</strong> · No maintenance job needed${inc.resolvedDate?' · closed '+inc.resolvedDate:''}</span>
    </div>`;
  } else if(!mj){
    warningBanner=`<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:#FCEBEB;border:1px solid #f0c8c5;border-radius:10px">
      <div style="width:8px;height:8px;border-radius:50%;background:#A32D2D;flex-shrink:0"></div>
      <span style="font-size:11px;color:#A32D2D;font-weight:500;flex:1">⚠ <strong>No maintenance job linked yet</strong> — create job to start tracking parts, progress, and costs</span>
      <button onclick="flCreateMaintFromInc('${inc.id}')" style="background:#A32D2D;color:white;border:none;border-radius:14px;padding:5px 12px;font-size:10px;font-weight:600;cursor:pointer">Create now</button>
    </div>`;
  } else if(hasMultiple){
    const JOB_ST={pending:{bg:'#FCEBEB',color:'#A32D2D',label:'PENDING'},inprogress:{bg:'#FAEEDA',color:'#854F0B',label:'IN PROG'},done:{bg:'#1D9E75',color:'white',label:'DONE'}};
    const jobRows=relatedJobs.map(j=>{
      const js=JOB_ST[j.status]||JOB_ST.pending;
      return `<div onclick="if(typeof flSelMaint==='function'){flSelMaint('${j.id}');nav(document.querySelector('[data-view=fl-maintenance]'))}" style="display:flex;align-items:center;gap:8px;padding:8px 12px;border-top:0.5px solid rgba(24,95,165,.15);cursor:pointer">
        <span style="font-size:10px;font-family:'DM Mono',monospace;font-weight:600;color:#185FA5">${j.no}</span>
        <span style="font-size:11px;color:#185FA5;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${j.title}</span>
        <span style="background:${js.bg};color:${js.color};padding:1px 7px;border-radius:8px;font-size:9px;font-weight:600;flex-shrink:0">${js.label}</span>
        <span style="color:#185FA5;font-size:12px">›</span>
      </div>`;
    }).join('');
    warningBanner=`<div style="background:#E6F1FB;border:1px solid #b5d4f4;border-radius:10px;overflow:hidden">
      <div style="display:flex;align-items:center;gap:8px;padding:10px 14px">
        <div style="width:8px;height:8px;border-radius:50%;background:#185FA5;flex-shrink:0"></div>
        <span style="font-size:11px;color:#185FA5;font-weight:600;flex:1">Linked Maintenance: <strong>${relatedJobs.length} jobs</strong> (split by engine unit)</span>
      </div>
      ${jobRows}
    </div>`;
  } else {
    warningBanner=`<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:#E6F1FB;border:1px solid #b5d4f4;border-radius:10px;cursor:pointer" onclick="if(typeof flSelMaint==='function'){flSelMaint('${mj.id}');nav(document.querySelector('[data-view=fl-maintenance]'))}">
      <div style="width:8px;height:8px;border-radius:50%;background:#185FA5;flex-shrink:0"></div>
      <span style="font-size:11px;color:#185FA5;font-weight:500;flex:1">Linked Maintenance: <strong>${mj.no}</strong> · ${mj.title}${mj.startDate?' · '+fmtD(mj.startDate):''}</span>
      <span style="color:#185FA5;font-size:14px">›</span>
    </div>`;
  }

  // Description
  const descSection=inc.detail?`<div>
    <div style="font-size:13px;font-weight:600;margin-bottom:8px">Description</div>
    <div style="background:#FBFAF7;border-radius:10px;padding:12px 14px;font-size:11px;color:${dim.ink2};line-height:1.5">${inc.detail}</div>
  </div>`:'';

  // Damaged assets
  const damaged=inc.damagedAssets||[];
  const TYPE_LBL={engine:'Engine',gearbox:'Gearbox',propeller:'Propeller',hull:'Hull'};
  const damagedRows=damaged.map(a=>{
    const posLbl=a.type==='engine'?'EN':a.type==='gearbox'?'GB':a.type==='propeller'?'PR':'HU';
    const swappable=a.type==='gearbox'||a.type==='propeller';
    return`<div style="background:#FCEBEB;border-radius:10px;padding:10px 14px;display:flex;align-items:center;gap:10px;border:1px solid rgba(163,45,45,.12)">
      <span style="font-size:9px;font-weight:700;color:white;background:#185FA5;padding:2px 7px;border-radius:5px;font-family:'DM Mono',monospace;flex-shrink:0">${posLbl}</span>
      <div style="flex:1;min-width:0">
        <div style="font-size:11px;font-weight:600">${TYPE_LBL[a.type]||'Asset'} · ${a.label||'—'}</div>
        ${a.note?`<div style="font-size:10px;color:#A32D2D;margin-top:1px">${a.note}</div>`:''}
      </div>
      ${a.swapped?`<span style="background:#1D9E75;color:white;padding:1px 7px;border-radius:8px;font-size:9px;font-weight:600">⇄ SWAPPED → ${a.swappedTo||''}</span>`:swappable?`<button onclick="flOpenSwapModal('${inc.id}','${a.type}','${a.id}')" style="background:#185FA5;color:white;border:none;border-radius:8px;padding:3px 8px;font-size:9px;font-weight:600;cursor:pointer">⇄ Swap spare</button>`:`<span style="background:#FAEEDA;color:#854F0B;padding:1px 7px;border-radius:8px;font-size:9px;font-weight:600">DAMAGED</span>`}
    </div>`;
  }).join('');
  const damagedSection=damaged.length?`<div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;justify-content:space-between">
      <span style="font-size:13px;font-weight:600">Damaged assets <span style="color:${dim.ink3};font-weight:400">${damaged.length}</span></span>
    </div>
    <div style="display:flex;flex-direction:column;gap:8px">${damagedRows}</div>
  </div>`:'';

  // Progress timeline — merged from incident's own log + ALL linked maintenance jobs' logs
  const incLog=(inc.progressLog||[]).map(l=>({...l,_fromJob:false}));
  // Collect all linked job IDs (maintId + relatedMaintIds, deduplicated)
  const linkedJobIds=[];
  if(inc.maintId) linkedJobIds.push(inc.maintId);
  if(Array.isArray(inc.relatedMaintIds)) inc.relatedMaintIds.forEach(id=>{if(!linkedJobIds.includes(id))linkedJobIds.push(id);});
  const linkedJobs=linkedJobIds.map(id=>FL_MAINT.find(x=>x.id===id)).filter(Boolean);
  const jobLog=linkedJobs.flatMap(j=>(j.progressLog||[]).map(l=>({...l,_fromJob:true,_jobNo:j.no})));
  // Merge + sort by date desc (newest first); tie-break: incident logs first within same date
  const merged=[...incLog,...jobLog].sort((a,b)=>{
    const da=a.date||'',db=b.date||'';
    if(da!==db) return db.localeCompare(da);
    // same date: incident first, job second
    return (a._fromJob?1:0)-(b._fromJob?1:0);
  });
  const timelineHtml=merged.length?merged.map((l,i,arr)=>{
    const isLast=i===arr.length-1;
    const isFirst=i===0;
    const fromJob=l._fromJob;
    const dotColor=fromJob?'#185FA5':(isFirst?SVG_PINK.accent:'#1D9E75');
    const jobPill=fromJob?`<span style="background:#E6F1FB;color:#185FA5;padding:1px 6px;border-radius:6px;font-size:9px;font-weight:600;margin-right:5px;font-family:'DM Mono',monospace;letter-spacing:.02em">${l._jobNo||'JOB'}</span>`:'';
    const backdated = l.createdAt && l.createdAt !== l.date;
    const backdateBadge = backdated ? `<span title="บันทึกเมื่อ ${l.createdAt}" style="background:rgba(0,0,0,.04);color:${dim.ink3};padding:1px 5px;border-radius:5px;font-size:8px;font-weight:500;margin-left:4px;font-family:'DM Mono',monospace">backdated</span>` : '';
    return`<div style="display:flex;gap:10px;${isLast?'':'margin-bottom:10px'};position:relative">
      ${!isLast?`<div style="position:absolute;left:3.5px;top:11px;bottom:-10px;width:1px;background:rgba(0,0,0,.08)"></div>`:''}
      <div style="width:8px;height:8px;border-radius:50%;background:${dotColor};flex-shrink:0;margin-top:3px;z-index:1;${fromJob?'box-shadow:0 0 0 2px #E6F1FB':''}"></div>
      <div style="flex:1;min-width:0">
        <div style="font-size:11px;font-weight:500;line-height:1.45">${jobPill}${l.text||''}</div>
        <div style="font-size:9px;color:${dim.ink3};margin-top:1px;font-family:'DM Mono',monospace">${l.date||''}${l.by?' · '+l.by:''}${backdateBadge}</div>
      </div>
    </div>`;
  }).join(''):`<div style="font-size:11px;color:${dim.ink3};text-align:center;padding:14px">No progress logged</div>`;
  const timelineSection=`<div>
    <div style="font-size:13px;font-weight:600;margin-bottom:8px;display:flex;align-items:center;gap:8px">Progress timeline${linkedJobs.length?`<span style="font-size:10px;font-weight:500;color:${dim.ink3};display:inline-flex;align-items:center;gap:3px"><span style="width:6px;height:6px;border-radius:50%;background:#185FA5;display:inline-block"></span>linked ${linkedJobs.map(j=>j.no).join(', ')}</span>`:''}</div>
    <div style="background:#FBFAF7;border-radius:10px;padding:12px 14px">${timelineHtml}</div>
    ${st!=='resolved'?`<div style="display:flex;gap:6px;margin-top:8px">
      <input id="log-text-${inc.id}" placeholder="Add progress note..." style="flex:1;background:#FBFAF7;border:1px solid rgba(0,0,0,.06);border-radius:10px;padding:8px 12px;font-size:11px;outline:none;font-family:inherit"/>
      <input id="log-by-${inc.id}" placeholder="By..." style="width:80px;background:#FBFAF7;border:1px solid rgba(0,0,0,.06);border-radius:10px;padding:8px 12px;font-size:11px;outline:none;font-family:inherit"/>
      <button onclick="flAddIncLog('${inc.id}')" style="background:${SVG_PINK.accent};color:white;border:none;border-radius:10px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer">Log</button>
    </div>`:''}
  </div>`;

  // Assignment
  const TYPE_DOT={incident:'#A32D2D',maintenance:'#BA7517',inspection:'#185FA5'};
  const TYPE_TEXT={incident:'Incident · Field failure',maintenance:'Maintenance request',inspection:'Inspection report'};
  const incType=inc.type||'incident';
  const assignmentSection=`<div>
    <div style="font-size:13px;font-weight:600;margin-bottom:8px">Assignment</div>
    <div style="background:#FBFAF7;border-radius:10px;padding:14px;display:flex;flex-direction:column;gap:10px">
      <div>
        <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Assigned to</div>
        <div style="font-size:12px;font-weight:600">${inc.remark||inc.assignee||'—'}</div>
      </div>
      <div>
        <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Reported by</div>
        <div style="font-size:12px;font-weight:500">${inc.reportedBy||'—'}</div>
      </div>
      <div>
        <div style="font-size:10px;color:${dim.ink3};text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Type</div>
        <div style="font-size:11px;font-weight:500;display:flex;align-items:center;gap:5px"><span style="width:8px;height:8px;border-radius:50%;background:${TYPE_DOT[incType]||'#666'}"></span>${TYPE_TEXT[incType]||incType}</div>
      </div>
    </div>
  </div>`;

  mount.innerHTML=`${headerStrip}<div style="padding:16px 20px;display:flex;flex-direction:column;gap:14px;max-height:calc(100vh - 280px);overflow-y:auto">
    ${statCards}
    ${warningBanner}
    ${descSection}
    ${damagedSection}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">${timelineSection}${assignmentSection}</div>
  </div>`;
}

function flAddIncLog(incId){
  const inc=FL_INCIDENTS.find(x=>x.id===incId);if(!inc)return;
  const text=document.getElementById('log-text-'+incId)?.value.trim();
  if(!text)return;
  const by=document.getElementById('log-by-'+incId)?.value.trim()||'';
  if(!inc.progressLog) inc.progressLog=[];
  inc.progressLog.push({date:TODAY_STR,text,by});
  flSave();flShowInc(incId);
}

function flIncUpdateDmgDropdowns(boatId){
  const engs=FL_ENGINES.filter(e=>e.boatId===boatId);
  const gbs=FL_GEARBOXES.filter(g=>g.boatId===boatId);
  const props=FL_PROPELLERS.filter(p=>p.boatId===boatId);
  const e=document.getElementById('fl-inc-dmg-engine');
  const g=document.getElementById('fl-inc-dmg-gearbox');
  const p=document.getElementById('fl-inc-dmg-propeller');
  const buildCheckboxList=(items,prefix,getLabel)=>{
    if(!items.length)return '<div style="color:var(--ink-soft);font-size:10px;text-align:center;padding:6px">ไม่มีรายการ</div>';
    return items.map(x=>`<label style="display:flex;align-items:center;gap:6px;padding:3px 4px;cursor:pointer;border-radius:4px" onmouseover="this.style.background='rgba(0,0,0,.04)'" onmouseout="this.style.background='transparent'"><input type="checkbox" class="dmg-${prefix}-cb" value="${x.id}" onchange="flUpdateDmgCount('${prefix}')" style="margin:0"><span>${getLabel(x)}</span></label>`).join('');
  };
  if(e) e.innerHTML=buildCheckboxList(engs,'engine',x=>`${x.serial} · ${x.pos||''}`);
  if(g) g.innerHTML=buildCheckboxList(gbs,'gearbox',x=>`${x.serial}${x.note?' · '+x.note:''}`);
  if(p) p.innerHTML=buildCheckboxList(props,'propeller',x=>`${x.serial}${x.note?' · '+x.note:''}`);
  // reset counts
  ['engine','gearbox','propeller'].forEach(t=>{
    const cnt=document.getElementById('fl-inc-dmg-'+t+'-count');
    if(cnt)cnt.textContent='';
  });
}

function flUpdateDmgCount(prefix){
  const checked=document.querySelectorAll('.dmg-'+prefix+'-cb:checked').length;
  const el=document.getElementById('fl-inc-dmg-'+prefix+'-count');
  if(el)el.textContent=checked?'('+checked+' รายการ)':'';
}

// ── Quick Swap (Spare exchange during incident) ──
let flSwapCtx={incId:null,assetType:null,assetId:null};
function flOpenSwapModal(incId,assetType,assetId){
  const inc=FL_INCIDENTS.find(x=>x.id===incId);if(!inc)return;
  const boatId=inc.boatId;
  flSwapCtx={incId,assetType,assetId};

  // Find the damaged asset
  const damaged=assetType==='gearbox'?FL_GEARBOXES.find(g=>g.id===assetId):FL_PROPELLERS.find(p=>p.id===assetId);
  if(!damaged){alert('ไม่พบ asset');return;}

  // Find compatible spares
  // - Schema: spare ถูกระบุด้วย spareLocation (truthy) — ไม่ใช่ status='spare' (legacy)
  // - ตัด shop:* ออก (อยู่ร้านซ่อม = ไม่พร้อมใช้)
  // - Business rule (แบบ A · เข้ม): ผูก spare กับ pier ของเรือเท่านั้น · cross-pier ไม่ให้เห็น
  const arr=assetType==='gearbox'?FL_GEARBOXES:FL_PROPELLERS;
  const allSpares=arr.filter(s=>s.spareLocation && !String(s.spareLocation).startsWith('shop:'));
  // Compatibility — relaxed: match brand only (warn if model differs)
  // For propeller: still match size (size IS the model)
  const compat=allSpares.filter(s=>{
    if(assetType==='gearbox') return s.brand===damaged.brand;
    return s.size===damaged.size;
  });
  // Group by location · ภายใต้ pier ของเรือเท่านั้น
  const boatPier=boatId?(getBoat(boatId)?.pier||''):'';
  const onBoat=compat.filter(s=>s.spareLocation===`boat:${boatId}`);
  const samePier=compat.filter(s=>boatPier && s.spareLocation===`pier:${boatPier}`);
  // ❌ ไม่มี otherSpares (cross-pier) — แบบ A ล็อกเฉพาะ pier ของเรือ
  const otherSpares=[];

  const renderSp=(sp,group)=>sp.map(s=>{
    const info=flParseSpareLoc(s.spareLocation);
    const extra=assetType==='gearbox'?'':` · ${s.size} · ${s.rotation||''}`;
    // Model mismatch warning (gearbox only; propeller compat is size-only)
    const modelMatch=assetType==='gearbox'?(s.model===damaged.model):true;
    const warnBadge=!modelMatch?`<span style="background:#FAEEDA;color:#854F0B;padding:2px 6px;border-radius:7px;font-size:9px;font-weight:600;letter-spacing:.02em" title="Model ของ spare ไม่ตรงกับเกียร์ที่พัง · ใส่แทนแล้วอาจไม่เข้ากับตำแหน่ง/ทิศหมุน">⚠ model ต่าง</span>`:'';
    const dimStyle=!modelMatch?'opacity:.78;':'';
    const modelLine=!modelMatch?`<div style="font-size:9.5px;color:#854F0B;margin-top:2px">spare: ${s.model||'?'} · damaged: ${damaged.model||'?'}</div>`:'';
    return`<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid ${modelMatch?'var(--border)':'#f0c875'};border-radius:6px;cursor:pointer;background:${modelMatch?'var(--white)':'#fffaf0'};${dimStyle}transition:all .12s" onmouseover="this.style.background='${modelMatch?'var(--ocean-50)':'#fff6e6'}';this.style.borderColor='${modelMatch?'var(--ocean)':'#d99c2b'}'" onmouseout="this.style.background='${modelMatch?'var(--white)':'#fffaf0'}';this.style.borderColor='${modelMatch?'var(--border)':'#f0c875'}'" onclick="flConfirmSwap('${s.id}')">
      <span style="font-size:14px">${info.icon}</span>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
          <span style="font-family:'DM Mono',monospace;font-size:11px;font-weight:600">${s.serial}${extra}</span>
          ${warnBadge}
        </div>
        <div style="font-size:10px;color:var(--ink-soft);margin-top:1px">${info.label}${s.note?` · ${s.note}`:''}</div>
        ${modelLine}
      </div>
      <span style="font-size:9px;color:${modelMatch?'var(--ocean)':'#854F0B'};font-weight:600;text-transform:uppercase">เลือก</span>
    </div>`;
  }).join('');

  const html=`<div style="margin-bottom:12px">
    <div style="font-size:11px;color:var(--ink-soft);margin-bottom:4px">เปลี่ยนแทน:</div>
    <div style="background:var(--red-light);border:1px solid rgba(196,58,46,.2);border-radius:6px;padding:8px 10px">
      <div style="font-family:'DM Mono',monospace;font-size:11px;font-weight:600;color:var(--red)">${damaged.serial}</div>
      <div style="font-size:10px;color:var(--ink-mid);margin-top:1px">${damaged.brand} ${damaged.model||damaged.size||''} · ${damaged.note||''}</div>
    </div>
  </div>
  ${onBoat.length?`<div style="margin-bottom:12px">
    <div style="font-size:10px;font-weight:600;color:#1c4e7e;text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px">🚢 บนเรือลำนี้ (เร็วที่สุด)</div>
    <div style="display:flex;flex-direction:column;gap:4px">${renderSp(onBoat,'boat')}</div>
  </div>`:''}
  ${samePier.length?`<div style="margin-bottom:12px">
    <div style="font-size:10px;font-weight:600;color:#0e6b87;text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px">🏪 คลังท่าเดียวกัน</div>
    <div style="display:flex;flex-direction:column;gap:4px">${renderSp(samePier,'pier')}</div>
  </div>`:''}
  ${otherSpares.length?`<div style="margin-bottom:12px">
    <div style="font-size:10px;font-weight:600;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px">📦 สแปร์อื่นๆ</div>
    <div style="display:flex;flex-direction:column;gap:4px">${renderSp(otherSpares,'other')}</div>
  </div>`:''}
  ${!onBoat.length && !samePier.length?`<div style="text-align:center;padding:20px;font-size:12px;color:var(--ink-soft);line-height:1.6">
    <div style="font-size:24px;opacity:.3;margin-bottom:8px">📭</div>
    <div style="font-weight:600;color:var(--ink-mid);margin-bottom:3px">ไม่มีสแปร์ ${damaged.brand} ที่ท่านี้</div>
    <div style="font-size:11px">ไม่พบ ${assetType==='gearbox'?'เกียร์':'ใบจักร'} ${damaged.brand} ในคลังท่า ${boatPier==='tublamu'?'Tub Lamu':boatPier==='panwa'?'Visit Panwa':boatPier||'—'} หรือบนเรือลำนี้<br/><span style="color:var(--ink-soft)">ลองขนสแปร์จากท่าอื่นมาก่อนใช้ · หรือเพิ่ม spare ใหม่</span></div>
  </div>`:''}`;

  document.getElementById('fl-swap-body').innerHTML=html;
  document.getElementById('fl-swap-title').textContent=`เลือกสแปร์ ${assetType==='gearbox'?'เกียร์':'ใบจักร'}`;
  openModal('fl-modal-swap');
}
function flConfirmSwap(spareId){
  const {incId,assetType,assetId}=flSwapCtx;
  const inc=FL_INCIDENTS.find(x=>x.id===incId);if(!inc)return;
  const arr=assetType==='gearbox'?FL_GEARBOXES:FL_PROPELLERS;
  const damaged=arr.find(x=>x.id===assetId);
  const spare=arr.find(x=>x.id===spareId);
  if(!damaged||!spare){alert('error');return;}
  if(!confirm(`ยืนยันเปลี่ยน ${damaged.serial} → ${spare.serial}?`))return;

  // Swap: spare takes damaged's position, damaged becomes spare (status=damaged)
  const dBoat=damaged.boatId, dEng=damaged.engineId, dGb=damaged.gearboxId;
  const dNote=damaged.note;
  const dPropPos=damaged.propPos;
  const dSpareLoc=damaged.spareLocation;
  const boatName=getBoat(dBoat)?.name||'';

  // engine hours snapshot for log
  let engHours=null;
  if(assetType==='gearbox'){
    const e=flGetEng(dEng);if(e)engHours=flEngHours(e.id);
  }else{
    const gb=FL_GEARBOXES.find(g=>g.id===dGb);
    const e=gb?flGetEng(gb.engineId):null;
    if(e)engHours=flEngHours(e.id);
  }

  // ── ประวัติของตัวเสียหาย (damaged) ──
  if(!damaged.log)damaged.log=[];
  // Calc usedHours since last install
  const lastInstall=[...damaged.log].reverse().find(l=>l.type==='install');
  const usedHours=lastInstall&&engHours!=null?Math.max(0,engHours-(lastInstall.engineHours||0)):null;
  damaged.log.push({
    date:TODAY_STR,
    type:'remove',
    desc:`ถอดจาก ${boatName} (Incident ${inc.no}) — สลับสแปร์ ${spare.serial}`,
    engineHours:engHours,
    usedHours:usedHours,
    incidentId:inc.id
  });
  damaged.log.push({
    date:TODAY_STR,
    type:'transfer',
    desc:`ส่งซ่อม → อู่ Honda Phuket`,
    incidentId:inc.id
  });

  // ── ประวัติของสแปร์ที่เอามาใส่ (spare → installed) ──
  if(!spare.log)spare.log=[];
  const dEngObj=assetType==='gearbox'?flGetEng(dEng):null;
  const posLabel=assetType==='gearbox'?(dEngObj?.pos||dNote||''):(dPropPos?'· '+dPropPos:'');
  spare.log.push({
    date:TODAY_STR,
    type:'install',
    desc:`ติดตั้งบน ${boatName} ${posLabel} (Quick Swap จาก Incident ${inc.no})`.replace(/\s+/g,' ').trim(),
    engineHours:engHours,
    incidentId:inc.id
  });

  // ── Apply swap ──
  // spare → installed
  spare.boatId=dBoat;
  if(assetType==='gearbox')spare.engineId=dEng;
  else spare.gearboxId=dGb;
  spare.status=assetType==='gearbox'?'ready':'active';
  spare.note=dNote;
  if(assetType==='propeller'&&dPropPos)spare.propPos=dPropPos;
  spare.spareLocation=null;
  // baseHours align with engine for new install cycle
  if(assetType==='gearbox'&&engHours!=null)spare.baseHours=engHours;
  if(assetType==='propeller'&&engHours!=null)spare.installHours=engHours;

  // damaged → out for repair
  damaged.boatId=null;
  if(assetType==='gearbox')damaged.engineId=null;
  else damaged.gearboxId=null;
  damaged.status=assetType==='gearbox'?'fixing':'damaged';
  damaged.spareLocation='shop:honda-phuket'; // default
  damaged.note='ส่งซ่อมจาก '+boatName;

  // Mark in damagedAssets
  if(!inc.damagedAssets)inc.damagedAssets=[];
  const ass=inc.damagedAssets.find(a=>a.type===assetType&&a.id===assetId);
  if(ass){ass.swapped=true;ass.swappedTo=spare.serial;ass.swappedDate=TODAY_STR;}

  // Add progress log
  if(!inc.progressLog)inc.progressLog=[];
  inc.progressLog.push({date:TODAY_STR,text:`เปลี่ยน${assetType==='gearbox'?'เกียร์':'ใบจักร'} ${damaged.serial} → ${spare.serial}`,by:'ระบบ Quick Swap'});

  flSave();
  closeModal('fl-modal-swap');
  // หาก swap gearbox และมีใบจักรผูกอยู่กับเกียร์เดิม → เปิด cascade modal ให้ user เลือก
  if(assetType==='gearbox'){
    const attached=FL_PROPELLERS.filter(p=>p.gearboxId===damaged.id || p._origGearboxId===damaged.id);
    if(attached.length){
      flOpenPropCascadeModal(incId, damaged.id, spare.id, attached.map(p=>p.id), engHours);
      return; // flShowInc จะถูกเรียกหลัง user confirm/cancel cascade
    }
  }
  flShowInc(incId);
}

// ════ Propeller Cascade Modal (หลัง swap gearbox) ════
// เปิดถามว่าจะทำยังไงกับใบจักรที่ผูกกับเกียร์เดิม:
//   - keep   : ย้ายไปติดกับ gearbox สแปร์ (default)
//   - stock  : ถอดเก็บคลัง (เลือก pier)
//   - repair : ส่งซ่อมตามไปกับ gearbox (ติดไปด้วย)
let flPropCascadeCtx={incId:null, damagedGbId:null, spareGbId:null, propIds:[], engHours:null};
function flOpenPropCascadeModal(incId, damagedGbId, spareGbId, propIds, engHours){
  flPropCascadeCtx={incId, damagedGbId, spareGbId, propIds, engHours};
  const damagedGb=FL_GEARBOXES.find(g=>g.id===damagedGbId);
  const spareGb=FL_GEARBOXES.find(g=>g.id===spareGbId);
  const props=propIds.map(id=>FL_PROPELLERS.find(p=>p.id===id)).filter(Boolean);
  const repairShop=damagedGb?.spareLocation||'shop:honda-phuket';
  const repairShopLbl=repairShop.replace('shop:','').replace(/-/g,' ');
  const PIERS=[
    {key:'pier:tublamu', label:'คลัง Tub Lamu'},
    {key:'pier:panwa',   label:'คลัง Visit Panwa'},
    {key:'pier:ranong',  label:'คลัง Ranong'},
    {key:'pier:central', label:'คลังกลาง'}
  ];
  const banner=`<div style="background:#FFF8E1;border:1px solid #F0D58C;border-radius:8px;padding:10px 12px;margin-bottom:14px;font-size:11px;color:#854F0B;line-height:1.55">
    <div style="font-weight:600;margin-bottom:3px">⚠️ ใบจักรที่ผูกอยู่กับเกียร์เดิม</div>
    เกียร์ <strong>${damagedGb?.serial||''}</strong> ถูกถอดออก · มีใบจักรผูกอยู่ <strong>${props.length}</strong> ใบ — กรุณาเลือกการจัดการ
  </div>`;
  const propCards=props.map((p,i)=>{
    return `<div style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:10px;padding:12px;margin-bottom:10px">
      <div style="font-size:12px;font-weight:600;color:var(--ink);margin-bottom:2px">${p.serial}${p.note?' · '+p.note:''}</div>
      <div style="font-size:10px;color:var(--ink-soft);margin-bottom:10px">${p.brand} ${p.size||''} · ${p.rotation||''}</div>
      <div style="display:flex;flex-direction:column;gap:6px" data-prop-id="${p.id}">
        <label style="display:flex;align-items:flex-start;gap:8px;padding:8px 10px;background:#E1F5EE;border:1px solid rgba(29,158,117,.3);border-radius:8px;cursor:pointer">
          <input type="radio" name="cascade-${p.id}" value="keep" checked style="margin-top:2px">
          <div style="flex:1;font-size:11px"><strong>🔄 ย้ายไปติดกับ ${spareGb?.serial||'เกียร์สแปร์'}</strong><div style="color:var(--ink-soft);margin-top:2px;font-size:10px">ถอดออกจากเกียร์เก่า ใส่กลับเข้าเกียร์ใหม่ทันที (recommended)</div></div>
        </label>
        <label style="display:flex;align-items:flex-start;gap:8px;padding:8px 10px;background:#FBFAF7;border:1px solid rgba(0,0,0,.08);border-radius:8px;cursor:pointer">
          <input type="radio" name="cascade-${p.id}" value="stock" style="margin-top:2px">
          <div style="flex:1;font-size:11px"><strong>📦 ถอดเก็บคลัง</strong>
            <select data-stock-pier="${p.id}" style="display:block;margin-top:6px;width:100%;font-size:11px;padding:4px 6px;border:1px solid rgba(0,0,0,.15);border-radius:6px">
              ${PIERS.map(pi=>`<option value="${pi.key}"${pi.key==='pier:tublamu'?' selected':''}>${pi.label}</option>`).join('')}
            </select>
          </div>
        </label>
        <label style="display:flex;align-items:flex-start;gap:8px;padding:8px 10px;background:#FBFAF7;border:1px solid rgba(0,0,0,.08);border-radius:8px;cursor:pointer">
          <input type="radio" name="cascade-${p.id}" value="repair" style="margin-top:2px">
          <div style="flex:1;font-size:11px"><strong>🔧 ส่งซ่อมไปกับเกียร์</strong><div style="color:var(--ink-soft);margin-top:2px;font-size:10px">ติดไปด้วยกัน → ${repairShopLbl}</div></div>
        </label>
      </div>
    </div>`;
  }).join('');
  document.getElementById('fl-prop-cascade-body').innerHTML=banner+propCards;
  openModal('fl-modal-prop-cascade');
}

function flCancelPropCascade(){
  // ผู้ใช้ปิดหรือกด "ข้าม" → ใบจักรยังผูกกับ gearbox เดิม (ไม่เปลี่ยนแปลง)
  const ctx=flPropCascadeCtx;
  closeModal('fl-modal-prop-cascade');
  flPropCascadeCtx={incId:null,damagedGbId:null,spareGbId:null,propIds:[],engHours:null};
  if(ctx.incId) flShowInc(ctx.incId);
}

function flConfirmPropCascade(){
  const ctx=flPropCascadeCtx;
  if(!ctx.incId){closeModal('fl-modal-prop-cascade');return;}
  const inc=FL_INCIDENTS.find(x=>x.id===ctx.incId);
  const damagedGb=FL_GEARBOXES.find(g=>g.id===ctx.damagedGbId);
  const spareGb=FL_GEARBOXES.find(g=>g.id===ctx.spareGbId);
  const repairShop=damagedGb?.spareLocation||'shop:honda-phuket';
  const boatName=damagedGb?(damagedGb._boatNameSnapshot||''):'';
  const summary={keep:0,stock:0,repair:0};
  ctx.propIds.forEach(pid=>{
    const p=FL_PROPELLERS.find(x=>x.id===pid);
    if(!p) return;
    const radio=document.querySelector(`input[name="cascade-${pid}"]:checked`);
    const choice=radio?.value||'keep';
    if(!Array.isArray(p.log)) p.log=[];
    if(choice==='keep'){
      // ย้ายไปติดกับ spare gearbox
      const prevGb=p.gearboxId;
      p.gearboxId=ctx.spareGbId;
      p.log.push({
        date:TODAY_STR, type:'transfer',
        desc:`ถอดจากเกียร์ ${damagedGb?.serial||prevGb} ใส่เข้าเกียร์ ${spareGb?.serial||ctx.spareGbId} (Quick Swap)`,
        engineHours:ctx.engHours, incidentId:ctx.incId
      });
      summary.keep++;
    } else if(choice==='stock'){
      // ถอดเก็บคลัง
      const pierSel=document.querySelector(`select[data-stock-pier="${pid}"]`);
      const targetPier=pierSel?.value||'pier:tublamu';
      const pierLabel={'pier:tublamu':'Tub Lamu','pier:panwa':'Visit Panwa','pier:ranong':'Ranong','pier:central':'คลังกลาง'}[targetPier]||targetPier;
      p.boatId=null;
      p.gearboxId=null;
      p.status='spare';
      p.spareLocation=targetPier;
      p.note=`ถอดจากเกียร์ ${damagedGb?.serial||''} เก็บที่ ${pierLabel}`;
      p.log.push({
        date:TODAY_STR, type:'remove',
        desc:`ถอดจากเกียร์ ${damagedGb?.serial||''} → เก็บคลัง ${pierLabel}`,
        engineHours:ctx.engHours, incidentId:ctx.incId
      });
      summary.stock++;
    } else { // repair
      // ส่งซ่อมตามไปกับ gearbox
      p.boatId=null;
      p.gearboxId=null;
      p.status='fixing';
      p.spareLocation=repairShop;
      p.note=`ส่งซ่อมพร้อมเกียร์ ${damagedGb?.serial||''}`;
      p.log.push({
        date:TODAY_STR, type:'transfer',
        desc:`ส่งซ่อม → ${repairShop.replace('shop:','').replace(/-/g,' ')} (ติดไปกับเกียร์ ${damagedGb?.serial||''})`,
        engineHours:ctx.engHours, incidentId:ctx.incId
      });
      summary.repair++;
    }
  });
  // เพิ่ม progress log ลง incident
  if(inc){
    if(!Array.isArray(inc.progressLog)) inc.progressLog=[];
    const parts=[];
    if(summary.keep) parts.push(`🔄 ย้ายใบจักร ${summary.keep} ใบไปติด ${spareGb?.serial||''}`);
    if(summary.stock) parts.push(`📦 ถอดเก็บคลัง ${summary.stock} ใบ`);
    if(summary.repair) parts.push(`🔧 ส่งซ่อมพร้อมเกียร์ ${summary.repair} ใบ`);
    if(parts.length){
      inc.progressLog.push({date:TODAY_STR, text:'⚙️ จัดการใบจักรหลัง swap: '+parts.join(' · '), by:'ระบบ Quick Swap'});
    }
  }
  flSave();
  closeModal('fl-modal-prop-cascade');
  const incId=ctx.incId;
  flPropCascadeCtx={incId:null,damagedGbId:null,spareGbId:null,propIds:[],engHours:null};
  flShowInc(incId);
}

// ── Move Spare to new location ──
let flMoveCtx={assetType:null,assetId:null};
function flOpenMoveSpare(assetType,assetId){
  const arr=assetType==='gearbox'?FL_GEARBOXES:FL_PROPELLERS;
  const item=arr.find(x=>x.id===assetId);
  if(!item)return;
  flMoveCtx={assetType,assetId};

  const curInfo=flParseSpareLoc(item.spareLocation);
  const subTitle=assetType==='gearbox'
    ?`${item.brand} ${item.model||''}`
    :`${item.brand} ${item.size||''} · ${item.rotation||''}`;

  // Build options
  const pierOpts=[
    {key:'pier:tublamu',label:'คลัง Tub Lamu'},
    {key:'pier:panwa',label:'คลัง Visit Panwa'},
    {key:'pier:central',label:'คลังกลาง'},
  ];
  const boatOpts=BOATS.filter(b=>b.ownership!=='charter'&&!b.retired).map(b=>({key:`boat:${b.id}`,label:`${b.name} (${b.pier==='tublamu'?'Tub Lamu':'Visit Panwa'})`}));
  const shopOpts=[
    {key:'shop:honda-phuket',label:'อู่ Honda Phuket'},
    {key:'shop:suzuki-phuket',label:'อู่ Suzuki Phuket'},
    {key:'shop:prop-shop-phuket',label:'ร้านใบจักร Phuket'},
  ];

  const renderRadio=(opts,groupColor)=>opts.map(o=>{
    const checked=item.spareLocation===o.key?'checked':'';
    return`<label style="display:flex;align-items:center;gap:8px;padding:6px 10px;border:1px solid var(--border);border-radius:6px;cursor:pointer;transition:all .12s;background:var(--white)" onmouseover="this.style.background='var(--ocean-50)'" onmouseout="this.style.background=this.querySelector('input').checked?'var(--ocean-50)':'var(--white)'">
      <input type="radio" name="fl-move-loc" value="${o.key}" ${checked} style="margin:0">
      <span style="font-size:11px;color:var(--ink);flex:1">${o.label}</span>
    </label>`;
  }).join('');

  const groupCard=(title,icon,color,opts)=>`<div style="border:1px solid var(--border);border-radius:8px;padding:10px;background:var(--sand)">
    <div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;font-size:11px;font-weight:600;color:${color}">
      <span>${icon}</span><span>${title}</span>
    </div>
    <div style="display:flex;flex-direction:column;gap:4px">${renderRadio(opts,color)}</div>
  </div>`;

  const html=`
    <div style="margin-bottom:14px;padding:10px 12px;background:var(--sand);border-radius:6px;border:1px solid var(--border)">
      <div style="font-size:10px;color:var(--ink-soft);margin-bottom:2px">ปัจจุบัน:</div>
      <div style="display:flex;align-items:center;gap:6px">
        <span style="font-size:14px">${curInfo.icon}</span>
        <span style="font-size:11px;font-weight:600;color:${curInfo.color}">${curInfo.label}</span>
      </div>
    </div>
    <div style="display:flex;flex-direction:column;gap:8px">
      ${groupCard('คลังท่าเรือ','🏪','#0e6b87',pierOpts)}
      ${groupCard('บนเรือ (พกระหว่างทริป)','🚢','#1c4e7e',boatOpts)}
      ${groupCard('อู่ซ่อม','🔧','#b76e00',shopOpts)}
    </div>
    <div style="margin-top:12px">
      <label style="font-size:10px;color:var(--ink-soft);font-weight:500">หมายเหตุ</label>
      <input type="text" id="fl-move-note" value="${(item.note||'').replace(/"/g,'&quot;')}" placeholder="เช่น พกบนเรือ Aluminous1 ตั้งแต่ ${TODAY_STR}" style="width:100%;font-size:12px;padding:6px 10px;border:1px solid var(--border);border-radius:6px;margin-top:4px">
    </div>`;

  document.getElementById('fl-move-body').innerHTML=html;
  document.getElementById('fl-move-title').textContent=`ย้ายสแปร์: ${item.serial}`;
  document.getElementById('fl-move-sub').textContent=subTitle;
  openModal('fl-modal-move');
}
function flConfirmMove(){
  const {assetType,assetId}=flMoveCtx;
  const arr=assetType==='gearbox'?FL_GEARBOXES:FL_PROPELLERS;
  const item=arr.find(x=>x.id===assetId);
  if(!item){closeModal('fl-modal-move');return;}
  const sel=document.querySelector('input[name="fl-move-loc"]:checked');
  if(!sel){alert('กรุณาเลือก location');return;}
  const newLoc=sel.value;
  const note=document.getElementById('fl-move-note').value.trim();
  const oldLoc=item.spareLocation;
  if(oldLoc===newLoc){closeModal('fl-modal-move');return;}
  const fromInfo=flParseSpareLoc(oldLoc);
  const toInfo=flParseSpareLoc(newLoc);

  // ── เพิ่ม log entry ──
  if(!item.log)item.log=[];
  let logType='transfer';
  let desc=`ย้าย: ${fromInfo.label} → ${toInfo.label}`;
  if(newLoc.startsWith('shop:')&&!oldLoc?.startsWith('shop:')){
    logType='repair';
    desc=`ส่งซ่อม: ${fromInfo.label} → ${toInfo.label}`;
  }else if(oldLoc?.startsWith('shop:')&&!newLoc.startsWith('shop:')){
    logType='repair';
    desc=`รับกลับจากซ่อม: ${fromInfo.label} → ${toInfo.label}`;
  }
  if(note&&note!==item.note)desc+=` · ${note}`;
  item.log.push({date:TODAY_STR,type:logType,desc,fromLoc:oldLoc,toLoc:newLoc});

  // Apply move
  item.spareLocation=newLoc;
  if(note)item.note=note;
  // status: shop → fixing, others → spare
  if(newLoc.startsWith('shop:')){
    item.status='fixing';
  }else{
    item.status='spare';
  }
  flSave();
  closeModal('fl-modal-move');
  if(flAssetTab==='overview')flRenderOverview();
}

