function flSaveAddSpare(){
  const type=document.getElementById('fl-add-spare-type').value;
  const serial=document.getElementById('fl-add-spare-serial').value.trim();
  if(!serial){alert('กรุณากรอก serial');return;}
  const brand=document.getElementById('fl-add-spare-brand').value.trim()||'Honda';
  const note=document.getElementById('fl-add-spare-note').value.trim();
  const loc=document.getElementById('fl-add-spare-loc').value;
  const locInfo=flParseSpareLoc(loc);
  const initLog=[{date:TODAY_STR,type:'purchase',desc:`ลงทะเบียนเข้าระบบ — ${locInfo.label}${note?' · '+note:''}`,toLoc:loc}];

  if(type==='gearbox'){
    const model=document.getElementById('fl-add-spare-model').value.trim()||'BF250D Gearbox';
    // Generate next id
    const ids=FL_GEARBOXES.map(g=>parseInt((g.id||'g0').replace('g',''))||0);
    const newId='g'+(Math.max(...ids,0)+1);
    FL_GEARBOXES.push({id:newId,boatId:null,engineId:null,brand,model,serial,status:loc.startsWith('shop:')?'fixing':'spare',baseHours:0,buyDate:TODAY_STR,note,spareLocation:loc,log:initLog});
  }else{
    const size=document.getElementById('fl-add-spare-size').value.trim()||'15.5×17';
    const rotation=document.getElementById('fl-add-spare-rotation').value;
    const sizeMatch=size.match(/^([\d.]+)[×x]([\d.]+)$/);
    const diameter=sizeMatch?parseFloat(sizeMatch[1]):15.5;
    const pitch=sizeMatch?parseFloat(sizeMatch[2]):17;
    const ids=FL_PROPELLERS.map(p=>parseInt((p.id||'p0').replace('p',''))||0);
    const newId='p'+(Math.max(...ids,0)+1);
    FL_PROPELLERS.push({id:newId,boatId:null,gearboxId:null,brand,serial,diameter,pitch,size,blades:'3',material:'Stainless',rotation,hubSize:'4.75',cupping:'no',cost:8500,status:loc.startsWith('shop:')?'fixing':'spare',buyDate:TODAY_STR,note,spareLocation:loc,log:initLog});
  }
  flSave();
  closeModal('fl-modal-add-spare');
  if(flAssetTab==='overview')flRenderOverview();
}

let _editingIncId=null;

// Toggle handler for "Quick Fix" checkbox in Incident modal
function flIncToggleQuickFix(on){
  const badge = document.getElementById('fl-inc-quickfix-badge');
  if(badge) badge.style.display = on ? 'inline-block' : 'none';
  const causeRow = document.getElementById('fl-inc-cause-row');
  if(causeRow) causeRow.style.display = on ? '' : 'none';
  const saveBtn = document.getElementById('fl-inc-save-btn');
  if(saveBtn){
    if(on){
      saveBtn.textContent = 'บันทึก + ปิดทันที';
      saveBtn.style.background = '#0F6E56';
    } else {
      saveBtn.textContent = 'บันทึก';
      saveBtn.style.background = '';
    }
  }
}

function flOpenAddIncidentModal(incId, opts){
  opts = opts || {};
  const editing = incId && (FL_INCIDENTS||[]).find(i=>i.id===incId);
  _editingIncId = editing ? incId : null;

  // Title
  const titleEl=document.querySelector('#fl-modal-incident .modal-title');
  if(titleEl) titleEl.textContent = editing ? ('แก้ไข Incident · ' + (editing.no||'')) : 'บันทึก Incident';

  // Common boat select
  const boatSel=document.getElementById('fl-inc-boat');
  boatSel.innerHTML=BOATS.filter(b=>b.ownership!=='charter'&&!b.retired).map(b=>`<option value="${b.id}">${b.name}</option>`).join('');
  boatSel.onchange=()=>flIncUpdateDmgDropdowns(boatSel.value);

  if(editing){
    // Pre-fill from existing record
    document.getElementById('fl-inc-date').value=editing.date||TODAY_STR;
    document.getElementById('fl-inc-time').value=editing.time||'';
    document.getElementById('fl-inc-title').value=editing.title||'';
    document.getElementById('fl-inc-detail-input').value=editing.detail||'';
    document.getElementById('fl-inc-remark').value=editing.remark||'';
    const pr=parseInt(editing.priority)||5;
    document.getElementById('fl-inc-priority').value=String(pr);
    const hullEl=document.getElementById('fl-inc-dmg-hull');
    if(hullEl) hullEl.value=(editing.damagedAssets||[]).filter(a=>a.type==='hull').map(a=>a.label).join(', ');
    document.querySelectorAll('#fl-inc-prio-pills .loc-pill').forEach((el,i)=>el.classList.toggle('on',i<pr));
    boatSel.value=editing.boatId;
    flIncUpdateDmgDropdowns(editing.boatId);
    // Re-check damaged assets after dropdowns rendered
    requestAnimationFrame(()=>{
      (editing.damagedAssets||[]).forEach(a=>{
        if(a.type==='hull'||!a.id) return;
        const cbId = a.id || a.gbId || a.propId;
        if(!cbId) return;
        const cb=document.querySelector('.dmg-'+a.type+'-cb[value="'+cbId+'"]');
        if(cb) cb.checked=true;
      });
    });
    // Quick Fix toggle: ON if editing record was quickFix OR status='resolved' (best-effort detection)
    const wasQuick = editing.quickFix===true;
    const qfCb=document.getElementById('fl-inc-quickfix');
    if(qfCb){ qfCb.checked = wasQuick; flIncToggleQuickFix(wasQuick); }
    const causeSel=document.getElementById('fl-inc-cause');
    if(causeSel){
      // Try to parse cause from remark if it starts with "Root cause:"
      const m = (editing.remark||'').match(/Root cause:\s*([a-z_]+)/i);
      causeSel.value = m ? m[1] : '';
    }
  } else {
    // Fresh create
    document.getElementById('fl-inc-date').value=TODAY_STR;
    document.getElementById('fl-inc-time').value='';
    document.getElementById('fl-inc-title').value='';
    document.getElementById('fl-inc-detail-input').value='';
    document.getElementById('fl-inc-remark').value='';
    // Quick Fix default = priority 2 (Minor), regular = 5 (highest)
    const defPr = opts.quickFix ? 2 : 5;
    document.getElementById('fl-inc-priority').value=String(defPr);
    const hullEl=document.getElementById('fl-inc-dmg-hull');if(hullEl)hullEl.value='';
    document.querySelectorAll('#fl-inc-prio-pills .loc-pill').forEach((el,i)=>el.classList.toggle('on',i<defPr));
    // Pre-select boat if provided
    if(opts.boatId){
      boatSel.value=opts.boatId;
    }
    flIncUpdateDmgDropdowns(boatSel.value);
    // Apply Quick Fix toggle preset
    const qfCb=document.getElementById('fl-inc-quickfix');
    if(qfCb){ qfCb.checked = !!opts.quickFix; flIncToggleQuickFix(!!opts.quickFix); }
    const causeSel=document.getElementById('fl-inc-cause');
    if(causeSel) causeSel.value = '';
  }

  openModal('fl-modal-incident');
}
function incSelPrio(val,el){
  document.getElementById('fl-inc-priority').value=val;
  document.querySelectorAll('#fl-inc-prio-pills .loc-pill').forEach((p,i)=>p.classList.toggle('on',i<val));
}
// ════════ Quick Fix INC + Resolve ════════
// "Found → fixed → done" in the unified Incident modal · just toggle ON Quick Fix checkbox
// (consolidated into fl-modal-incident · see flIncToggleQuickFix + flSaveIncident)
function qfOpen(boatId){
  // Open the unified Incident modal with Quick Fix toggle pre-checked + boat pre-selected
  flOpenAddIncidentModal(null, {boatId, quickFix:true});
  setTimeout(()=>{ const t=document.getElementById('fl-inc-title'); if(t) t.focus(); }, 50);
}

function flSaveIncident(){
  const boatId=document.getElementById('fl-inc-boat').value;
  const date=document.getElementById('fl-inc-date').value;
  const time=document.getElementById('fl-inc-time').value;
  const title=document.getElementById('fl-inc-title').value.trim();
  if(!boatId||!date||!title){alert('กรุณากรอกข้อมูลให้ครบ');return;}
  // collect damaged assets (multi-select)
  const damagedAssets=[];
  document.querySelectorAll('.dmg-engine-cb:checked').forEach(cb=>{
    const id=cb.value;const e=flGetEng(id);
    if(e)damagedAssets.push({type:'engine',id,label:`${e.serial} · ${e.pos||''}`});
  });
  document.querySelectorAll('.dmg-gearbox-cb:checked').forEach(cb=>{
    const id=cb.value;const g=FL_GEARBOXES.find(x=>x.id===id);
    if(g)damagedAssets.push({type:'gearbox',id,label:`${g.serial}${g.note?' · '+g.note:''}`});
  });
  document.querySelectorAll('.dmg-propeller-cb:checked').forEach(cb=>{
    const id=cb.value;const p=FL_PROPELLERS.find(x=>x.id===id);
    if(p)damagedAssets.push({type:'propeller',id,label:`${p.serial}${p.note?' · '+p.note:''}`});
  });
  const dmgHullRaw=document.getElementById('fl-inc-dmg-hull')?.value.trim()||'';
  if(dmgHullRaw){
    dmgHullRaw.split(',').map(s=>s.trim()).filter(Boolean).forEach(label=>{
      damagedAssets.push({type:'hull',id:null,label});
    });
  }
  const remark=document.getElementById('fl-inc-remark').value.trim();
  const detail=document.getElementById('fl-inc-detail-input').value.trim();
  const priority=parseInt(document.getElementById('fl-inc-priority').value)||5;
  const severity=priority>=4?'critical':priority>=3?'major':'minor';

  // ── EDIT MODE — update existing incident ──
  if(_editingIncId){
    const existing=FL_INCIDENTS.find(i=>i.id===_editingIncId);
    if(existing){
      existing.boatId=boatId;
      existing.date=date;
      existing.time=time;
      existing.title=title;
      existing.detail=detail;
      existing.remark=remark;
      existing.damagedAssets=damagedAssets;
      existing.priority=priority;
      existing.severity=severity;
      if(!existing.progressLog) existing.progressLog=[];
      existing.progressLog.push({date:TODAY_STR,text:`✎ แก้ไขรายละเอียด${damagedAssets.length?' · ความเสียหาย: '+damagedAssets.map(a=>a.label).join(', '):''}`,by:remark||'ระบบ'});
    }
    _editingIncId=null;
    flSave();closeModal('fl-modal-incident');flRenderIncident();
    return;
  }

  // ── CREATE MODE — new incident ──
  const isQuickFix = !!document.getElementById('fl-inc-quickfix')?.checked;
  const cause = document.getElementById('fl-inc-cause')?.value || '';

  const _incMaxNo = FL_INCIDENTS.length
    ? Math.max(0, ...FL_INCIDENTS.map(i => parseInt(String(i.no||'').replace(/^INC-/,'')) || 0))
    : 0;
  const no='INC-'+String(_incMaxNo+1).padStart(3,'0');

  // Build remark — prepend Root cause if specified
  const remarkParts = [];
  if(cause) remarkParts.push(`Root cause: ${cause}`);
  if(remark) remarkParts.push(remark);
  if(isQuickFix) remarkParts.push('Quick Fix · resolved same-day · no maintenance job');
  const remarkFinal = remarkParts.join(' · ');

  // Build progress log
  const progressLog = [{date, text:`เปิด Incident: ${title}${damagedAssets.length?' · ความเสียหาย: '+damagedAssets.map(a=>a.label).join(', '):''}`, by:remark||'ระบบ'}];
  if(isQuickFix){
    progressLog.push({date, text:`✓ ปิดทันที (Quick Fix)${cause?' · Root cause: '+cause:''}${detail?' · '+detail.slice(0,140)+(detail.length>140?'…':''):''}`, by:''});
  }

  const inc={
    id:LA_UID('inc'), no, boatId, date, time, title,
    detail, remark:remarkFinal, damagedAssets, priority, severity,
    type:'incident',
    status: isQuickFix ? 'resolved' : 'open',
    maintId:null,
    quickFix: isQuickFix ? true : undefined,
    resolvedDate: isQuickFix ? date : undefined,
    progressLog
  };
  flAssertUniqueNo(FL_INCIDENTS, no, 'INC');
  FL_INCIDENTS.unshift(inc);

  // Append asset log entries (audit trail) for Quick Fix
  if(isQuickFix){
    damagedAssets.forEach(a => {
      let obj = null;
      if(a.type==='engine') obj = (FL_ENGINES||[]).find(e=>e.id===a.id);
      else if(a.type==='gearbox') obj = (FL_GEARBOXES||[]).find(g=>g.id===(a.gbId||a.id));
      else if(a.type==='propeller') obj = (FL_PROPELLERS||[]).find(p=>p.id===(a.propId||a.id));
      if(obj){
        obj.log = obj.log || [];
        obj.log.push({date, type:'quickfix', desc:`Quick Fix · ${no} · ${title}`, engineHours:0});
      }
    });
  }

  flSave();
  closeModal('fl-modal-incident');
  if(typeof flRenderIncident==='function') flRenderIncident();
  if(isQuickFix && typeof renderBoats==='function') renderBoats();
  if(typeof flShowToast==='function') flShowToast(`${isQuickFix?'Quick Fix':'Incident'} logged: ${no}`);
}


// ── INVENTORY ──
let _invCat='all',_invLowOnly=false,_memoStFilter='all',_memoArchiveTab='active',_invLoc='all',_invSearch='',_invTab='stock',_selInvId=null,_memoSearch='',_memoDensity='comfortable',_memoView='list';
// Multi-select state for bulk Memo creation
let _invSelected=new Set();
// Group collapse state: { 'Honda BF250D': false, 'Suzuki DF325A': false, ... }
let _invGroupCollapsed={};
function invToggleGroup(key){
  _invGroupCollapsed[key] = !_invGroupCollapsed[key];
  flRenderInventory();
}
// Derive engine model group for inventory item
function invGetGroup(item){
  // Explicit note (DF325A, BF250D, etc.) takes priority
  const note=(item.note||'').trim();
  if(/DF325A/i.test(note)) return 'Suzuki DF325A';
  if(/DF250W/i.test(note)) return 'Suzuki DF250W';
  if(/BF250D/i.test(note)) return 'Honda BF250D';
  if(/BF250A/i.test(note)) return 'Honda BF250A';
  // Fall back to supplier inference
  const sup=(item.supplier||'').toLowerCase();
  if(sup.includes('honda')) return 'Honda BF250D'; // default Honda → 250D
  if(sup.includes('suzuki')) return 'Suzuki DF325A'; // default Suzuki → 325A
  // Special: oil items (MARINE OIL, GEAR OIL) → General
  if(item.partNo && /^(AC-NP-|ZFR)/i.test(item.partNo)) return 'ทั่วไป';
  // Default
  return 'ทั่วไป';
}
function invToggleSelect(id){
  if(_invSelected.has(id)) _invSelected.delete(id);
  else _invSelected.add(id);
  flRenderInventory();
}
function invSelectAllVisible(visibleIds){
  // If all visible already selected, clear all; else select all visible
  const allSelected = visibleIds.every(id=>_invSelected.has(id));
  if(allSelected) visibleIds.forEach(id=>_invSelected.delete(id));
  else visibleIds.forEach(id=>_invSelected.add(id));
  flRenderInventory();
}
function invClearSelection(){ _invSelected.clear(); flRenderInventory(); }

function invSwitchTab(tab){_invTab=tab;flRenderInventory();}
function invLocFilter(loc){_invLoc=loc;flRenderInventory();}
function invCatFilter(cat){_invCat=cat;flRenderInventory();}
function invToggleLow(){_invLowOnly=!_invLowOnly;flRenderInventory();}
function memoFilterSt(st){_memoStFilter=st;flRenderInventory();}
function memoSetArchive(t){
  _memoArchiveTab=t;
  // Reset sub-status filter when switching tabs (Archive only has 'paid')
  _memoStFilter='all';
  flRenderInventory();
}
function memoSetSearch(v){
  _memoSearch=v;
  flRenderInventory();
  requestAnimationFrame(()=>{
    const el=document.querySelector('input[data-search="memo"]');
    if(el){el.focus();const len=el.value.length;try{el.setSelectionRange(len,len);}catch(_){}}
  });
}
function memoSetDensity(v){_memoDensity=v;flRenderInventory();}
function memoSetView(v){_memoView=v;_memoStFilter='all';flRenderInventory();}
function _memoLastDate(m){var ds=[m.createdDate,m.approvedDate,m.orderedDate,m.receivedDate,m.paidDate].filter(Boolean);return ds.length?ds.sort()[ds.length-1]:'';}
function invSetSearch(v){
  _invSearch=v;
  flRenderInventory();
  // Restore focus to search input after re-render (preserve cursor at end)
  requestAnimationFrame(()=>{
    const el=document.querySelector('#view-fl-asset-overview input[data-search="inv"]')
          || document.querySelector('input[data-search="inv"]');
    if(el){
      el.focus();
      const len=el.value.length;
      try{el.setSelectionRange(len,len);}catch(_){}
    }
  });
}
function invSelItem(id){_selInvId=_selInvId===id?null:id;flRenderInventory();}
function flCloseInvPanel(){_selInvId=null;flRenderInventory();}

function flRenderInventory(){
  const wrap=document.getElementById('fl-inv-pink-wrap');
  if(!wrap)return;
  const dim={bg:'#F4F2EE',ink:'#1A1A1A',ink2:'#666',ink3:'#999',ink4:'#bbb',ink5:'#ccc',line:'rgba(0,0,0,.04)'};
  const SVG_PINK={accent:'#E03B7E',soft:'#FCE5EC',text:'#9F1B4F'};

  const all=FL_INVENTORY||[];
  const totalItems=all.length;
  const totalValue=all.reduce((s,x)=>s+(x.qty||0)*(x.cost||0),0);
  const lowStock=all.filter(x=>x.qty<=(x.minQty||0));
  const cntLow=lowStock.length;

  const catCounts={engine:0,gearbox:0,propeller:0,hull:0,general:0};
  all.forEach(x=>{const c=x.category||'general';if(catCounts[c]!=null)catCounts[c]++;});

  const tubCount=all.filter(x=>(x.location||'').toLowerCase().includes('tub')).length;
  const panwaCount=all.filter(x=>(x.location||'').toLowerCase().includes('panwa')).length;

  const memos=FL_MEMOS||[];
  const cntPendingMemo=memos.filter(m=>m.status==='pending_approval').length;
  const cntApprovedMemo=memos.filter(m=>m.status==='approved'||m.status==='ordered').length;
  const cntReceivedMemo=memos.filter(m=>m.status==='received').length;
  const cntPaidMemo=memos.filter(m=>m.status==='paid').length;
  const pendingAmount=memos.filter(m=>m.status==='pending_approval').reduce((s,m)=>s+(m.amount||0),0);
  const thisMonth=TODAY_STR.slice(0,7);
  const paidThisMonth=memos.filter(m=>m.status==='paid'&&(m.paidDate||m.createdDate||'').startsWith(thisMonth));
  const paidAmount=paidThisMonth.reduce((s,m)=>s+(m.amount||0),0);

  const topCats=Object.entries(catCounts).sort((a,b)=>b[1]-a[1]).slice(0,3).filter(function(x){return x[1]>0});

  const CAT_COLOR={engine:'#185FA5',gearbox:'#BA7517',propeller:'#0F6E56',hull:'#7F77DD',general:'#666'};
  const CAT_ABBR={engine:'EN',gearbox:'GB',propeller:'PR',hull:'HU',general:'GN'};
  const CAT_LBL={engine:'Engine',gearbox:'Gearbox',propeller:'Propeller',hull:'Hull',general:'General'};
  const catPills=topCats.map(function(x){var cat=x[0],c=x[1];return '<div style="display:flex;align-items:center;gap:6px;background:white;border:1px solid '+dim.line+';border-radius:20px;padding:3px 12px 3px 3px"><div style="width:24px;height:24px;border-radius:50%;background:'+(CAT_COLOR[cat]||'#666')+';color:white;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700">'+(CAT_ABBR[cat]||cat.slice(0,2).toUpperCase())+'</div><span style="font-size:12px;font-weight:500">'+(CAT_LBL[cat]||cat)+' \u00b7 '+c+'</span></div>'}).join('');

  const headerBar='<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px"><div style="display:flex;align-items:center;gap:6px">'+catPills+'<div style="width:32px;height:32px;border-radius:50%;background:'+dim.ink+';color:white;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600">I</div></div><div style="display:flex;gap:6px"><button onclick="flOpenReceiveStock()" style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:20px;padding:5px 14px;font-size:11px;font-weight:500;cursor:pointer">+ Receive</button><button onclick="flOpenAddStockModal()" style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:20px;padding:5px 14px;font-size:11px;font-weight:500;cursor:pointer">+ Add item</button><button onclick="flOpenMemoFromInventory()" style="background:'+dim.ink+';color:white;border:none;border-radius:20px;padding:7px 16px;font-size:11px;font-weight:600;cursor:pointer">+ Create Memo</button></div></div>';

  const kpiStrip='<div style="display:grid;grid-template-columns:1.6fr 0.85fr 0.85fr 0.85fr 1fr;gap:8px;margin-bottom:14px;align-items:stretch"><div style="grid-column:1;align-self:end;padding-bottom:6px"><div style="font-size:13px;font-weight:500;color:'+dim.ink4+';margin-bottom:2px">Inventory & Memos</div><div style="display:flex;align-items:baseline;gap:8px;margin-bottom:8px;flex-wrap:wrap"><span style="font-size:42px;font-weight:700;letter-spacing:-1.5px;line-height:1">'+totalItems+'</span><span style="font-size:18px;color:'+dim.ink3+';font-weight:500">items</span><span style="display:inline-flex;align-items:center;background:'+SVG_PINK.accent+';color:white;padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600">\u25b4 \u0e3f'+totalValue.toLocaleString()+' value</span>'+(cntLow?'<span style="display:inline-flex;align-items:center;background:#FCEBEB;color:#A32D2D;padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600">'+cntLow+' low stock</span>':'')+'</div><div style="font-size:11px;color:'+dim.ink3+'">2 warehouses \u00b7 Tub Lamu ('+tubCount+') \u00b7 Visit Panwa ('+panwaCount+')</div></div><div style="grid-column:2;background:white;border-radius:14px;padding:11px 13px;border:2px solid '+(cntLow?'#A32D2D':dim.line)+'"><div style="font-size:10px;color:'+dim.ink3+'">Low stock</div><div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="background:#A32D2D;color:white;padding:2px 9px;border-radius:14px;font-size:14px;font-weight:700">'+cntLow+'</span><span style="font-size:11px;color:'+dim.ink3+';margin-left:2px">items</span></div><div style="font-size:11px;color:#A32D2D;margin-top:7px;font-weight:600">need restock</div></div><div style="grid-column:3;background:white;border-radius:14px;padding:11px 13px;border:2px solid '+(cntPendingMemo?'#BA7517':dim.line)+'"><div style="font-size:10px;color:'+dim.ink3+'">Pending memos</div><div style="display:flex;align-items:baseline;gap:4px;margin-top:2px"><span style="background:#BA7517;color:white;padding:2px 9px;border-radius:14px;font-size:14px;font-weight:700">'+cntPendingMemo+'</span><span style="font-size:11px;color:'+dim.ink3+';margin-left:2px">memos</span></div><div style="font-size:11px;color:#854F0B;margin-top:7px;font-weight:600">\u0e3f'+pendingAmount.toLocaleString()+' awaiting</div></div><div style="grid-column:4;background:white;border-radius:14px;padding:11px 13px;border:1px solid '+dim.line+'"><div style="font-size:10px;color:'+dim.ink3+'">Paid this month</div><div style="display:flex;align-items:baseline;gap:3px;margin-top:2px"><span style="font-size:18px;font-weight:700;line-height:1.2;color:#1D9E75">'+paidThisMonth.length+'</span><span style="font-size:11px;color:'+dim.ink3+';font-weight:500">memos</span></div><div style="font-size:11px;color:#0F6E56;margin-top:6px;font-weight:600">\u0e3f'+paidAmount.toLocaleString()+' spent</div></div><div style="grid-column:5;background:'+dim.ink+';color:white;border-radius:14px;padding:11px 13px"><div style="font-size:10px;color:#aaa">By status</div><div style="display:flex;flex-direction:column;gap:3px;margin-top:4px"><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Pending</span><span style="font-size:11px;font-weight:600;color:'+(cntPendingMemo?'#FF8FA8':'white')+'">'+cntPendingMemo+'</span></div><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Approved</span><span style="font-size:11px;font-weight:600;color:white">'+cntApprovedMemo+'</span></div><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Received</span><span style="font-size:11px;font-weight:600;color:white">'+cntReceivedMemo+'</span></div><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:#aaa">Paid</span><span style="font-size:11px;font-weight:600;color:#9BE6BC">'+cntPaidMemo+'</span></div></div></div></div>';

  const tabBtn=function(val,label,count){var isOn=_invTab===val;return '<button onclick="invSwitchTab(\''+val+'\')" style="background:'+(isOn?dim.ink:'transparent')+';color:'+(isOn?'white':dim.ink2)+';border:none;border-radius:10px;padding:7px 16px;font-size:12px;font-weight:'+(isOn?600:500)+';cursor:pointer">'+label+' <span style="background:'+(isOn?'rgba(255,255,255,.2)':'rgba(0,0,0,.06)')+';padding:0 6px;border-radius:8px;margin-left:4px;font-size:10px">'+count+'</span></button>'};
  const tabToggle='<div style="background:white;border-radius:14px;padding:4px;display:flex;gap:2px;margin-bottom:12px;width:fit-content;border:1px solid '+dim.line+'">'+tabBtn('stock','Stock items',totalItems)+tabBtn('memo','Memorandum',memos.length)+'</div>';

  let content='';
  if(_invTab==='stock'){content=buildStockTab();}else{content=buildMemoTab();}
  wrap.innerHTML=headerBar+kpiStrip+tabToggle+content;

  function buildStockTab(){
    let items=all.slice();
    if(_invCat!=='all') items=items.filter(x=>x.category===_invCat);
    // Warehouse filter: match ANY stocks[] location, not just the primary x.location
    // (an item stocked in both warehouses must appear under both tabs)
    const _invWhMatch=(x,kw)=>{
      const ss=(x.stocks&&x.stocks.length)?x.stocks:[{location:x.location}];
      return ss.some(s=>(s.location||'').toLowerCase().includes(kw));
    };
    if(_invLoc==='tub') items=items.filter(x=>_invWhMatch(x,'tub'));
    else if(_invLoc==='panwa') items=items.filter(x=>_invWhMatch(x,'panwa'));
    if(_invLowOnly) items=items.filter(x=>x.qty<=(x.minQty||0));
    if(_invSearch){const s=_invSearch.toLowerCase();items=items.filter(x=>(x.name+(x.partNo||'')+(x.supplier||'')).toLowerCase().includes(s));}

    const catBtn=function(val,label){var isOn=_invCat===val;return '<button onclick="invCatFilter(\''+val+'\')" style="background:'+(isOn?dim.ink:'transparent')+';color:'+(isOn?'white':dim.ink2)+';border:none;border-radius:14px;padding:5px 14px;font-size:11px;font-weight:'+(isOn?600:500)+';cursor:pointer">'+label+'</button>'};
    const locBtn=function(val,label){var isOn=_invLoc===val;return '<button onclick="invLocFilter(\''+val+'\')" style="background:'+(isOn?dim.ink:'transparent')+';color:'+(isOn?'white':dim.ink2)+';border:none;border-radius:14px;padding:5px 12px;font-size:11px;font-weight:'+(isOn?600:500)+';cursor:pointer">'+label+'</button>'};

    const filterBar='<div style="position:sticky;top:0;z-index:5;background:'+dim.bg+';padding:8px 0 12px;margin-bottom:6px;display:flex;gap:6px;align-items:center;flex-wrap:wrap;border-bottom:1px solid '+dim.line+'"><input data-search="inv" value="'+_invSearch.replace(/"/g,'&quot;')+'" oninput="invSetSearch(this.value)" placeholder="Search name / part no..." style="flex:0 0 220px;background:white;border:1px solid '+dim.line+';border-radius:20px;padding:6px 14px;font-size:11px;outline:none;font-family:inherit"/><span style="font-size:11px;color:'+dim.ink3+';margin-left:6px;font-weight:500">filter</span><div style="background:white;border:1px solid '+dim.line+';border-radius:24px;padding:2px;display:flex">'+catBtn('all','All')+catBtn('engine','Engine')+catBtn('gearbox','Gearbox')+catBtn('propeller','Propeller')+catBtn('hull','Hull')+catBtn('general','General')+'</div><div style="background:white;border:1px solid '+dim.line+';border-radius:24px;padding:2px;display:flex">'+locBtn('all','All warehouses')+locBtn('tub','Tub Lamu')+locBtn('panwa','Visit Panwa')+'</div><button onclick="invToggleLow()" style="background:'+(_invLowOnly?'#A32D2D':'transparent')+';color:'+(_invLowOnly?'white':'#A32D2D')+';border:1px solid '+(_invLowOnly?'#A32D2D':'#ebd0d0')+';border-radius:14px;padding:5px 12px;font-size:11px;font-weight:500;cursor:pointer">\u26a0 Low stock only</button></div>';

    const tableRows=items.length?items.map(function(item){
      const isSel=_selInvId===item.id;
      const isLow=item.qty<=(item.minQty||0);
      const cat=item.category||'general';
      const qtyColor=isLow?'#A32D2D':'#1D9E75';
      const showOrder=isLow;
      const isChecked=_invSelected.has(item.id);
      const cbCell='<td style="padding:8px 8px 8px 12px;width:30px;text-align:center;border-bottom:0.5px solid rgba(0,0,0,.04)" onclick="event.stopPropagation();invToggleSelect(\''+item.id+'\')"><div style="width:16px;height:16px;border-radius:4px;border:1.5px solid '+(isChecked?SVG_PINK.accent:'rgba(0,0,0,.18)')+';background:'+(isChecked?SVG_PINK.accent:'white')+';display:inline-flex;align-items:center;justify-content:center;cursor:pointer;vertical-align:middle">'+(isChecked?'<span style="color:white;font-size:11px;font-weight:700;line-height:1">✓</span>':'')+'</div></td>';
      return '<tr onclick="invSelItem(\''+item.id+'\')" style="cursor:pointer;'+(isSel?'background:'+SVG_PINK.soft+';':'')+'">'+cbCell+'<td style="padding:8px 12px;'+(isSel?'border-left:3px solid '+SVG_PINK.accent:'')+';border-bottom:0.5px solid rgba(0,0,0,.04)"><div style="font-size:12px;font-weight:'+(isSel?600:500)+';color:'+(isSel?SVG_PINK.text:dim.ink)+'">'+(item.name||'\u2014')+'</div><span style="background:'+CAT_COLOR[cat]+'22;color:'+CAT_COLOR[cat]+';padding:1px 7px;border-radius:7px;font-size:9px;font-weight:600;margin-top:2px;display:inline-block">'+(CAT_LBL[cat]||cat)+'</span></td><td style="padding:8px 12px;border-bottom:0.5px solid rgba(0,0,0,.04)"><div style="font-size:11px;font-family:\'DM Mono\',monospace;color:'+(isSel?SVG_PINK.text:dim.ink2)+';font-weight:500">'+(item.partNo||'\u2014')+'</div><div style="font-size:10px;color:'+(isSel?SVG_PINK.text:dim.ink3)+';opacity:'+(isSel?'.7':'1')+'">'+(item.supplier||'\u2014')+'</div></td><td style="padding:8px 12px;border-bottom:0.5px solid rgba(0,0,0,.04);font-size:11px;color:'+(isSel?SVG_PINK.text:dim.ink2)+'">'+(function(){
  if(item.stocks && item.stocks.length > 1){
    const nonZero = item.stocks.filter(s=>s.qty>0);
    if(nonZero.length === 0) return '<span style="color:#999;font-size:10px;font-style:italic">no stock</span>';
    if(nonZero.length === 1) return nonZero[0].location.replace('คลัง ','');
    return nonZero.map(s=>'<div style="font-size:10px;line-height:1.4">'+s.location.replace('คลัง ','')+' <span style="color:#999;font-family:\'DM Mono\',monospace">('+s.qty+')</span></div>').join('');
  }
  if(!item.location && (!item.stocks || item.stocks.length === 0)){
    return '<span style="color:#999;font-size:10px;font-style:italic">registered · no stock</span>';
  }
  return item.location || '\u2014';
})()+'</td><td style="padding:8px 12px;text-align:center;border-bottom:0.5px solid rgba(0,0,0,.04)"><div style="font-size:16px;font-weight:700;color:'+qtyColor+';font-family:\'DM Mono\',monospace;line-height:1.1">'+(item.qty||0)+'</div><div style="font-size:9px;color:'+dim.ink3+'">'+(item.unit||'')+'</div>'+(isLow?'<div style="font-size:9px;color:#A32D2D;font-weight:600;margin-top:1px">\u26a0 below min '+(item.minQty||0)+'</div>':'')+'</td><td style="padding:8px 12px;text-align:right;font-family:\'DM Mono\',monospace;font-size:12px;font-weight:500;border-bottom:0.5px solid rgba(0,0,0,.04)">\u0e3f'+(item.cost||0).toLocaleString()+'</td><td style="padding:8px 12px;text-align:center;border-bottom:0.5px solid rgba(0,0,0,.04)"><div style="display:flex;gap:4px;justify-content:center" onclick="event.stopPropagation()"><button onclick="flOpenReceiveOne(\''+item.id+'\')" style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:8px;padding:3px 10px;font-size:10px;font-weight:500;cursor:pointer">+ Receive</button><button onclick="event.stopPropagation();flOpenTransfer(\''+item.id+'\')" style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:8px;padding:3px 10px;font-size:10px;font-weight:500;cursor:pointer;color:#666" title="ย้ายระหว่างคลัง">↔ Transfer</button><button onclick="event.stopPropagation();flOpenInvEdit(\''+item.id+'\')" style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:8px;padding:3px 10px;font-size:10px;font-weight:500;cursor:pointer;color:#666">Edit</button>'+(showOrder?'<button onclick="flOrderItem&&flOrderItem(\''+item.id+'\')" style="background:#A32D2D;color:white;border:none;border-radius:8px;padding:3px 10px;font-size:10px;font-weight:600;cursor:pointer">Order</button>':'')+'</div></td></tr>';
    }).join(''):'';

    // Group items by engine model
    const groupOrder=['Honda BF250D','Honda BF250A','Suzuki DF250W','Suzuki DF325A','ทั่วไป'];
    const groupColor={'Honda BF250D':'#185FA5','Honda BF250A':'#1f7ac9','Suzuki DF250W':'#A32D2D','Suzuki DF325A':'#c43e3e','ทั่วไป':'#666'};
    const groups={};
    items.forEach(it=>{
      const k=invGetGroup(it);
      if(!groups[k]) groups[k]=[];
      groups[k].push(it);
    });

    // Helper: build a single row HTML (extracted for reuse in groups)
    const buildRow=function(item){
      const isSel=_selInvId===item.id;
      const isLow=item.qty<=(item.minQty||0);
      const cat=item.category||'general';
      const qtyColor=isLow?'#A32D2D':'#1D9E75';
      const showOrder=isLow;
      const isChecked=_invSelected.has(item.id);
      const cbCell='<td style="padding:4px 8px 4px 12px;width:30px;text-align:center;border-bottom:0.5px solid rgba(0,0,0,.04)" onclick="event.stopPropagation();invToggleSelect(\''+item.id+'\')"><div style="width:16px;height:16px;border-radius:4px;border:1.5px solid '+(isChecked?SVG_PINK.accent:'rgba(0,0,0,.18)')+';background:'+(isChecked?SVG_PINK.accent:'white')+';display:inline-flex;align-items:center;justify-content:center;cursor:pointer;vertical-align:middle">'+(isChecked?'<span style="color:white;font-size:11px;font-weight:700;line-height:1">✓</span>':'')+'</div></td>';
      const _loc=(function(){
        if(item.stocks && item.stocks.length > 1){
          const nonZero = item.stocks.filter(s=>s.qty>0);
          if(nonZero.length === 0) return '<span style="color:#999;font-style:italic">no stock</span>';
          if(nonZero.length === 1) return nonZero[0].location.replace('คลัง ','');
          return nonZero.map(s=>s.location.replace('คลัง ','')+' <span style="color:#999;font-family:\'DM Mono\',monospace">('+s.qty+')</span>').join(' · ');
        }
        if(!item.location && (!item.stocks || item.stocks.length === 0)) return '<span style="color:#999;font-style:italic">registered · no stock</span>';
        return item.location || '—';
      })();
      const _txt=isSel?SVG_PINK.text:dim.ink, _sub=isSel?SVG_PINK.text:dim.ink2, _bb='border-bottom:0.5px solid rgba(0,0,0,.04)';
      return '<tr onclick="invSelItem(\''+item.id+'\')" style="cursor:pointer;'+(isSel?'background:'+SVG_PINK.soft+';':'')+'">'+cbCell+'<td style="padding:5px 12px;'+(isSel?'border-left:3px solid '+SVG_PINK.accent:'')+';'+_bb+';font-size:11px;font-family:\'DM Mono\',monospace;color:'+_sub+'">'+(item.partNo||'—')+'</td><td style="padding:5px 12px;'+_bb+';font-size:12px;color:'+_txt+'">'+(item.name||'—')+'</td><td style="padding:5px 12px;'+_bb+'"><span style="background:'+CAT_COLOR[cat]+'22;color:'+CAT_COLOR[cat]+';padding:1px 8px;border-radius:7px;font-size:10px">'+(CAT_LBL[cat]||cat)+'</span></td><td style="padding:5px 12px;'+_bb+';font-size:11px;color:'+_sub+'">'+(item.supplier||'—')+'</td><td style="padding:5px 12px;'+_bb+';font-size:11px;color:'+_sub+'">'+_loc+'</td><td style="padding:5px 12px;text-align:center;'+_bb+';white-space:nowrap"><span style="font-size:13px;color:'+qtyColor+';font-family:\'DM Mono\',monospace">'+(item.qty||0)+'</span><span style="font-size:10px;color:'+dim.ink3+'"> '+(item.unit||'ชิ้น')+'</span>'+(isLow?' <span style="font-size:10px;color:#A32D2D">⚠ below min '+(item.minQty||0)+'</span>':'')+'</td><td style="padding:5px 12px;text-align:right;font-family:\'DM Mono\',monospace;font-size:12px;'+_bb+'">฿'+(item.cost||0).toLocaleString()+'</td><td style="padding:5px 12px;text-align:center;'+_bb+'"><div style="display:flex;gap:4px;justify-content:center" onclick="event.stopPropagation()"><button onclick="flOpenReceiveOne(\''+item.id+'\')" style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:7px;padding:2px 9px;white-space:nowrap;font-size:10px;font-weight:400;cursor:pointer">+ Receive</button><button onclick="event.stopPropagation();flOpenTransfer(\''+item.id+'\')" style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:7px;padding:2px 9px;white-space:nowrap;font-size:10px;font-weight:400;cursor:pointer;color:#666" title="ย้ายระหว่างคลัง">↔ Transfer</button><button onclick="event.stopPropagation();flOpenInvEdit(\''+item.id+'\')" style="background:white;border:1px solid rgba(0,0,0,.08);border-radius:7px;padding:2px 9px;white-space:nowrap;font-size:10px;font-weight:400;cursor:pointer;color:#666">Edit</button>'+(showOrder?'<button onclick="flOrderItem&&flOrderItem(\''+item.id+'\')" style="background:#A32D2D;color:white;border:none;border-radius:7px;padding:2px 9px;white-space:nowrap;font-size:10px;font-weight:500;cursor:pointer">Order</button>':'')+'</div></td></tr>';
    };

    // Build grouped table body
    let groupedRows='';
    const presentGroups=groupOrder.filter(g=>groups[g]&&groups[g].length>0);
    if(items.length===0){
      groupedRows='<tr><td colspan="9" style="padding:30px;text-align:center;color:'+dim.ink3+';font-size:11px">No items match filter</td></tr>';
    } else {
      presentGroups.forEach(grp=>{
        const grpItems=groups[grp];
        const collapsed=_invGroupCollapsed[grp]===true;
        const cnt=grpItems.length;
        const sumCost=grpItems.reduce((s,x)=>s+(x.cost||0),0);
        const color=groupColor[grp]||'#666';
        const chevron=collapsed?'▶':'▼';
        // Group header row
        groupedRows+='<tr onclick="invToggleGroup(\''+grp.replace(/'/g,"\\'")+'\')" style="cursor:pointer;background:'+color+'08;border-top:2px solid '+color+'33"><td colspan="9" style="padding:9px 14px"><div style="display:flex;align-items:center;gap:10px"><span style="color:'+color+';font-size:10px;width:10px">'+chevron+'</span><span style="font-size:12px;font-weight:700;color:'+color+';letter-spacing:.01em">'+grp+'</span><span style="background:'+color+'1a;color:'+color+';padding:1px 8px;border-radius:10px;font-size:10px;font-weight:600;font-family:\'DM Mono\',monospace">'+cnt+'</span><span style="margin-left:auto;font-size:10px;color:'+dim.ink3+';font-family:\'DM Mono\',monospace">รวม ฿'+sumCost.toLocaleString()+'/หน่วย</span></div></td></tr>';
        if(!collapsed){
          groupedRows+=grpItems.slice().sort(function(a,b){return (b.qty||0)-(a.qty||0);}).map(buildRow).join('');
        }
      });
    }

    // Header checkbox: select-all of currently visible items
    const visibleIds = items.map(x=>x.id);
    const allVisibleSelected = visibleIds.length>0 && visibleIds.every(id=>_invSelected.has(id));
    const someVisibleSelected = visibleIds.some(id=>_invSelected.has(id)) && !allVisibleSelected;
    const headerCbState = allVisibleSelected ? '✓' : (someVisibleSelected ? '−' : '');
    const headerCbBg = (allVisibleSelected||someVisibleSelected) ? SVG_PINK.accent : 'white';
    const headerCbBorder = (allVisibleSelected||someVisibleSelected) ? SVG_PINK.accent : 'rgba(0,0,0,.18)';
    const headerCbCell = '<th style="padding:6px 8px 6px 12px;width:30px;text-align:center;border-bottom:1px solid rgba(0,0,0,.06);background:#FBFAF7" onclick="invSelectAllVisible('+JSON.stringify(visibleIds).replace(/"/g,'&quot;')+')"><div style="width:16px;height:16px;border-radius:4px;border:1.5px solid '+headerCbBorder+';background:'+headerCbBg+';display:inline-flex;align-items:center;justify-content:center;cursor:pointer;vertical-align:middle">'+(headerCbState?'<span style="color:white;font-size:11px;font-weight:700;line-height:1">'+headerCbState+'</span>':'')+'</div></th>';

    const tablePanel='<div style="background:white;border-radius:14px;border:1px solid '+dim.line+';overflow:hidden"><table style="width:100%;border-collapse:separate;border-spacing:0;font-size:11px"><thead><tr style="background:#FBFAF7">'+headerCbCell+'<th style="padding:7px 12px;text-align:left;font-weight:500;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:10px;border-bottom:1px solid rgba(0,0,0,.06)">Part No</th><th style="padding:7px 12px;text-align:left;font-weight:500;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:10px;border-bottom:1px solid rgba(0,0,0,.06)">Item</th><th style="padding:7px 12px;text-align:left;font-weight:500;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:10px;border-bottom:1px solid rgba(0,0,0,.06)">Category</th><th style="padding:7px 12px;text-align:left;font-weight:500;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:10px;border-bottom:1px solid rgba(0,0,0,.06)">Supplier</th><th style="padding:7px 12px;text-align:left;font-weight:500;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:10px;border-bottom:1px solid rgba(0,0,0,.06)">Location</th><th style="padding:7px 12px;text-align:center;font-weight:500;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:10px;border-bottom:1px solid rgba(0,0,0,.06)">Qty</th><th style="padding:7px 12px;text-align:right;font-weight:500;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:10px;border-bottom:1px solid rgba(0,0,0,.06)">Cost</th><th style="padding:7px 12px;text-align:center;font-weight:500;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:10px;border-bottom:1px solid rgba(0,0,0,.06)">Action</th></tr></thead><tbody>'+groupedRows+'</tbody></table></div>';

    // Floating action bar (only when something is selected)
    let floatBar = '';
    if(_invSelected.size > 0){
      const selectedItems = all.filter(x=>_invSelected.has(x.id));
      const cnt = selectedItems.length;
      const estTotal = selectedItems.reduce((s,x)=>s+(x.cost||0),0); // 1 unit each by default
      floatBar = '<div style="position:sticky;bottom:14px;margin-top:14px;background:'+dim.ink+';color:white;border-radius:14px;padding:12px 18px;display:flex;align-items:center;justify-content:space-between;gap:14px;box-shadow:0 8px 24px rgba(0,0,0,.18);z-index:10"><div style="display:flex;align-items:center;gap:14px"><div style="display:flex;align-items:center;gap:8px"><span style="background:'+SVG_PINK.accent+';color:white;width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;font-family:\'DM Mono\',monospace">'+cnt+'</span><span style="font-size:12px;font-weight:600">รายการที่เลือก</span></div><div style="font-size:11px;color:#bbb;font-family:\'DM Mono\',monospace">est. ฿'+estTotal.toLocaleString()+' @ qty=1</div></div><div style="display:flex;gap:6px"><button onclick="invClearSelection()" style="background:transparent;color:white;border:1px solid rgba(255,255,255,.2);border-radius:18px;padding:6px 14px;font-size:11px;font-weight:500;cursor:pointer">ยกเลิก</button><button onclick="flOpenMemoFromSelected()" style="background:'+SVG_PINK.accent+';color:white;border:none;border-radius:18px;padding:7px 18px;font-size:11px;font-weight:600;cursor:pointer">+ สร้าง Memo จาก '+cnt+' รายการ</button></div></div>';
    }

    const item=_selInvId?all.find(x=>x.id===_selInvId):null;
    const detailPanel=item?buildItemDetail(item):'<div style="background:white;border-radius:14px;border:1px solid '+dim.line+';padding:40px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:'+dim.ink3+';gap:10px;text-align:center;min-height:400px"><div style="font-size:24px;opacity:.25;letter-spacing:.1em">INVENTORY</div><div style="font-size:13px;color:'+dim.ink2+';font-weight:500">Select an item to see history</div><div style="font-size:11px;color:'+dim.ink3+'">Click on a row to see movement history and details</div></div>';

    return filterBar+'<div style="display:grid;grid-template-columns:1fr 360px;gap:12px;align-items:start">'+tablePanel+detailPanel+'</div>'+floatBar;
  }

  function buildItemDetail(item){
    const MONTHS_EN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    const fmtD=function(s){if(!s)return '\u2014';const d=new Date(s);return MONTHS_EN[d.getMonth()]+' '+d.getDate()+', '+d.getFullYear();};
    const isLow=item.qty<=(item.minQty||0);
    const hist=(item.history||[]).slice().reverse();

    const histHtml=hist.length?hist.map(function(h,i,arr){
      const isLast=i===arr.length-1;
      const isEdit=h.type==='edit';
      const isIn=h.type==='receive';
      const dotColor=isEdit?'#666':(isIn?'#1D9E75':'#A32D2D');
      // Build label + right-side info per type
      let mainText, rightText;
      if(isEdit){
        const chCount=(h.changes||[]).length;
        // Show field names of changes
        const fieldsList=(h.changes||[]).map(c=>c.field).join(', ');
        mainText='แก้ไข: '+(fieldsList||'รายการ');
        rightText='<span style="font-size:10px;font-weight:500;color:'+dim.ink3+';font-family:\'DM Mono\',monospace">'+chCount+' field'+(chCount>1?'s':'')+'</span>';
      } else {
        mainText=h.note||h.desc||'\u2014';
        rightText='<span style="font-size:11px;font-weight:600;color:'+dotColor+';font-family:\'DM Mono\',monospace">'+(isIn?'+':'\u2212')+(h.qty||0)+' '+(item.unit||'')+'</span>';
      }
      return '<div style="display:flex;gap:10px;padding:8px 0;'+(isLast?'':'border-bottom:0.5px solid rgba(0,0,0,.06)')+'"><div style="position:relative;flex-shrink:0"><div style="width:8px;height:8px;border-radius:50%;background:'+dotColor+';margin-top:4px"></div>'+(!isLast?'<div style="position:absolute;left:3.5px;top:13px;bottom:-9px;width:1px;background:rgba(0,0,0,.08)"></div>':'')+'</div><div style="font-size:10px;font-family:\'DM Mono\',monospace;color:'+dim.ink3+';flex-shrink:0;min-width:55px">'+fmtD(h.date)+'</div><div style="flex:1;min-width:0"><div style="font-size:11px;color:'+dim.ink+'">'+mainText+'</div>'+(h.by?'<div style="font-size:9px;color:'+dim.ink3+'">'+h.by+'</div>':'')+'</div>'+rightText+'</div>';
    }).join(''):'<div style="font-size:11px;color:'+dim.ink3+';text-align:center;padding:20px">No movement history</div>';

    return '<div style="background:white;border-radius:14px;border:1px solid '+dim.line+';overflow:hidden;position:sticky;top:0"><div style="padding:14px 18px;border-bottom:1px solid rgba(0,0,0,.06);background:linear-gradient(to right,#FFF5EC 0%,#FBEAF0 60%,#F5DDE6 100%)"><div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px"><div style="flex:1;min-width:0"><div style="font-size:14px;font-weight:700">'+(item.name||'\u2014')+'</div><div style="font-size:10px;color:'+dim.ink2+';margin-top:2px;font-family:\'DM Mono\',monospace">'+(item.partNo||'')+(item.supplier?' \u00b7 '+item.supplier:'')+(item.location?' \u00b7 '+item.location:'')+'</div></div><button onclick="flCloseInvPanel()" style="background:transparent;border:none;color:'+dim.ink2+';font-size:18px;cursor:pointer;line-height:1;padding:0">\u00d7</button></div></div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px;padding:12px 14px;border-bottom:1px solid rgba(0,0,0,.06)"><div style="background:'+(isLow?SVG_PINK.soft:dim.bg)+';border-radius:8px;padding:8px;text-align:center"><div style="font-size:20px;font-weight:700;font-family:\'DM Mono\',monospace;color:'+(isLow?'#A32D2D':dim.ink)+'">'+(item.qty||0)+'</div><div style="font-size:9px;color:'+(isLow?SVG_PINK.text:dim.ink3)+'">in stock</div></div><div style="background:'+dim.bg+';border-radius:8px;padding:8px;text-align:center"><div style="font-size:20px;font-weight:700;font-family:\'DM Mono\',monospace;color:'+dim.ink2+'">'+(item.minQty||0)+'</div><div style="font-size:9px;color:'+dim.ink3+'">min qty</div></div><div style="background:'+dim.bg+';border-radius:8px;padding:8px;text-align:center"><div style="font-size:14px;font-weight:700;font-family:\'DM Mono\',monospace;color:'+dim.ink+'">\u0e3f'+(item.cost||0).toLocaleString()+'</div><div style="font-size:9px;color:'+dim.ink3+'">per unit</div></div></div><div style="padding:12px 14px;max-height:380px;overflow-y:auto"><div style="font-size:11px;font-weight:600;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;margin-bottom:10px">Movement history</div>'+histHtml+'</div><div style="padding:10px 14px;border-top:1px solid rgba(0,0,0,.06);background:#FBFAF7;display:flex;justify-content:space-between;align-items:center"><span style="font-size:10px;color:'+dim.ink3+'">Current balance</span><span style="font-size:14px;font-weight:700;color:'+(isLow?'#A32D2D':dim.ink)+';font-family:\'DM Mono\',monospace">'+(item.qty||0)+' '+(item.unit||'')+(isLow?' \u00b7 \u26a0 low':'')+'</span></div></div>';
  }

  function buildMemoTab(){
    // Split active vs archive
    const activeStatuses=new Set(['created','pending_approval','approved','ordered','received']);
    const archiveStatuses=new Set(['paid']);
    const allActive=memos.filter(m=>activeStatuses.has(m.status));
    const allArchive=memos.filter(m=>archiveStatuses.has(m.status));
    const tabMemos=(_memoArchiveTab==='archive')?allArchive:allActive;

    let memoList=tabMemos.slice();
    if(_memoStFilter!=='all') memoList=memoList.filter(m=>m.status===_memoStFilter);
    if(_memoSearch){
      var _q=_memoSearch.toLowerCase();
      memoList=memoList.filter(function(m){
        var _b=getBoat(m.boatId);
        return ((m.no||'')+' '+(m.title||'')+' '+(m.supplier||'')+' '+(m.proposer||'')+' '+(_b?_b.name:'')+' '+(m.generalCategory||'')).toLowerCase().indexOf(_q)>=0;
      });
    }
    memoList.sort((a,b)=>_memoLastDate(b).localeCompare(_memoLastDate(a)));
    const compact=(_memoDensity==='compact');

    const ST_STYLE={created:{bg:'#F4F2EE',color:'#666',label:'CREATED',stripe:'#999'},pending_approval:{bg:'#FAEEDA',color:'#854F0B',label:'PENDING',stripe:'#BA7517'},approved:{bg:'#E6F1FB',color:'#185FA5',label:'APPROVED',stripe:'#185FA5'},ordered:{bg:'#E6F1FB',color:'#185FA5',label:'ORDERED',stripe:'#185FA5'},received:{bg:'#1D9E75',color:'white',label:'RECEIVED',stripe:'#1D9E75'},paid:{bg:'#1D9E75',color:'white',label:'PAID',stripe:'#1D9E75'}};

    const stBtn=function(val,label,color){var isOn=_memoStFilter===val;return '<button onclick="memoFilterSt(\''+val+'\')" style="background:'+(isOn?dim.ink:'transparent')+';color:'+(isOn?'white':(color||dim.ink2))+';border:'+(isOn?'none':'1px solid rgba(0,0,0,.08)')+';border-radius:12px;padding:5px 12px;font-size:11px;font-weight:'+(isOn?600:500)+';cursor:pointer">'+label+'</button>'};

    // Tab buttons: Active / Archive
    const archBtn=function(val,label,count){var isOn=_memoArchiveTab===val;return '<button onclick="memoSetArchive(\''+val+'\')" style="background:'+(isOn?'white':'transparent')+';color:'+(isOn?dim.ink:dim.ink3)+';border:none;border-bottom:'+(isOn?'2px solid '+SVG_PINK.accent:'2px solid transparent')+';padding:8px 16px;font-size:12px;font-weight:'+(isOn?600:500)+';cursor:pointer;border-radius:0;margin-bottom:-1px">'+label+' <span style="background:'+(isOn?SVG_PINK.soft:dim.bg)+';color:'+(isOn?SVG_PINK.text:dim.ink3)+';padding:1px 7px;border-radius:8px;font-size:10px;font-weight:600;margin-left:4px;font-family:\'DM Mono\',monospace">'+count+'</span></button>'};

    const tabBar='<div style="display:flex;border-bottom:1px solid '+dim.line+';margin-bottom:14px;gap:0">'+
      archBtn('active','Active',allActive.length)+
      archBtn('archive','Archive',allArchive.length)+
    '</div>';

    // Status filter (different sub-statuses per tab)
    let filterBtns;
    if(_memoArchiveTab==='active'){
      filterBtns=stBtn('all','All')+stBtn('pending_approval','Pending','#854F0B')+stBtn('approved','Approved','#185FA5')+stBtn('ordered','Ordered','#185FA5')+stBtn('received','Received','#0F6E56');
    } else {
      filterBtns=stBtn('all','All')+stBtn('paid','Paid','#0F6E56');
    }
    const filterBar='<div style="display:flex;gap:6px;margin-bottom:14px;align-items:center;flex-wrap:wrap"><span style="font-size:11px;color:'+dim.ink3+';margin-right:6px;font-weight:500">filter</span>'+filterBtns+'</div>';
    const _densBtn=function(val,label){var on=_memoDensity===val;return '<button onclick="memoSetDensity(\''+val+'\')" style="background:'+(on?dim.ink:'transparent')+';color:'+(on?'white':dim.ink2)+';border:none;border-radius:10px;padding:4px 11px;font-size:10px;font-weight:'+(on?600:500)+';cursor:pointer">'+label+'</button>'};
    const _viewBtn=function(val,label){var on=_memoView===val;return '<button onclick="memoSetView(\''+val+'\')" style="background:'+(on?dim.ink:'transparent')+';color:'+(on?'white':dim.ink2)+';border:none;border-radius:10px;padding:4px 11px;font-size:10px;font-weight:'+(on?600:500)+';cursor:pointer">'+label+'</button>'};
    const _viewToggle='<div style="display:flex;background:white;border:1px solid '+dim.line+';border-radius:12px;padding:2px;flex-shrink:0">'+_viewBtn('list','List')+_viewBtn('board','Board')+'</div>';
    const _densToggle=(_memoView==='list')?'<div style="display:flex;background:white;border:1px solid '+dim.line+';border-radius:12px;padding:2px;flex-shrink:0">'+_densBtn('comfortable','ละเอียด')+_densBtn('compact','กระชับ')+'</div>':'';
    const searchRow='<div style="display:flex;gap:8px;margin-bottom:10px;align-items:center"><div style="flex:1;display:flex;align-items:center;gap:8px;background:white;border:1px solid '+dim.line+';border-radius:20px;padding:6px 14px"><span style="color:'+dim.ink3+';font-size:12px">🔍</span><input data-search="memo" value="'+(_memoSearch||'').replace(/"/g,'&quot;')+'" oninput="memoSetSearch(this.value)" placeholder="ค้นหา MO / ชื่อเรื่อง / supplier / เรือ..." style="flex:1;border:none;background:transparent;outline:none;font-size:11px;font-family:inherit"/>'+(_memoSearch?'<span onclick="memoSetSearch(\'\')" style="cursor:pointer;color:'+dim.ink3+';font-size:14px;line-height:1">×</span>':'')+'</div>'+_viewToggle+_densToggle+'</div>';

    const MONTHS_EN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    const fmtD=function(s){if(!s)return '';const d=new Date(s);return MONTHS_EN[d.getMonth()]+' '+d.getDate()+', '+d.getFullYear();};

    const MEMO_TYPE_STYLE={parts:{bg:'#E6F1FB',color:'#185FA5',label:'Parts',dot:'#185FA5'},labor:{bg:'#FAEEDA',color:'#854F0B',label:'Labor',dot:'#BA7517'},mixed:{bg:'#EEEDF8',color:'#534AB7',label:'Mixed',dot:'#7F77DD'}};
    const _monthAgg={};
    memoList.forEach(function(mm){var _k=_memoLastDate(mm).slice(0,7);if(!_monthAgg[_k])_monthAgg[_k]={c:0,t:0};_monthAgg[_k].c++;_monthAgg[_k].t+=(mm.amount||0);});
    // §memoTable · โครงคอลัมน์ · โหมดกระชับตัด "ผู้ขอ" ออก (ที่เหลือตัดในระดับเซลล์)
    const _MCOL=compact
      ? [['',3],['MO',78],['เรื่อง',0],['เรือ · งานซ่อม',140],['วันที่',76],['รายการ',46,'c'],['ยอด',108,'r'],['สถานะ',104],['ถัดไป',150],['',102,'r']]
      : [['',3],['MO',78],['เรื่อง',0],['เรือ · งานซ่อม',150],['ผู้ขอ',74],['วันที่',76],['รายการ',52,'c'],['ยอด',108,'r'],['สถานะ',132],['ถัดไป',150],['',102,'r']];
    const _NCOL=_MCOL.length;
    /* §memoTable · เงินบาทไม่มีหลักที่สาม · toLocaleString() ดิบพ่นเศษจาก qty×ราคาออกมาหมด
       ตรึง 2 ตำแหน่งให้จุดทศนิยมตรงกันทุกแถวด้วย · ตัวเลขที่เก็บจริงไม่ถูกแตะ */
    const _mAmt=function(n){ return '฿'+(+n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}); };
    const _mTd='padding:9px 10px;border-bottom:0.5px solid rgba(0,0,0,.055);vertical-align:middle';
    const _mIco=function(on,title,svg,bg,fg){ return '<span onclick="event.stopPropagation();'+on+'" title="'+title+'" style="width:26px;height:26px;border-radius:8px;border:1px solid #EAE7E0;background:'+(bg||'#fff')+';color:'+(fg||'#8a857e')+';cursor:pointer;display:inline-flex;align-items:center;justify-content:center;flex:none">'+svg+'</span>'; };
    const _MICO={
      eye:'<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12z"/><circle cx="12" cy="12" r="3"/></svg>',
      copy:'<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>',
      print:'<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>'
    };
    let _curMonth=null;
    const memoCards=memoList.length?memoList.map(function(m){
      let _divider='';
      const _mk=_memoLastDate(m).slice(0,7);
      if(_mk!==_curMonth){
        _curMonth=_mk;
        const _agg=_monthAgg[_mk]||{c:0,t:0};
        const _ml=_mk?(MONTHS_EN[parseInt(_mk.slice(5,7),10)-1]+' '+_mk.slice(0,4)):'ไม่ระบุวันที่';
        // §memoTable · หัวเดือนกลายเป็นแถวคั่นในตาราง · ยอดรวมชิดขวาให้ตรงคอลัมน์ยอด
        _divider='<tr><td colspan="'+_NCOL+'" style="background:'+dim.bg+';padding:7px 12px;border-bottom:1px solid #E5E1DA"><span style="font-size:11.5px;font-weight:700">'+_ml+'</span><span style="font-size:10px;color:'+dim.ink3+';margin-left:8px">'+_agg.c+' ใบ</span><span style="float:right;font-size:11px;font-weight:700;font-family:\'DM Mono\',monospace;color:'+dim.ink2+'">'+_mAmt(_agg.t)+'</span></td></tr>';
      }
      const ss=ST_STYLE[m.status]||ST_STYLE.created;
      const b=getBoat(m.boatId);
      const mj=m.maintId?FL_MAINT.find(x=>x.id===m.maintId):null;
      const items=m.items||[];
      const mts=MEMO_TYPE_STYLE[m.memoType||'parts']||MEMO_TYPE_STYLE.parts;
      const typeBadge='<span style="background:'+mts.bg+';color:'+mts.color+';padding:2px 8px;border-radius:10px;font-size:9px;font-weight:600;flex-shrink:0;display:inline-flex;align-items:center;gap:4px"><span style="width:6px;height:6px;border-radius:50%;background:'+mts.dot+'"></span>'+mts.label+'</span>';
      const buildItemRow=function(it){
        const cat=it.category||m.memoType||'parts';
        const dotColor=cat==='labor'?'#BA7517':'#185FA5';
        const lblColor=cat==='labor'?'#854F0B':'#185FA5';
        const lblBg=cat==='labor'?'#FAEEDA':'#E6F1FB';
        const catBadge=' <span style="background:'+lblBg+';color:'+lblColor+';padding:1px 6px;border-radius:5px;font-size:8px;font-weight:600;margin-left:4px;display:inline-flex;align-items:center;gap:3px"><span style="width:5px;height:5px;border-radius:50%;background:'+dotColor+'"></span>'+(cat==='labor'?'Labor':'Parts')+'</span>';
        return '<tr style="border-top:0.5px solid rgba(0,0,0,.04)"><td style="padding:7px 14px">'+(it.name||'')+catBadge+(it.fromInventory?' <span style="background:#E1F5EE;color:#0F6E56;padding:1px 5px;border-radius:5px;font-size:8px;font-weight:600;margin-left:4px">INV</span>':'')+'</td><td style="padding:7px 12px;text-align:center;font-family:\'DM Mono\',monospace">'+(it.qty||0)+(it.unit?' '+it.unit:'')+'</td><td style="padding:7px 12px;text-align:right;font-family:\'DM Mono\',monospace">\u0e3f'+(it.price||0).toLocaleString()+'</td><td style="padding:7px 14px;text-align:right;font-family:\'DM Mono\',monospace;font-weight:600">\u0e3f'+((it.qty||0)*(it.price||0)).toLocaleString()+'</td></tr>';
      };
      const itemsTable=items.length?'<div style="border-top:1px solid rgba(0,0,0,.06);background:#FBFAF7"><table style="width:100%;border-collapse:collapse;font-size:10px"><thead><tr style="background:rgba(0,0,0,.02)"><th style="padding:6px 14px;text-align:left;font-weight:600;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:9px">Item</th><th style="padding:6px 12px;text-align:center;font-weight:600;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:9px;width:50px">Qty</th><th style="padding:6px 12px;text-align:right;font-weight:600;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:9px;width:90px">Price</th><th style="padding:6px 14px;text-align:right;font-weight:600;color:'+dim.ink3+';text-transform:uppercase;letter-spacing:.05em;font-size:9px;width:90px">Total</th></tr></thead><tbody>'+items.map(buildItemRow).join('')+'<tr style="border-top:1px solid rgba(0,0,0,.08)"><td colspan="3" style="padding:8px 14px;text-align:right;font-weight:600;font-size:11px">\u0e23\u0e27\u0e21\u0e17\u0e31\u0e49\u0e07\u0e2a\u0e34\u0e49\u0e19</td><td style="padding:8px 14px;text-align:right;font-weight:700;font-family:\'DM Mono\',monospace;color:'+SVG_PINK.text+';font-size:12px">\u0e3f'+(m.amount||0).toLocaleString()+'</td></tr></tbody></table></div>':'';

      // ─── Approval workflow stepper ───
      const isLaborOnly=m.memoType==='labor'||(m.memoType==='mixed'&&!(m.items||[]).some(it=>(it.category||'parts')==='parts'));
      const SVG_ICONS={
        create:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>',
        clock:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',
        check:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>',
        box:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 8 21 19a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8"/><rect x="1" y="3" width="22" height="5" rx="1"/><line x1="10" y1="12" x2="14" y2="12"/></svg>',
        inbox:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="22 12 16 12 14 15 10 15 8 12 2 12"/><path d="M5.45 5.11 2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11Z"/></svg>',
        money:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="2" x2="12" y2="22"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>',
        arrow:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>'
      };
      const STEPS=isLaborOnly?
        [{key:'created',label:'สร้าง',svg:SVG_ICONS.create},{key:'pending_approval',label:'รออนุมัติ',svg:SVG_ICONS.clock},{key:'approved',label:'อนุมัติ',svg:SVG_ICONS.check},{key:'paid',label:'จ่ายแล้ว',svg:SVG_ICONS.money}]:
        [{key:'created',label:'สร้าง',svg:SVG_ICONS.create},{key:'pending_approval',label:'รออนุมัติ',svg:SVG_ICONS.clock},{key:'approved',label:'อนุมัติ',svg:SVG_ICONS.check},{key:'ordered',label:'สั่งซื้อ',svg:SVG_ICONS.box},{key:'received',label:'รับของ',svg:SVG_ICONS.inbox},{key:'paid',label:'จ่ายแล้ว',svg:SVG_ICONS.money}];
      const stepIdx=STEPS.findIndex(s=>s.key===m.status);
      const currentIdx=stepIdx>=0?stepIdx:0;
      const isPaid=m.status==='paid';

      const stepperHtml=STEPS.map(function(s,i){
        const done=i<currentIdx, cur=i===currentIdx, future=i>currentIdx;
        const dotBg=done?'#1D9E75':cur?SVG_PINK.accent:'#E5E1DA';
        const dotColor=done||cur?'white':dim.ink3;
        const lblColor=done?'#0F6E56':cur?SVG_PINK.text:dim.ink3;
        const lineColor=done?'#1D9E75':'#E5E1DA';
        const iconHtml=done?SVG_ICONS.check:s.svg;
        return '<div style="display:flex;align-items:center;flex:1;min-width:0">'+
          '<div style="display:flex;flex-direction:column;align-items:center;flex-shrink:0">'+
            '<div style="width:24px;height:24px;border-radius:50%;background:'+dotBg+';color:'+dotColor+';display:flex;align-items:center;justify-content:center;'+(cur?'box-shadow:0 0 0 3px '+SVG_PINK.soft:'')+'">'+iconHtml+'</div>'+
            '<span style="font-size:8px;color:'+lblColor+';margin-top:2px;font-weight:'+(cur?600:500)+';white-space:nowrap">'+s.label+'</span>'+
          '</div>'+
          (i<STEPS.length-1?'<div style="height:2px;background:'+lineColor+';flex:1;margin:0 4px;margin-bottom:12px"></div>':'')+
        '</div>';
      }).join('');

      // Next action button
      let actionBtn='';
      if(!isPaid){
        const nextStep=STEPS[currentIdx+1];
        if(nextStep){
          const ACTION_STYLE={
            pending_approval:{bg:'#BA7517',label:'ส่งขออนุมัติ',svg:SVG_ICONS.arrow},
            approved:{bg:'#1D9E75',label:'อนุมัติ',svg:SVG_ICONS.check},
            ordered:{bg:'#185FA5',label:'สั่งซื้อ',svg:SVG_ICONS.box},
            received:{bg:'#185FA5',label:'รับของเข้าสต็อก',svg:SVG_ICONS.inbox},
            paid:{bg:'#1D9E75',label:'จ่ายเงินแล้ว',svg:SVG_ICONS.money}
          };
          const a=ACTION_STYLE[nextStep.key]||{bg:dim.ink,label:'Next',svg:SVG_ICONS.arrow};
          actionBtn='<button onclick="event.stopPropagation();flAdvanceMemo(\''+m.id+'\')" style="background:'+a.bg+';color:white;border:none;border-radius:14px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer;flex-shrink:0;display:inline-flex;align-items:center;gap:5px">'+a.svg+' '+a.label+'</button>';
        }
      } else {
        actionBtn='<span style="background:#1D9E75;color:white;padding:4px 12px;border-radius:14px;font-size:11px;font-weight:600;flex-shrink:0;display:inline-flex;align-items:center;gap:5px">'+SVG_ICONS.check+' เสร็จสมบูรณ์</span>';
      }

      // Approval info (if approved)
      let approvalInfo='';
      if(m.approvedBy){
        approvalInfo='<div style="display:flex;align-items:center;gap:8px;padding:8px 14px;background:#E1F5EE;border-top:1px solid rgba(29,158,117,.15);font-size:10px;color:#0F6E56"><span style="display:inline-flex;align-items:center">'+SVG_ICONS.check+'</span><span><strong>'+m.approvedBy+'</strong> อนุมัติเมื่อ '+(m.approvedDate||'')+'</span>'+(m.approvedNote?'<span style="font-style:italic;opacity:.85">"'+m.approvedNote+'"</span>':'')+'</div>';
      }

      const _totalSteps=STEPS.length;
      const _pctDone=_totalSteps>1?Math.round((currentIdx/(_totalSteps-1))*100):100;
      const _curStepLabel=STEPS[currentIdx]?STEPS[currentIdx].label:'';
      const _barColor=isPaid?'#1D9E75':SVG_PINK.accent;
      const stepperRow=compact?'':'<div style="padding:9px 14px;border-top:1px solid rgba(0,0,0,.04);background:#FBFAF7;display:flex;align-items:center;gap:10px"><span style="font-size:10px;color:'+dim.ink2+';white-space:nowrap;font-weight:500">ขั้น '+(currentIdx+1)+'/'+_totalSteps+' · '+_curStepLabel+'</span><span style="flex:1;height:4px;background:#E5E1DA;border-radius:3px;overflow:hidden"><span style="display:block;width:'+_pctDone+'%;height:100%;background:'+_barColor+'"></span></span>'+actionBtn+'</div>';

      // §memoTable · หนึ่งใบ = หนึ่งแถว · รายการอะไหล่ซ่อนเป็น <tr> ใต้แถวนั้น
      const _bcol=(m.boatId && typeof getBoatColor==='function')?getBoatColor(m.boatId):null;
      let _whoCell;
      if(m.scope==='general'){
        _whoCell='<span style="display:inline-flex;align-items:center;gap:4px;font-size:10.5px;font-weight:600;padding:1px 8px;border-radius:9px;background:'+dim.bg+';color:'+dim.ink2+';white-space:nowrap">&#127970; '+(m.generalCategory||'General')+'</span>';
      } else if(b){
        _whoCell='<span style="display:inline-flex;align-items:center;gap:4px;font-size:10.5px;font-weight:600;padding:1px 8px;border-radius:9px;background:'+(_bcol?_bcol.bg:dim.bg)+';color:'+(_bcol?_bcol.text:dim.ink2)+';white-space:nowrap">'+b.name+'</span>';
      } else {
        _whoCell='<span style="color:#c9c5bd;font-size:10.5px">&mdash;</span>';
      }
      if(mj) _whoCell+='<span style="font-size:9.5px;color:'+dim.ink3+';font-family:\'DM Mono\',monospace;margin-left:5px">&rarr;'+mj.no+'</span>';

      // สถานะ + ใครอนุมัติ + ความคืบหน้า อยู่ในเซลล์เดียว · เดิมกินไปคนละแถว
      let _stCell='<span style="background:'+ss.bg+';color:'+ss.color+';padding:2px 9px;border-radius:10px;font-size:9.5px;font-weight:700;letter-spacing:.04em;white-space:nowrap;display:inline-flex">'+ss.label+'</span>';
      if(m.approvedBy) _stCell+='<div title="'+String(m.approveNote||m.approvedNote||'').replace(/"/g,'&quot;')+'" style="font-size:9px;color:#0F6E56;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">&#10003; '+m.approvedBy+(m.approvedDate?(' · '+String(m.approvedDate).slice(5)):'')+'</div>';
      else if(currentIdx>=2) _stCell+='<div style="font-size:9px;color:#c9c5bd;margin-top:3px;white-space:nowrap">&mdash; ไม่มีชื่อผู้อนุมัติ</div>';
      if(!compact) _stCell+='<div style="display:flex;align-items:center;gap:5px;margin-top:4px"><span style="width:52px;height:3px;background:#E9E5DE;border-radius:2px;overflow:hidden;display:inline-block"><span style="display:block;height:100%;width:'+_pctDone+'%;background:'+_barColor+'"></span></span><i style="font-style:normal;font-size:8.5px;color:'+dim.ink3+';font-family:\'DM Mono\',monospace">'+(currentIdx+1)+'/'+_totalSteps+'</i></div>';

      const _tools='<div style="display:flex;gap:4px;justify-content:flex-end">'
        + _mIco("flViewMemo('"+m.id+"')",'รายละเอียด · แก้รายการ / ยกเลิก',_MICO.eye,'#E1F5EE','#0F6E56')
        + _mIco("flCopyMemoItems('"+m.id+"')",'คัดลอกรายการไปวางในระบบบัญชี',_MICO.copy)
        + _mIco("flPrintMemo('"+m.id+"')",'Print',_MICO.print)
        + (items.length?'<span data-chev style="width:26px;height:26px;border-radius:8px;background:'+dim.bg+';color:'+dim.ink2+';display:inline-flex;align-items:center;justify-content:center;flex:none;transition:transform .2s ease"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg></span>':'<span style="width:26px;display:inline-block"></span>')
        + '</div>';

      const _openJs="var r=this.nextElementSibling;if(!r||!r.hasAttribute('data-memo-items'))return;var o=r.style.display!=='none';r.style.display=o?'none':'table-row';var c=this.querySelector('[data-chev]');if(c)c.style.transform=o?'rotate(0deg)':'rotate(180deg)';";

      let _row='<tr onclick="'+_openJs+'" onmouseover="this.style.background=\'#FCFBF8\'" onmouseout="this.style.background=\'\'" style="cursor:'+(items.length?'pointer':'default')+'">'
        +'<td style="width:3px;padding:0;background:'+ss.stripe+';border-bottom:0.5px solid rgba(0,0,0,.055)"></td>'
        +'<td style="'+_mTd+'"><span style="font-size:11px;font-family:\'DM Mono\',monospace;color:'+dim.ink3+';font-weight:700">'+(m.no||'\u2014')+'</span></td>'
        +'<td style="'+_mTd+'"><div style="font-size:12px;font-weight:600;line-height:1.35">'+(m.title||'\u2014')+' '+typeBadge+'</div>'
          +((!compact && items.length)?('<div style="font-size:9.5px;color:'+dim.ink3+';margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:330px">'+items.slice(0,3).map(x=>x.name).join(' · ')+(items.length>3?(' +'+(items.length-3)+' more'):'')+'</div>'):'')
          +'</td>'
        +'<td style="'+_mTd+'">'+_whoCell+'</td>'
        +(compact?'':'<td style="'+_mTd+';font-size:11px">'+(m.proposer||'<span style="color:#c9c5bd">\u2014</span>')+'</td>')
        +'<td style="'+_mTd+';font-size:10.5px;color:'+dim.ink3+';font-family:\'DM Mono\',monospace;white-space:nowrap">'+fmtD(m.createdDate)+'</td>'
        +'<td style="'+_mTd+';text-align:center;font-size:11px;color:'+dim.ink3+';font-family:\'DM Mono\',monospace">'+(items.length||'\u2014')+'</td>'
        +'<td style="'+_mTd+';text-align:right;white-space:nowrap"><span style="font-size:13px;font-weight:700;font-family:\'DM Mono\',monospace;font-variant-numeric:tabular-nums;color:'+SVG_PINK.text+'">'+_mAmt(m.amount)+'</span></td>'
        +'<td style="'+_mTd+'">'+_stCell+'</td>'
        +'<td style="'+_mTd+'">'+actionBtn+'</td>'
        +'<td style="'+_mTd+';text-align:right">'+_tools+'</td>'
        +'</tr>';
      if(itemsTable) _row+='<tr data-memo-items style="display:none"><td colspan="'+_NCOL+'" style="padding:0;background:#FBFAF7;border-bottom:1px solid rgba(0,0,0,.06)">'+itemsTable+'</td></tr>';
      return _divider+_row;
    }).join(''):'<tr><td colspan="11" style="padding:30px;text-align:center;color:'+dim.ink3+';font-size:12px">No memos match filter</td></tr>';

    var useBoard=(_memoView==='board' && _memoArchiveTab==='active');
    if(useBoard){
      var COLS=[
        {label:'Pending', sts:['created','pending_approval'], hbg:'#FAEEDA',ht:'#633806',cb:'#EF9F27',ct:'#412402',am:'#854F0B'},
        {label:'Approved',sts:['approved'], hbg:'#E6F1FB',ht:'#0C447C',cb:'#85B7EB',ct:'#042C53',am:'#185FA5'},
        {label:'Ordered', sts:['ordered'], hbg:'#EEEDFE',ht:'#3C3489',cb:'#AFA9EC',ct:'#26215C',am:'#534AB7'},
        {label:'Received',sts:['received'],hbg:'#E1F5EE',ht:'#085041',cb:'#5DCAA5',ct:'#04342C',am:'#0F6E56'}
      ];
      var boardHtml='<div style="display:flex;gap:8px;align-items:flex-start;overflow-x:auto;padding-bottom:4px">'+COLS.map(function(col){
        var cm=memoList.filter(function(m){return col.sts.indexOf(m.status)>=0;});
        cm.sort(function(a,b){return _memoLastDate(b).localeCompare(_memoLastDate(a));});
        var tot=cm.reduce(function(s,m){return s+(m.amount||0);},0);
        var head='<div style="background:'+col.hbg+';border-radius:8px;padding:8px 10px"><div style="display:flex;align-items:center;gap:6px"><span style="font-size:12px;font-weight:600;color:'+col.ht+'">'+col.label+'</span><span style="font-size:10px;font-family:\'DM Mono\',monospace;background:'+col.cb+';color:'+col.ct+';padding:0 6px;border-radius:8px">'+cm.length+'</span></div><div style="font-size:10px;font-family:\'DM Mono\',monospace;color:'+col.am+';margin-top:2px">฿'+tot.toLocaleString()+'</div></div>';
        var cards=cm.map(function(m){
          var b=getBoat(m.boatId);
          var mts=MEMO_TYPE_STYLE[m.memoType||'parts']||MEMO_TYPE_STYLE.parts;
          var who=(m.scope==='general')?(m.generalCategory||'General'):(b?b.name:'—');
          return '<div style="background:white;border:1px solid '+dim.line+';border-radius:8px;padding:8px 10px">'+
            '<div style="display:flex;align-items:center;gap:5px"><span style="font-size:10px;font-family:\'DM Mono\',monospace;color:'+dim.ink3+'">'+(m.no||'—')+'</span><span style="width:5px;height:5px;border-radius:50%;background:'+mts.dot+'"></span><span style="flex:1"></span><button onclick="event.stopPropagation();flViewMemo(\''+m.id+'\')" title="รายละเอียด · แก้รายการ" style="background:#E1F5EE;border:none;border-radius:7px;height:20px;padding:0 8px;cursor:pointer;color:#0F6E56;font-size:9px;font-weight:700;line-height:1;flex-shrink:0">รายละเอียด</button><button onclick="flPrintMemo(\''+m.id+'\')" title="Print" style="background:'+dim.bg+';border:none;border-radius:7px;height:20px;padding:0 7px;cursor:pointer;color:'+dim.ink2+';font-size:9px;font-weight:500;line-height:1;flex-shrink:0">Print</button><button onclick="flAdvanceMemo(\''+m.id+'\')" title="ขั้นถัดไป" style="background:'+dim.bg+';border:none;border-radius:7px;width:20px;height:20px;cursor:pointer;color:'+dim.ink2+';font-size:12px;line-height:1;flex-shrink:0">→</button></div>'+
            '<div style="font-size:12px;font-weight:600;margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(m.title||'—')+'</div>'+
            '<div style="font-size:10px;color:'+dim.ink3+';margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+who+' · '+fmtD(_memoLastDate(m))+'</div>'+
            '<div style="font-size:12px;font-weight:700;font-family:\'DM Mono\',monospace;color:'+SVG_PINK.text+';margin-top:4px">฿'+(m.amount||0).toLocaleString()+'</div>'+
          '</div>';
        }).join('')||'<div style="font-size:10px;color:'+dim.ink3+';text-align:center;padding:14px 4px">—</div>';
        return '<div style="flex:1;min-width:150px;display:flex;flex-direction:column;gap:7px">'+head+cards+'</div>';
      }).join('')+'</div>';
      return tabBar+searchRow+boardHtml;
    }
    // §memoTable · หัวตารางค้างไว้ · เลื่อนยาวแค่ไหนก็ยังรู้ว่าคอลัมน์ไหนคืออะไร
    const _mHead='<thead><tr>'+_MCOL.map(function(c){
      var al=(c[2]==='r')?'right':(c[2]==='c')?'center':'left';
      return '<th style="'+(c[1]?('width:'+c[1]+'px;'):'')+'position:sticky;top:0;z-index:2;background:#FBFAF7;padding:'+(c[1]===3?'0':'9px 10px')+';text-align:'+al+';font-size:9px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;color:'+dim.ink3+';white-space:nowrap;border-bottom:1px solid #E5E1DA">'+(c[0]||'')+'</th>';
    }).join('')+'</tr></thead>';
    const _mTable='<div style="background:white;border:1px solid '+dim.line+';border-radius:14px;overflow:hidden">'
      +'<table style="width:100%;border-collapse:collapse">'+_mHead+'<tbody>'+memoCards+'</tbody></table></div>';
    return tabBar+searchRow+filterBar+_mTable;
  }
}


function flOpenReceiveStock(){
  _receiveItemId=null;
  document.getElementById('receive-item-sel').style.display='block';
  document.getElementById('receive-item-fixed').style.display='none';
  document.getElementById('receive-item-sel').innerHTML='<option value="">— เลือกรายการ —</option>'+FL_INVENTORY.map(x=>`<option value="${x.id}">${x.name} (คงเหลือ ${x.qty} ${x.unit})</option>`).join('');
  document.getElementById('receive-qty').value='1';
  document.getElementById('receive-note').value='';
  document.getElementById('receive-date').value=TODAY_STR;
  // Default location empty (user picks after selecting item)
  const _locE = document.getElementById('receive-location');
  if(_locE) _locE.value = 'คลัง Tub Lamu';
  const _warnE = document.getElementById('receive-location-warn');
  if(_warnE){ _warnE.style.display = 'none'; _warnE.textContent = ''; }
  // When user picks item in select, sync location
  document.getElementById('receive-item-sel').onchange = function(){
    const sel = this.value;
    if(sel){
      const it = FL_INVENTORY.find(x=>x.id===sel);
      if(it && it.location){
        _locE.value = it.location;
        if(_warnE){ _warnE.style.display = 'none'; _warnE.textContent = ''; }
      }
    }
  };
  // Warn if user changes location to something different
  _locE.onchange = function(){
    const selId = document.getElementById('receive-item-sel').value;
    if(selId){
      const it = FL_INVENTORY.find(x=>x.id===selId);
      if(it && it.location && it.location !== this.value){
        _warnE.style.display = 'block';
        _warnE.textContent = `⚠️ Item เดิมอยู่ที่ "${it.location}" · เปลี่ยนเป็น "${this.value}" จะอัพเดท location ของ item`;
      } else {
        _warnE.style.display = 'none'; _warnE.textContent = '';
      }
    }
  };
  openModal('fl-modal-receive');
}
function flOpenReceiveOne(id){
  _receiveItemId=id;
  const item=FL_INVENTORY.find(x=>x.id===id);if(!item)return;
  document.getElementById('receive-item-sel').style.display='none';
  const fixed=document.getElementById('receive-item-fixed');
  fixed.style.display='block';fixed.textContent=`${item.name} (คงเหลือ ${item.qty} ${item.unit})`;
  document.getElementById('receive-qty').value='1';
  document.getElementById('receive-note').value='';
  document.getElementById('receive-date').value=TODAY_STR;
  // Default location = item's current location
  const _locE = document.getElementById('receive-location');
  if(_locE) _locE.value = item.location || 'คลัง Tub Lamu';
  const _warnE = document.getElementById('receive-location-warn');
  /* §memoRecvWh · โมดัลตัวเดียวกันถูกใช้สองโหมด · โหมด memo เปลี่ยนสีกล่องนี้เป็นโทนคำอธิบายไว้
     ถ้าไม่คืนค่า คำเตือนจริงของโหมดรับรายตัวจะออกมาเป็นสีเทากลืนไปเลย */
  if(_warnE){ _warnE.style.display='none'; _warnE.textContent='';
    _warnE.style.color='#854F0B'; _warnE.style.background='#FFF8E1'; _warnE.style.borderColor='#F0D58C'; }
  // Warn when user changes location
  _locE.onchange = function(){
    if(item.location && item.location !== this.value){
      _warnE.style.display = 'block';
      _warnE.textContent = `⚠️ Item เดิมอยู่ที่ "${item.location}" · เปลี่ยนเป็น "${this.value}" จะอัพเดท location ของ item`;
    } else {
      _warnE.style.display = 'none'; _warnE.textContent = '';
    }
  };
  openModal('fl-modal-receive');
}
let _receiveItemId=null;

// ── Edit Inventory Item — opens modal pre-filled with item data ──
function flOpenInvEdit(id){
  const item=FL_INVENTORY.find(x=>x.id===id);
  if(!item){alert('ไม่พบรายการนี้');return;}
  document.getElementById('inv-edit-id').value=id;
  document.getElementById('inv-edit-name').value=item.name||'';
  document.getElementById('inv-edit-partno').value=item.partNo||'';
  document.getElementById('inv-edit-cat').value=item.category||'general';
  document.getElementById('inv-edit-supplier').value=item.supplier||'';
  document.getElementById('inv-edit-location').value=item.location||'';
  document.getElementById('inv-edit-qty').value=item.qty||0;
  document.getElementById('inv-edit-unit').value=item.unit||'ชิ้น';
  document.getElementById('inv-edit-min').value=item.minQty||0;
  document.getElementById('inv-edit-cost').value=item.cost||0;
  // Detect engine model from note (BF250D/BF250A/DF250W/DF325A) — split out for dropdown
  const fullNote=item.note||'';
  const engineMatch=fullNote.match(/^(BF250D|BF250A|DF250W|DF325A)\b/i);
  const detectedEngine=engineMatch?engineMatch[1].toUpperCase():'';
  const remainingNote=detectedEngine?fullNote.replace(/^(BF250D|BF250A|DF250W|DF325A)\s*·?\s*/i,'').trim():fullNote;
  document.getElementById('inv-edit-engine').value=detectedEngine;
  document.getElementById('inv-edit-note').value=remainingNote;
  document.getElementById('inv-edit-warn').style.display='none';
  // Render audit history (filter to 'edit' + 'receive' types)
  const hist=(item.history||[]).slice().reverse(); // newest first
  const histEl=document.getElementById('inv-edit-history');
  if(hist.length===0){
    histEl.innerHTML='<div style="color:#aaa;font-style:italic;font-size:11px;text-align:center;padding:8px">ยังไม่มีประวัติการแก้ไข</div>';
  } else {
    histEl.innerHTML='<div style="font-weight:600;color:#666;margin-bottom:6px;font-size:10px;text-transform:uppercase;letter-spacing:.05em">ประวัติการเปลี่ยนแปลง</div>'+
      hist.slice(0,10).map(h=>{
        const dateStr=h.date||'';
        if(h.type==='edit' && h.changes){
          const changesHtml=h.changes.map(ch=>`<div style="margin-left:8px;font-size:10.5px;color:#666"><strong>${ch.field}:</strong> <span style="color:#A32D2D;text-decoration:line-through">${ch.from||'(ว่าง)'}</span> → <span style="color:#0F6E56">${ch.to||'(ว่าง)'}</span></div>`).join('');
          return `<div style="margin-bottom:6px;padding:6px 8px;background:#FBFAF7;border-radius:6px"><div style="display:flex;justify-content:space-between;font-size:10.5px;font-weight:500"><span>📝 แก้ไข</span><span style="color:#aaa;font-family:'DM Mono',monospace">${dateStr}</span></div>${changesHtml}${h.note?`<div style="margin-top:3px;font-size:10px;font-style:italic;color:#888">"${h.note}"</div>`:''}</div>`;
        } else if(h.type==='receive'){
          return `<div style="margin-bottom:6px;padding:6px 8px;background:#F1F5EE;border-radius:6px;font-size:10.5px"><div style="display:flex;justify-content:space-between"><span>📥 รับของ +${h.qty}</span><span style="color:#aaa;font-family:'DM Mono',monospace">${dateStr}</span></div>${h.note?`<div style="font-size:10px;color:#666;margin-top:2px">${h.note}</div>`:''}</div>`;
        } else {
          return `<div style="margin-bottom:4px;font-size:10.5px;color:#888">${h.type||''} ${dateStr}</div>`;
        }
      }).join('')+
      (hist.length>10?`<div style="text-align:center;color:#aaa;font-size:10px;margin-top:4px">+${hist.length-10} more entries</div>`:'');
  }
  openModal('fl-modal-inv-edit');
}

function flSaveInvEdit(){
  const id=document.getElementById('inv-edit-id').value;
  const item=FL_INVENTORY.find(x=>x.id===id);
  if(!item){alert('ไม่พบรายการ');return;}

  // Collect new values
  const engineModel=document.getElementById('inv-edit-engine')?.value||'';
  const extraNote=document.getElementById('inv-edit-note').value.trim();
  const combinedNote=[engineModel, extraNote].filter(Boolean).join(' · ');
  const newVals={
    name: document.getElementById('inv-edit-name').value.trim(),
    partNo: document.getElementById('inv-edit-partno').value.trim(),
    category: document.getElementById('inv-edit-cat').value,
    supplier: document.getElementById('inv-edit-supplier').value.trim(),
    location: document.getElementById('inv-edit-location').value.trim(),
    qty: parseFloat(document.getElementById('inv-edit-qty').value)||0,
    unit: document.getElementById('inv-edit-unit').value.trim(),
    minQty: parseFloat(document.getElementById('inv-edit-min').value)||0,
    cost: parseFloat(document.getElementById('inv-edit-cost').value)||0,
    note: combinedNote,
  };

  if(!newVals.name){alert('กรุณากรอกชื่อรายการ');return;}

  // Compute changes
  const FIELD_LABELS={name:'ชื่อรายการ',partNo:'Part No',category:'หมวดหมู่',supplier:'Supplier',location:'ที่เก็บ',qty:'จำนวน',unit:'หน่วย',minQty:'ขั้นต่ำ',cost:'ราคา/หน่วย',note:'หมายเหตุ'};
  const changes=[];
  Object.keys(newVals).forEach(k=>{
    const oldV=item[k];
    const newV=newVals[k];
    // Normalize for comparison
    const oldStr=String(oldV==null?'':oldV);
    const newStr=String(newV==null?'':newV);
    if(oldStr!==newStr){
      changes.push({field:FIELD_LABELS[k]||k,from:oldStr,to:newStr,key:k});
    }
  });

  if(changes.length===0){
    closeModal('fl-modal-inv-edit');
    return;
  }

  // Warn if partNo changed (might break memo links)
  const partNoChange=changes.find(c=>c.key==='partNo');
  if(partNoChange){
    if(!confirm(`⚠ คุณกำลังเปลี่ยน Part Number\nจาก: ${partNoChange.from}\nเป็น: ${partNoChange.to}\n\nอาจกระทบประวัติ Memo เก่าที่อ้างอิง Part No นี้\nต้องการดำเนินการต่อหรือไม่?`)) return;
  }

  // Apply changes
  Object.keys(newVals).forEach(k=>{ item[k]=newVals[k]; });

  // Append audit log entry
  if(!item.history) item.history=[];
  item.history.push({
    date: new Date().toISOString().slice(0,10),
    type: 'edit',
    changes: changes.map(c=>({field:c.field,from:c.from,to:c.to})),
    note: '',
    by: ''
  });

  flSave();
  closeModal('fl-modal-inv-edit');
  flRenderInventory();
}

function flSaveReceive(){
  if(_receiveMemoId){
    const mo=FL_MEMOS.find(x=>x.id===_receiveMemoId);
    if(mo){
      const date=document.getElementById('receive-date').value;
      const note=document.getElementById('receive-note').value;
      const memoLocation = document.getElementById('receive-location')?.value || 'คลัง Tub Lamu';
      let updatedCount=0, createdCount=0;
      (mo.items||[]).forEach((it,i)=>{
        const qtyEl=document.getElementById('recv-qty-'+i);
        const qty=parseFloat(qtyEl?.value)||0;
        if(qty<=0) return;
        // Skip labor items — they don't go into stock
        const cat=it.category||mo.memoType||'parts';
        if(cat==='labor') return;
        // match by invId first, then by exact name
        let inv=it.invId
          ?FL_INVENTORY.find(x=>x.id===it.invId)
          :FL_INVENTORY.find(x=>x.name===it.name||it.name.includes(x.name));
        if(inv){
          // Ensure stocks[] exists, then add at chosen location
          invSyncLegacy(inv);
          invAddAt(inv, memoLocation, qty);
          if(!inv.history)inv.history=[];
          inv.history.push({id:(typeof LA_UID==='function'?LA_UID('h'):'h'+Math.random().toString(36).slice(2)),date,type:'receive',qty,location:memoLocation,note:`จาก ${mo.no} · ${note} · @ ${memoLocation}`,by:'',memoId:mo.id});   // §dupNoId
          updatedCount++;
        } else {
          // Auto-create new inventory item from memo line — with multi-warehouse stocks
          const newInv={
            id:'i'+Date.now()+Math.floor(Math.random()*1000),
            name:it.name,
            partNo:'',
            category:'อื่นๆ',
            supplier:mo.supplier||'',
            location:memoLocation,
            stocks:[{location:memoLocation, qty:qty, minQty:0}],
            qty:qty, totalQty:qty,
            minQty:0,
            unit:it.unit||'ชิ้น',
            cost:it.price||0,
            note:`สร้างอัตโนมัติจาก ${mo.no}`,
            createdFrom:mo.no,
            createdDate:date,
            history:[{date,type:'receive',qty,location:memoLocation,note:`รับครั้งแรก · จาก ${mo.no} · ${note} · @ ${memoLocation}`,by:''}]
          };
          FL_INVENTORY.push(newInv);
          it.invId=newInv.id;
          createdCount++;
        }
      });
      mo.currentStep=4;mo.status='received';
      let toastMsg=`รับของ ${mo.no} เรียบร้อย · @ ${memoLocation}`;
      if(updatedCount&&createdCount) toastMsg+=` · อัพเดท ${updatedCount} · สร้างใหม่ ${createdCount} items`;
      else if(updatedCount) toastMsg+=` · อัพเดท ${updatedCount} items`;
      else if(createdCount) toastMsg+=` · สร้างใหม่ ${createdCount} items`;
      flShowToast(toastMsg);
    }
    _receiveMemoId=null;
    document.getElementById('receive-item-sel').style.display='block';
    document.getElementById('receive-item-fixed').style.display='none';
    const qtyRow=document.getElementById('receive-qty');if(qtyRow)qtyRow.style.display='';
    flSave();closeModal('fl-modal-receive');flRenderInventory();
    return;
  }
  const id=_receiveItemId||document.getElementById('receive-item-sel').value;
  if(!id){alert('กรุณาเลือกรายการ');return;}
  const item=FL_INVENTORY.find(x=>x.id===id);if(!item)return;
  const qty=parseFloat(document.getElementById('receive-qty').value)||0;
  if(qty<=0){alert('กรุณาระบุจำนวน');return;}
  const newLocation = document.getElementById('receive-location')?.value || item.location;
  // Ensure migrated before adding
  invSyncLegacy(item);
  // Multi-warehouse: add qty to the specific location's stock entry
  invAddAt(item, newLocation, qty);
  if(!item.history)item.history=[];
  const baseNote = document.getElementById('receive-note').value;
  item.history.push({
    date:document.getElementById('receive-date').value,
    type:'receive',
    qty,
    location: newLocation,
    note: (baseNote ? baseNote : '') + ` · @ ${newLocation}`,
    by:''
  });
  flSave();closeModal('fl-modal-receive');flRenderInventory();
  flShowToast(`รับ ${item.name} +${qty} ${item.unit} · ${newLocation} เรียบร้อย`);
  _receiveItemId=null;
}
// ── Transfer Modal Functions (Multi-Warehouse Phase 2) ──
let _transferItemId = null;
function flOpenTransfer(id){
  _transferItemId = id;
  const item = FL_INVENTORY.find(x=>x.id===id);
  if(!item) return;
  // Ensure migrated
  invSyncLegacy(item);
  document.getElementById('transfer-item-name').textContent = `${item.name} (Total: ${item.totalQty||0} ${item.unit||''})`;
  // Populate "From" dropdown with locations that have stock > 0
  const fromSel = document.getElementById('transfer-from');
  fromSel.innerHTML = '';
  const stocksWithQty = (item.stocks||[]).filter(s=>s.qty>0);
  if(stocksWithQty.length === 0){
    fromSel.innerHTML = '<option value="">— ไม่มีของในคลัง —</option>';
  } else {
    stocksWithQty.forEach(s=>{
      const opt = document.createElement('option');
      opt.value = s.location;
      opt.textContent = `${s.location} (${s.qty} ${item.unit||''})`;
      fromSel.appendChild(opt);
    });
  }
  document.getElementById('transfer-qty').value = '1';
  document.getElementById('transfer-date').value = TODAY_STR;
  document.getElementById('transfer-note').value = '';
  // Default "To" = different from "From"
  const firstFrom = stocksWithQty[0]?.location || 'คลัง Tub Lamu';
  const toSel = document.getElementById('transfer-to');
  const fallback = WAREHOUSE_LOCATIONS.find(l => l !== firstFrom) || 'คลัง Visit Panwa';
  toSel.value = fallback;
  transferUpdateMax();
  openModal('fl-modal-transfer');
}

function transferUpdateMax(){
  const item = FL_INVENTORY.find(x=>x.id===_transferItemId);
  if(!item) return;
  const fromLoc = document.getElementById('transfer-from').value;
  const qty = invQtyAt(item, fromLoc);
  const qtyEl = document.getElementById('transfer-qty');
  if(qtyEl) qtyEl.max = qty;
  const stockEl = document.getElementById('transfer-from-stock');
  if(stockEl) stockEl.textContent = `คงเหลือ: ${qty} ${item.unit||''}`;
}

function flSaveTransfer(){
  const id = _transferItemId;
  if(!id){alert('No item');return;}
  const item = FL_INVENTORY.find(x=>x.id===id);
  if(!item){alert('Item not found');return;}
  const fromLoc = document.getElementById('transfer-from').value;
  const toLoc = document.getElementById('transfer-to').value;
  if(!fromLoc){alert('กรุณาเลือกคลังต้นทาง');return;}
  if(!toLoc){alert('กรุณาเลือกคลังปลายทาง');return;}
  if(fromLoc === toLoc){alert('คลังต้นทางและปลายทางต้องต่างกัน');return;}
  const qty = parseFloat(document.getElementById('transfer-qty').value)||0;
  if(qty <= 0){alert('กรุณาระบุจำนวน > 0');return;}
  const available = invQtyAt(item, fromLoc);
  if(qty > available){alert(`คลัง ${fromLoc} มีเพียง ${available} ${item.unit||''}`);return;}
  const date = document.getElementById('transfer-date').value || TODAY_STR;
  const note = document.getElementById('transfer-note').value.trim();
  
  const success = invTransfer(item, fromLoc, toLoc, qty, date, note);
  if(!success){alert('ย้ายไม่สำเร็จ');return;}
  
  flSave();
  closeModal('fl-modal-transfer');
  flRenderInventory();
  flShowToast(`ย้าย ${item.name} · ${qty} ${item.unit||''} · ${fromLoc} → ${toLoc} เรียบร้อย`);
  _transferItemId = null;
}

// Pier Assignment functions
let _pierAsnBoatId = null;
function flOpenNewAssignment(boatId){
  _pierAsnBoatId = boatId;
  const b = BOATS.find(x=>x.id===boatId);
  if(!b) return;
  document.getElementById('asn-boat-name').textContent = b.name;
  // Default from = current pier
  const curPier = typeof getBoatCurrentPier==='function' ? getBoatCurrentPier(b) : (b.pier||'tublamu');
  document.getElementById('asn-from').value = curPier;
  // Default to = different pier
  const piers = ['tublamu','panwa','ranong'];
  document.getElementById('asn-to').value = piers.find(p=>p!==curPier) || 'panwa';
  document.getElementById('asn-type').value = 'temporary';
  document.getElementById('asn-start').value = TODAY_STR;
  // Default end = 7 days from today
  const end = new Date();
  end.setDate(end.getDate()+7);
  document.getElementById('asn-end').value = end.toISOString().slice(0,10);
  document.getElementById('asn-reason').value = '';
  document.getElementById('asn-cost').value = '';
  document.getElementById('asn-warn').style.display='none';
  openModal('fl-modal-assignment');
}

function flSaveAssignment(){
  const boatId = _pierAsnBoatId;
  if(!boatId){alert('No boat selected');return;}
  const b = BOATS.find(x=>x.id===boatId);
  if(!b){alert('Boat not found');return;}
  const fromPier = document.getElementById('asn-from').value;
  const toPier = document.getElementById('asn-to').value;
  if(fromPier === toPier){alert('From และ To ต้องต่างกัน');return;}
  const type = document.getElementById('asn-type').value;
  const startDate = document.getElementById('asn-start').value;
  const endDate = document.getElementById('asn-end').value;
  if(!startDate || !endDate){alert('กรุณาระบุวันเริ่ม-วันจบ');return;}
  if(endDate < startDate){alert('วันจบต้องหลังวันเริ่ม');return;}
  const reason = document.getElementById('asn-reason').value.trim();
  const cost = parseFloat(document.getElementById('asn-cost').value) || 0;
  
  if(!b.assignments) b.assignments = [];
  const newId = 'asn_' + Date.now();
  // Determine initial status
  let status = 'planned';
  if(startDate <= TODAY_STR && endDate >= TODAY_STR) status = 'active';
  else if(endDate < TODAY_STR) status = 'completed';
  
  b.assignments.push({
    id: newId,
    type,
    fromPier,
    toPier,
    startDate,
    endDate,
    reason,
    cost,
    status,
    createdDate: TODAY_STR
  });
  
  // If permanent and active, update home pier
  if(type === 'permanent' && status === 'active'){
    b.pier = toPier;
  }
  
  // Save to localStorage
  const ls = JSON.parse(localStorage.getItem(LS_KEY)||'{}');
  if(ls.boats){
    const bls = ls.boats.find(x=>x.id===boatId);
    if(bls){
      bls.assignments = b.assignments;
      if(type === 'permanent' && status === 'active') bls.pier = toPier;
    }
    localStorage.setItem(LS_KEY, JSON.stringify(ls));
  }
  
  closeModal('fl-modal-assignment');
  // Re-render boat detail (works in both Asset>Boats and Boat Status views)
  if(typeof flRenderBoatDetailPink === 'function') flRenderBoatDetailPink();
  if(typeof renderBoats === 'function') renderBoats();
  if(typeof renderBoatDetailPink === 'function') renderBoatDetailPink();
  flShowToast(`บันทึก Assignment: ${PIER_LABELS[fromPier]} → ${PIER_LABELS[toPier]} (${status})`);
  _pierAsnBoatId = null;
}

function flCancelAssignment(boatId, asnId){
  if(!confirm('ยกเลิก assignment นี้?')) return;
  const b = BOATS.find(x=>x.id===boatId);
  if(!b || !b.assignments) return;
  const a = b.assignments.find(x=>x.id===asnId);
  if(!a) return;
  a.status = 'cancelled';
  // Save to localStorage
  const ls = JSON.parse(localStorage.getItem(LS_KEY)||'{}');
  if(ls.boats){
    const bls = ls.boats.find(x=>x.id===boatId);
    if(bls && bls.assignments){
      const aLs = bls.assignments.find(x=>x.id===asnId);
      if(aLs) aLs.status = 'cancelled';
    }
    localStorage.setItem(LS_KEY, JSON.stringify(ls));
  }
  if(typeof flRenderBoatDetailPink === 'function') flRenderBoatDetailPink();
  if(typeof renderBoats === 'function') renderBoats();
  if(typeof renderBoatDetailPink === 'function') renderBoatDetailPink();
  flShowToast('ยกเลิก Assignment เรียบร้อย');
}

// Auto-update assignment statuses on load (planned→active→completed)
function flAutoUpdateAssignments(){
  const today = TODAY_STR;
  let changed = false;
  BOATS.forEach(b=>{
    if(!b.assignments) return;
    b.assignments.forEach(a=>{
      if(a.status === 'cancelled') return;
      const newStatus = (a.startDate <= today && a.endDate >= today) ? 'active'
        : (a.endDate < today) ? 'completed' : 'planned';
      if(a.status !== newStatus){
        a.status = newStatus;
        changed = true;
      }
    });
  });
  if(changed){
    const ls = JSON.parse(localStorage.getItem(LS_KEY)||'{}');
    if(ls.boats){
      ls.boats.forEach(blS=>{
        const b = BOATS.find(x=>x.id===blS.id);
        if(b && b.assignments) blS.assignments = b.assignments;
      });
      localStorage.setItem(LS_KEY, JSON.stringify(ls));
    }
  }
}

// ── Edit Boat Status during Job ──
let _ebsJobId = null;
let _ebsNewStatus = null;
function flOpenEditBoatStatus(jobId){
  const m = FL_MAINT.find(x=>x.id===jobId);
  if(!m) return;
  _ebsJobId = jobId;
  const b = getBoat(m.boatId);
  document.getElementById('ebs-job-name').textContent = `${m.no} · ${m.title}${b?' · '+b.name:''}`;
  const curBoatSt = m.boatStatus || (m.setFixing===false ? 'available' : 'fixing');
  const lblMap = {available:'🟢 Available · เรือยังออกได้', fixing:'🟡 Fixing · ระหว่างซ่อม', unavailable:'🔴 Unavailable · หยุดให้บริการ'};
  document.getElementById('ebs-current').textContent = lblMap[curBoatSt] || curBoatSt;
  // Reset picker
  document.querySelectorAll('.ebs-st-opt').forEach(el=>{
    el.classList.remove('on');
    el.style.background = 'white';
    el.style.borderColor = 'rgba(0,0,0,.08)';
  });
  _ebsNewStatus = null;
  document.getElementById('ebs-reason-row').style.display = 'none';
  document.getElementById('ebs-reason').value = '';
  document.getElementById('ebs-date').value = TODAY_STR;
  document.getElementById('ebs-note').value = '';
  openModal('fl-modal-edit-boat-status');
}

function ebsSelectStatus(st, el){
  _ebsNewStatus = st;
  document.querySelectorAll('.ebs-st-opt').forEach(c=>{
    c.classList.remove('on');
    c.style.background = 'white';
    c.style.borderColor = 'rgba(0,0,0,.08)';
  });
  el.classList.add('on');
  if(st==='fixing'){ el.style.background='#FDF6E9'; el.style.borderColor='#BA7517'; }
  if(st==='unavailable'){ el.style.background='#FBE9E9'; el.style.borderColor='#A32D2D'; }
  if(st==='available'){ el.style.background='#E6F4ED'; el.style.borderColor='#0F6E56'; }
  document.getElementById('ebs-reason-row').style.display = (st==='unavailable') ? '' : 'none';
}

function flSaveEditBoatStatus(){
  const jobId = _ebsJobId;
  if(!jobId){alert('No job');return;}
  const m = FL_MAINT.find(x=>x.id===jobId);
  if(!m){alert('Job not found');return;}
  const newSt = _ebsNewStatus;
  if(!newSt){alert('กรุณาเลือก status');return;}
  const oldSt = m.boatStatus || (m.setFixing===false ? 'available' : 'fixing');
  if(newSt === oldSt){alert('Status ใหม่เหมือนปัจจุบัน');return;}
  const effDate = document.getElementById('ebs-date').value;
  if(!effDate){alert('กรุณาระบุวันที่');return;}
  const reason = (newSt==='unavailable') ? document.getElementById('ebs-reason').value : '';
  if(newSt==='unavailable' && !reason){alert('กรุณาเลือกเหตุผล');return;}
  const note = document.getElementById('ebs-note').value.trim();
  
  // 1. Update MJ
  m.boatStatus = newSt;
  m.boatStatusReason = reason;
  m.setFixing = (newSt === 'fixing' || newSt === 'unavailable');
  
  // 2. Update boat log
  const b = getBoat(m.boatId);
  if(b){
    if(!b.log) b.log = [];
    // Close any open log entry from this MJ on effDate
    b.log.forEach(l=>{
      if(!l.to && l.note && l.note.includes(m.no)){
        l.to = effDate;
      }
    });
    // If newSt is not available, push new log entry
    if(newSt !== 'available'){
      b.log.push({
        id: 'sl' + Date.now(),
        s: newSt,
        from: effDate, to: null,
        loc: m.location || '',
        note: `Maintenance Job ${m.no} (status changed)`,
        reason: reason
      });
    } else {
      // newSt === 'available' → close any open fixing/unavailable logs
      // (already done above) · also push an explicit available entry for visibility
      b.log.push({
        id: 'sl' + Date.now(),
        s: 'available',
        from: effDate, to: null,
        loc: '',
        note: `${m.no} · เรือกลับมาใช้งานได้${note?' · '+note:''}`,
        reason: ''
      });
    }
  }
  
  // 3. Progress log
  if(!m.progressLog) m.progressLog = [];
  const lblMap = {available:'🟢 Available', fixing:'🟡 Fixing', unavailable:'🔴 Unavailable'};
  m.progressLog.push({
    date: effDate,
    text: `⚙️ เปลี่ยน Boat Status: ${lblMap[oldSt]||oldSt} → ${lblMap[newSt]||newSt}${reason?' · '+reason:''}${note?' · "'+note+'"':''}`,
    by: 'ผู้ใช้'
  });
  
  flSave();
  closeModal('fl-modal-edit-boat-status');
  if(typeof flRenderMaintDetail==='function') flRenderMaintDetail(jobId);
  if(typeof flRenderMaint==='function') flRenderMaint();
  if(typeof renderBoats==='function') renderBoats();
  flShowToast(`Boat status: ${lblMap[oldSt]||oldSt} → ${lblMap[newSt]||newSt}`);
  _ebsJobId = null;
  _ebsNewStatus = null;
}

function flShowItemHistory(id){
  const item=FL_INVENTORY.find(x=>x.id===id);if(!item)return;
  const MONTHS=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  const fmtD=s=>{if(!s)return'—';const d=new Date(s);return`${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()+543}`;};
  const isLow=item.qty<(item.minQty||0);
  document.getElementById('ihp-name').textContent=item.name;
  document.getElementById('ihp-sub').textContent=`${item.partNo||''}${item.supplier?' · '+item.supplier:''} · ${item.location||''}`;
  document.getElementById('ihp-qty').innerHTML=`<span style="color:${isLow?'var(--red)':'var(--green)'}">${item.qty}</span><span style="font-size:10px;color:var(--ink-soft);margin-left:3px">${item.unit}</span>`;
  document.getElementById('ihp-min').textContent=`${item.minQty||0} ${item.unit}`;
  document.getElementById('ihp-cost').textContent=`฿${(item.cost||0).toLocaleString()}`;
  document.getElementById('ihp-bal').innerHTML=`<span style="color:${isLow?'var(--red)':'var(--green)'}">${item.qty} ${item.unit}${isLow?' ⚠️':''}</span>`;
  const hist=(item.history||[]).slice().reverse();
  document.getElementById('ihp-hist').innerHTML=hist.length
    ?hist.map((h,i,arr)=>{
      const isEdit=h.type==='edit';
      const isIn=h.type==='receive';
      const isLast=i===arr.length-1;
      const dotColor=isEdit?'#666':(isIn?'var(--green)':'var(--red)');
      let mainText, rightText;
      if(isEdit){
        const chCount=(h.changes||[]).length;
        const fieldsList=(h.changes||[]).map(c=>c.field).join(', ');
        mainText='แก้ไข: '+(fieldsList||'รายการ');
        rightText=`<span style="font-size:10px;font-weight:500;color:var(--ink-soft);font-family:'DM Mono',monospace">${chCount} field${chCount>1?'s':''}</span>`;
      } else {
        mainText=h.note||h.desc||'-';
        rightText=`<span style="font-size:11px;font-weight:500;color:${isIn?'var(--green)':'var(--red)'};font-family:'DM Mono',monospace">${isIn?'+':'-'}${h.qty||0} ${item.unit||''}</span>`;
      }
      return`<div style="display:flex;gap:8px;padding:7px 0;border-bottom:${isLast?'none':'0.5px solid var(--border)'}">
        <div style="position:relative;flex-shrink:0">
          <div style="width:8px;height:8px;border-radius:50%;background:${dotColor};margin-top:4px"></div>
          ${!isLast?`<div style="position:absolute;left:3.5px;top:12px;bottom:-7px;width:1px;background:var(--border)"></div>`:''}
        </div>
        <div style="font-size:10px;font-family:'DM Mono',monospace;color:var(--ink-soft);min-width:60px;flex-shrink:0">${fmtD(h.date)}</div>
        <div style="flex:1"><div style="font-size:11px;color:var(--ink)">${mainText}</div>
        ${h.by?`<div style="font-size:10px;color:var(--ink-soft)">${h.by}</div>`:''}</div>
        <div style="flex-shrink:0">${rightText}</div>
      </div>`;
    }).join('')
    :'<div style="font-size:11px;color:var(--ink-soft)">ยังไม่มีประวัติ</div>';
  const panel=document.getElementById('inv-hist-panel');
  const grid=document.getElementById('inv-grid-wrap');
  panel.style.display='block';
  grid.style.gridTemplateColumns='1fr 330px';
  document.querySelectorAll('#fl-inv-list tr').forEach(r=>r.style.background='');
  const rows=document.querySelectorAll('#fl-inv-list tr');
  rows.forEach(r=>{if(r.innerHTML.includes(`flShowItemHistory('${id}')`))r.style.background='var(--ocean-50)';});
}
