// Open Memo pre-filled with checked inventory items
function flOpenMemoFromSelected(){
  if(_invSelected.size===0){alert('กรุณาเลือกรายการก่อน');return;}
  _memoMaintId=null;
  const selectedItems=FL_INVENTORY.filter(x=>_invSelected.has(x.id));
  _memoItems=selectedItems.map(it=>({
    name:it.name,
    qty:1,
    price:it.cost||0,
    fromInventory:true,
    invId:it.id,
    unit:it.unit,
    partNo:it.partNo,
    category:'parts'
  }));
  // Group supplier(s) into the subject
  const suppliers=Array.from(new Set(selectedItems.map(x=>x.supplier).filter(Boolean)));
  const supplierTxt=suppliers.length===1?suppliers[0]:(suppliers.length>1?`${suppliers.length} suppliers`:'');
  const locations=Array.from(new Set(selectedItems.map(x=>x.location).filter(Boolean)));
  const subject=`สั่งซื้ออะไหล่ ${selectedItems.length} รายการ${supplierTxt?' · '+supplierTxt:''}`;

  document.getElementById('memo-subject').value=subject;
  const _dE3=document.getElementById('memo-date');if(_dE3)_dE3.value=TODAY_STR;
  document.getElementById('memo-from').value='ท่าเรือภูเก็ต';
  document.getElementById('memo-proposer').value='';
  const _ne=document.getElementById('memo-note');if(_ne)_ne.value='';
  document.getElementById('memo-to').value='กรรมการผู้จัดการ';

  // Build reference list (collapsible item summary in ref box)
  const refList=selectedItems.slice(0,5).map(x=>`${x.name}${x.partNo?' ('+x.partNo+')':''}`).join(' · ');
  const refMore=selectedItems.length>5?` + ${selectedItems.length-5} more`:'';
  const locTxt=locations.length===1?locations[0]:(locations.length>1?`${locations.length} warehouses`:'');
  document.getElementById('memo-ref-box').innerHTML=
    `<div style="font-size:11px;color:var(--ink-soft);line-height:1.5">`+
    `<div><strong style="color:var(--ink)">Memo จาก Inventory (Bulk)</strong> · ${selectedItems.length} รายการ${locTxt?' · '+locTxt:''}</div>`+
    `<div style="margin-top:4px;font-size:10px;opacity:.85">${refList}${refMore}</div>`+
    `</div>`;

  const vatChk=document.getElementById('memo-vat-enabled');if(vatChk)vatChk.checked=true;
  const vatRate=document.getElementById('memo-vat-rate');if(vatRate)vatRate.value=7;
  const discPct=document.getElementById('memo-discount-pct');if(discPct)discPct.value='';
  const discAmt=document.getElementById('memo-discount-amt');if(discAmt)discAmt.value='';

  memoSelectType('parts');memoSelectScope('vessel');
  memoSelectMode('quick');
  memoRenderItems();
  if(typeof memoCalcTotal==='function')memoCalcTotal();
  // Reset + auto-fill supplier from majority of selected items
  const _supBulk=document.getElementById('memo-supplier');
  if(_supBulk){
    _supBulk.value='';
    memoPopulateSupplierList();
    // Pick majority supplier among selected items
    if(suppliers.length === 1){
      _supBulk.value = suppliers[0];
    } else if(suppliers.length > 1){
      // Count items per supplier, pick majority
      const counts = {};
      selectedItems.forEach(it=>{ if(it.supplier) counts[it.supplier]=(counts[it.supplier]||0)+1; });
      const top = Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];
      if(top) _supBulk.value = top[0];
    }
  }
  openModal('fl-modal-memo');
}

