// §memoRecvWh · เดาคลังปลายทางจากท่าประจำของเรือในใบ memo
function flMemoWarehouse(mo){
  const MAP={ tublamu:'คลัง Tub Lamu', panwa:'คลัง Visit Panwa', ranong:'คลัง Ranong' };
  try{
    const b=(mo&&mo.boatId&&typeof BOATS!=='undefined')?(BOATS||[]).find(x=>x.id===mo.boatId):null;
    const p=b?((typeof getBoatCurrentPier==='function'?getBoatCurrentPier(b):b.pier)||b.pier||b.homePier||''):'';
    if(MAP[p]) return { wh:MAP[p], why:'ท่าประจำของ '+(b.name||'เรือลำนี้') };
  }catch(_){}
  return { wh:'คลัง Tub Lamu', why:(mo&&mo.boatId)?'ใบนี้ไม่ได้ระบุท่าของเรือ':'ใบนี้ไม่ได้ผูกกับเรือ' };
}
function flOpenReceiveMemo(moId){
  const mo=FL_MEMOS.find(x=>x.id===moId);if(!mo)return;
  _receiveMemoId=moId;
  /* §memoRecvWh · ช่องคลังค้างค่าจากครั้งก่อนได้ · ต้องตั้งใหม่ทุกครั้งที่เปิด */
  const _wh=flMemoWarehouse(mo);
  const _locE=document.getElementById('receive-location');
  if(_locE){
    _locE.onchange=null;                     // ล้าง handler ที่ flOpenReceiveOne ผูกทิ้งไว้
    if([..._locE.options].some(o=>o.value===_wh.wh)) _locE.value=_wh.wh;
    else _locE.selectedIndex=0;
  }
  const _warnE=document.getElementById('receive-location-warn');
  if(_warnE){
    _warnE.style.display='block';
    _warnE.style.color='#5F5E5A'; _warnE.style.background='#FBFAF7'; _warnE.style.borderColor='#E9E7E0';
    _warnE.textContent='ตั้งให้จาก '+_wh.why+' · ของทั้งใบจะเข้าคลังเดียวกันหมด — ถ้าไม่ใช่ เปลี่ยนที่ช่องด้านบนก่อนกดบันทึก';
  }
  // Only parts items can be received into stock (labor items are not received)
  const allItems=(mo.items||[]).filter(it=>(it.category||'parts')==='parts');
  if(allItems.length===0){
    // No parts to receive — skip to paid
    mo.currentStep=5;mo.status='paid';
    flSave();flRenderInventory();
    flShowToast(`Memo ${mo.no} → จ่ายแล้ว (ไม่มี parts รับเข้าสต็อก)`);
    return;
  }
  const sel=document.getElementById('receive-item-sel');
  const fixed=document.getElementById('receive-item-fixed');
  sel.style.display='none';
  fixed.style.display='block';
  fixed.innerHTML=`<div style="font-size:11px;font-weight:500;color:var(--ink);margin-bottom:4px">${mo.no} · ${mo.title}</div>
    <div style="font-size:10px;color:var(--ink-soft);margin-bottom:6px">รายการ Parts ที่จะรับเข้าสต็อค <span style="color:#999">(จำนวนตาม Memo ที่อนุมัติแล้ว · แก้ไขไม่ได้)</span>:</div>
    ${allItems.map((it,i)=>{
      // Check if exists in inventory
      const inv=it.invId
        ?FL_INVENTORY.find(x=>x.id===it.invId)
        :FL_INVENTORY.find(x=>x.name===it.name||it.name.includes(x.name));
      const isNew=!inv;
      const newBadge=isNew?`<span style="font-size:8px;background:#FAEEDA;color:#854F0B;padding:1px 6px;border-radius:5px;margin-left:2px;font-weight:600">+ ใหม่</span>`:`<span style="font-size:9px;color:var(--ink-soft);margin-left:2px">มีในสต็อก ${inv.qty||0}</span>`;
      const qtyVal=it.qty||1;
      return `<div style="display:flex;align-items:center;gap:6px;margin-top:4px;font-size:11px;padding:5px 8px;background:${isNew?'#FFF9F0':'transparent'};border-radius:6px;${isNew?'border:1px dashed #E5C9A0':''}">
        <span style="flex:1">${it.name} <span style="font-size:9px;background:#E6F1FB;color:#185FA5;padding:1px 6px;border-radius:5px;margin-left:2px;display:inline-flex;align-items:center;gap:3px"><span style="width:5px;height:5px;border-radius:50%;background:#185FA5"></span>Parts</span>${newBadge}</span>
        <span style="width:52px;font-size:12px;font-weight:600;color:var(--ink);text-align:center;font-family:'DM Mono',monospace;background:#F4F2EE;padding:3px 5px;border-radius:4px;border:1px solid rgba(0,0,0,.06)">${qtyVal}</span>
        <input type="hidden" id="recv-qty-${i}" value="${qtyVal}">
        <span style="color:var(--ink-soft);font-size:10px;min-width:24px">${it.unit||'ชิ้น'}</span>
      </div>`;
    }).join('')}
    <div style="font-size:9px;color:var(--ink-soft);margin-top:8px;padding:6px 8px;background:#FBFAF7;border-radius:6px">
      <span style="font-weight:600">หมายเหตุ:</span> รายการ <span style="background:#FAEEDA;color:#854F0B;padding:0 4px;border-radius:3px;font-weight:600">+ ใหม่</span> จะถูกสร้างเป็น inventory item อัตโนมัติ (category: อื่นๆ — แก้ภายหลังได้)
    </div>`;
  document.getElementById('receive-qty').style.display='none';
  document.getElementById('receive-date').value=TODAY_STR;
  document.getElementById('receive-note').value='';
  document.getElementById('fl-modal-receive').querySelector('.modal-title'||'.mhd-title').textContent=`รับของ - ${mo.no}`;
  openModal('fl-modal-receive');
}
let _receiveMemoId=null;
const flStValues=['ready','fixing','broken','spare'];
const flPropStValues=['active','fixing','broken','spare'];
let flSelSts={eng:0,gb:0,prop:0};
let flEditEngId=null,flEditGbId=null,flEditPropId=null;

function flPickSt(type,idx){
  flSelSts[type]=idx;
  const grid=document.getElementById(`fl-${type}-st-grid`);if(!grid)return;
  const opts=grid.querySelectorAll('.fl-st-opt');
  const colors=[{border:'var(--green)',bg:'var(--green-light)',txt:'var(--green-dark)'},{border:'var(--amber)',bg:'var(--amber-light)',txt:'#7a4a00'},{border:'var(--red)',bg:'var(--red-light)',txt:'var(--red)'},{border:'var(--border)',bg:'var(--sand)',txt:'var(--ink-soft)'}];
  opts.forEach((el,i)=>{
    if(i===idx){el.style.border=`1px solid ${colors[i].border}`;el.style.background=colors[i].bg;el.querySelector('div').style.color=colors[i].txt;}
    else{el.style.border='1px solid var(--border)';el.style.background='var(--white)';el.querySelector('div').style.color='var(--ink-soft)';}
  });
  const spareRow=document.getElementById(`fl-${type}-spare-loc-row`);
  const installRow=document.getElementById(`fl-${type}-install-row`);
  // location row shows for Spare (idx 3) and, for engines, also Fixing (idx 1 · where it's sent for repair)
  if(spareRow)spareRow.style.display=(idx===3||(type==='eng'&&idx===1))?'flex':'none';
  if(installRow)installRow.style.display=idx===3?'none':(type==='prop'?'grid':'grid');
}

/* §boatOwn · เรือที่ "ติดเครื่องได้" คือเรือบริษัทที่ยังไม่ปลดระวางเท่านั้น
   ถ้าเครื่องตัวนี้ถูกผูกกับเรือนอกกลุ่มไว้ก่อนหน้า ยังคงโชว์ค้างไว้พร้อมป้ายกำกับ
   จะได้เห็นแล้วย้ายออกเอง · ไม่ใช่หายเงียบแล้วโดนเซฟทับเป็น "ยังไม่ติดตั้ง" */
function flBoatsForInstall(curId){
  let ok=BOATS.filter(b=>!b.retired && b.ownership!=='charter');
  if(curId && !ok.some(b=>b.id===curId)){
    const cur=BOATS.filter(b=>b.id===curId)[0];
    if(cur) ok=[cur].concat(ok);
  }
  return ok;
}
function flBoatInstallLabel(b){
  return b.name + (b.retired ? ' · ปลดระวางแล้ว' : (b.ownership==='charter' ? ' · เรือเช่า/ร่วม' : ''));
}
function flOpenAddEngineModal(id){
  flEditEngId=id||null;
  const e=id?flGetEng(id):null;
  document.getElementById('fl-eng-modal-title').textContent=e?'แก้ไขเครื่องยนต์':'เพิ่มเครื่องยนต์';
  ['fl-eng-model','fl-eng-serial','fl-eng-hp','fl-eng-buydate','fl-eng-price','fl-eng-base-hours','fl-eng-svc','fl-eng-note'].forEach(fid=>{document.getElementById(fid).value=e?e[fid.replace('fl-eng-','').replace('-','')]||'':''});
  if(e){document.getElementById('fl-eng-brand').value=e.brand;document.getElementById('fl-eng-model').value=e.model;document.getElementById('fl-eng-serial').value=e.serial;document.getElementById('fl-eng-base-hours').value=e.baseHours||'';document.getElementById('fl-eng-svc').value=e.serviceInterval||'';}
  document.getElementById('fl-eng-boat-sel').innerHTML='<option value="">— ยังไม่ติดตั้ง —</option>'+flBoatsForInstall(e&&e.boatId).map(b=>`<option value="${b.id}"${e&&e.boatId===b.id?' selected':''}>${flBoatInstallLabel(b)}</option>`).join('');
  // preselect the engine's current position · add a legacy option if its saved pos isn't in the standard list
  { const _ps=document.getElementById('fl-eng-pos-sel'); const _p=(e&&e.pos)||''; if(_p){ _ps.value=_p; if(_ps.value!==_p){ const o=document.createElement('option'); o.value=_p; o.textContent=_p; o.selected=true; _ps.appendChild(o); } } else { _ps.selectedIndex=0; } }
  flPickSt('eng',e?flStValues.indexOf(e.status):0);
  // preselect saved location (Spare or Fixing) · add a legacy option if the saved value isn't in the list
  if(e&&e.spareLocation){ const _el=document.getElementById('fl-eng-spare-loc'); _el.value=e.spareLocation; if(_el.value!==e.spareLocation){ const o=document.createElement('option'); o.value=e.spareLocation; o.textContent=e.spareLocation+' (legacy)'; o.selected=true; _el.appendChild(o); } }
  openModal('fl-modal-engine');
}
function flOpenEditEngModal(id){
  flOpenAddEngineModal(id);
}

function flSaveEngine(){
  const brand=document.getElementById('fl-eng-brand').value;
  const model=document.getElementById('fl-eng-model').value.trim();
  const serial=document.getElementById('fl-eng-serial').value.trim();
  if(!model||!serial){alert('กรุณาระบุ รุ่น และ Serial');return;}
  const hp=parseFloat(document.getElementById('fl-eng-hp').value)||null;
  const buyDate=document.getElementById('fl-eng-buydate').value||null;
  const price=parseFloat(document.getElementById('fl-eng-price').value)||null;
  const baseHours=parseFloat(document.getElementById('fl-eng-base-hours').value)||0;
  const serviceInterval=parseInt(document.getElementById('fl-eng-svc').value)||100;
  const note=document.getElementById('fl-eng-note').value.trim();
  const status=flStValues[flSelSts.eng];
  const boatId=document.getElementById('fl-eng-boat-sel').value||null;
  const pos=document.getElementById('fl-eng-pos-sel').value;
  const spareLocation=(status==='spare'||status==='fixing')?document.getElementById('fl-eng-spare-loc').value:null;
  if(flEditEngId){const e=flGetEng(flEditEngId);if(e)Object.assign(e,{brand,model,serial,hp,buyDate,price,baseHours,serviceInterval,note,status,boatId,pos,spareLocation});}
  else FL_ENGINES.push({id:LA_UID('e'),brand,model,serial,hp,buyDate,price,baseHours,serviceInterval,note,status,boatId,pos,spareLocation});
  flSave();closeModal('fl-modal-engine');
  // preserve the engine-list scroll across the re-render (was jumping back to top after save)
  const _lp=document.getElementById('fl-eng-listpanel'); const _lt=_lp?_lp.scrollTop:0; const _wy=window.scrollY||window.pageYOffset||0;
  flRenderEngList();
  const _rs=()=>{ const p=document.getElementById('fl-eng-listpanel'); if(p)p.scrollTop=_lt; window.scrollTo(0,_wy); };
  _rs(); requestAnimationFrame(_rs);
  if(flEditEngId&&typeof flRenderEngDetailPink==='function') flRenderEngDetailPink();
}

function flOpenAddGearboxModal(id){
  flEditGbId=id||null;
  const g=id?flGetGb(id):null;
  document.getElementById('fl-gb-modal-title').textContent=g?'แก้ไข Gearbox':'เพิ่ม Gearbox';
  const fields=['fl-gb-model','fl-gb-serial','fl-gb-suffix','fl-gb-buydate','fl-gb-base-hours','fl-gb-note','fl-gb-last-svc','fl-gb-oil-cap','fl-gb-svc-interval'];
  if(g){
    document.getElementById('fl-gb-brand').value=g.brand||'Honda';
    fields.forEach(fid=>{
      const key=fid.replace('fl-gb-','').replace(/-([a-z])/g,(_,c)=>c.toUpperCase());
      const el=document.getElementById(fid);
      if(el) el.value=g[key]||g[fid.replace('fl-gb-','')]||'';
    });
    document.getElementById('fl-gb-serial').value=g.serial||'';
    document.getElementById('fl-gb-suffix').value=g.modelSuffix||'';
    document.getElementById('fl-gb-shaft').value=g.shaftLength||'';
    document.getElementById('fl-gb-rotation').value=g.rotation||'Standard';
    document.getElementById('fl-gb-ratio').value=g.gearRatio||'';
    document.getElementById('fl-gb-oil-cap').value=g.oilCapacity||'';
    document.getElementById('fl-gb-svc-interval').value=g.serviceInterval||100;
    document.getElementById('fl-gb-last-svc').value=g.lastServiceDate||'';
    document.getElementById('fl-gb-base-hours').value=g.baseHours||'';
    document.getElementById('fl-gb-buydate').value=g.buyDate||'';
    document.getElementById('fl-gb-note').value=g.note||'';
    // Pre-select spare location (สำคัญสำหรับ Edit เมื่อ status=spare)
    const _gbLocSel=document.getElementById('fl-gb-spare-loc');
    if(_gbLocSel && g.spareLocation){
      _gbLocSel.value=g.spareLocation;
      // ถ้าค่าเดิมไม่อยู่ใน options (legacy data) ก็เพิ่ม option ใหม่
      if(_gbLocSel.value!==g.spareLocation){
        const opt=document.createElement('option');
        opt.value=g.spareLocation;opt.textContent=g.spareLocation+' (legacy)';opt.selected=true;
        _gbLocSel.appendChild(opt);
      }
    }
  } else {
    fields.forEach(fid=>{const el=document.getElementById(fid);if(el)el.value='';});
    document.getElementById('fl-gb-svc-interval').value='100';
    document.getElementById('fl-gb-rotation').value='Standard';
    document.getElementById('fl-gb-shaft').value='';
    document.getElementById('fl-gb-ratio').value='';
  }
  // Only engines that are mounted on a boat AND don't already have a gearbox (1 engine = 1 gearbox).
  // A spare engine (no boat) can't carry a gearbox. Always keep this gearbox's own engine when editing.
  const _gbUsedEng=new Set(FL_GEARBOXES.filter(x=>x.engineId && (!g||x.id!==g.id)).map(x=>x.engineId));
  document.getElementById('fl-gb-engine-sel').innerHTML='<option value="">— ยังไม่ติดตั้ง (Spare) —</option>'+FL_ENGINES.filter(e=>!_gbUsedEng.has(e.id) && (e.boatId || (g&&g.engineId===e.id))).map(e=>{const b=getBoat(e.boatId);return`<option value="${e.id}"${g&&g.engineId===e.id?' selected':''}>${e.serial}${b?' · '+b.name+' '+e.pos:' · Spare'}</option>`;}).join('');
  flPickSt('gb',g?flStValues.indexOf(g.status):0);
  openModal('fl-modal-gearbox');
}
function flSaveGearbox(){
  const brand=document.getElementById('fl-gb-brand').value;
  const model=document.getElementById('fl-gb-model').value.trim();
  const serial=document.getElementById('fl-gb-serial').value.trim();
  const buyDate=document.getElementById('fl-gb-buydate').value||null;
  const baseHours=parseFloat(document.getElementById('fl-gb-base-hours').value)||0;
  const note=document.getElementById('fl-gb-note').value.trim();
  const status=flStValues[flSelSts.gb];
  let engineId=document.getElementById('fl-gb-engine-sel').value||null;
  // Invariant: a SPARE gearbox is on the shelf → cannot stay linked to an engine.
  if(status==='spare') engineId=null;
  // spareLocation logic:
  //   - status='spare' → ใช้ค่าจาก dropdown
  //   - status อื่น + ยังเป็น orphan (ไม่มี engineId) → เก็บค่าเดิมไว้ (อย่าทำลาย)
  //   - status อื่น + มี engineId (ติดเครื่อง) → set null
  let spareLocation;
  if(status==='spare'){
    spareLocation=document.getElementById('fl-gb-spare-loc')?.value||null;
  } else if(engineId){
    spareLocation=null;  // ติดเครื่องแล้ว ไม่ใช่ spare
  } else {
    // orphan แต่ status เป็น ready/fixing/broken → เก็บค่าเดิม
    const _curGb=flEditGbId?flGetGb(flEditGbId):null;
    spareLocation=_curGb?.spareLocation||null;
  }
  // new fields
  const modelSuffix=document.getElementById('fl-gb-suffix').value.trim();
  const shaftLength=document.getElementById('fl-gb-shaft').value;
  const rotation=document.getElementById('fl-gb-rotation').value;
  const gearRatio=document.getElementById('fl-gb-ratio').value;
  const oilCapacity=document.getElementById('fl-gb-oil-cap').value;
  const serviceInterval=parseInt(document.getElementById('fl-gb-svc-interval').value)||100;
  const lastServiceDate=document.getElementById('fl-gb-last-svc').value||null;
  const data={brand,model,serial,buyDate,baseHours,note,status,engineId,spareLocation,modelSuffix,shaftLength,rotation,gearRatio,oilCapacity,serviceInterval,lastServiceDate};
  if(flEditGbId){const g=flGetGb(flEditGbId);if(g)Object.assign(g,data);}
  else FL_GEARBOXES.push({id:LA_UID('g'),...data});
  flSave();closeModal('fl-modal-gearbox');
  // ใช้ flRenderAsset() เพื่อ refresh tab ปัจจุบัน (รวม Overview · Gearboxes · etc.)
  if(typeof flRenderAsset==='function') flRenderAsset();
  else flRenderGbList();
}

function flOpenAddPropModal(id){
  flEditPropId=id||null;
  const p=id?FL_PROPELLERS.find(x=>x.id===id):null;
  document.getElementById('fl-prop-modal-title').textContent=p?'แก้ไข Propeller':'เพิ่ม Propeller';
  if(p){
    document.getElementById('fl-prop-brand').value=p.brand||'Solas';
    document.getElementById('fl-prop-serial').value=p.serial||'';
    document.getElementById('fl-prop-diameter').value=p.diameter||'';
    document.getElementById('fl-prop-pitch').value=p.pitch||'';
    document.getElementById('fl-prop-blades').value=p.blades||'3';
    document.getElementById('fl-prop-material').value=p.material||'Stainless';
    document.getElementById('fl-prop-rotation').value=p.rotation||'Standard';
    document.getElementById('fl-prop-hub').value=p.hubSize||'';
    document.getElementById('fl-prop-cup').value=p.cupping||'no';
    document.getElementById('fl-prop-cost').value=p.cost||'';
    document.getElementById('fl-prop-buydate').value=p.buyDate||'';
    document.getElementById('fl-prop-note').value=p.note||'';
    // Pre-select spare location
    const _pLocSel=document.getElementById('fl-prop-spare-loc');
    if(_pLocSel && p.spareLocation){
      _pLocSel.value=p.spareLocation;
      if(_pLocSel.value!==p.spareLocation){
        const opt=document.createElement('option');
        opt.value=p.spareLocation;opt.textContent=p.spareLocation+' (legacy)';opt.selected=true;
        _pLocSel.appendChild(opt);
      }
    }
  } else {
    ['fl-prop-serial','fl-prop-diameter','fl-prop-pitch','fl-prop-hub','fl-prop-cost','fl-prop-buydate','fl-prop-note'].forEach(fid=>{const el=document.getElementById(fid);if(el)el.value='';});
    document.getElementById('fl-prop-rotation').value='Standard';
    document.getElementById('fl-prop-cup').value='no';
  }
  // Only gearboxes that are installed on an engine AND don't already have a propeller (1 gearbox = 1 propeller).
  // A spare/uninstalled gearbox can't carry a propeller. Always keep this propeller's own gearbox when editing.
  const _pUsedGb=new Set(FL_PROPELLERS.filter(x=>x.gearboxId && (!p||x.id!==p.id)).map(x=>x.gearboxId));
  document.getElementById('fl-prop-gb-sel').innerHTML='<option value="">— ยังไม่ติดตั้ง (Spare) —</option>'+FL_GEARBOXES.filter(g=>!_pUsedGb.has(g.id) && (g.engineId || (p&&p.gearboxId===g.id))).map(g=>{const eng=flGetEng(g.engineId);const b=eng?getBoat(eng.boatId):null;return`<option value="${g.id}"${p&&p.gearboxId===g.id?' selected':''}>${g.serial}${b?' · '+b.name+' '+g.note:''}</option>`;}).join('');
  flPickSt('prop',p?flPropStValues.indexOf(p.status):0);
  openModal('fl-modal-propeller');
}
function flSavePropeller(){
  const brand=document.getElementById('fl-prop-brand').value;
  const serial=document.getElementById('fl-prop-serial').value.trim();
  const diameter=parseFloat(document.getElementById('fl-prop-diameter').value)||null;
  const pitch=parseFloat(document.getElementById('fl-prop-pitch').value)||null;
  const size=diameter&&pitch?`${diameter}×${pitch}`:document.getElementById('fl-prop-diameter').value||'';
  const blades=document.getElementById('fl-prop-blades').value;
  const material=document.getElementById('fl-prop-material').value;
  const rotation=document.getElementById('fl-prop-rotation').value;
  const hubSize=document.getElementById('fl-prop-hub').value.trim();
  const cupping=document.getElementById('fl-prop-cup').value;
  const cost=parseFloat(document.getElementById('fl-prop-cost').value)||0;
  const buyDate=document.getElementById('fl-prop-buydate').value||null;
  const note=document.getElementById('fl-prop-note').value.trim();
  const status=flPropStValues[flSelSts.prop];
  let gearboxId=document.getElementById('fl-prop-gb-sel').value||null;
  // Invariant: a SPARE propeller is on the shelf → cannot stay linked to a gearbox.
  if(status==='spare') gearboxId=null;
  // spareLocation logic (เหมือน gearbox):
  //   - status spare/fixing → ใช้ค่าจาก dropdown
  //   - status อื่น + มี gearboxId → set null
  //   - status อื่น + ไม่มี gearboxId (orphan) → เก็บค่าเดิม
  let spareLocation;
  if(status==='spare'||status==='fixing'){
    spareLocation=document.getElementById('fl-prop-spare-loc')?.value||null;
  } else if(gearboxId){
    spareLocation=null;
  } else {
    const _curP=flEditPropId?FL_PROPELLERS.find(x=>x.id===flEditPropId):null;
    spareLocation=_curP?.spareLocation||null;
  }
  // spare = detached from gearbox — keep status and gearboxId consistent
  // (the Spare Overview decides "is spare" from !gearboxId)
  if(status==='spare') gearboxId=null;
  const data={brand,serial,diameter,pitch,size,blades,material,rotation,hubSize,cupping,cost,buyDate,note,status,gearboxId,spareLocation};
  if(flEditPropId){const p=FL_PROPELLERS.find(x=>x.id===flEditPropId);if(p)Object.assign(p,data);}
  else FL_PROPELLERS.push({id:LA_UID('p'),...data});
  flSave();closeModal('fl-modal-propeller');
  if(typeof flRenderAsset==='function') flRenderAsset();
  else flRenderPropList();
}

