flLoad();
// Layer 4: ตรวจ data integrity หลัง load · แสดง warning ใน console ถ้ามี
if(typeof flValidateDataIntegrity === 'function') flValidateDataIntegrity();
flDrWeekStart=addDays(TODAY,-TODAY.getDay()+1);
